L["|cff808080Nothing found|r"] = "|cff808080找不到結果|r"
L["Scroll for %d more"] = "捲動以查看另外 %d 項"
L["Fades the UI and adds letterbox bars between fights. Combat, casting and opening windows like the spellbook bring it back. Typing just shows the chat. The pages under this one cover what shows when (CineMode, Game Frames, Addon Frames, Minimap, Quest tracker, Nameplates, Chat), visual effects and sound, the camera modes and triggers, and keybinds."] = "在戰鬥之間淡出介面並加上電影黑邊。戰鬥、施法以及開啟法術書等視窗時,介面會恢復顯示。輸入文字時只會顯示聊天。此頁面底下的各頁面涵蓋何時顯示什麼(CineMode、遊戲框架、插件框架、小地圖、任務追蹤、名條、聊天)、視覺效果與音效、鏡頭模式與觸發條件,以及按鍵設定。"
L["Also toggled with /cine or the keybind under Key Bindings > AddOns."] = "也可以用 /cine 或「按鍵設定 > 插件」中的按鍵切換。"
L["Start in CineMode (fade UI, queue music, etc.)"] = "以 CineMode 啟動(淡出介面、播放音樂等)"
L["Off: the UI stays as it is and the camera's left to you, with just the visual effects over it (as the Visual Effects page says), as in the Subtle profile. Events ticked in the Camera Triggers page's CineMode column still bring CineMode on while their camera runs: standing still or going AFK, say, for a screensaver."] = "關閉:介面維持原樣,鏡頭由你自己控制,只在上面套用視覺效果(依視覺效果頁面的設定),與「Subtle」設定檔相同。在鏡頭觸發頁面的 CineMode 欄中勾選的事件,仍會在其鏡頭運作期間開啟 CineMode:例如站著不動或暫離時,當作螢幕保護程式。"
L["Left-click it for quick options (combat, music, tint), right-click for these settings, drag to move it."] = "左鍵點擊開啟快速選項(戰鬥、音樂、色調),右鍵點擊開啟這些設定,拖曳可移動。"
L["Language"] = "語言"
L["Game language"] = "遊戲語言"
L["The language Cinematic's text is in, for all your characters. Game language follows the game's (English where Cinematic has no translation yet). A change needs a reload."] = "Cinematic 文字所使用的語言,套用於你所有的角色。「遊戲語言」會跟隨遊戲的語言(Cinematic 尚無翻譯的部分則顯示英文)。變更後需要重新載入介面。"
L["Turn off in"] = "在以下情況關閉"
L["Combat"] = "戰鬥"
L["Being in combat brings the UI back. Unticked, CineMode stays on in fights: only the frames ticked under In combat on the Game Frames page show. (Targeting an enemy only ever shows the frames chosen for it there.)"] = "進入戰鬥時介面會恢復顯示。取消勾選時,CineMode 在戰鬥中仍保持開啟:只會顯示遊戲框架頁面中「戰鬥中」所勾選的框架。(選取敵人時,一律只顯示那裡為此選擇的框架。)"
L["Open world"] = "開放世界"
L["Anywhere outside cities, dungeons and raids (inns too), while you're not PvP flagged. Flights still go cinematic."] = "主城、地城與團隊副本以外的任何地方(旅店也算),且未開啟 PvP 狀態時。飛行時仍會有電影效果。"
L["Cities"] = "主城"
L["Capital cities, including Dalaran. Flights leaving a city still go cinematic."] = "主城,包括達拉然。從主城出發的飛行仍會有電影效果。"
L["Dungeons"] = "地城"
L["Keep the normal UI in dungeons and scenarios."] = "在地城與事件中保持一般介面。"
L["Raids"] = "團隊副本"
L["PvP"] = "PvP"
L["Keep the normal UI while you're in a party (but not a raid group)."] = "身處隊伍(但非團隊)時保持一般介面。"
L["Raid group"] = "團隊"
L["Keep the normal UI while you're in a raid group, wherever you are."] = "身處團隊時,無論在哪裡都保持一般介面。"
L["Moving"] = "移動中"
L["Walking or riding about yourself brings the UI back (names too), say to look for an NPC in a city. CineMode comes back once you've stood still, or kept moving, for the time below. Auto-run, RP walking and flights stay in CineMode."] = "自己走動或騎乘時介面會恢復顯示(名稱也是),例如在主城中尋找 NPC 時。在你站著不動或持續移動達下方設定的時間後,CineMode 會恢復。自動奔跑、RP 漫步與飛行時仍保持 CineMode。"
L["Keep VFX on"] = "保留視覺效果"
L["The visual effects (letterbox, tint and the rest on the Visual Effects page) stay on while moving brings the UI back."] = "移動使介面恢復顯示時,視覺效果(黑邊、色調及視覺效果頁面中的其他效果)仍保持開啟。"
L["Back after"] = "恢復時間"
L["%d sec"] = "%d 秒"
L["CineMode comes back once you've stood still this long, or kept moving this long without stopping (a long walk or ride)."] = "在你站著不動達此時間,或持續移動不停達此時間(長距離步行或騎乘)後,CineMode 會恢復。"
L["Reset profile"] = "重置設定檔"
L["Put the active profile's settings back to how it started (a built-in profile's own values, or the defaults). Frames you added or stopped fading are kept."] = "將目前設定檔的設定還原為初始狀態(內建設定檔本身的值,或預設值)。你加入或停止淡出的框架會保留。"
L["Profile: |cffff8000none yet|r (pick one on the Profiles page)"] = "設定檔:|cffff8000尚未選擇|r(請在設定檔頁面中選擇)"
L["Profile: %s"] = "設定檔:%s"
L[" (this character)"] = "(此角色)"
L["How fast the UI fades, what brings it (or parts of it) back while CineMode is on, and combat text. Fights and targeting are on the Game Frames page, names and nameplates on the Nameplates page, buffs on the Buffs/debuffs page, the minimap on the Minimap page, the quest tracker on the Quest tracker page, chat on the Chat page."] = "介面淡出的速度、CineMode 開啟時什麼會讓介面(或其中一部分)恢復顯示,以及戰鬥文字。戰鬥與選取目標位於遊戲框架頁面,名稱與名條位於名條頁面,增益位於增益/減益頁面,小地圖位於小地圖頁面,任務追蹤位於任務追蹤頁面,聊天位於聊天頁面。"
L["Fading"] = "淡出"
L["Fade in time"] = "淡入時間"
L["How long things take to fade in out of combat: targeting something, a mouseover, a window opening. In fights the Combat fade in time is used."] = "非戰鬥時介面淡入所需的時間：選取目標、滑鼠懸停、開啟視窗。戰鬥中使用戰鬥淡入時間。"
L["%.1f sec"] = "%.1f 秒"
L["Fade out time"] = "淡出時間"
L["How long things take to fade out, in and out of fights: letting go of a target, after a mouseover, and after a fight once the Calm Timer below is over. The mouseover time (Hover groups page) includes it: a time shorter than the fade just fades straight away."] = "介面淡出所需的時間，戰鬥中和戰鬥外都用：放開目標、滑鼠懸停之後，以及戰鬥後下方的平靜計時結束時。滑鼠懸停時間（滑鼠懸停群組頁面）包含它：比淡出更短的時間會立即淡出。"
L["Combat fade in time"] = "戰鬥淡入時間"
L["How long things take to fade in during a fight: the UI coming back as one starts, and anything else that shows mid-fight. Other times use the Fade in time."] = "戰鬥中各項元素淡入所需的時間:戰鬥開始時恢復顯示的介面,以及戰鬥中途顯示的任何其他東西。其他時候則使用淡入時間。"
L["Calm Timer"] = "平靜計時"
L["Exit Calm Timer when healthy"] = "生命值滿時結束平靜計時"
L["as soon as you're healthy"] = "一恢復健康就結束"
L["%d sec after you're healthy"] = "恢復健康後 %d 秒"
L["Include your pet"] = "包括寵物"
L["The Calm Timer runs out early once your health and power are back to full after a fight (mana, energy and focus refilled; rage, runic power, Insanity and the like drained). The seconds: how long things stay up once you're full, before they fade out at the Fade out time (a little wait keeps them up between pulls when you took no damage). Off: the Calm Timer always runs its full length."] = "戰鬥後生命值和能量恢復滿時，平靜計時提前結束（法力、能量和集中值回滿；怒氣、符文能量、瘋狂值等清空）。秒數：恢復滿後介面再保留多久，然後依淡出時間淡出（沒有受到傷害時稍等一下，可讓介面在兩波怪之間保持顯示）。關閉：平靜計時總是走完全程。"
L["With a pet out, the Calm Timer only ends early once its health is back to full as well. No pet, or a dead one: just yours counts."] = "有寵物時，只有當寵物生命值也回滿，平靜計時才會提前結束。沒有寵物或寵物已死亡：只看你自己的。"
L["%d sec after a fight"] = "戰鬥後 %d 秒"
L["How long things take to settle back into CineMode after a fight. Nameplates and names ticked In combat stay up this long (so they don't drop away between pulls), and visual effects that step aside for fights wait this long before fading back in. Your portrait and buffs, if they only show after combat, count a fight as recent for this long too, the RP walk, auto-run and cozy cameras wait this long before starting, and music muted for fights comes back after it. Then things fade out at the Fade out time. 0 settles at once. Exit Calm Timer when healthy, below, can end it early."] = "戰鬥後各項元素回到 CineMode 所需的時間。勾選「戰鬥中」的名條與名稱會保持顯示這麼久(在兩次拉怪之間不會消失),因戰鬥而暫時讓開的視覺效果也會等待這麼久才重新淡入。你的頭像與增益若設為只在戰鬥後顯示,也會以此時間判斷是否剛結束戰鬥;RP 漫步、自動奔跑與悠閒鏡頭會等待這麼久才啟動;因戰鬥而靜音的音樂也會在此之後恢復。之後介面依淡出時間淡出。0 表示立即平靜。下方的「生命值滿時結束平靜計時」可以提前結束它。"
L["Combat text"] = "戰鬥文字"
L["Hide combat text out of combat"] = "非戰鬥中隱藏戰鬥文字"
L["No floating damage and healing numbers (like \"+10\" from a heal or regen) in cinematic mode while you're out of combat. They come back the moment a fight starts and stay for the Calm Timer after it, and your combat text settings are put back when the UI returns."] = "在電影模式中、非戰鬥狀態下,不顯示浮動的傷害與治療數字(例如治療或回復產生的「+10」)。戰鬥一開始就會恢復顯示,並在戰鬥後的平靜計時內保持顯示;介面恢復時,你的戰鬥文字設定也會還原。"
L["Hide all floating text: XP, damage, healing (restart required)"] = "隱藏所有浮動文字:經驗值、傷害、治療(需重新啟動)"
L["The game has no way to hide just the XP you gain over your character: it draws that, the damage and healing numbers, misses and the like all in one font. This blanks that font, so they all go, always (not just in CineMode). Takes effect after you fully restart the game; /reload isn't enough."] = "遊戲無法只隱藏角色上方顯示的經驗值獲得:它和傷害與治療數字、未命中等文字全都使用同一種字型。此選項會將該字型清空,所以它們會全部消失,而且是一直消失(不只是在 CineMode 中)。需要完全重新啟動遊戲後才會生效;/reload 並不夠。"
L["Floating text changes after you fully restart the game (/reload isn't enough). Exit the game now?"] = "浮動文字需要完全重新啟動遊戲後才會改變(僅 /reload 不夠)。現在離開遊戲嗎?"
L["Misc"] = "雜項"
L["Frames CineMode brings back while they have something to tell you. Always keeping a frame up, or in fights, is on the Game Frames page."] = "在有事要提醒你時,CineMode 會讓這些框架重新出現。要讓框架一直顯示或在戰鬥中顯示,請到遊戲框架頁面設定。"
L["Show your portrait until health and power are full"] = "顯示你的頭像直到生命值與能量全滿"
L["Keeps your player portrait up while you're recovering. Rage and runic power don't count, so a warrior's portrait hides once their health is full."] = "在你恢復期間保持顯示你的玩家頭像。怒氣與符文能量不計算在內,所以戰士的頭像會在生命值全滿時隱藏。"
L["Only after combat"] = "僅限戰鬥後"
L["Only keep the portrait up if you've been in combat (or taken fall damage) within the Calm Timer (CineMode page), so things like casting a buff in town don't bring it up."] = "只有在平靜計時(CineMode 頁面)內曾進入戰鬥(或受到墜落傷害)時才保持顯示頭像,這樣在城裡施放增益之類的動作就不會讓它出現。"
L["Also after you resurrect"] = "復活後也顯示"
L["After you come back to life, keep the portrait up until your health and power are full, however long that takes."] = "復活後保持顯示頭像,直到生命值與能量全滿為止,無論需要多久。"
L["Show the durability figure when gear is damaged"] = "裝備損壞時顯示耐久度人形圖"
L["Keeps the armor figure (by the minimap) up in CineMode, and in fights, while the game shows it: some of your gear is badly damaged (yellow) or broken (red). It goes again once you repair. Off, it fades with the rest of the UI."] = "在遊戲顯示護甲人形圖(小地圖旁)時,於 CineMode 及戰鬥中保持顯示:表示你有裝備嚴重損壞(黃色)或已損毀(紅色)。修理後就會消失。關閉時,它會隨介面其他部分一起淡出。"
L["While a camera mode runs (AFK, auto-run, RP walk, flights and the rest), the figure fades with the rest of the UI. It comes back when the camera mode ends."] = "鏡頭模式運行時（暫離、自動奔跑、RP 步行、飛行等），人形圖會隨其餘介面一起淡出。鏡頭模式結束後它會重新出現。"
L["Show the pet frame when your pet isn't happy"] = "寵物不快樂時顯示寵物框架"
L["Keeps your pet's portrait up in CineMode, and in fights, while its happiness isn't green: content (yellow) or unhappy (red). It goes again once your pet is happy."] = "當寵物的快樂度不是綠色（滿足：黃色，不快樂：紅色）時，在 CineMode 和戰鬥中保持寵物頭像顯示。寵物快樂後再次隱藏。"
L["While a camera mode runs (AFK, auto-run, RP walk, flights and the rest), the pet frame fades with the rest of the UI. It comes back when the camera mode ends."] = "鏡頭模式運行時（暫離、自動奔跑、RP 漫步、飛行等），寵物框架隨其餘介面一起淡出。鏡頭模式結束後重新出現。"
L["Buffs/debuffs"] = "增益/減益"
L["Buffs/Debuffs"] = "增益/減益"
L["Your buff and debuff icons. They fade with the UI in CineMode; these bring them back."] = "你的增益與減益圖示。它們在 CineMode 中會隨介面淡出;以下選項可讓它們恢復顯示。"
L["Show buffs when you gain or refresh one"] = "獲得或刷新增益時顯示增益"
L["Gaining or refreshing a buff briefly shows your buffs and debuffs. Not on flights."] = "獲得或刷新增益時會短暫顯示你的增益與減益。飛行時除外。"
L["On: CineMode fades your buffs and debuffs as this page and their Game Frames row say. Off: it leaves them alone, with no peeks."] = "開啟:CineMode 會依此頁面及遊戲框架中對應列的設定淡出你的增益與減益。關閉:不予處理,也不會短暫顯示。"
L["Only within the Calm Timer after a fight, so buffing up in town doesn't count."] = "僅限戰鬥後的平靜計時內,這樣在城裡上增益就不算數。"
L["Not ones you cast on yourself"] = "不含自己施放在自己身上的"
L["Your own buffs on yourself (Power Word: Fortitude, Arcane Intellect, a self-cast shield...) and your pet's don't bring them up; ones from other players and the world still do."] = "你施放在自己身上的增益(真言術:韌、秘法智力、自己施放的護盾……)及你寵物的增益不會讓它們顯示;來自其他玩家和世界的增益仍會。"
L["Show debuffs when you gain or refresh one"] = "獲得或刷新減益時顯示減益"
L["Gaining or refreshing a debuff briefly shows your buffs and debuffs. Not on flights."] = "獲得或刷新減益時會短暫顯示你的增益與減益。飛行時除外。"
L["Only within the Calm Timer after a fight. Off: debuffs like Hunter's Mark show any time."] = "僅限戰鬥後的平靜計時內。關閉:獵人印記之類的減益隨時都會顯示。"
L["Keep them up until the debuff is gone"] = "保持顯示直到減益消失"
L["A debuff that brings them up keeps them up while you have any debuff (bar the ones listed below), however long that is. Combat still takes over."] = "讓它們顯示的減益,會在你身上有任何減益(下方清單中的除外)期間保持顯示,無論多久。戰鬥狀態仍優先。"
L["Show buffs for"] = "增益顯示時間"
L["Show debuffs for"] = "減益顯示時間"
L["Except for these buffs and debuffs:"] = "以下增益與減益除外:"
L["Remove"] = "移除"
L["Add"] = "加入"
L["Gaining or stacking this doesn't bring your buffs up. Type a spell ID or a name. Names must match your game language; spell IDs work in any language (2479 is Honorless Target, 8326 and 20584 are Ghost)."] = "獲得或疊加這些不會讓你的增益顯示。請輸入法術 ID 或名稱。名稱必須與你的遊戲語言相符;法術 ID 適用於任何語言(2479 是無榮譽目標,8326 與 20584 是鬼魂)。"
L["Camera Modes"] = "鏡頭模式"
L["While CineMode is on, the camera comes alive in eight situations: Flight (on flight paths), AFK (once you've stood still a while, or go AFK), Cozy (campfires and emotes), Tele (casting your Hearthstone or a teleport), Vista (/stare), Fish (fishing), RP Walk (auto-walking) and Auto-run. Moving by hand cancels them all. Death Cam turns round your body when you die, and Quest Cam swings behind you at quest givers. The Camera Triggers page picks which camera each emote or event starts. Everything goes back to normal when the UI returns. The settings here apply to all of them."] = "CineMode 開啟時,鏡頭會在八種情況下動起來:飛行(搭乘飛行路線時)、暫離(站著不動一段時間或暫離時)、悠閒(營火與表情動作)、傳送(使用爐石或施放傳送時)、遠景(/stare)、釣魚(釣魚時)、RP 漫步(自動行走時)與自動奔跑。手動移動會取消上述所有鏡頭。死亡鏡頭會在你死亡時繞著你的屍體旋轉,任務鏡頭會在你與任務 NPC 對話時轉到你身後。鏡頭觸發頁面用來選擇每個表情動作或事件啟動哪個鏡頭。介面恢復顯示時,一切都會恢復正常。此處的設定適用於所有鏡頭。"
L["In the camera modes, the minimap and quest tracker hover holds and the buff and chat peeks use their short default times, so they clear the view quickly."] = "在鏡頭模式中,小地圖與任務追蹤的滑鼠指向停留時間,以及增益與聊天的短暫顯示,都會使用較短的預設時間,以便迅速讓出畫面。"
L["Ticked, that camera doesn't start there (and stops if it's running): the UI stays faded, with the camera left to you. With the Death Cam off, dying brings the UI back as usual. To keep the normal UI somewhere instead, use Turn off in on the main page. For flights, Cities means taking off from one, and Open world taking off anywhere else. Calm Timer, on the right: ticked, that camera waits until the Calm Timer (CineMode page) has run out after a fight before it starts."] = "勾選時,該鏡頭不會在該處啟動(若正在運作則會停止):介面維持淡出,鏡頭由你自己控制。關閉死亡鏡頭時,死亡會像平常一樣讓介面恢復顯示。若想在某處保持一般介面,請使用主頁面的「在以下情況關閉」。就飛行而言,「主城」指從主城起飛,「開放世界」指從其他任何地方起飛。右側的平靜計時:勾選時,該鏡頭會等到戰鬥後的平靜計時(CineMode 頁面)結束後才啟動。"
L["in capital cities"] = "在主城中"
L["in dungeons, scenarios and raids"] = "在地城、事件與團隊副本中"
L["in battlegrounds and arenas"] = "在戰場與競技場中"
L["out in the world (not in a capital city or an instance), inns included"] = "在野外(不在主城或副本中),包括旅店"
L["Tick a camera here to turn it off %s."] = "在此勾選鏡頭,即可%s關閉它。"
L["Tick a camera here to have it wait until the Calm Timer (CineMode page) has run out after a fight before it starts."] = "在此勾選鏡頭,使其等到戰鬥後的平靜計時(CineMode 頁面)結束後才啟動。"
L["Flights don't start %s."] = "%s不會啟動飛行鏡頭。"
L["No Flight Cam on flights taking off from a capital city."] = "從主城起飛的飛行不使用飛行鏡頭。"
L["No Flight Cam on flights taking off anywhere but a capital city."] = "從主城以外任何地方起飛的飛行不使用飛行鏡頭。"
L["No %s Cam %s."] = "不使用「%s」鏡頭:%s。"
L["You die in a fight: the Death Cam can't wait for one to be over."] = "你會在戰鬥中死亡:死亡鏡頭無法等到戰鬥結束。"
L["The %s Cam waits until the Calm Timer has run out after a fight."] = "「%s」鏡頭會等到戰鬥後的平靜計時結束才啟動。"
L["Depth of field"] = "景深"
L["Cozy camera"] = "悠閒鏡頭"
L["Vista camera"] = "遠景鏡頭"
L["Fish camera"] = "釣魚鏡頭"
L["AFK camera"] = "暫離鏡頭"
L["No camera"] = "無鏡頭"
L["Flight camera"] = "飛行鏡頭"
L["RP walk camera"] = "RP 漫步鏡頭"
L["Auto-run camera"] = "自動奔跑鏡頭"
L["Death camera"] = "死亡鏡頭"
L["Quest camera"] = "任務鏡頭"
L["Tele camera"] = "傳送鏡頭"
L["Standing or sitting still with any of the buffs listed below (like Welcoming Campfire)."] = "帶著下方清單中的任一增益(例如「溫暖營火」)站著或坐著不動。"
L["Doing the emote (or pressing the sit key). Moving, jumping or another emote ends it."] = "做出該表情動作(或按坐下鍵)。移動、跳躍或做其他表情動作會結束它。"
L["Doing the emote. Moving, jumping or another emote ends it."] = "做出該表情動作。移動、跳躍或做其他表情動作會結束它。"
L["Right-clicking a seat to sit on it; standing up ends it. Seats are recognized by name, using the words below."] = "右鍵點擊座位坐下;站起來就會結束。座位是依名稱辨識,使用下方的關鍵字。"
L["Unsheathing your weapon with your Sheathe/Unsheathe key out of combat, for a \"hero shot\" (not when it comes out from attacking or casting). Putting it away, running or combat ends it. With the cozy camera it carries on while you auto-walk (the camera swings round in front as you walk, even with Stop on move)."] = "非戰鬥中用收/拔武器鍵拔出武器,拍一張「英雄特寫」(攻擊或施法時拔出的不算)。收起武器、奔跑或戰鬥會結束它。使用悠閒鏡頭時,自動行走期間會繼續(行走時鏡頭會轉到你前方,即使開啟了「移動時停止」也一樣)。"
L["Casting your Hearthstone (or Astral Recall, or any spell with \"Hearthstone\" in its name). The tele camera swings round in front of you and spins faster and faster as it zooms in, until you go. The cast doesn't bring the UI back or pause the camera."] = "使用爐石(或星界傳送,或任何名稱中含有「爐石」的法術)。傳送鏡頭會轉到你前方,一邊拉近一邊越轉越快,直到你傳走為止。施法不會讓介面恢復顯示,也不會暫停鏡頭。"
L["Casting a teleport (a mage's \"Teleport: Stormwind\" and the like, or a druid's Teleport: Moonglade). The tele camera, as for the Hearthstone."] = "施放傳送(法師的「傳送:暴風城」之類,或德魯伊的傳送:月光林地)。使用傳送鏡頭,與爐石相同。"
L["Logging out or quitting where the game counts down 20 seconds first (out in the world). In an inn or a city, logging out is instant, so there's nothing to see. Moving, jumping, casting or Cancel ends it. It comes before any other event (a Hearthstone or teleport cast calls it off)."] = "在遊戲會先倒數 20 秒的地方(野外)登出或離開遊戲。在旅店或主城中登出是即時的,所以沒什麼可看。移動、跳躍、施法或按取消會結束它。它優先於其他任何事件(使用爐石或施放傳送會取消它)。"
L["Doing the emote while standing still. Moving, jumping or another emote ends it."] = "站著不動時做出該表情動作。移動、跳躍或做其他表情動作會結束它。"
L["Casting Fishing. It carries on after the cast ends (looting, casting again) until you move or jump. The cast doesn't bring the UI back or pause the camera."] = "施放釣魚。施法結束後仍會繼續(拾取、再次拋竿),直到你移動或跳躍為止。施法不會讓介面恢復顯示,也不會暫停鏡頭。"
L["Being flagged AFK (/afk, or away long enough). With \"No camera\", Stand still below still applies once you've stood still for its time."] = "處於暫離狀態(/afk,或離開夠久)。選擇「無鏡頭」時,只要你站著不動達其時間,下方的「站著不動」仍然適用。"
L["Standing still for the time below with nothing else going on (no emote, no other event). \"No camera\": standing still starts nothing, though going AFK and the other events still do."] = "在沒有其他事情發生的情況下(沒有表情動作或其他事件)站著不動達下方設定的時間。「無鏡頭」:站著不動不會啟動任何鏡頭,但暫離和其他事件仍會。"
L["Taking off on a flight path. With \"No camera\", the camera is left to you for the whole flight."] = "搭乘飛行路線起飛。選擇「無鏡頭」時,整段飛行的鏡頭都由你自己控制。"
L["Talking to a quest giver (a quest to pick up or hand in). Works whether or not CineMode is on."] = "與任務 NPC 對話(要接受或交付任務時)。無論 CineMode 是否開啟都有效。"
L["Camera Triggers"] = "鏡頭觸發"
L["What starts the AFK, cozy, vista and fish cameras. Pick a camera for each event; a Hearthstone or teleport cast comes first, then logging out, going AFK, the latest emote, a drawn weapon, a campfire, and standing still last. Taking a flight has the flight camera, talking to a quest giver the quest camera, and auto-walking, auto-running and dying their own."] = "什麼會啟動暫離、悠閒、遠景與釣魚鏡頭。為每個事件選擇一個鏡頭;優先順序為使用爐石或施放傳送,接著是登出、暫離、最近的表情動作、拔出武器、營火,最後是站著不動。搭乘飛行使用飛行鏡頭,與任務 NPC 對話使用任務鏡頭,自動行走、自動奔跑與死亡則各有專屬鏡頭。"
L["Event"] = "事件"
L["Camera"] = "鏡頭"
L["Music"] = "音樂"
L["Music starts as this event's camera starts, unless the addon started music within the fatigue time (Audio page). Music already playing just carries on. Off: this camera never starts music. Needs \"Allow CineMode to queue Music\" on the Audio page."] = "此事件的鏡頭啟動時開始播放音樂,除非插件在疲勞時間(音效頁面)內已經播放過音樂。正在播放的音樂會直接繼續。關閉:此鏡頭永遠不會播放音樂。需要開啟音效頁面中的「允許 CineMode 播放音樂」。"
L["With \"Start in CineMode\" off (Cinematic's main page), this event's camera starting brings CineMode on (the UI fades, music, visual effects), and it ends with the camera. Tick Stand still and Go AFK for a screensaver: the normal UI while you play, CineMode once you've been idle a while."] = "關閉「以 CineMode 啟動」(Cinematic 主頁面)時,此事件的鏡頭啟動會開啟 CineMode(介面淡出、音樂、視覺效果),並隨鏡頭結束而結束。勾選「站著不動」與「暫離」即可當作螢幕保護程式:遊玩時是一般介面,閒置一段時間後進入 CineMode。"
L[" While you're flagged AFK, whatever the camera. Off also keeps music from coming back after a pause while you're away."] = "處於暫離狀態時,無論使用哪個鏡頭。關閉時也會讓音樂在你離開期間暫停後不再恢復。"
L[" Off also keeps music from coming back after a pause while you stand still."] = "關閉時也會讓音樂在你站著不動期間暫停後不再恢復。"
L["Buff names or spell IDs, separated by commas. Names must match your game language; spell IDs work in any language."] = "增益名稱或法術 ID,以逗號分隔。名稱必須與你的遊戲語言相符;法術 ID 適用於任何語言。"
L["Buffs, separated by commas."] = "增益,以逗號分隔。"
L["Words that mark a seat when they're in an object's name (\"Wooden Chair\"), separated by commas. Use words in your game language."] = "出現在物件名稱中(例如「木椅」)就代表座位的關鍵字,以逗號分隔。請使用你遊戲語言的字詞。"
L["Seat words, separated by commas."] = "座位關鍵字,以逗號分隔。"
L["After standing still for"] = "站著不動經過"
L["How long you stand still before this row's camera starts (an event set to the AFK camera, like going AFK, skips the wait). Also used by the other options that mention standing still (tint, tracking, music, tooltips)."] = "站著不動多久後才啟動此列的鏡頭(設為暫離鏡頭的事件,例如暫離,會跳過等待)。其他提到站著不動的選項(色調、追蹤、音樂、滑鼠提示)也會使用此時間。"
L["Auto-walk (RP walk)"] = "自動行走(RP 漫步)"
L["After auto-walking for"] = "自動行走經過"
L["Auto-walking (auto-run in walk mode). The camera's settings are under RP Walk Cam on the Camera Settings page; Camera Modes turns it off in some places."] = "自動行走(行走模式下的自動奔跑)。鏡頭設定位於鏡頭設定頁面的 RP 漫步鏡頭中;鏡頭模式可在某些地方關閉它。"
L["After auto-running for"] = "自動奔跑經過"
L["Auto-running. The camera's settings are under Auto-run Cam on the Camera Settings page; Camera Modes turns it off in some places."] = "自動奔跑。鏡頭設定位於鏡頭設定頁面的自動奔跑鏡頭中;鏡頭模式可在某些地方關閉它。"
L["Die"] = "死亡"
L["Dying, until you release or are resurrected. The camera's settings are under Death Cam on the Camera Settings page; Camera Modes turns it off in some places."] = "死亡後,直到你釋放靈魂或被復活為止。鏡頭設定位於鏡頭設定頁面的死亡鏡頭中;鏡頭模式可在某些地方關閉它。"
L["A song of its own plays while the death camera runs, in place of the zone music (pick the songs under Death Cam on the Camera Settings page). With CineMode music off, only if your game music is on."] = "死亡鏡頭執行時,會播放專屬歌曲取代區域音樂(在鏡頭設定頁面的死亡鏡頭中選擇歌曲)。關閉 CineMode 音樂時,僅在遊戲音樂開啟時播放。"
L["How long you keep going before this row's camera starts (and CineMode, if its CineMode box is ticked). 0: straight away. Stopping or moving by hand first starts the count over."] = "持續多久後才啟動此列的鏡頭(若勾選了 CineMode 方塊,也會啟動 CineMode)。0:立即啟動。在此之前停下或手動移動會重新計時。"
L["An event set to the AFK camera starts it without waiting out Stand still's time."] = "設為暫離鏡頭的事件會直接啟動它,不必等待「站著不動」的時間。"
L["Strength"] = "強度"
L["%.2f sec"] = "%.2f 秒"
L["Visual Effects"] = "視覺效果"
L["How the game world looks in CineMode (or over the normal UI, with Start in CineMode off on the main page): letterbox bars, color grading, vignette, inn glow and weather. The UI isn't tinted. Names and nameplates are on the Nameplates page."] = "遊戲世界在 CineMode 中的樣貌(或在主頁面關閉「以 CineMode 啟動」時,套用在一般介面上):電影黑邊、調色、暗角、旅店光暈與天氣。介面本身不會被染色。名稱與名條位於名條頁面。"
L["Turns everything on this page on or off at once: the letterbox, tint, time of day, zone tints, vignette, inn glow, weather and depth of field. Each keeps its own settings for when you turn this back on."] = "一次開啟或關閉此頁面的所有效果:黑邊、色調、時段、區域色調、暗角、旅店光暈、天氣與景深。重新開啟時,各項會保留自己的設定。"
L["Ticked, that effect doesn't show there. Always: not at all. Combat: it goes for fights, and comes back once the Calm Timer (CineMode page) has run out after. Outside camera modes: it only shows while a camera mode runs (flights, AFK, cozy and the rest)."] = "勾選時,該效果不會在該處顯示。一律:完全不顯示。戰鬥:戰鬥時消失,戰鬥後平靜計時(CineMode 頁面)結束時恢復。鏡頭模式以外:只在鏡頭模式運作時顯示(飛行、暫離、悠閒等)。"
L["Letterbox"] = "黑邊"
L["Vignette"] = "暗角"
L["Weather"] = "天氣"
L["letterbox"] = "黑邊"
L["tint"] = "色調"
L["vignette"] = "暗角"
L["weather tint"] = "天氣色調"
L["Always"] = "一律"
L["No %s at all."] = "完全不顯示%s。"
L["No %s %s."] = "%s:%s不顯示。"
L["The %s goes for fights, and comes back once the Calm Timer (CineMode page) has run out after one."] = "%s在戰鬥時消失,戰鬥後平靜計時(CineMode 頁面)結束時恢復。"
L["Outside camera modes"] = "鏡頭模式以外"
L["The %s only shows while a camera mode runs: flights, AFK, cozy and the rest."] = "%s只在鏡頭模式運作時顯示:飛行、暫離、悠閒等。"
L["Bar height"] = "黑邊高度"
L["Black bars slide in at the top and bottom of the screen."] = "黑色橫條從螢幕上方與下方滑入。"
L["Bar opacity"] = "黑邊不透明度"
L["Current time"] = "目前時間"
L["Preview time"] = "預覽時間"
L["See how the tint looks at another time of day. Only a preview: it goes back to the real clock when you leave this page."] = "查看色調在其他時段的樣子。僅為預覽:離開此頁面後就會回到實際時間。"
L["Here: %s (%s's own preset)"] = "此處:%s(%s 的專屬預設)"
L["Here: %s (%s%s)"] = "此處:%s(%s%s)"
L[", your choice"] = ",你的選擇"
L["Previewing: %s (%02d:00)"] = "預覽中:%s(%02d:00)"
L["Now: %s (%02d:%02d your time)"] = "現在:%s(你的時間 %02d:%02d)"
L["Now: %s (%02d:%02d game time)"] = "現在:%s(遊戲時間 %02d:%02d)"
L["Custom color"] = "自訂顏色"
L["Click to choose the color used by the Custom preset."] = "點擊以選擇「自訂」預設所使用的顏色。"
L["Subtle drift"] = "細微飄移"
L["The tint's strength slowly wanders up and down over a few minutes, so a still scene feels a little more alive. Paused while this page is open."] = "色調強度會在幾分鐘內緩慢地上下飄移,讓靜止的畫面多一點生氣。此頁面開啟時暫停。"
L["Drift amount"] = "飄移幅度"
L["How far the strength wanders either way, as a share of the strength."] = "強度向上或向下飄移的幅度,以強度的比例表示。"
L["Time of day"] = "時段"
L["For the Time of day and Zone + time of day presets, and the time of day message."] = "用於「時段」與「區域 + 時段」預設,以及時段訊息。"
L["Follows"] = "依據"
L["Game time (matches the game's day and night)"] = "遊戲時間(與遊戲中的日夜一致)"
L["Your computer's clock"] = "你電腦的時鐘"
L["Time of day strength"] = "時段強度"
L["How strongly the time-of-day color applies, in Time of day and Zone + time of day. Lower it for softer nights; 0 leaves just the zone mood."] = "在「時段」與「區域 + 時段」中套用時段顏色的強度。調低可讓夜晚更柔和;設為 0 則只保留區域氛圍。"
L["Phases (click a color to change it)"] = "各時段(點擊顏色即可變更)"
L["Reset"] = "重置"
L["Back to the built-in color and strength."] = "恢復內建的顏色與強度。"
L["Choose your own color for %s."] = "為%s選擇你自己的顏色。"
L["Zone tints"] = "區域色調"
L["Give the zone you're standing in, or just the area within it (a town, a port), a preset of its own: it replaces your main preset there. With a Zone preset you can also choose its color, which replaces the built-in mood. An area's choices win over its zone's."] = "為你所在的區域,或只為其中的地點(城鎮、港口)指定專屬預設:在該處會取代你的主要預設。使用「區域」預設時還可以選擇顏色,取代內建氛圍。地點的設定優先於所屬區域的設定。"
L[", |cffffd100%s|r preset"] = ",|cffffd100%s|r 預設"
L["This zone: |cffffd100%s|r - %s%s, %d%% strength%s%s"] = "此區域:|cffffd100%s|r - %s%s,強度 %d%%%s%s"
L[" (your choice)"] = "(你的選擇)"
L[" (built in)"] = "(內建)"
L[" (its own)"] = "(專屬)"
L["This area: |cffffd100%s|r - %s%s, %d%% strength%s%s"] = "此地點:|cffffd100%s|r - %s%s,強度 %d%%%s%s"
L["Change:"] = "變更:"
L["the zone"] = "區域"
L["this area (%s)"] = "此地點(%s)"
L["this area (none here)"] = "此地點(此處沒有)"
L["Same as the zone"] = "與區域相同"
L["Main preset"] = "主要預設"
L["Preset here"] = "此處預設"
L["A preset for the zone or area chosen above, used there instead of your main preset."] = "為上方所選區域或地點指定的預設,在該處取代你的主要預設。"
L["Built-in mood"] = "內建氛圍"
L["No tint"] = "無色調"
L["Pick a color..."] = "選擇顏色……"
L["Choose your own color for the zone or area chosen above (for the Zone presets)."] = "為上方所選的區域或地點選擇你自己的顏色(用於「區域」預設)。"
L["Your zone tints"] = "你的區域色調"
L["%s preset, "] = "%s 預設,"
L[", %d%% strength"] = ",強度 %d%%"
L["None yet."] = "目前沒有。"
L["...and %d more."] = "……還有另外 %d 個。"
L["At zone borders"] = "區域交界處"
L["Fade time"] = "轉換時間"
L["With a Zone tint preset, crossing into a zone with a different mood fades the old mood out over this long, pauses, then fades the new one in over this long."] = "使用「區域」色調預設時,進入氛圍不同的區域,舊氛圍會在此時間內淡出,停頓一下,再於此時間內淡入新氛圍。"
L["Pause between tints when flying"] = "飛行時色調之間的停頓"
L["Untinted time between the two zones' moods while you're in the air, where you see the old zone's ground for longer (snow under an ember tint looks red)."] = "在空中時,兩個區域氛圍之間不套用色調的時間;因為在空中你會更久地看到舊區域的地面(餘燼色調下的雪地看起來是紅的)。"
L["Pause between tints on the ground"] = "地面上色調之間的停頓"
L["The same pause when you cross a border on foot or riding."] = "步行或騎乘越過交界時的同樣停頓。"
L["Vignette strength"] = "暗角強度"
L["Soft dark edges that draw the eye to the middle. Works with any tint."] = "柔和的暗色邊緣,把視線引向畫面中央。可搭配任何色調。"
L["Inns"] = "旅店"
L["Light up inns"] = "點亮旅店"
L["Indoors in an inn, the outdoor tint (a gloomy marsh, a moonlit night) partly lifts and a soft firelit glow fades in, colored by the zone: cooler in the snow, greener in a swamp. Blends over a few seconds as you go through the door."] = "在旅店室內,戶外色調(陰鬱的沼澤、月夜)會部分褪去,並淡入柔和的爐火光暈,顏色依區域而定:雪地偏冷,沼澤偏綠。穿過門口時會在幾秒內逐漸融合。"
L["Inn glow amount"] = "旅店光暈量"
L["How much light the glow adds at its brightest, low on the screen."] = "光暈在最亮處(螢幕下方)增加的亮度。"
L["Weather strength"] = "天氣強度"
L["Rain grays and cools the scene, snow turns it pale blue and a sandstorm gives it a dusty orange haze, more strongly the heavier the weather. Works with any tint (None included), lifts under a roof and blends in as a storm builds. Needs a game version that reports the weather."] = "下雨會讓畫面變灰變冷,下雪會染上淡藍,沙塵暴則帶來塵土般的橙色薄霧,天氣越劇烈效果越強。可搭配任何色調(包括「無」),在屋簷下會褪去,並隨風暴增強逐漸融入。需要會回報天氣的遊戲版本。"
L["Haze the screen edges in the camera modes"] = "在鏡頭模式中模糊螢幕邊緣"
L["A soft haze around the edges of the screen, as if the camera had focused on you. Each camera mode's page sets its own strength. /cine doftest shows it on demand."] = "在螢幕邊緣加上柔和的模糊,就像鏡頭對焦在你身上。各鏡頭模式的頁面可設定各自的強度。/cine doftest 可隨時顯示效果。"
L["Sound during CineMode. Your own sound settings are saved first and put back afterwards, even after a crash. Pick which cameras play music as they start."] = "CineMode 期間的音效。你自己的音效設定會先儲存,之後再還原,即使遊戲當機也一樣。選擇哪些鏡頭在啟動時播放音樂。"
L["With your game music off, a camera starting (the ones ticked under Music on the Camera Triggers page) switches it on and fades it in, at your music volume; it fades out when the UI returns and your music is switched off again (logging out too). With your game music on, it's left alone. Unticked, music is never switched on."] = "遊戲音樂關閉時,鏡頭啟動(鏡頭觸發頁面中「音樂」欄勾選的鏡頭)會以你的音樂音量開啟並淡入音樂;介面恢復顯示時音樂會淡出,並再次關閉(登出時也是)。遊戲音樂開啟時則不予處理。取消勾選時,永遠不會開啟音樂。"
L["Music fade time"] = "音樂轉換時間"
L["How long music takes to fade in or out with CineMode."] = "音樂隨 CineMode 淡入或淡出所需的時間。"
L["Fatigue"] = "疲勞"
L["Music fatigue"] = "音樂疲勞"
L["Once a camera has started music, no camera starts it again for this long, counted from when it started. The first camera after a login or /reload always can. Music coming back after a mute doesn't count. 0 turns this off."] = "某個鏡頭播放音樂後,從開始播放算起的這段時間內,不會有鏡頭再次播放音樂。登入或 /reload 後的第一個鏡頭一定可以播放。靜音後恢復的音樂不算在內。設為 0 則關閉此功能。"
L["Stop music"] = "停止音樂"
L["In combat"] = "戰鬥中"
L["Music fades out over about a second when a fight starts, and a fresh track fades back in once the Calm Timer (on the CineMode page) has passed with no new fight. Works on your own game music too; your volume is put back afterwards."] = "戰鬥開始時,音樂會在大約一秒內淡出;在平靜計時(CineMode 頁面)內沒有新的戰鬥時,會淡入一首新曲目。也適用於你自己的遊戲音樂;之後會還原你的音量。"
L["Leaving a camera mode"] = "離開鏡頭模式時"
L["Music fades out once you leave the camera modes and move on: walking off from the cozy camera, say. Going from one camera straight to another (vista to cozy) keeps it playing, as does standing still. A fresh track fades in when the next camera starts (standing still counts once the AFK camera starts, with Go AFK's music on, Camera Triggers page). Fades at the music fade time."] = "當你離開鏡頭模式並繼續前進時,音樂會淡出:例如從悠閒鏡頭中走開。從一個鏡頭直接切換到另一個(遠景到悠閒)時音樂會繼續播放,站著不動時也是。下一個鏡頭啟動時會淡入一首新曲目(站著不動在暫離鏡頭啟動時才算,需開啟鏡頭觸發頁面中「暫離」的音樂)。依音樂轉換時間淡入淡出。"
L["In cities"] = "在主城中"
L["In dungeons"] = "在地城中"
L["In raids"] = "在團隊副本中"
L["In PvP"] = "PvP 中"
L["Music fades out here (your own game music too) and back in when you leave."] = "音樂在此處會淡出(包括你自己的遊戲音樂),離開時再淡入。"
L["Tar enemy"] = "選取敵方"
L["Tar friendly"] = "選取友方"
L["More settings on the %s page. They can keep it up beyond what's ticked here (hovering, tracking, new auras, cooldowns recharging and the like)."] = "更多設定位於%s頁面。那些設定可以讓它在此處勾選的情況以外保持顯示(滑鼠指向、追蹤、新的光環、冷卻充能中等)。"
L["Show it whenever its frame shows. This overrides its Hover groups: untick it to hide it in CineMode except when hovered or brought up by the other columns."] = "只要其框架顯示就顯示。這會覆蓋它的滑鼠指向群組:取消勾選可在 CineMode 中隱藏它,除非滑鼠指向或由其他欄位讓它顯示。"
L["Show it all through CineMode, instead of hiding it. (The other columns then have nothing to add.)"] = "在 CineMode 期間全程顯示,而不隱藏。(此時其他欄位就沒有作用了。)"
L["Standard Frames"] = "標準框架"
L["Everything here is hidden in CineMode unless ticked. Tick a column to show that frame: Always shows it the whole time, the next three only while you fight or have something targeted, and the places the whole time while you're there (Grouped: in a party or raid). Frames fade in and out at the fade times on the CineMode page. Other addons' frames are on the Addon Frames page."] = "除非勾選,此處的所有項目在 CineMode 中都會隱藏。勾選某一欄即可顯示該框架:「一律」為全程顯示,接下來三欄只在你戰鬥或選取目標時顯示,地點欄則是在你身處該處時全程顯示(組隊時:在隊伍或團隊中)。框架依 CineMode 頁面的淡入淡出時間淡入淡出。其他插件的框架位於插件框架頁面。"
L["Enable Page"] = "啟用頁面"
L["On: CineMode fades the frames on this page as their rows say. Off: it leaves them all alone, the minimap, quest tracker, buffs and Cooldown Manager included (their pages' switches only count while this is on)."] = "開啟:CineMode 會依各列的設定淡出此頁面的框架。關閉:全部不予處理,包括小地圖、任務追蹤、增益與冷卻管理器(它們頁面上的開關只在此項開啟時才有作用)。"
L["In combat rows stay for the Calm Timer"] = "「戰鬥中」各列在平靜計時內保持顯示"
L["Frames ticked In combat (here and on the Addon Frames page) stay up after a fight until the Calm Timer (CineMode page) has run out, then fade. Off: they fade as soon as the fight ends."] = "勾選「戰鬥中」的框架(此處及插件框架頁面)會在戰鬥後保持顯示,直到平靜計時(CineMode 頁面)結束後才淡出。關閉:戰鬥一結束就淡出。"
L["Cast fade into combat"] = "施法漸入戰鬥"
L["Out of combat, casting a spell at an enemy brings up the frames ticked In combat, as if the fight had started: they fade in over the cast and are fully up as it lands. Instant spells bring them up at the Combat fade in time."] = "在戰鬥外對敵人施法時，勾選「戰鬥中」的框架會像戰鬥已經開始一樣出現：它們在施法過程中漸顯，法術命中時完全顯示。瞬發法術以戰鬥漸顯時間顯示它們。"
L["Unit frames"] = "單位框架"
L["Unit Frames"] = "單位框架"
L["Interface"] = "介面"
L["Party frames (not raid-style)"] = "隊伍框架(非團隊樣式)"
L["Battlegrounds"] = "戰場"
L["Other"] = "其他"
L["Fishing"] = "釣魚"
L["Casting and catching, with the mouse or a gamepad, CineMode or not."] = "使用滑鼠或控制器拋竿與收竿,無論是否處於 CineMode。"
L["On: right-click (or a gamepad button) casts again, and the Fishing cast bar hides, as this page says. Off: fishing is left to the game. (The fish camera is on the Camera Modes and Camera Triggers pages.)"] = "開啟:依此頁面的設定,右鍵(或控制器按鈕)可再次拋竿,並隱藏釣魚施法條。關閉:釣魚交由遊戲處理。(釣魚鏡頭位於鏡頭模式與鏡頭觸發頁面。)"
L["Casting"] = "拋竿"
L["Hide the Fishing cast bar"] = "隱藏釣魚施法條"
L["Your cast bar stays hidden while it shows Fishing. Every other spell shows it as usual."] = "施法條顯示釣魚時保持隱藏。其他法術則照常顯示。"
L["Right-click to cast again"] = "右鍵再次拋竿"
L["While the fish camera is on and no bobber is out, right-clicking in the world casts Fishing again. Each cast still comes from your own click. While the bobber is out, right-click clicks it as usual; in combat, with the loot window open or with your mouse on a player or NPC, right-click is left alone. (Meanwhile right-drag doesn't turn the camera: left-drag still does.)"] = "釣魚鏡頭開啟且沒有浮標時,在世界中按右鍵會再次施放釣魚。每次拋竿仍然來自你自己的點擊。浮標在水上時,右鍵照常點擊浮標;在戰鬥中、拾取視窗開啟時,或滑鼠指向玩家或 NPC 時,右鍵不受影響。(在此期間,右鍵拖曳不會轉動鏡頭:左鍵拖曳仍然可以。)"
L["Also the first cast, with a pole equipped"] = "裝備魚竿時,第一次拋竿也適用"
L["With a fishing pole in your main hand, standing still, right-clicking in the world casts Fishing, so you don't have to start the first cast yourself. Not while your mouse is on a player, NPC or object (mailbox, corpse...): right-click works on them as usual. Swap the pole out to have right-click back everywhere."] = "主手裝備魚竿並站著不動時,在世界中按右鍵會施放釣魚,所以你不必自己進行第一次拋竿。滑鼠指向玩家、NPC 或物件(郵箱、屍體……)時除外:右鍵對它們照常運作。換下魚竿即可讓右鍵在各處恢復正常。"
L["Wait after a cast ends"] = "拋竿結束後的等待"
L["How long after a cast ends (a catch looted, or the bobber gone) before right-click casts again, so the click that loots the fish doesn't cast straight away."] = "拋竿結束(拾取漁獲或浮標消失)後,要等多久右鍵才會再次拋竿,這樣拾取魚的那一下點擊就不會立刻拋竿。"
L["Pause after a missed cast"] = "拋竿失敗後的暫停"
L["When a cast doesn't land in fishable water (say, a pole left equipped away from water), right-click goes back to normal for this long before it casts again. Moving and then standing still for 1 sec ends it early: you're likely at a new spot to fish from. Off doesn't pause. (\"Skill not high enough\" always pauses it for 30 sec, moving or not.)"] = "拋竿沒有落在可釣魚的水域時(例如在遠離水邊的地方仍裝備著魚竿),右鍵會在這段時間內恢復正常,之後才會再次拋竿。移動後站著不動 1 秒會提前結束:你很可能到了新的釣點。關閉則不暫停。(「技能等級不夠」一律暫停 30 秒,無論是否移動。)"
L["Gamepad: a button casts too"] = "控制器:按鈕也能拋竿"
L["In gamepad mode, the button below casts Fishing whenever right-click would: in the fish camera with no bobber out, and (if ticked above) with a pole equipped, standing still. The rest of the time it does what it usually does. Each cast still comes from your own press."] = "在控制器模式中,只要右鍵會拋竿的時候,下方的按鈕也會施放釣魚:在釣魚鏡頭中且沒有浮標時,以及(若上方已勾選)裝備魚竿並站著不動時。其他時候則照常運作。每次拋竿仍然來自你自己的按壓。"
L["Left face button (Xbox X)"] = "左方主按鈕(Xbox X)"
L["Top face button (Xbox Y)"] = "上方主按鈕(Xbox Y)"
L["Bottom face button (Xbox A)"] = "下方主按鈕(Xbox A)"
L["Right face button (Xbox B)"] = "右方主按鈕(Xbox B)"
L["The gamepad button that casts Fishing."] = "用來施放釣魚的控制器按鈕。"
L["Gamepad"] = "控制器"
L["The frames gamepad mode adds (Options, Controls, Gamepad): its action bars, the button hints and the reticle (the dot you aim with). As on the Game Frames page, each is hidden in CineMode unless ticked: Always shows it the whole time, the next three only while you fight or have something targeted, and the places while you're there. Rows also on the Game Frames page (the experience bars) follow this page in gamepad mode, and that one otherwise."] = "控制器模式新增的框架(選項、控制、控制器):其快捷列、按鈕提示與準心(用來瞄準的圓點)。與遊戲框架頁面相同,除非勾選,每一項在 CineMode 中都會隱藏:「一律」為全程顯示,接下來三欄只在你戰鬥或選取目標時顯示,地點欄則是在你身處該處時顯示。同時出現在遊戲框架頁面的列(經驗值條),在控制器模式中依此頁面設定,其他時候則依遊戲框架頁面設定。"
L["On: CineMode fades the gamepad's bars, button hints and reticle as this page says. Off: it leaves them alone."] = "開啟:CineMode 會依此頁面的設定淡出控制器的快捷列、按鈕提示與準心。關閉:不予處理。"
L["Show the interact prompt (X)"] = "顯示互動提示(X)"
L["The button prompt over things you can use or talk to (your bobber, an NPC) stays up in CineMode while the nameplates fade, so you can see what the gamepad can reach: a bobber showing it can be caught. Unticked, it fades with them."] = "在可使用或可對話的對象(你的浮標、NPC)上方的按鈕提示,在 CineMode 中名條淡出時仍保持顯示,讓你知道控制器能互動的對象:浮標顯示提示時就可以收竿。取消勾選時,它會隨名條一起淡出。"
L["Show the action bars when you press a button"] = "按下按鈕時顯示快捷列"
L["Gamepad mode's mouseover: pressing any gamepad button brings the action bars up, and they fade out again your \"stays after mouseover\" time later (Hover groups page). Each press starts that time again. Choose the buttons in the list below. Presses that make you jump don't count (whichever button jumps), nor presses while you fish (the fish camera on, a cast going, or looting)."] = "控制器模式的「滑鼠指向」:按下任何控制器按鈕都會顯示快捷列,並在你的「滑鼠指向後停留」時間(滑鼠指向群組頁面)後再次淡出。每次按壓都會重新計時。在下方清單中選擇按鈕。讓你跳躍的按壓不算(無論哪個按鈕是跳躍),釣魚時的按壓也不算(釣魚鏡頭開啟、正在拋竿或拾取中)。"
L["Buttons that show them"] = "會讓它們顯示的按鈕"
L["Click to show or hide the list of buttons: untick one and pressing it doesn't bring the action bars up."] = "點擊以顯示或隱藏按鈕清單:取消勾選某個按鈕後,按下它就不會顯示快捷列。"
L["Action bar fading"] = "快捷列淡出"
L["Stay after a press"] = "按壓後停留"
L["How long the action bars stay after your last button press, counting their fade out."] = "最後一次按下按鈕後,快捷列停留的時間(包含淡出時間)。"
L["How long the gamepad action bars take to fade in: for button presses, fights and targets alike. The rest of the UI uses the fade times on the CineMode page."] = "控制器快捷列淡入所需的時間:按壓按鈕、戰鬥與選取目標時都適用。介面其他部分使用 CineMode 頁面的淡入淡出時間。"
L["How long the gamepad action bars take to fade out."] = "控制器快捷列淡出所需的時間。"
L["Nameplates"] = "名條"
L["Friendly nameplates"] = "友方名條"
L["Enemy nameplates"] = "敵方名條"
L["Which nameplates and names stay up in CineMode: in groups, in fights and in each kind of place."] = "哪些名條與名稱在 CineMode 中保持顯示:組隊時、戰鬥中,以及各類地點。"
L["On: CineMode fades nameplates and names as this page says. Off: it leaves them alone, and the game's own options decide, in CineMode and out."] = "開啟:CineMode 會依此頁面的設定淡出名條與名稱。關閉:不予處理,無論是否處於 CineMode,都由遊戲本身的選項決定。"
L["Show in fights, and for the Calm Timer after."] = "在戰鬥中及戰鬥後的平靜計時內顯示。"
L["Show in fights while you're PvP flagged, and for the Calm Timer after."] = "在開啟 PvP 狀態時的戰鬥中及戰鬥後的平靜計時內顯示。"
L["Always show while you're in a party or raid."] = "身處隊伍或團隊時一律顯示。"
L["Blizzard's Always Show Nameplates is off, so nameplates only show in combat."] = "Blizzard 的「總是顯示名條」已關閉,所以名條只會在戰鬥中顯示。"
L["Target Nameplate"] = "目標名條"
L["Enemy Player"] = "敵方玩家"
L["Enemy NPC"] = "敵方 NPC"
L["Neutral Player"] = "中立玩家"
L["Neutral NPC"] = "中立 NPC"
L["Friendly Player"] = "友方玩家"
L["Friendly NPC"] = "友方 NPC"
L["Your pet"] = "你的寵物"
L["Group members"] = "隊伍成員"
L[" Your target's nameplate while it's a player you can attack, whatever the Nameplates grid says."] = " 目標為你可攻擊的玩家時顯示目標的名條，無論名條表格如何設定。"
L[" Your target's nameplate while it's a hostile NPC, whatever the Nameplates grid says."] = " 目標為敵對 NPC 時顯示目標的名條，無論名條表格如何設定。"
L[" Your target's nameplate while it's the other faction's player but you can't attack them, whatever the Nameplates grid says."] = " 目標為你無法攻擊的另一陣營玩家時顯示目標的名條，無論名條表格如何設定。"
L[" Your target's nameplate while it's a neutral NPC, whatever the Nameplates grid says."] = " 目標為中立 NPC 時顯示目標的名條，無論名條表格如何設定。"
L[" Your target's nameplate while it's a friendly or dead player, whatever the Nameplates grid says."] = " 目標為友方或已死亡的玩家時顯示目標的名條，無論名條表格如何設定。"
L[" Your target's nameplate while it's a friendly or dead NPC, whatever the Nameplates grid says."] = " 目標為友方或已死亡的 NPC 時顯示目標的名條，無論名條表格如何設定。"
L[" Your pet's nameplate, whatever the Minions rows say, grouped or not."] = " 你寵物的名條,無論僕從列如何設定,是否在隊伍中都一樣。"
L[" Your party or raid members' nameplates, whatever Friendly players says. Not in dungeons and raids: there, Friendly plates in dungeons and raids decides."] = " 你的隊伍或團隊成員的名條，不受「友方玩家」影響。地城與團隊副本中除外：那裡由「地城與團隊副本中的友方名條」決定。"
L["Friendly plates in dungeons and raids"] = "地城與團隊副本中的友方名條"
L["In dungeons and raids the game won't let addons fade friendly nameplates, so each kind below is either all on or all off there, in CineMode. The grids' friendly rows (your target's included) have no Instances box: these take its place.\n\nWith a friendly target: on while you have one of that kind targeted, out of fights. Every plate of that kind shows then, not just your target's.\n\nThe game won't switch nameplates on or off during a fight: they stay as the fight found them.\n\nFriendly players' setting covers their pets too, so with pets shown, friendly players' plates show as well."] = "在地城與團隊副本中，遊戲不允許插件淡化友方名條，因此在 CineMode 中，下面每一類在那裡只能全部顯示或全部隱藏。表格中的友方列（包括你目標的列）沒有「副本」勾選框：由這裡代替。\n\n有友方目標時：在戰鬥外，當你選取該類目標時顯示。此時該類的所有名條都會顯示，而不只是你目標的。\n\n戰鬥中遊戲不會開關名條：它們維持戰鬥開始時的狀態。\n\n友方玩家的設定也涵蓋他們的寵物，因此顯示寵物時，友方玩家的名條也會顯示。"
L["Pets and minions"] = "寵物與僕從"
L["Hidden"] = "隱藏"
L["Shown"] = "顯示"
L["With a friendly target"] = "有友方目標時"
L[" Your party or raid members' pets, whatever the Minions rows say."] = " 你的隊伍或團隊成員的寵物,無論僕從列如何設定。"
L["Show while PvP flagged, outside battlegrounds and arenas."] = "在戰場與競技場以外開啟 PvP 狀態時顯示。"
L["Show in battlegrounds and arenas."] = "在戰場與競技場中顯示。"
L["Show everywhere else, cities and inns included."] = "在其他所有地方顯示,包括主城與旅店。"
L["Show everywhere, in fights and out. The rest of the row keeps its ticks for when you untick this."] = "在任何地方顯示,戰鬥中和戰鬥外皆是。取消勾選此項時,該行其餘的勾選仍會保留。"
L["Show in dungeons, scenarios and raids."] = "在地城、事件與團隊副本中顯示。"
L["In PvP combat"] = "PvP 戰鬥中"
L["Hostile NPCs"] = "敵對 NPC"
L["Neutral NPCs"] = "中立 NPC"
L["Minor"] = "次要"
L["Friendly NPCs"] = "友方 NPC"
L[" Also turns these nameplates on in the game's options."] = "也會在遊戲選項中開啟這些名條。"
L[" Ticking any box turns these names on in the game's options. Ticking none turns them off."] = "勾選任一方塊都會在遊戲選項中開啟這些名稱。全部不勾選則關閉。"
L[" Beyond nameplate range (the game's nameplateMaxDistance setting: 60 yards on retail) the game draws raid markers over units itself, as it does over your own head, and addons can't hide them."] = "超出名條距離(遊戲的 nameplateMaxDistance 設定:正式服為60碼)時,遊戲會自己在單位頭上繪製團隊標記,就像在你自己頭上一樣,插件無法隱藏。"
L[" Ticked, raid markers (skull, moon...) stay over their units in CineMode as the rest of their nameplates fades, or shows just their names, so your group can still see what's marked. Unticked, they fade with the plates (the Plate parts row decides them on the plates that are up)."] = "勾選後,在 CineMode 中,當名條的其餘部分淡出或只顯示名稱時,團隊標記(骷髏、月亮……)仍留在單位頭上,讓你的隊伍仍能看到標記了什麼。不勾選則隨名條一起淡出(在顯示的名條上由名條部件中的那一列決定)。"
L[" In CineMode, away from dungeons and raids, the name shows on the unit's nameplate instead, with the rest of the plate hidden."] = "在 CineMode 中,地城與團隊副本之外,名稱改為顯示在單位的名條上,名條的其餘部分隱藏。"
L[" The game only allows this to be set as the fight starts."] = "遊戲只允許在戰鬥開始時設定此項。"
L["The chat window fades with the rest of the UI in CineMode. Mousing over it or typing always shows it."] = "在 CineMode 中,聊天視窗會隨介面其他部分一起淡出。滑鼠指向或輸入文字時一律會顯示。"
L["On: CineMode fades the chat windows and tabs as this page says. Off: it leaves them alone."] = "開啟:CineMode 會依此頁面的設定淡出聊天視窗與分頁。關閉:不予處理。"
L["Chat window"] = "聊天視窗"
L["Show chat when a message arrives"] = "收到訊息時顯示聊天"
L["While the UI is faded, a new message briefly shows just the chat window it arrived in, with its tabs. Choose which messages below."] = "介面淡出時,新訊息只會短暫顯示它所在的聊天視窗及其分頁。在下方選擇哪些訊息。"
L["Show chat for"] = "聊天顯示時間"
L["How long chat stays up after a message arrives or after you finish typing."] = "收到訊息或結束輸入後,聊天保持顯示的時間。"
L["Keep chat up until whispers are read"] = "保持顯示聊天直到密語已讀"
L["When a whisper arrives in its own tab, the whole chat window stays up in CineMode while that tab flashes, until you click it. Whispers that land in the tab you're looking at don't flash, so they just show as above."] = "密語出現在專屬分頁時,只要該分頁在閃爍,整個聊天視窗就會在 CineMode 中保持顯示,直到你點擊它為止。出現在你正在查看的分頁中的密語不會閃爍,所以只會依上述方式顯示。"
L["Hide your messages"] = "隱藏你的訊息"
L["Your own messages don't show chat: your emotes (a /bow, or sitting or kneeling at the campfire), and what you say in /say, party, guild and so on. Other people's still do."] = "你自己的訊息不會顯示聊天：你的表情（/bow，或在營火旁坐下或跪下），以及你在 /say、隊伍、公會等頻道說的話。其他人的訊息仍會顯示。"
L["Hide speech you can see as a bubble"] = "隱藏能在泡泡中看到的話"
L["Says and yells (people's and NPCs') don't show chat when their chat bubble shows on your screen: you can read it there. Ones from out of view, or where bubbles are off, still do."] = "說話和大喊（玩家和NPC）的泡泡出現在你的螢幕上時不會顯示聊天：你可以在那裡看到。視野外的，或泡泡已關閉時，仍會顯示。"
L["%s is under attack!"] = "%s正遭受攻擊！"
L["Show chat for these messages"] = "收到這些訊息時顯示聊天"
L["Game messages"] = "遊戲訊息"
L["Capital cities. "] = "主城。"
L["Show chat for these channels"] = "這些頻道有訊息時顯示聊天"
L["Channels you've joined, like General or Trade. The list updates each time you open this page."] = "你已加入的頻道,例如綜合或交易。每次開啟此頁面時清單都會更新。"
L["No channels joined."] = "尚未加入任何頻道。"
L["Takes this frame off the list. A frame you added stops fading; one you kept up fades again if it's one the addon fades by itself."] = "將此框架從清單中移除。你加入的框架會停止淡出;你保持顯示的框架,若是插件本身就會淡出的框架,則會再次淡出。"
L["Show this frame the whole time in CineMode (Cinematic leaves it alone). Unticked, it's hidden, except as the other columns say."] = "在 CineMode 中全程顯示此框架(Cinematic 不予處理)。取消勾選時則隱藏,除非其他欄位另有設定。"
L["picked"] = "已選取"
L["When the minimap (and on retail the quest waypoint) stays up in CineMode. Hovering the minimap always shows it. To keep it up all the time, or in fights, see the Game Frames page."] = "小地圖(以及正式版中的任務路徑點)何時在 CineMode 中保持顯示。滑鼠指向小地圖時一律會顯示。若要全程或在戰鬥中保持顯示,請參閱遊戲框架頁面。"
L["On: CineMode fades and shrinks the minimap as this page and its Game Frames row say. Off: it leaves it alone."] = "開啟:CineMode 會依此頁面及遊戲框架中對應列的設定淡出並縮小小地圖。關閉:不予處理。"
L["Always show the quest waypoint"] = "一律顯示任務路徑點"
L["Keeps the marker showing where your tracked quest or map pin is, with its distance, visible in CineMode. Off, it fades with the rest of the UI."] = "在 CineMode 中保持顯示標示你追蹤中任務或地圖標記位置及距離的標記。關閉時,它會隨介面其他部分一起淡出。"
L["Keep minimap open while tracking"] = "追蹤時保持顯示小地圖"
L["While you're tracking one of the kinds ticked below, the minimap stays up during CineMode. Also on the minimap button's menu."] = "當你在追蹤下方勾選的任一類型時,小地圖會在 CineMode 期間保持顯示。小地圖按鈕的選單中也有此選項。"
L["Reveal when a group member pings it"] = "隊友點擊標記時顯示"
L["You or someone in your party or raid pinging the minimap shows it as if you'd hovered it, so you can see where, with the rest of the Hover groups that have Minimap ping ticked, for as long as the slider under it says. Ore, herbs and treasure pinged by Ping where it is don't count."] = "你或隊伍或團隊中有人在小地圖上點擊標記時,小地圖會像你用滑鼠指向一樣顯示,讓你看到標記位置,並一同顯示勾選了「小地圖點擊標記」的其他滑鼠指向群組,持續時間由下方的滑桿決定。「在位置發信號」標記的礦石、草藥和寶藏不算。"
L["Show for"] = "顯示時間"
L["How long the minimap stays up after someone pings it, before it fades."] = "有人在小地圖上點擊標記後,小地圖在淡出前保持顯示的時間。"
L["Keep minimap open indoors"] = "在室內保持顯示小地圖"
L["Inside buildings, caves and cities like Ironforge, the minimap stays up during CineMode. The game stops updating the indoor map while the minimap is hidden, so after walking around it can come back blank or out of date for a moment. Off, it's redrawn as it comes back."] = "在建築物、洞穴及鐵爐堡之類的城市內,小地圖會在 CineMode 期間保持顯示。小地圖隱藏時遊戲會停止更新室內地圖,所以四處走動後,它恢復顯示時可能會短暫空白或過時。關閉時,它會在恢復顯示時重新繪製。"
L["While this tracking is active, the minimap stays up during cinematic mode so you can spot nodes or creatures."] = "此追蹤啟用時,小地圖會在電影模式期間保持顯示,讓你找到採集點或生物。"
L["Herbs (Find Herbs)"] = "草藥(尋找草藥)"
L["Minerals (Find Minerals)"] = "礦物(尋找礦物)"
L["Reveal"] = "顯示"
L["Pings"] = "信號"
L["Keep open"] = "保持開啟"
L["Nearby ore, herbs and treasure"] = "附近的礦石、草藥和寶藏"
L["Ping where it is"] = "在位置發信號"
L["When a vein, herb or chest shows up on the minimap, it's pinged there, the same ping as clicking the minimap: in a group, everyone sees it."] = "礦脈、草藥或箱子出現在小地圖上時，會在那裡發出信號，和點擊小地圖一樣：在隊伍中所有人都能看到。"
L["Quest turn-ins"] = "交任務"
L["Other icons"] = "其他圖示"
L["Tracking creatures or fish"] = "追蹤生物或魚"
L["Tracking herbs, minerals or treasure"] = "追蹤草藥、礦物或寶藏"
L["Cinematic looks every second or two by pointing at the minimap the way your mouse would (not in combat), and the minimap fades again a few seconds after it's gone. While any of these is ticked, the faded minimap stays in its place, invisible, instead of being shrunk away."] = "Cinematic 每一兩秒像滑鼠一樣指向小地圖查看（戰鬥中不會），消失幾秒後小地圖會再次淡出。只要勾選了其中任一項，淡出的小地圖會留在原位隱形，而不是被縮小。"
L["With Find Minerals, Find Herbs or Find Treasure on, the minimap comes up while a vein, herb or chest shows on it."] = "開啟尋找礦物、尋找草藥或尋找寶藏時，小地圖上出現礦脈、草藥或箱子時會顯示小地圖。"
L["The minimap comes up while a quest of yours that's done shows on it, where you hand it in."] = "小地圖上出現你已完成任務的交付地點時會顯示小地圖。"
L["Quest areas"] = "任務區域"
L["The minimap comes up while the area of a quest of yours that isn't done shows on it, the shaded part where its objectives are."] = "小地圖上出現你未完成任務的區域（任務目標所在的陰影部分）時會顯示小地圖。"
L["The minimap comes up while anything else with a name shows on it: quest givers with a quest for you, flight masters and innkeepers you track and the like. Your group and pets don't count."] = "小地圖上出現其他有名字的東西時會顯示小地圖：有任務給你的NPC、你追蹤的飛行管理員和旅店老闆等。隊伍和寵物不算。"
L["While hunter, druid or warlock creature tracking, or Find Fish, is on, the minimap stays up during CineMode."] = "開啟獵人、德魯伊或術士的生物追蹤或尋找魚類時，小地圖在 CineMode 中保持顯示。"
L["While Find Herbs, Find Minerals or Find Treasure is on, the minimap stays up during CineMode, except in the places below."] = "開啟尋找草藥、尋找礦物或尋找寶藏時，小地圖在 CineMode 中保持顯示，下面的地點除外。"
L["Treasure (Find Treasure)"] = "寶藏(尋找寶藏)"
L["Fish (Find Fish)"] = "魚群(尋找魚群)"
L["Creatures (hunter, druid, warlock)"] = "生物(獵人、德魯伊、術士)"
L["Except in"] = "以下地點除外"
L["Battlegrounds and arenas (being flagged for PvP out in the world doesn't count). Alterac Valley's mines do have ore, so untick this if you mine there. "] = "戰場與競技場(在野外開啟 PvP 狀態不算)。奧特蘭克山谷的礦坑確實有礦脈,如果你會在那裡採礦,請取消勾選此項。"
L["BGs"] = "戰場"
L["Tracking doesn't keep the minimap up here. Hovering it still shows it."] = "在此處,追蹤不會讓小地圖保持顯示。滑鼠指向時仍會顯示。"
L["Hide in camera modes"] = "在鏡頭模式中隱藏"
L["When the quest tracker comes up in CineMode. Hovering it always shows it. To keep it up all the time, or in fights, see the Game Frames page."] = "任務追蹤何時在 CineMode 中顯示。滑鼠指向時一律會顯示。若要全程或在戰鬥中保持顯示,請參閱遊戲框架頁面。"
L["Reveal on new quest"] = "接受新任務時顯示"
L["Accepting a quest shows the quest tracker as if you'd hovered it (with the rest of the Hover groups that have Quest progress ticked): it goes after \"Stays after mouseover\" (Hover groups page)."] = "接受任務時,任務追蹤會像你用滑鼠指向一樣顯示(並一同顯示勾選了「任務進度」的其他滑鼠指向群組):經過「滑鼠指向後停留」(滑鼠指向群組頁面)的時間後消失。"
L["On: CineMode fades the quest tracker (and the quest timer and waypoint) as this page and its Game Frames row say. Off: it leaves them alone."] = "開啟:CineMode 會依此頁面及遊戲框架中對應列的設定淡出任務追蹤(以及任務計時器與路徑點)。關閉:不予處理。"
L["Reveal on receiving quest objective"] = "任務目標有進展時顯示"
L["Keep up for the Calm Timer"] = "在平靜計時內保持顯示"
L["The quest tracker stays up for the Calm Timer (CineMode page) instead of the mouseover time, if that's longer."] = "任務追蹤會在平靜計時(CineMode 頁面)內保持顯示,而不是滑鼠懸停時間(取較長者)。"
L["Progress on a quest's objectives (a kill or item counted towards it) shows the quest tracker the same way."] = "任務目標有進展時(擊殺或取得計入任務的物品),任務追蹤也會以相同方式顯示。"
L["Show just that quest"] = "只顯示該任務"
L["When accepting a quest or progress on one brings the quest tracker up, just that quest shows (and any others accepted or moved on while it's up); the rest of the tracker, headers and all, stays faded. Scenario progress shows just the scenario. Hovering it shows it all."] = "接受任務或任務有進展而顯示任務追蹤器時，只顯示該任務（以及顯示期間接受或有進展的其他任務）；追蹤器的其餘部分（包括標題）保持隱藏。場景有進展時只顯示該場景。滑鼠懸停時顯示全部。"
L["Stay up for the Calm Timer after a fight"] = "戰鬥後在平靜計時內保持顯示"
L["With the quest tracker ticked In combat (Game Frames page), it stays up after a fight until the Calm Timer (CineMode page) has run out, then fades. Off: it fades as soon as the fight ends."] = "任務追蹤勾選「戰鬥中」(遊戲框架頁面)時,會在戰鬥後保持顯示,直到平靜計時(CineMode 頁面)結束後才淡出。關閉:戰鬥一結束就淡出。"
L["Show the quest timer while one is running"] = "有任務計時進行中時顯示任務計時器"
L["Keeps the quest timer box up in CineMode, and in fights, while a timed quest counts down. Just the timer: the quest tracker stays faded."] = "限時任務倒數期間,在 CineMode 及戰鬥中保持顯示任務計時器框。只有計時器:任務追蹤仍維持淡出。"
L["Which of the game's swing timer bars show, in CineMode and out. When they come up in CineMode is the Swing timer row on the Game Frames page."] = "遊戲的揮擊計時條中哪些會顯示,無論是否處於 CineMode。它們在 CineMode 中何時顯示,由遊戲框架頁面的「揮擊計時器」列決定。"
L["On: CineMode fades the swing timer as this page and its Game Frames row say. Off: it leaves it alone, and the game shows every bar as usual, in CineMode and out."] = "開啟:CineMode 會依此頁面及遊戲框架中對應列的設定淡出揮擊計時器。關閉:不予處理,無論是否處於 CineMode,遊戲都會照常顯示所有計時條。"
L["Only show the weapons you're using"] = "只顯示你正在使用的武器"
L["The main hand (and off-hand) bars show while you auto-attack, the ranged bar while you shoot. A hunter's main hand bar comes up when they melee, a warrior's ranged bar when they shoot, and each fades out a while after (the slider below)."] = "自動攻擊時顯示主手(及副手)計時條,射擊時顯示遠程計時條。獵人近戰時會顯示主手計時條,戰士射擊時會顯示遠程計時條,而且各自會在一段時間後淡出(下方的滑桿)。"
L["Fade out after the bar is done for"] = "計時條結束後淡出時間"
L["Once you stop swinging or shooting and the bar has run down to 0, it stays this long before fading out."] = "當你停止揮擊或射擊且計時條歸 0 後,會停留這麼久才淡出。"
L["Hide the off-hand bar"] = "隱藏副手計時條"
L["Never show the off-hand swing timer, dual wielding or not."] = "無論是否雙持武器,都不顯示副手揮擊計時器。"
L["Ranged bar on top for %s"] = "%s的遠程計時條置頂"
L["The main hand and ranged bars trade places, so the ranged bar is where the main hand's was. Set for each class on its own (ticked for hunters, mages, priests and warlocks to start with), so one profile suits all your characters."] = "主手與遠程計時條交換位置,讓遠程計時條位於原本主手計時條的位置。每個職業分別設定(獵人、法師、牧師與術士預設為勾選),讓同一個設定檔適用於你所有的角色。"
L["When the Cooldown Manager comes up in CineMode (Enhanced Cooldown Manager's bars too). Hovering it always shows it. To keep it up all the time, or in fights, see the Game Frames page; what comes up with it is on the Hover groups page."] = "冷卻管理器(以及 Enhanced Cooldown Manager 的計時條)何時在 CineMode 中顯示。滑鼠指向時一律會顯示。若要全程或在戰鬥中保持顯示,請參閱遊戲框架頁面;與它一起顯示的項目位於滑鼠指向群組頁面。"
L["On: CineMode fades the Cooldown Manager as this page and its Game Frames row say. Off: it leaves it alone, and the game's own options decide, in CineMode and out."] = "開啟:CineMode 會依此頁面及遊戲框架中對應列的設定淡出冷卻管理器。關閉:不予處理,無論是否處於 CineMode,都由遊戲本身的選項決定。"
L["Stay up while a cooldown is recharging"] = "冷卻充能中時保持顯示"
L["Keeps the Cooldown Manager up until every cooldown in it is ready again, then it fades. Not the global cooldown, nor its buff bars. (It brings up the Hover groups with Cooldown recharging ticked: the Cooldowns group by default.)"] = "保持顯示冷卻管理器,直到其中所有冷卻都再次就緒才淡出。不含公共冷卻,也不含其增益條。(會一同顯示勾選了「冷卻充能中」的滑鼠指向群組:預設為「冷卻」群組。)"
L["Only within the Calm Timer after a fight (CineMode page): after that it fades even with a long cooldown still going, and cooldowns used out of fights don't bring it up."] = "僅限戰鬥後的平靜計時內(CineMode 頁面):之後即使仍有長冷卻在進行也會淡出,非戰鬥中使用的冷卻也不會讓它顯示。"
L["Only when ready in combat"] = "僅在戰鬥中就緒時"
L["Tick a spell to show its icon only in fights, and only once it's nearly ready: out of fights, and while it recharges, it fades out, in CineMode or not. It comes back once it's ready, or with Show early ticked the seconds set beside it before (left empty: %d%% of its cooldown). Its place in the bar stays, so it sits best at the end of one. In fights the game may not say how long is left, so then it goes by when you last cast it."] = "勾選法術後,其圖示只在戰鬥中、且快要就緒時才顯示:非戰鬥中及充能期間,無論是否處於 CineMode,都會淡出。就緒時恢復顯示;若勾選「提前顯示」,則在就緒前旁邊設定的秒數恢復顯示(留空:冷卻時間的 %d%%)。它在計時條中的位置會保留,所以最好放在一列的末端。戰鬥中遊戲可能不會告知剩餘時間,此時會依你上次施放的時間推算。"
L["Spell"] = "法術"
L["Show early"] = "提前顯示"
L["No spells in the Cooldown Manager's spell bars right now."] = "冷卻管理器的法術列目前沒有任何法術。"
L["Out of fights, and while it recharges, this spell's icon fades out of the Cooldown Manager."] = "非戰鬥中及充能期間,此法術的圖示會從冷卻管理器中淡出。"
L["Bring the icon back a little before it's ready, by the seconds beside it. Unticked, it comes back once it's ready."] = "在就緒前稍早(旁邊設定的秒數)恢復顯示圖示。取消勾選時,就緒後才恢復顯示。"
L["How many seconds before it's ready the icon comes back. Leave it empty for %d%% of its cooldown."] = "在就緒前幾秒恢復顯示圖示。留空則為冷卻時間的 %d%%。"
L["sec (empty: %d)"] = "秒(留空:%d)"
L["sec (empty: %d%%)"] = "秒(留空:%d%%)"
L["Spell %d"] = "法術 %d"
L[" |cff808080(not in it now)|r"] = " |cff808080(目前不在其中)|r"
L["On: CineMode hides tooltips as this page says. Off: every tooltip shows as normal."] = "開啟:CineMode 會依此頁面的設定隱藏滑鼠提示。關閉:所有滑鼠提示照常顯示。"
L["Only in CineMode. Hold your Show hidden tooltips key (set it on the Keybinds page) to see a hidden one anyway."] = "只在 CineMode 中。按住你的「顯示隱藏的滑鼠提示」鍵(在按鍵綁定頁面設定)就能照樣查看隱藏的提示。"
L["Players and NPCs you can attack (neutral mobs too), and their pets, minions and totems."] = "你可以攻擊的玩家和 NPC(包括中立怪物),以及他們的寵物、僕從和圖騰。"
L["Herbs, ore and creatures you can skin."] = "草藥、礦石和可剝皮的生物。"
L["Tooltips listing one of your quest objectives (like \"5/7 Thistle Boar slain\")."] = "列出你某個任務目標的滑鼠提示(例如 \"已殺死薊皮野豬 5/7\")。"
L["Mouse still"] = "滑鼠靜止"
L["Hide tooltips"] = "隱藏滑鼠提示"
L["In CineMode. Ticked, those tooltips hide. Always: in and out of fights. In combat: just in fights. Something that's more than one kind (a quest mob is an enemy too) hides only with each of its kinds ticked."] = "在CineMode中。勾選後，這些滑鼠提示會隱藏。總是：戰鬥內外都隱藏。戰鬥中：僅在戰鬥時。同時屬於多種類型的(任務怪也是敵人),只有其所有類型都勾選時才隱藏。"
L["Hidden all the time."] = "一直隱藏。"
L["Hidden in fights only."] = "僅在戰鬥時隱藏。"
L["Objects in the world, and the UI's tooltips: action bars, buffs and debuffs, bags, menus and the rest."] = "世界中的物件,以及介面的滑鼠提示:快捷列、增益和減益效果、背包、選單等。"
L["Every tooltip in the world and on unit frames is hidden while this camera mode is running."] = "此鏡頭模式運作時,隱藏世界中和單位框架上的所有滑鼠提示。"
L["Tooltip look"] = "滑鼠提示外觀"
L["Ticked, that part of the tooltip shows: On first hover, as soon as it appears; After, once you've hovered as long as set above, until you mouse over something else. In and out of CineMode."] = "勾選後，滑鼠提示的該部分會顯示：首次懸停——一出現就顯示；之後——懸停達到上面設定的時間後顯示，直到你把滑鼠移到別的東西上。CineMode內外皆然。"
L["Where the game's tooltips (things in the world, unit frames, action bars, bags) show: in their default position (the bottom-right corner, or wherever you've moved it), or by the mouse cursor, following it (or just in fights)."] = "遊戲的滑鼠提示（世界中的事物、單位框架、快捷列、背包）顯示在哪裡：預設位置（右下角，或你移動到的地方），或滑鼠游標旁並跟隨它（或僅在戰鬥時）。"
L["Default position"] = "預設位置"
L["At the mouse cursor in combat"] = "戰鬥中在滑鼠游標旁"
L["Fade in/out"] = "淡入/淡出"
L["How long tooltips take to fade in as they show, and to fade out when the mouse has been still too long (Mouse still, below). Off: no fading."] = "滑鼠提示顯示時淡入的用時，以及滑鼠靜止太久時淡出的用時（下面的滑鼠靜止）。關閉：不淡入淡出。"
L["After hovering for"] = "懸停時間"
L["How long you hover over something before the After column's parts take over, until you mouse over something else. Off: tooltips show as normal, every part of them."] = "懸停多久後改用\"之後\"欄的部分，直到你把滑鼠移到別的東西上。關閉：滑鼠提示照常完整顯示。"
L["On first hover"] = "首次懸停"
L["After %d sec"] = "%d秒後"
L["After (off)"] = "之後（關閉）"
L["Shown as soon as the tooltip appears."] = "滑鼠提示一出現就顯示。"
L["Shown once you've hovered as long as set above."] = "懸停達到上面設定的時間後顯示。"
L["At the mouse cursor"] = "在滑鼠游標旁"
L["Health bar"] = "生命條"
L["The health bar under the tooltips of players, NPCs and mobs."] = "玩家、NPC和怪物滑鼠提示下方的生命條。"
L["Works with this page switched off too."] = "即使此頁面關閉也有效。"
L["Background and border"] = "背景和邊框"
L["The box around the tooltip. Unticked, just the text shows."] = "滑鼠提示周圍的邊框。不勾選時只顯示文字。"
L["Guild and title (<...>)"] = "公會和頭銜 (<...>)"
L["A player's <Guild> line, or an NPC's <Innkeeper>-style title."] = "玩家的<公會>行，或NPC的<旅店老闆>之類的頭銜。"
L["The level line (for players, with their race and class)."] = "等級行（玩家的還包括種族和職業）。"
L["Level"] = "等級"
L["Spec and class"] = "專精和職業"
L["A player's spec and class line (\"Fury Warrior\")."] = "玩家的專精和職業行（\"狂怒戰士\"）。"
L["Creature type"] = "生物類型"
L["The kind of creature: Elemental, Beast, Humanoid and so on."] = "生物的種類：元素生物、野獸、人型生物等。"
L["Faction and PvP"] = "陣營和PvP"
L["The Horde or Alliance line and the PvP line."] = "部落或聯盟行，以及PvP行。"
L["Reputation faction"] = "聲望陣營"
L["The faction an NPC belongs to, whose reputation you earn (\"Hara'ti\")."] = "NPC所屬的聲望陣營，你可以獲得其聲望（\"Hara'ti\"）。"
L["Threat"] = "仇恨"
L["How much of the mob's threat you have (\"100% Threat\")."] = "你占該怪物仇恨的多少（\"100%仇恨\"）。"
L["Quest lines"] = "任務行"
L["The names of your quests the unit is for, and their objectives (\"5/7 Thistle Boar slain\")."] = "該單位相關的你的任務名稱及其目標（\"5/7 薊皮野豬已殺死\"）。"
L["Quest lines on objects"] = "物體上的任務行"
L["The same on things in the world you use or pick up for a quest (\"0/1 Palehill Runestone\")."] = "對你為任務使用或拾取的世界中的物體同樣適用（\"0/1 Palehill符文石\"）。"
L["On flights"] = "飛行時"
L["AFK camera (standing still or AFK)"] = "暫離鏡頭(站著不動或暫離)"
L["Cozy (campfire, sitting, emotes)"] = "悠閒(營火、坐下、表情動作)"
L["Tele (Hearthstone, teleports)"] = "傳送(爐石、傳送法術)"
L["Vista (/stare)"] = "遠景(/stare)"
L["Fish (fishing)"] = "釣魚(釣魚時)"
L["RP walking"] = "RP 漫步"
L["Auto-running"] = "自動奔跑"
L["Quest camera (talking to quest givers)"] = "任務鏡頭(與任務 NPC 對話)"
L["Enemies"] = "敵方"
L["Friendlies"] = "友方"
L["Gatherables (herbs, ore, skinnable)"] = "可採集物(草藥、礦石、可剝皮)"
L["Quest objectives"] = "任務目標"
L["Players and NPCs you can't attack, and their pets, minions and totems."] = "你無法攻擊的玩家與 NPC,以及他們的寵物、僕從與圖騰。"
L["Everything else"] = "其他所有項目"
L["Advanced Frames"] = "進階框架"
L["On: CineMode fades the supported addons' frames, and frames you added, as this page says. Off: it leaves them all alone."] = "開啟:CineMode 會依此頁面的設定淡出支援插件的框架,以及你加入的框架。關閉:全部不予處理。"
L["Supported addons"] = "支援的插件"
L["These addons' frames are hidden in CineMode unless ticked, like the game's frames on the Game Frames page. Tick Always to leave an addon's frames alone (shown the whole time); the next three show them only while you fight or have something targeted, and the places while you're there."] = "與遊戲框架頁面中遊戲的框架相同,除非勾選,這些插件的框架在 CineMode 中都會隱藏。勾選「一律」可讓插件的框架不受處理(全程顯示);接下來三欄只在你戰鬥或選取目標時顯示,地點欄則是在你身處該處時顯示。"
L["Show %s the whole time in CineMode (Cinematic leaves them alone). Unticked, they're hidden, except as the other columns say.%s"] = "在 CineMode 中全程顯示 %s(Cinematic 不予處理)。取消勾選時則隱藏,除非其他欄位另有設定。%s"
L["Click to show or hide its parts."] = "點擊以顯示或隱藏其組成部分。"
L["Loaded"] = "已載入"
L["Installed, not loaded"] = "已安裝,未載入"
L["Not installed"] = "未安裝"
L["Also supported, when installed: %s"] = "安裝後同樣支援:%s"
L["Custom frames"] = "自訂框架"
L["To fade something else, hover over it and type |cffffd100/cine add|r, or type |cffffd100/cine add|r and its frame name. To pick up several, use the button below (or |cffffd100/cine add mode|r) and hover over each one. The columns work as for the supported addons above; the X takes a frame off the list."] = "若要淡出其他東西,將滑鼠移到它上面並輸入 |cffffd100/cine add|r,或輸入 |cffffd100/cine add|r 加上它的框架名稱。若要一次選取多個,請使用下方的按鈕(或 |cffffd100/cine add mode|r),並將滑鼠逐一移到它們上面。各欄的作用與上方支援的插件相同;X 可將框架從清單中移除。"
L["Hover over the frames you want to fade (move this window out of the way, or close it), then click Stop or type /cine add mode again to fade them all. The game's own frames and ones already faded are left out. /cine add cancel drops them."] = "將滑鼠移到你要淡出的框架上(把此視窗移開或關閉),然後點擊「停止」或再次輸入 /cine add mode 將它們全部淡出。遊戲本身的框架和已經淡出的框架不會列入。/cine add cancel 可放棄。"
L["Stop"] = "停止"
L["Pick frames by hovering"] = "以滑鼠指向選取框架"
L["Hide the UI"] = "隱藏介面"
L["Like Blizzard's Alt+Z: hides the whole UI, but keeps the tint, letterbox and time-of-day title. Press again (or Blizzard's key) to bring it back."] = "如同 Blizzard 的 Alt+Z:隱藏整個介面,但保留色調、黑邊與時段標題。再按一次(或按 Blizzard 的按鍵)即可恢復。"
L["Take a CineShot"] = "拍攝 CineShot"
L["Hides the UI but keeps the tint and letterbox, takes a screenshot, then brings the UI straight back. Not in a fight."] = "隱藏介面但保留色調和電影黑邊，擷取一張畫面，然後立即恢復介面。戰鬥中無法使用。"
L["Turns CineMode on or off, like /cine."] = "開啟或關閉 CineMode,與 /cine 相同。"
L["Starts the AFK camera now, without waiting out its delay. Press again, move or jump to stop it."] = "立即啟動暫離鏡頭,不必等待延遲時間。再按一次、移動或跳躍即可停止。"
L["Starts the cozy camera now, as if you'd sat down. Press again, move or jump to stop it."] = "立即啟動悠閒鏡頭,就像你坐下一樣。再按一次、移動或跳躍即可停止。"
L["Starts the vista camera now, as if you'd done a /stare. Press again, move or jump to stop it."] = "立即啟動遠景鏡頭,就像你做了 /stare 一樣。再按一次、移動或跳躍即可停止。"
L["Starts the fish camera now, without casting. Press again, move or jump to stop it."] = "立即啟動釣魚鏡頭,不必拋竿。再按一次、移動或跳躍即可停止。"
L["Starts the tele camera now, as if you were casting your Hearthstone. Press again, move or jump to stop it."] = "立即啟動傳送鏡頭,就像你正在使用爐石一樣。再按一次、移動或跳躍即可停止。"
L["Death camera test"] = "死亡鏡頭測試"
L["Camera wheel"] = "鏡頭輪盤"
L["Hold to bring up a wheel of the cameras below, an icon for each: point at one and let go to start it. Tap it instead and the wheel stays up for you to click one. Picking the camera that's running stops it."] = "按住以開啟下列鏡頭的輪盤，每個鏡頭一個圖示：指向其中一個並放開即可啟動。只輕按一下，輪盤會保持開啟，供你點擊選擇。選擇正在執行的鏡頭會將其停止。"
L["Menu wheel"] = "選單輪盤"
L["Hold to bring up a wheel of the game's menu buttons (character, spellbook, quest log...), the ones on your menu bar: point at one and let go to open its window, even with the UI hidden. Tap it instead and the wheel stays up for you to click one."] = "按住以叫出由遊戲選單按鈕（角色、法術書、任務日誌……）組成的輪盤，也就是你選單列上的那些按鈕：指向其中一個並放開即可開啟它的視窗，即使介面已隱藏。若只是輕按，輪盤會保持開啟，讓你點擊選擇。"
-- CameraWheel.lua
L["running: pick it to stop it"] = "執行中：再次選擇以停止"
L["can't start now"] = "現在無法啟動"
-- MenuWheel.lua
L["open: pick it to close it"] = "已開啟：再次選擇以關閉"
L["can't open now"] = "現在無法開啟"
L["Pretends you're dead for 30 seconds so the death camera runs. Press again to stop. Like /cine deathtest."] = "假裝你死亡 30 秒,讓死亡鏡頭運作。再按一次即可停止。與 /cine deathtest 相同。"
L["Show hidden tooltips"] = "顯示隱藏的滑鼠提示"
L["Hold to see the tooltips the Tooltips page hides, in combat and in CineMode. Pressing it while you're on a unit or something in the world brings its tooltip up; anything else, hover it again with the key held."] = "按住即可查看滑鼠提示頁面所隱藏的滑鼠提示,在戰鬥中與 CineMode 中皆可。滑鼠指向單位或世界中的物件時按下,就會顯示其滑鼠提示;其他東西則請按住按鍵再指向一次。"
L["Turns the Tooltips page's \"CineMode Tooltips\" switch on or off."] = "開啟或關閉滑鼠提示頁面中的「CineMode 滑鼠提示」開關。"
L["Press a key"] = "請按下按鍵"
L["|cff808080Not bound|r"] = "|cff808080未設定|r"
L["keybinds can't be changed in combat"] = "戰鬥中無法變更按鍵設定"
L["%s was bound to %s and now isn't"] = "%s 原本設定給 %s,現在已取消"
L["Click, then press a key (with Shift, Ctrl or Alt if you like). Right-click to clear. Escape cancels."] = "點擊後按下按鍵(可搭配 Shift、Ctrl 或 Alt)。右鍵點擊可清除。按 Esc 取消。"
L["Keybinds"] = "按鍵設定"
L["Keys for Cinematic. These are the same bindings as under Key Bindings > AddOns, so setting them in either place works."] = "Cinematic 的按鍵。這些與「按鍵設定 > 插件」中的設定相同,所以在任一處設定皆可。"
L["Keys"] = "按鍵"
L["settings can't be opened in combat"] = "戰鬥中無法開啟設定"
L["A profile needs a name."] = "設定檔需要名稱。"
L["There's already a profile called %s."] = "已經有名為 %s 的設定檔。"
L["Name the new profile (it starts from your current settings):"] = "為新的設定檔命名(會以你目前的設定為起點):"
L["Rename the profile:"] = "重新命名設定檔:"
L["Describe the profile:"] = "描述設定檔:"
L["Delete the profile %s?"] = "要刪除設定檔 %s 嗎?"
L["Put the profile %s back to how it started? Every change you've made to it goes."] = "要將設定檔 %s 還原為初始狀態嗎?你對它所做的所有變更都會消失。"
L["Profiles"] = "設定檔"
L["A profile is a whole set of settings. Pick one to switch to it; changes you make go into the active profile and stay with it. The built-in ones keep your changes too, until you reset them. New profile starts one of your own from the settings you have now. Every character uses the same profile unless you tick the box below for one. Not part of a profile: the minimap button, frames you added or stopped fading, and the zone and time tint colors you picked."] = "設定檔是一整組設定。選擇一個即可切換;你所做的變更會存入目前的設定檔並保留在其中。內建設定檔也會保留你的變更,直到你重置為止。「新增設定檔」會以你目前的設定建立你自己的設定檔。除非你為某個角色勾選下方的方塊,否則所有角色都使用同一個設定檔。不屬於設定檔的項目:小地圖按鈕、你加入或停止淡出的框架,以及你選擇的區域與時段色調顏色。"
L["Use a profile just for this character"] = "此角色使用專屬設定檔"
L["Ticked: switching profiles changes only this character's, and it stays on it whatever your other characters use. Unticked: this character uses the same profile as the rest (switching back to it now if this one's differs)."] = "勾選:切換設定檔只會變更此角色的設定檔,而且無論你的其他角色使用什麼,此角色都會維持。取消勾選:此角色與其他角色使用同一個設定檔(若目前不同,會立即切換回去)。"
L["Use a profile just for this character |cff808080(other characters use %s)|r"] = "此角色使用專屬設定檔 |cff808080(其他角色使用 %s)|r"
L["New profile"] = "新增設定檔"
L["A profile of your own, starting from your current settings. To copy another profile, switch to it first."] = "以你目前的設定為起點,建立你自己的設定檔。若要複製其他設定檔,請先切換到該設定檔。"
L["Rename"] = "重新命名"
L["Rename the active profile (your own ones only)."] = "重新命名目前的設定檔(僅限你自己的設定檔)。"
L["Description"] = "描述"
L["Write what the active profile is for, shown when you point at its icon (your own ones only)."] = "寫下目前設定檔的用途,滑鼠指向它的圖示時會顯示(僅限你自己的設定檔)。"
L["Delete"] = "刪除"
L["Delete the active profile (your own ones only), switching to %s."] = "刪除目前的設定檔(僅限你自己的設定檔),並切換到 %s。"
L["Put the active built-in profile back to its own values (your own profiles keep your changes as you go)."] = "將目前的內建設定檔還原為其本身的值(你自己的設定檔會隨時保存你的更改)。"
L["Your own profile. Pick it, then Description to say what it's for."] = "你自己的設定檔。選擇它,然後點擊「描述」說明它的用途。"
L["Mouseover groups"] = "滑鼠指向群組"
L["Mouseover Groups"] = "滑鼠指向群組"
L["UI Manager"] = "介面管理器"
L["Frames in the same group come up together when you mouse over any of them. A frame can be in more than one group; one in no group comes up on its own."] = "滑鼠指向同一群組中的任一框架時,該群組的框架會一起顯示。一個框架可以屬於多個群組;不屬於任何群組的框架會單獨顯示。"
L["Pointing at a faded frame shows it, with the rest of its groups."] = "指向已淡出的框架會顯示它,以及其所屬群組的其他框架。"
L["Stays after mouseover"] = "滑鼠指向後停留"
L["How long until a frame is gone after your mouse leaves it (and its groups), fade included. Events that bring a group up hold it this long too. In the camera modes the shorter default is used."] = "滑鼠離開框架(及其群組)後,框架消失前的時間,包含淡出時間。讓群組顯示的事件也會讓它保持這麼久。在鏡頭模式中則使用較短的預設值。"
