L["Settings window"] = "設定視窗"
L["Force reload on Settings exit"] = "離開設定時強制重新載入"
L["A workaround for a game bug: in gamepad mode, closing the Settings window after using an addon's settings (any addon's, not just Cinematic's) can freeze the game. With this on, once you've opened a Cinematic page, closing Settings (X, Close, Escape or the gamepad) reloads the UI instead, which closes it without the freeze. Your settings are saved first, as they are on every reload. Turning it off takes effect after a reload."] = "針對遊戲錯誤的變通辦法：在手把模式下，使用過插件的設定（任何插件，不只是Cinematic）後關閉設定視窗可能會讓遊戲當機。開啟後，在開過Cinematic頁面後關閉設定（X、關閉、Esc或手把）會改為重新載入介面，從而關閉視窗而不當機。和每次重新載入一樣，你的設定會先儲存。關閉此項需重新載入後生效。"
L["closing Settings now reloads the UI (Force reload on Settings exit, Gamepad Frames page)."] = "現在關閉設定會重新載入介面（離開設定時強制重新載入，手把頁面）。"
L["Hide the minimap button in gamepad mode"] = "手把模式下隱藏小地圖按鈕"
L["Using Cinematic's minimap button in gamepad mode tends to freeze the game, like closing Settings does. With this on, the button is hidden while gamepad mode is on and comes back when it's off. Cinematic's settings are still in the game's Settings (AddOns tab), or type /cine."] = "在手把模式下使用Cinematic的小地圖按鈕常會讓遊戲當機，就像關閉設定時一樣。開啟後，手把模式開啟期間按鈕會隱藏，關閉手把模式後再出現。Cinematic的設定仍在遊戲設定（插件標籤）中，或輸入/cine。"
