-- Profiles.lua
L["Everything on: the UI fades, the letterbox and tint, and every camera mode. The defaults, and how the developer plays every day."] = "全部開啟:介面淡出、黑邊與色調,以及所有鏡頭模式。這是預設值,也是開發者每天遊玩的方式。"
L["Immersive, with the Cooldown Manager in place of action bars 1 to 3, the micro menu and the XP bar in fights and with an enemy targeted. After a fight it stays up until its cooldowns are ready."] = "沉浸式,在戰鬥中與以敵人為目標時,以冷卻管理器取代快捷列1到3、微型選單與經驗條。戰鬥後冷卻管理器會保持顯示,直到其冷卻全部就緒。"
L["The UI fades and the look stays, with just a few cameras: flights (and fly-bys), AFK, and your Hearthstone and teleports. No cozy, vista, fish, RP walk, auto-run, death or quest cameras."] = "介面淡出並保留畫面效果,只使用少數鏡頭:飛行(及掠過鏡頭)、暫離,以及爐石與傳送。不使用悠閒、遠景、釣魚、RP 漫步、自動奔跑、死亡或任務鏡頭。"
L["Just the visual effects (tint, vignette, weather) over your normal UI: nothing fades, no letterbox, and the camera's left to you."] = "只在一般介面上套用視覺效果(色調、暗角、天氣):不淡出任何東西,沒有黑邊,鏡頭由你自己控制。"
L["The normal UI until a camera starts (standing still, going AFK, a flight, an emote...), then CineMode until it ends. The letterbox, tint, vignette and weather show only while a camera mode runs; no soft edges. Standing still starts the AFK camera, and every camera can start music."] = "在鏡頭啟動前(站著不動、暫離、飛行、表情動作……)都是一般介面,之後進入 CineMode 直到鏡頭結束。黑邊、色調、暗角與天氣只在鏡頭模式運作時顯示;沒有邊緣模糊。站著不動會啟動暫離鏡頭,而且每個鏡頭都可以播放音樂。"
L["Everything on while you're out in the world on your own; the normal UI in a group, in dungeons, raids and PvP."] = "獨自在野外時全部開啟;組隊時以及在地城、團隊副本與 PvP 中使用一般介面。"
L["As little UI as possible: chat, buffs, the quest tracker and your portrait don't pop up on their own (hovering still shows them), group members' nameplates aren't kept up, and fights don't bring the letterbox down. Fights bring up only your target and your cast bar (hidden otherwise), and every camera can start music."] = "盡可能減少介面:聊天、增益、任務追蹤與你的頭像不會自行跳出(滑鼠指向時仍會顯示),隊友的名條不會保持顯示,戰鬥也不會移除黑邊。戰鬥時只顯示你的目標與施法條(其他時候隱藏),而且每個鏡頭都可以播放音樂。"
L["Started from %s."] = "以 %s 為基礎建立。"

-- Share.lua
L["Export"] = "匯出"
L["Import"] = "匯入"
L["The active profile as a line of text to copy and paste wherever your friends will see it, so they can import it (your own ones only: everyone has the built-in ones)."] = "將目前的設定檔轉為一行文字，複製並貼到朋友看得到的地方，他們就能匯入（僅限你自己的：內建設定檔人人都有）。"
L["Add a profile someone shared with you, from the text they gave you. Your own profiles stay as they are."] = "用別人分享給你的文字新增一個設定檔。你自己的設定檔維持不變。"
L["Share a profile with friends."] = "與朋友分享設定檔。"
L["share the active profile as text to copy"] = "將目前的設定檔分享為可複製的文字"
L["add a profile someone shared with you"] = "新增別人分享給你的設定檔"
L["%s is a built-in profile, which everyone has already. To share your changes to it, make a New profile from it on the Profiles page and export that."] = "%s 是內建設定檔，人人都已經有了。要分享你對它的修改，請在設定檔頁面用它新增一個設定檔，再匯出那個。"
L["Shared profile"] = "分享的設定檔"
L["This profile needs a newer version of Cinematic. Update it, then try again."] = "此設定檔需要較新版本的 Cinematic。請更新後再試。"
L["That isn't a whole Cinematic profile. Copy all of it and paste it again."] = "這不是完整的 Cinematic 設定檔。請全部複製後重新貼上。"
L["Paste a profile someone shared with you (Ctrl+V)."] = "貼上別人分享給你的設定檔（Ctrl+V）。"
L["%s, shared by %s: %d settings changed from the defaults."] = "%s，由 %s 分享：%d 項設定與預設值不同。"
L["%s: %d settings changed from the defaults."] = "%s：%d 項設定與預設值不同。"
L["%d settings from a newer Cinematic (%s) will be skipped. Update Cinematic to get them all."] = "將略過 %d 項來自較新版 Cinematic（%s）的設定。更新 Cinematic 即可全部取得。"
L["Shared by %s."] = "由 %s 分享。"
L["profile imported: %s"] = "已匯入設定檔：%s"
L["Select all"] = "全選"
L["Save as:"] = "儲存為："
L["Export profile: %s"] = "匯出設定檔：%s"
L["Press Ctrl+C to copy this, then paste it wherever your friends will see it. They add it with Import on their Cinematic Profiles page (or /cine import)."] = "按 Ctrl+C 複製，然後貼到朋友看得到的地方。他們可在 Cinematic 設定檔頁面點選匯入（或 /cine import）來新增。"
L["Only Cinematic settings are in it: nothing about you or your character but its name. Not in it, as with any profile: frames you added and your zone and time tint colors."] = "其中只有 Cinematic 設定：除了角色名稱外，不含任何關於你或你角色的資訊。與所有設定檔一樣，不包含你新增的框架以及區域和時段的色調顏色。"
L["Import a profile"] = "匯入設定檔"
L["Paste in a profile someone shared, give it a name, and Import. It's added as a new profile and switched to; your own profiles stay as they are."] = "貼上分享的設定檔，取個名字，然後點選匯入。它會作為新設定檔加入並啟用；你自己的設定檔維持不變。"

