L["its action bars 6 to 10"] = "它的快捷列 6 至 10"
L["Its bars 1-5, pet, stance and XP bars are rows on the Game Frames page, with its unit frames and quest tracker."] = "它的快捷列 1-5、寵物列、姿態列與經驗值條,連同它的單位框架與任務追蹤,都是遊戲框架頁面中的列。"
L["its cooldown bars"] = "它的冷卻條"
L["its health, power and totem bars"] = "它的生命值、能量與圖騰條"
L["Its cast bar isn't faded, like the game's. Its swing timer is the Swing timer row on the Game Frames page."] = "它的施法條與遊戲的一樣不會淡出。它的揮擊計時器是遊戲框架頁面中的「揮擊計時器」列。"
L["its data bars"] = "它的資料條"
L["its missing-buff reminders"] = "它的缺少增益提醒"
