L["Plater's nameplates fade in CineMode and follow the Nameplates page's rows. Plater can change the game's nameplate settings itself (at login, and with its auto toggles); Cinematic puts its own back afterwards."] = "Plater 的名條會在 CineMode 中淡出,並依據名條頁面各列的設定。Plater 本身可能會變更遊戲的名條設定(登入時,以及透過其自動切換功能);Cinematic 之後會還原自己的設定。"

-- Tint.lua
L["None"] = "無"
L["No color tint."] = "不套用色調。"
L["Warm / golden hour"] = "暖色/黃金時刻"
L["Soft orange, like late-afternoon light."] = "柔和的橙色,如同傍晚前的陽光。"
L["Cool"] = "冷色"
L["Pale blue, crisp and wintry."] = "淡藍色,清爽而有冬日氣息。"
L["Night"] = "夜晚"
L["Deep blue and darker, like moonlight."] = "深藍且更暗,如同月光。"
L["Dusk gradient"] = "黃昏漸層"
L["Orange at the top fading to purple at the bottom, like a sunset."] = "上方橙色漸變為下方紫色,如同日落。"
L["Sepia-ish"] = "類懷舊棕褐"
L["Warm brownish yellow, old-photo warmth. (The world can't be truly desaturated.)"] = "溫暖的棕黃色,帶有老照片的暖意。(遊戲世界無法真正去飽和。)"
L["Dreamy"] = "夢幻"
L["A faint warm glow added over the scene. Soft and hazy."] = "在畫面上加上淡淡的暖色光暈。柔和朦朧。"
L["Custom"] = "自訂"
L["Your own color, chosen with the color picker below."] = "你自己的顏色,用下方的顏色選擇器選取。"
L["Changes through the day: blue at night, pink at dawn, clear in the day, golden in the evening and purple at dusk."] = "隨一天中的時間變化:夜晚是藍色,黎明是粉紅色,白天是無色,傍晚是金色,黃昏是紫色。"
L["Zone"] = "區域"
L["A mood for the zone you're in: pale blue in the snow, sandy in deserts, green in swamps and jungles, sickly in blighted lands, ember red near volcanoes. Other zones are left untinted."] = "依你所在區域而定的氛圍:雪地是淡藍色,沙漠是沙色,沼澤與叢林是綠色,荒蕪之地是病態色,火山附近是餘燼紅。其他區域不套用色調。"
L["Zone + time of day"] = "區域 + 時段"
L["The zone's mood and the time-of-day color together: a desert at night is warm sand darkened by moonlight."] = "區域氛圍與時段顏色兩者結合:夜晚的沙漠是被月光染暗的溫暖沙色。"
L["Snow"] = "雪地"
L["Desert"] = "沙漠"
