-- Welcome.lua
L["Trying %s. Pick another to compare."] = "正在試用 %s。可選擇其他設定檔比較。"
L["Done"] = "完成"
L["Nothing runs until you pick one."] = "在你選擇之前,不會有任何功能運作。"
L["Decide later"] = "稍後決定"
L["Welcome to Cinematic"] = "歡迎使用 Cinematic"
L["Between fights, Cinematic fades your UI away, adds letterbox bars and a color tint, and brings the camera to life: on flights, standing still, sitting by a campfire. Fights, casting and opening windows bring the UI back. Hovering a faded frame shows it.\n\nHow much of that do you want? Pick a profile to start from:"] = "在戰鬥之間,Cinematic 會淡出你的介面,加上電影黑邊與色調,並讓鏡頭動起來:飛行時、站著不動時、坐在營火旁時。戰鬥、施法以及開啟視窗時,介面會恢復顯示。滑鼠指向已淡出的框架就會顯示它。\n\n你想要多少這些效果?選擇一個設定檔作為起點:"
L["Try as many as you like: each one starts straight away behind this window. Afterwards you can switch any time, tweak a profile or make your own on the Profiles page (Options > AddOns > Cinematic, or right-click the minimap button), or with /cine profile. /cine toggles Cinematic on and off."] = "想試幾個都可以:每個設定檔都會立即在此視窗後方生效。之後你隨時可以在設定檔頁面(選項 > 插件 > Cinematic,或右鍵點擊小地圖按鈕)或用 /cine profile 切換、調整設定檔或建立你自己的設定檔。/cine 可開啟或關閉 Cinematic。"
L["off until you pick a profile. This window comes back next login, or now with /cine welcome."] = "在你選擇設定檔之前為關閉狀態。此視窗會在下次登入時再次出現,或現在輸入 /cine welcome 開啟。"
L["profile: %s. Change it any time on the Profiles settings page, or with /cine profile."] = "設定檔:%s。隨時可在設定檔設定頁面或用 /cine profile 變更。"
L["Turn Cinematic off"] = "關閉 Cinematic"
L["turned off. /cine brings this window back to pick a profile."] = "已關閉。輸入 /cine 可再次開啟此視窗以選擇設定檔。"
L["Settings"] = "設定"

