-- Campfire.lua
L["Quality of life"] = "便利功能"
L["Small helpers for getting about the world. Ideas for more in the spirit of this page are welcome: please send them to the developer."] = "在世界中遊歷時的小幫手。若有更多與本頁類似的點子,歡迎提供給開發者。"
L["Campfire button"] = "營火按鈕"
L["Hovering a campfire with the cursor near the middle of the screen shows a campfire icon where the cursor is: click it to settle down by the fire (sit, kneel or lie down, as ticked below), without typing the emote. Moving the cursor off it puts it away. Not in a fight or while mounted."] = "游標在畫面中央附近停在營火上時，游標處會出現營火圖示：點擊即可在火邊歇息（坐下、跪下或躺下，依下方勾選），無需輸入表情指令。游標移開後圖示消失。戰鬥中或騎乘時不會出現。"
L["Sit"] = "坐下"
L["Kneel"] = "跪下"
L["Lie down"] = "躺下"
L["What clicking the Campfire button does. With more than one ticked, it's one of them at random each time."] = "點擊營火按鈕時做的動作。勾選多個時，每次隨機選其中一個。"
L["Clicking the Campfire button (Quality of life page). Once the campfire's buff comes, the first row's camera takes over. Moving, jumping or another emote ends it."] = "點擊營火按鈕（便利功能頁面）。營火增益出現後，由第一列的鏡頭接手。移動、跳躍或其他表情會結束它。"
L["Stand up once you get Camp Benefits"] = "獲得營地增益後站起"
L["Open the character window when dragging gear out of your bags"] = "把裝備拖出背包時打開角色視窗"
L["Dragging something you can wear out of your bags, over the game world, opens the character window, so its slots are there to drop it on. Moving it between bags doesn't. Put it back without wearing it and the window closes again. Not in a fight."] = "把可穿戴的物品拖出背包、移到遊戲世界上方時會打開角色視窗，方便把它放到欄位上。在背包之間移動不會打開。沒穿上就放回去，視窗會再次關閉。戰鬥中不生效。"
L["Off by default on this client: opened by an addon, the window makes your player frame's health and power numbers show errors in BugSack and other error catchers. They're harmless."] = "此用戶端預設關閉：由插件打開時，該視窗會讓你的玩家框架的生命值和能量數字在 BugSack 等錯誤收集插件中報錯。這些錯誤無害。"
L["Open windows in the middle of the screen"] = "在畫面中間開啟視窗"
L["Windows the game opens on the left (quest log, group finder, character, spellbook and the like) open in the middle of the screen instead. Two open at once still sit side by side, together in the middle. Quest givers' windows open a little in from the left edge instead, out of the way of the quest giver. A window another addon has moved stays where that addon put it."] = "遊戲在左側開啟的視窗（任務日誌、隊伍搜尋器、角色、法術書等）改為在畫面中間開啟。同時開啟兩個時仍並排顯示，一起置中。任務給予者的視窗則在離左邊緣稍遠處開啟，以免擋住任務給予者。被其他插件移動過的視窗留在該插件放置的位置。"
L["Drag windows to move them"] = "拖曳視窗來移動它們"
L["Drag the game's windows (quest log, group finder, character, spellbook and the like) to move them. A window opens where you last dropped it from then on, in this profile. Some windows can't be moved in a fight."] = "拖曳遊戲的視窗（任務日誌、隊伍搜尋器、角色、法術書等）來移動它們。此後視窗會在你上次放下的位置開啟（本設定檔）。部分視窗在戰鬥中無法移動。"
L["Put windows back"] = "視窗歸位"
L["Forget where you've dragged the windows to: each opens in its usual place again."] = "忘記你把視窗拖到了哪裡：每個視窗重新在原本的位置開啟。"
L["Sitting by a Welcoming Campfire for its minute gives you Camp Benefits: as it arrives, you stand up again, ready to go."] = "在迎賓營火旁坐滿一分鐘會獲得營地增益：獲得時你會站起來，隨時出發。"

-- Options.lua: the Camera Settings page
L["Camera Settings"] = "鏡頭設定"
L["Each camera's own settings. Click a camera's name to open its settings, and again to close them. The Camera Modes page has the settings they share, and Camera Triggers what starts each one."] = "每個鏡頭各自的設定。點擊鏡頭名稱展開其設定，再次點擊收起。共用設定在鏡頭模式頁面，啟動各鏡頭的條件在鏡頭觸發頁面。"
L["Put this camera's settings back to the profile's own?"] = "要將此鏡頭的設定還原為設定檔本身的值嗎?"
L["Put this camera's settings back to the active profile's own values (the defaults, or a built-in profile's)."] = "將此鏡頭的設定還原為目前設定檔的值(預設值或內建設定檔的值)。"
L["While the death camera runs, a song picked at random from the list below plays in place of the zone music. With CineMode music off, only if your game music is on. It stops when you release or come back."] = "死亡鏡頭執行時,會從下方清單中隨機選一首歌取代區域音樂播放。關閉 CineMode 音樂時,僅在遊戲音樂開啟時播放。釋放靈魂或復活時停止。"
L["Hunter"] = "獵人"

-- QuestTalk.lua (and its options on the Quest Vision page)
L["%s artifact power"] = "%s 神兵之力"
L["%s honor"] = "%s 榮譽"
L["Quests"] = "任務"
L["Show the game's window"] = "顯示遊戲視窗"
L["Talk"] = "對話"
L["Title: %s"] = "頭銜：%s"
L["campaign"] = "戰役"
L["daily"] = "每日"
L["done"] = "已完成"
L["important"] = "重要"
L["in progress"] = "進行中"
L["legendary"] = "傳說"
L["locked"] = "已鎖定"
L["low level"] = "低等級"
L["meta"] = "元任務"
L["ready to turn in"] = "可交付"
L["repeatable"] = "可重複"
L["weekly"] = "每週"
L["Talking to NPCs"] = "與NPC對話"
L["Custom dialogue frames"] = "自訂對話框"
L["Talking to an NPC, what they say shows in a speech bubble over their head, and what you can say back in a list near the bottom of the screen, instead of the game's gossip and quest windows. The list has everything the window would: quests to turn in, pick up or still in progress, and every other option (vendor, trainer, inn, flight master...). A quest offered or turned in shows its objective and rewards on a card, with its buttons; click a reward to choose it. \"Show the game's window\" on the card brings the game's window back for that conversation. The game's popups (a cost to confirm, a party member's escort quest) come up as usual."] = "與NPC對話時，NPC說的話會顯示在其頭上的對話泡泡中，你可以回答的內容則顯示在畫面下方的列表中，取代遊戲的對話和任務視窗。列表包含視窗中的所有內容：可交付、可接取或仍在進行的任務，以及所有其他選項（商人、訓練師、旅店、飛行管理員……）。提供或交付的任務會在卡片上顯示目標和獎勵以及按鈕；點擊獎勵即可選擇。卡片上的「顯示遊戲視窗」會在這次對話中恢復遊戲視窗。遊戲的彈出視窗（確認費用、隊友的護送任務）照常出現。"
L["Parchment"] = "羊皮紙"
L["Chat bubble"] = "聊天泡泡"
L["How the bubble looks: parchment like the quest window's, or the game's own chat bubble."] = "泡泡的外觀：像任務視窗那樣的羊皮紙，或遊戲自己的聊天泡泡。"
L["Bubble look"] = "泡泡外觀"
L["Number keys and Space"] = "數字鍵和空白鍵"
L["1 to 9 and 0 pick from the list, as numbered. Space shows the next paragraph, and on the last one does the card's first button (Accept, Continue, Complete Quest). Only keys that do something there are held back from your action bars, and none in a fight."] = "1到9和0按編號從列表中選擇。空白鍵顯示下一段，在最後一段時按下卡片的第一個按鈕（接受、繼續、完成任務）。只有在這裡有作用的按鍵才會從快捷列截留，戰鬥中一個也不會。"
L["Size"] = "大小"
L["The size of the bubble and the list."] = "泡泡和列表的大小。"
L["List height on the screen"] = "列表在畫面上的高度"
L["How far up the screen the list of replies starts: its top edge, from the bottom of the screen. Moving this also forgets where you dragged the list to."] = "回答列表在畫面上從多高開始：從畫面底部算起到它的上邊緣。調整它也會忘記你拖曳列表到的位置。"
L["The NPC's portrait"] = "NPC頭像"
L["Their portrait, round, on the bubble's top left corner, as on the game's quest window. Not for a quest from an item, with nobody to show."] = "在泡泡左上角顯示其圓形頭像，就像遊戲的任務視窗。來自物品的任務沒有人可顯示，因此不顯示。"
L["Put them back"] = "全部復位"
L["Drag the list of replies to move it, and the bubble while it isn't over an NPC. This forgets where you dropped them: each opens in its usual place again."] = "拖曳回答列表可以移動它，泡泡不在NPC上方時也可以拖曳。此按鈕會忘記你放置的位置：它們會重新在原來的位置開啟。"
L["Bubble height"] = "泡泡高度"
L["%d lines"] = "%d 行"
L["How many lines of their words the bubble holds. It's always this tall, however little is on the page; more words go on the next page."] = "泡泡能容納幾行話。無論頁面上內容多少，它總是這個高度；更多的話放到下一頁。"
L["Below"] = "下方"
L["Quest card beside the bubble"] = "泡泡旁的任務卡片"
L["Quest card on the bubble's background"] = "任務卡片使用泡泡背景"
L["The quest card has the bubble's look (parchment, or the chat bubble) instead of its own dark one, its words in colors that suit it."] = "任務卡片使用泡泡的外觀（羊皮紙或聊天泡泡）而不是自己的深色背景，文字顏色隨之調整。"
L["Space above the bubble"] = "泡泡上方留白"
L["Over the NPC's head, the bubble always stays at least this far down from the top of the screen (and below the letterbox), so it never sits right against the edge."] = "在NPC頭上時，泡泡總是離畫面頂部（以及電影黑邊下方）至少這麼遠，不會貼著邊緣。"
L["Over the head"] = "頭上"
L["Fixed"] = "固定"
L["Opposite clicked"] = "點擊的對側"
L["Where the bubble goes. Over the head: over the NPC's nameplate, following them on the screen. Fixed: above the middle of the screen, or wherever you drag it. Opposite clicked: wherever you drag it, but when you clicked the NPC on that half of the screen, at the same spot on the other half (they stand where you clicked, so that half is clearer), the quest card beside it. With nobody to stand over or no click (a quest from an item, or the interact key), it goes where Fixed would."] = "泡泡的位置。頭上：在NPC名條上方，在畫面上跟隨它。固定：畫面中央上方，或你拖曳到的位置。點擊的對側：在你拖曳到的位置，但如果你在畫面那一半點擊了NPC，就放在另一半的相同位置（NPC站在你點擊的地方，所以那一半更空），任務卡片在旁邊。沒有可跟隨的人或沒有點擊時（來自物品的任務，或互動鍵），放在固定的位置。"
L["Bubble position"] = "泡泡位置"
L["Hold the camera still"] = "保持鏡頭靜止"
L["With the bubble over the head, the quest camera turns in as usual but doesn't drift to and fro while you talk: following the NPC on the screen, the bubble and card would jiggle as it moved."] = "泡泡在頭上時，任務鏡頭照常轉入，但在對話時不會來回漂移：泡泡和卡片在畫面上跟隨NPC，鏡頭移動會讓它們抖動。"
L["+%d reputation"] = "+%d 聲望"
L["More rewards"] = "更多獎勵"
L["Back"] = "返回"
L["Right"] = "右側"
L["Left"] = "左側"
L["Where the quest card (the objective, rewards and buttons, or the list of replies) goes beside the bubble. Below: as wide as the bubble, which moves up to make room for it. Side: with Opposite clicked, on the bubble's outer side (away from the middle of the screen), else on the right. Right or Left: always that side. Beside it, it's as tall as the bubble."] = "任務卡片（目標、獎勵和按鈕，或回答列表）放在泡泡旁的哪裡。下方：與泡泡等寬，泡泡上移騰出空間。側邊：使用點擊的對側時放在泡泡外側（遠離畫面中央），否則放在右側。右側或左側：總是那一側。在旁邊時與泡泡等高。"
L["\"Show the game's window\" link"] = "「顯示遊戲視窗」連結"
L["A small link at the bottom of the quest card that brings back the game's own quest window for the rest of that conversation (for a long quest text, or to read it the usual way)."] = "任務卡片底部的小連結，在這次對話剩下的時間恢復遊戲自己的任務視窗（用於很長的任務文字，或用平常的方式閱讀）。"
L["Look"] = "外觀"
L["Where they go"] = "位置"

-- StoryVision.lua
L["Opens the Story Vision page."] = "開啟 Story Vision 頁面。"
L["Shows it now, to see how it looks."] = "立即顯示，看看效果。"
L["Words that fade in on the screen at moments in your session that aren't your own fights: what you did last time, the time of day, a place under attack, your death. (Fights and bosses: Battle Vision.)"] = "在並非你自己戰鬥的時刻，於螢幕上淡入的文字：你上次做了什麼、時段、遭受攻擊的地點、你的死亡。（戰鬥與首領：Battle Vision。）"
L["Last time"] = "上次"
L["On a real login (not a reload), a line under the zone name saying what you did last time you played: where you spent the most time, quests done, a level reached and bosses killed, such as \"Last time: Darkshore · 3 quests done · reached level 24\". Only what happened, and nothing if nothing did; never in a fight, nor after more than two weeks away."] = "真正登入時（不是重新載入），在區域名稱下方用一行文字說明你上次遊戲時做了什麼：待得最久的地方、完成的任務、達到的等級和擊敗的首領，例如「上次：黑海岸 · 完成3個任務 · 達到24級」。只顯示發生過的事，什麼都沒發生就不顯示；戰鬥中不顯示，離開超過兩週也不顯示。"
L["Last time: nothing to say yet this session (no quests, level or bosses), so this is a sample."] = "上次：本次遊戲暫時沒有可說的（沒有任務、等級或首領），所以這是範例。"
L["Plays your login now: the zone name fades in with the Last time line under it, from this session so far (a sample if nothing counted yet). Close the settings to see it."] = "立即重現登入畫面：區域名稱淡入，下方顯示依本次遊戲到目前為止的「上次」一行（尚未記錄任何內容時顯示範例）。關閉設定即可看到。"
L["The font of every line on this page. General: the one picked on the Style hub's General page, so changing it there changes it here. Russian, Korean or Chinese text keeps the game's, so its letters show. Only with Enable Style on (Style hub, General page)."] = "此頁面上每一行文字的字型。General：Style 中心 General 頁面所選的字型，在那裡更改，這裡也會跟著更改。俄文、韓文或中文文字保留遊戲字型，以便正常顯示。僅在開啟 Enable Style 時生效（Style 中心，General 頁面）。"
L["Last time: %s"] = "上次：%s"
L["%d quest done"] = "完成%d個任務"
L["%d quests done"] = "完成%d個任務"
L["reached level %d"] = "達到%d級"
L["%d boss down"] = "擊敗%d個首領"
L["%d bosses down"] = "擊敗%d個首領"
L["On: each moment below shows as ticked. Off: none of them do, and each keeps its tick for when you turn this back on."] = "開啟：下方每個時刻依勾選顯示。關閉：都不顯示，各自保留勾選，待你重新開啟。"
L["Time of day at login"] = "登入時的時段"
L["Dawn, Morning, Midday, Afternoon, Evening, Dusk or Night, under the zone name when you log in or reload. Follows the clock picked on the Tint page."] = "登入或重新載入時，在區域名稱下方顯示黎明、早晨、正午、午後、傍晚、黃昏或夜晚。依色調頁面所選的時鐘為準。"
L["Time of day changes"] = "時段變化"
L["When the time of day changes during play (not in combat), its name fades in where the zone name shows, with a fitting sound: a rooster at dawn, a horse in the morning, your faction's bell at midday, frogs in the evening, an owl at dusk and a wolf at night."] = "遊戲中時段改變時（非戰鬥中），其名稱會在區域名稱出現的位置淡入，並搭配合適的音效：黎明是公雞，早晨是馬，正午是你陣營的鐘聲，傍晚是青蛙，黃昏是貓頭鷹，夜晚是狼。"
L["Under attack"] = "遭受攻擊"
L["When the LocalDefense channel says a place is under attack (\"Dun Algaz is under attack!\"), it shows in red where the zone name appears, with your faction's city bell. The same place shows at most once every 90 seconds."] = "當本地防務頻道通報某地正遭受攻擊時（\"丹奧加茲正遭受攻擊！\"），會在區域名稱出現的位置以紅色顯示，並敲響你所屬陣營的城市鐘聲。同一地點每90秒最多顯示一次。"
L["Only with the death camera on (the Die row on the Scenes page)."] = "僅在死亡鏡頭開啟時（場景頁面的死亡一列）。"
L["The time of day's title and sound:"] = "時段的標題與音效："
L["Attacks shown on the screen:"] = "螢幕上顯示的攻擊："
L["The death banner:"] = "死亡橫幅："

-- Options.lua: the Interface hub's pages, sections and links
L["Game Frames"] = "遊戲框架"
L["Addon Frames"] = "插件框架"
L["Hover Groups"] = "滑鼠指向群組"
L["Gamepad Frames"] = "控制器框架"
L["Resource Display"] = "資源顯示"
L["Visibility"] = "顯示"
L["Trackers"] = "追蹤"
L["Info and menus"] = "資訊與選單"
L["Click to open it."] = "點擊開啟。"
L["Parts"] = "部件"
L["When it shows in CineMode (always, in fights, in places): its rows on the Game Frames page."] = "在 CineMode 中何時顯示（一律、戰鬥中、特定地點）：遊戲框架頁面上的對應列。"
L["Opens the Unit Frames page: which parts of your own, your target's and the other unit frames show, and when."] = "開啟單位框架頁面：你自己的、目標的及其他單位框架顯示哪些部分，以及何時顯示。"

-- More pages and settings (AI translation)
L[" A class icon beside enemy players' health bars."] = " 敵方玩家生命條旁的職業圖示。"
L[" A class icon beside friendly players' health bars."] = " 友方玩家生命條旁的職業圖示。"
L[" A mark on your target's nameplate (and its name, health bar or border in its color), shown even while the rest of the plate is faded or shows just its name. Its look: the Style hub's Nameplates page."] = " 目標名條上的標記（以及以其顏色顯示的名稱、生命條或邊框），即使名條其餘部分已淡出或只顯示名稱也會顯示。外觀：「風格」分類的名條頁面。"
L[" A role icon beside your group's damage dealers' health bars."] = " 隊伍中傷害輸出者生命條旁的職責圖示。"
L[" A role icon beside your group's healers' health bars."] = " 隊伍中治療者生命條旁的職責圖示。"
L[" A role icon beside your group's tanks' health bars."] = " 隊伍中坦克生命條旁的職責圖示。"
L[" Beyond nameplate range, and in dungeons and raids, the game has no setting for neutral NPCs' names alone: they show there while all three NPC rows do."] = " 在名條範圍之外，以及在地城與團隊副本中，遊戲沒有單獨控制中立 NPC 名稱的設定：只有當三個 NPC 列都顯示時，它們才會在那裡顯示。"
L[" Beyond nameplate range, and in dungeons and raids, the game only shows friendly NPCs with something for you (quest givers, vendors, flight masters...) unless all three NPC rows show: then all of them, guards too."] = " 在名條範圍之外，以及在地城與團隊副本中，遊戲只會顯示對你有用的友方 NPC（任務 NPC、商人、飛行管理員……），除非三個 NPC 列都顯示：那時會全部顯示，包括衛兵。"
L[" In CineMode, on the nameplates that are up."] = " 在 CineMode 中，顯示於已出現的名條上。"
L[" Its look: the Dialogue tab."] = " 外觀：對話分頁。"
L[" Its look: the Quest Item Button tab."] = " 外觀：任務物品按鈕分頁。"
L[" Off unless ticked. In CineMode, on the nameplates that are up; outside it, only with Always ticked."] = " 未勾選時關閉。在 CineMode 中，顯示於已出現的名條上；CineMode 以外，只有勾選「一律」時才顯示。"
L[" Players' guilds, under their names wherever their names show: over their heads, and in CineMode on nameplates showing just the name."] = " 玩家的公會，顯示在其名稱下方，凡是顯示名稱的地方都有：頭頂上方，以及 CineMode 中只顯示名稱的名條上。"
L[" Quest objective icons and other widgets over the plate."] = " 名條上方的任務目標圖示與其他小工具。"
L[" The border round your target's or mouseover's plate."] = " 你的目標或滑鼠指向對象名條周圍的邊框。"
L[" The buffs shown on the plate."] = " 名條上顯示的增益。"
L[" The cast bar."] = " 施法條。"
L[" The debuffs (and crowd control) shown on the plate."] = " 名條上顯示的減益（以及控場效果）。"
L[" The elite, rare or boss icon."] = " 精英、稀有或首領圖示。"
L[" The glow while a mob has you (or is about to) as its target."] = " 怪物以你為目標（或即將以你為目標）時的光暈。"
L[" The health bar."] = " 生命條。"
L[" The level."] = " 等級。"
L[" The name on the plate (the Names grid below is for names without a plate)."] = " 名條上的名稱（下方的名稱表格是給沒有名條的名稱用的）。"
L[" The raid target marker (skull, star...)."] = " 團隊目標標記（骷髏、星星……）。"
L[" Their look: the Style hub's Names page."] = " 外觀：「風格」分類的名稱頁面。"
L[" Your target's name, even with its kind's names off in the Names grid. For some kinds only, name them in its rule (Edit): Enemy players, Hostile NPCs, Neutral players... Beyond nameplate range, and in dungeons and raids, the game has one setting for your target's name, which can't change in fights: it stays as the fight found it."] = " 你目標的名稱，即使名稱表格中關閉了該類別的名稱也會顯示。若只想用於某些類別，請在其規則中寫出（編輯）：敵方玩家、敵對 NPC、中立玩家……在名條範圍之外，以及在地城與團隊副本中，遊戲只有一個控制目標名稱的設定，且無法在戰鬥中變更：它會維持戰鬥開始時的狀態。"
L[" Your target's nameplate, whatever the Nameplates grid says. For some kinds only, name them in its rule (Edit): Enemy players, Hostile NPCs, Neutral players... In dungeons and raids, friendly targets go by Friendly plates in dungeons and raids."] = " 你目標的名條，不論名條表格怎麼設定。若只想用於某些類別，請在其規則中寫出（編輯）：敵方玩家、敵對 NPC、中立玩家……在地城與團隊副本中，友方目標依「地城與團隊副本中的友方名條」而定。"
L["\"%s\" isn't a word it knows"] = "「%s」不是它認得的字詞"
L["\"%s\" isn't in the dropdowns"] = "「%s」不在下拉選單中"
L["\"Boss 2 of 3\" over the name, from the Adventure Guide, as the fight starts (not in a letterbox bar)."] = "戰鬥開始時，在名稱上方顯示來自冒險指南的「首領 2/3」（不在黑邊中）。"
