L["%s is a built-in profile, which everyone has already. To share your changes to it, make a copy with Copy profile on the Profiles page and export that."] = "%s 是內建設定檔，每個人都已經有了。若要分享你對它所做的變更，請在設定檔頁面用「複製設定檔」建立複本，再匯出該複本。"
