L["%s test item"] = "%s 測試物品"
L["%s vs %s"] = "%s 對 %s"
L["%s won"] = "%s 獲勝"
L["%s |cffffd100%.1f%%|r (%.3f ms a frame, %d s)"] = "%s |cffffd100%.1f%%|r（每幀 %.3f 毫秒，%d 秒）"
L["%s's own row is above this one, so it sets its parts first: move this one above it."] = "%s 自己的列在這一列上方，所以會先設定它的部件：請將這一列移到它上方。"
