L["(the emote they did at you)"] = "（他們對你做的表情動作）"
L["+ Add trigger"] = "+ 新增觸發條件"
L["+ New camera"] = "+ 新增鏡頭"
L["+ New scene"] = "+ 新增場景"
L["+ New shot"] = "+ 新增鏡頭片段"
L["+%s ahead"] = "+%s 領先"
L[", doing these"] = "，做這些"
L["-%s behind"] = "-%s 落後"
L["/cine add %s fades it in CineMode, or add it on the Addon Frames page"] = "/cine add %s 可讓它在 CineMode 中淡出，或在插件框架頁面中加入它"
L["/who results"] = "/who 結果"
L["0%: black, like the death screen. 100%: the theme's own color (deep red for blood)."] = "0%：黑色，像死亡畫面一樣。100%：主題本身的顏色（血液為深紅色）。"
L["1 death"] = "1 次死亡"
L["1 minute"] = "1 分鐘"
L["1 need"] = "1 個需求"
L["1 scene"] = "1 個場景"
L["1. Type |cffffd100/cine log|r in chat, or click Open the log below.\n2. The log opens already selected: press Ctrl+C to copy it.\n3. Paste it into your bug report. On Discord it's too long for a message: paste it into a .txt file and attach that.\nIt holds the addon's recent history, any Lua errors and a summary of your setup (game version, changed settings, other addons). It doesn't include your character's name or realm."] = "1. 在聊天中輸入 |cffffd100/cine log|r，或點擊下方的「開啟記錄」。\n2. 記錄開啟時已全選：按 Ctrl+C 複製。\n3. 貼到你的錯誤回報中。在 Discord 上它太長，無法放在一則訊息中：請貼到 .txt 檔案並附加該檔案。\n它包含插件最近的歷程、任何 Lua 錯誤，以及你的設定摘要（遊戲版本、變更過的設定、其他插件）。不包含你角色的名稱或伺服器。"
L["1.85:1"] = "1.85:1"
L["2 minutes"] = "2 分鐘"
L["2.39:1 (cinema)"] = "2.39:1（電影院）"
L["2:1"] = "2:1"
L["30 seconds"] = "30 秒"
L["5 minutes"] = "5 分鐘"
L["< Back"] = "< 返回"
L["<NAME>"] = "<NAME>"
L["A 2.39:1 frame, as at the cinema."] = "2.39:1 的畫面比例，與電影院相同。"
L["A Stop camera button on screen while its steps run (under the release popup when you're dead): click it for your own view back, until what started it is over."] = "步驟執行時在畫面上顯示「停止鏡頭」按鈕（死亡時位於釋放靈魂視窗下方）：點擊即可取回你自己的視角，直到啟動它的事件結束為止。"
L["A big bar in a gold frame, red when you're behind, gold when you lead, loud words."] = "金框中的大計量條，落後時為紅色，領先時為金色，搭配醒目的文字。"
L["A big hit takes"] = "重擊持續"
L["A big hit's flash, and the color the world drains toward."] = "重擊的閃光，以及世界逐漸褪向的顏色。"
L["A black border round its numbers."] = "數字周圍的黑色外框。"
L["A black border around the letters, for see-through backgrounds."] = "文字周圍的黑色外框，適用於透明背景。"
L["A black border around the letters, on every Vision that follows this page."] = "文字周圍的黑色外框，套用於所有依此頁面設定的 Vision。"
L["A black border around the letters, on every page that follows General. The game's: as each page's default has it."] = "文字周圍的黑色外框，套用於所有依「一般」設定的頁面。遊戲的：依各頁面的預設值。"
L["A black border around the letters, so they stand out against the world. Thick + shadow also drops a shadow below and to the right of them."] = "文字周圍的黑色外框，讓文字在世界中更醒目。「粗 + 陰影」還會在文字右下方加上陰影。"
L["A black border around the letters: easier to read with no panel behind them."] = "文字周圍的黑色外框：沒有底板時更容易閱讀。"
L["A black border around the letters: for light words with no panel behind them."] = "文字周圍的黑色外框：適用於沒有底板的淺色文字。"
L["A border in the color beside it around the icon while it flashes."] = "圖示閃爍時，周圍顯示旁邊所選顏色的邊框。"
L["A border around the letters."] = "文字周圍的外框。"
L["A boss"] = "首領"
L["A box where it and its recap show: drag it where you want it, left-click to set, right-click to put it back. Close the settings to see it."] = "顯示它與其回顧的方框：拖曳到你想要的位置，左鍵點擊確定，右鍵點擊還原。關閉設定後即可看到。"
L["A breeze that shows you the way: wind blows across the screen toward your waypoint (your map pin, or the quest you're tracking), in gusts. When it's off the screen, the wind sweeps off the side to turn to. It goes by the way you face, so it's off while you swing the camera round on its own (on retail it follows the game's waypoint marker exactly). A demo for now."] = "為你指路的微風：風會一陣一陣地吹過畫面，朝向你的路徑點（你的地圖標記，或你正在追蹤的任務）。當目標不在畫面上時，風會從畫面一側吹出，提示你該轉向哪邊。它依你面對的方向而定，所以當鏡頭自行旋轉時會關閉（正式版中它完全跟隨遊戲的路徑點標記）。目前為示範功能。"
L["A bubble the game would put at the very top of the screen (someone above you, up some stairs say) shows a little lower instead, below the letterbox bar (or a bit down from the top with the bars off), where you can read it."] = "遊戲原本會放在畫面最頂端的對話泡泡（例如有人在你上方的樓梯上），會改為稍微往下顯示，位於黑邊下方（或關閉黑邊時離頂端稍遠一點），讓你看得到。"
L["A built-in camera: Copy it to change it."] = "內建鏡頭：複製後才能變更。"
L["A button on your talents window opens a talent calculator: your class's three trees side by side, to plan a build without learning anything. Left-click adds a point, right-click takes one back; above the trees, the level the build needs and the points left. It opens in the talents window's place, and a button on it takes you back. It starts from the talents you have; Copy over changes puts what the plan adds in your talents window, to apply there. Also /cine talents."] = "天賦視窗上的一個按鈕會開啟天賦模擬器：你職業的三個天賦樹並排顯示，不必學習任何東西就能規劃配置。左鍵點擊加一點，右鍵點擊收回一點；天賦樹上方顯示此配置所需的等級與剩餘點數。它會在天賦視窗的位置開啟，上面有按鈕可返回。它從你目前的天賦開始；「複製變更」會把計畫新增的天賦放到你的天賦視窗中，在那裡套用。也可用 /cine talents。"
L["A button under the release popup while the death camera's on: click it for your own view back until you release or come back. The Stop the camera key binding does the same."] = "死亡鏡頭開啟時，釋放靈魂視窗下方的一個按鈕：點擊即可取回你自己的視角，直到你釋放靈魂或復活。「停止鏡頭」按鍵設定的作用相同。"
L["A change here starts a profile of your own, %s."] = "在此做出變更會建立你自己的設定檔：%s。"
L["A chat message is peeking"] = "有聊天訊息正在短暫顯示"
L["A close, gentle zoom: it starts by easing in to the close-up distance below, then drifts a little in and out around it."] = "近距離、輕柔的縮放：先緩緩拉近到下方設定的特寫距離，然後在其附近輕微地前後飄移。"
L["A color of your own (the swatch), for both lines."] = "你自己選的顏色（色塊），套用於兩行。"
L["A color of your own (the swatch)."] = "你自己選的顏色（色塊）。"
L["A copy of this camera's script, yours to change, and its tab opened."] = "此鏡頭腳本的複本，可由你變更，並開啟它的分頁。"
L["A copy of this script, yours to change."] = "此腳本的複本，可由你變更。"
L["A crown"] = "王冠"
L["A crown and the number in its color."] = "王冠，以及以其顏色顯示的數字。"
L["A damage dealer (or anyone without a role) shows once their health drops below this. 100% shows them at any damage; lower keeps them hidden through small hits."] = "傷害輸出者（或沒有職責的任何人）的生命值降到此值以下時顯示。100% 表示受到任何傷害都顯示；較低的值可讓小傷害時保持隱藏。"
L["A dark copy of the letters just behind them, down and to the right."] = "文字正後方、偏右下方的一層深色複本。"
L["A dark copy of the letters just behind them, to lift them off the world."] = "文字正後方的一層深色複本，讓文字從世界中浮現出來。"
L["A dark fill over the icon, going down as the cooldown runs out."] = "圖示上的深色填色，隨冷卻結束而逐漸下降。"
L["A dark panel behind it all, this dark. 0: none."] = "整體後方的深色底板，此為其深度。0：無。"
L["A dark panel in the rounded edge of the game's roll frames, in the item's quality color."] = "遊戲擲骰框架圓角邊緣內的深色底板，使用物品品質的顏色。"
L["A dark panel with a thin line round it, in the item's quality color."] = "帶有細框線的深色底板，使用物品品質的顏色。"
L["A debuff that brings them up keeps them up while you have any debuff (bar the ones listed below), however long that is, fights included."] = "讓它們顯示的減益，會在你身上有任何減益（下方清單中的除外）期間保持顯示，無論多久，包括戰鬥中。"
L["A dungeon"] = "地城"
L["A feared, stunned, polymorphed, rooted or silenced duelist gets an icon of the spell beside their nameplate, with the time left."] = "受到恐懼、昏迷、變形、定身或沉默的決鬥者，名條旁會出現該法術的圖示及剩餘時間。"
L["A fight you go into with your mana, rage, energy or the like at rest (rage at 0, mana full...) brings up your resource bar only once it changes: your first cast, your first hit. Going in with it still filling or draining, it comes up straight away. It stays up for the rest of the fight."] = "進入戰鬥時，若你的法力、怒氣、能量等處於靜止狀態（怒氣為 0、法力全滿……），資源條只會在它變動時才出現：你的第一次施法、第一次攻擊。若進入戰鬥時它仍在充填或消耗中，就會立即出現。之後它會在整場戰鬥中保持顯示。"
L["A film's frame"] = "電影畫面"
L["A flat bubble in a color of your own (the swatch)."] = "使用你自己所選顏色（色塊）的平面泡泡。"
L["A flat dark bubble."] = "深色平面泡泡。"
L["A flat fill in your colors on a dark ground, a thin black edge, Arial Narrow, the seconds left."] = "深色底上以你的顏色平塗填色，細黑邊，Arial Narrow 字型，顯示剩餘秒數。"
L["A glow along the row, a crown and the number in its color."] = "沿著該列的光暈、王冠，以及以其顏色顯示的數字。"
L["A golden exclamation mark beside their nameplates' health bars, wherever their plates show (beside their names when just their names show). Always on with Quest mark above. Needs the Nameplates page enabled."] = "在他們名條的生命條旁顯示金色驚嘆號，凡是名條顯示的地方都有（只顯示名稱時則在名稱旁）。勾選上方「任務標記」時一律開啟。需要啟用名條頁面。"
L["A group of your own, to pick its frames and icon."] = "你自己的群組，可選擇它的框架與圖示。"
L["A healer shows once their health drops below this. 100% shows them at any damage; lower keeps them hidden through small hits."] = "治療者的生命值降到此值以下時顯示。100% 表示受到任何傷害都顯示；較低的值可讓小傷害時保持隱藏。"
L["A line of text to copy and paste to friends, who add it with Import a wheel."] = "一行可複製並貼給朋友的文字，他們可用「匯入輪盤」加入。"
L["A little icon before each detail: a map, a watch, a quest mark, a skull, coins..."] = "每項細節前的小圖示：地圖、手錶、任務標記、骷髏、錢幣……"
L["A made-up fight for 25 seconds, to see how it looks (Stop ends it). It works with the page off too. Close the settings to see it."] = "一場持續 25 秒的模擬戰鬥，用來看看效果（「停止」可結束）。即使此頁面關閉也有效。關閉設定後即可看到。"
L["A member with a debuff you can dispel shows, at full health too."] = "身上有你可驅散之減益的成員會顯示，即使生命值全滿也一樣。"
L["A member with any debuff at all shows, at full health too."] = "身上有任何減益的成員都會顯示，即使生命值全滿也一樣。"
L["A message shows"] = "有訊息顯示"
L["A minimap blip's tooltip, which always shows"] = "小地圖光點的滑鼠提示，它一律會顯示"
L["A name of your own for it, shown on the rows. Empty: what starts it."] = "你自己為它取的名稱，顯示在各列上。留空：顯示啟動它的事件。"
L["A name of your own for this row, shown on the grid and the preview, say Far trash. Empty: its kind's name."] = "你自己為此列取的名稱，顯示在表格與預覽中，例如「遠處小怪」。留空：顯示其類別名稱。"
L["A name of your own for this row, shown on the grid, say AFK in dungeons. Empty: its trigger's."] = "你自己為此列取的名稱，顯示在表格中，例如「地城中暫離」。留空：顯示其觸發條件的名稱。"
L["A new camera of yours, with a few steps to start from."] = "你的新鏡頭，附帶幾個步驟作為起點。"
L["A new name for this theme of yours."] = "你這個主題的新名稱。"
L["A new rule above the last one, for the fights you pick."] = "在最後一條規則上方新增一條規則，用於你所選的戰鬥。"
L["A new rule at the end, for the places you pick (move it up to read it first)."] = "在最後新增一條規則，用於你所選的地點（上移可讓它優先判斷）。"
L["A new rule at the end, for the time of day and places you pick."] = "在最後新增一條規則，用於你所選的時段與地點。"
L["A new rule for boss fights, first on this tab."] = "新增一條首領戰規則，放在此分頁的最前面。"
L["A new script of yours, with a few steps to start from."] = "你的新腳本，附帶幾個步驟作為起點。"
L["A pet shows once its health drops below this. 100% shows it at any damage."] = "寵物的生命值降到此值以下時顯示。100% 表示受到任何傷害都顯示。"
L["A picture: red with a dark outline, on a flat black band, its own colors."] = "圖片：紅色帶深色外框，位於平面黑色帶上，使用自身的顏色。"
L["A plate takes its whole look (mark, colors, opacity) from the first row that fits it, top to bottom; the rows below aren't looked at. Click a row to open its settings: its mark, the plate's colors and opacity, and When it fits. The chips beside its name show what's set apart from the usual. Move a row with its arrows, copy it with its two squares, take it off with its x. Add row puts a new one at the end; its Row line says what it's for: a Kind, for Aggro and Units which of them, Who for just its enemies, neutral units or friends, and Distance for just those within or past 11, 28 or 40 yards (Any unit past 40 yards fades far plates). The same kind again is another row of it (Target (2)), say with a different When for raids. Put a row for just some units above its kind's own row, so it comes first for them. Default, always last, is for plates no row fits: the game's look unless you change it."] = "名條會從上到下，套用第一個符合它的列的完整外觀（標記、顏色、不透明度）；下方的列不會再判斷。點擊某列可開啟其設定：它的標記、名條的顏色與不透明度，以及「符合時機」。名稱旁的標籤顯示與一般不同的設定。用箭頭移動列，用兩個方塊複製列，用 x 移除列。「新增列」會在最後加入新列；其「列」一行說明用途：類別、仇恨與單位要選哪一種、「對象」只限敵方、中立單位或友方，以及「距離」只限 11、28 或 40 碼以內或以外的單位（「40 碼外的任何單位」可淡出遠處名條）。同一類別再加一次就是它的另一列（目標 (2)），例如為團隊副本設定不同的「符合時機」。將只限部分單位的列放在其類別本身的列上方，讓它對那些單位優先。「預設」永遠在最後，用於沒有任何列符合的名條：除非你變更，否則為遊戲的外觀。"
L["A player's class icon in place of their face (NPCs keep theirs)."] = "以玩家的職業圖示取代其臉孔（NPC 保留自己的）。"
L["A pretend 8-second cast, on the screen (close the settings to see it)."] = "畫面上模擬的 8 秒施法（關閉設定後即可看到）。"
L["A profile of your own, a copy of the active one as you have it now, named after it. To copy another profile, right-click it, then Copy profile."] = "你自己的設定檔，是目前設定檔現況的複本，並以它命名。若要複製其他設定檔，請在它上面按右鍵，然後選「複製設定檔」。"
L["A profile of your own, a copy of the active one as you have it now, named after it. To copy another profile, switch to it first."] = "你自己的設定檔，是目前設定檔現況的複本，並以它命名。若要複製其他設定檔，請先切換到該設定檔。"
L["A profile preview shows just its own frames"] = "設定檔預覽只顯示它自己的框架"
L["A quest timer is running"] = "有任務計時器正在計時"
L["A quiet flat bar: no icon, spark or border, a soft ground, small outlined text."] = "安靜的平面計量條：沒有圖示、火花或邊框，柔和的底色，帶外框的小字。"
L["A ring of color round it."] = "環繞它的一圈顏色。"
L["A round button with a soft glow when ready."] = "就緒時帶有柔和光暈的圓形按鈕。"
L["A scene of your own. Open it to set its triggers, when it ends, and where it comes among the others."] = "你自己的場景。開啟它以設定其觸發條件、何時結束，以及它在其他場景中的順序。"
L["A script holds 80 steps at most."] = "一個腳本最多容納 80 個步驟。"
L["A set time"] = "固定時間"
L["A shot is one of the cameras that run while you stand still (cozy, vista, fish or AFK) with numbers of your own for how it sways and zooms. Make one here, then pick it as a scene's camera on the Scenes page. A number you haven't changed follows the camera's own settings."] = "鏡頭片段是你站著不動時運作的鏡頭之一（悠閒、遠景、釣魚或暫離），使用你自己設定的擺動與縮放數值。在此建立一個，然後在場景頁面中將它選為某個場景的鏡頭。你沒有變更的數值會依照該鏡頭本身的設定。"
L["A slider changes nothing until you move it. Higher (in gold) costs frame rate, lower (in blue) saves it. Tick and untick a setting to compare it with the game's own; Reset page leaves them all alone again."] = "滑桿在你移動它之前不會改變任何東西。較高（金色）會降低幀數，較低（藍色）可提升幀數。勾選再取消勾選某項設定，可與遊戲本身的設定比較；「重置頁面」會讓它們全部恢復不受影響。"
L["A small Reload button at the top of the screen reloads the UI in one click. It stays up with the UI hidden. Drag it to move it. There's a key for it too (Keybinds page)."] = "畫面頂端的小型「重新載入」按鈕，點一下即可重新載入介面。介面隱藏時它仍保持顯示。拖曳可移動。也有對應的按鍵（按鍵設定頁面）。"
L["A small icon in the bottom right of a chat window, while your mouse is over it, opens that window's lines as text you can select and copy with Ctrl+C."] = "滑鼠移到聊天視窗上時，右下角會出現一個小圖示，可將該視窗的內容開啟為文字，讓你選取並用 Ctrl+C 複製。"
L["A small line low on the screen, where a film's subtitles go."] = "畫面下方的一小行字，位於電影字幕的位置。"
L["A soft halo round it."] = "環繞它的柔和光環。"
L["A soft haze around the edges of the screen in the camera modes, as if the camera had focused on you. Each camera mode's page sets its own strength: this turns them all up or down. /cine doftest shows it on demand."] = "鏡頭模式中，畫面邊緣出現柔和的朦朧感，彷彿鏡頭對焦在你身上。每個鏡頭模式的頁面各自設定強度：此處可整體調高或調低。/cine doftest 可隨時顯示效果。"
L["A soft haze around the edges of the screen in this camera mode, as if the camera had focused on you. 0% leaves it off. Moving the slider shows it for a moment. Needs \"Camera haze\" on the Visual Effects page, which also turns it up or down."] = "此鏡頭模式中，畫面邊緣出現柔和的朦朧感，彷彿鏡頭對焦在你身上。0% 表示關閉。移動滑桿時會短暫顯示效果。需要開啟視覺效果頁面中的「鏡頭朦朧」，它也可整體調高或調低。"
L["A soft haze around the edges of the screen while this camera runs, as if it had focused on you. 0 leaves it off. Needs Camera haze on the Visual Effects page, which also turns it up or down."] = "此鏡頭運作時，畫面邊緣出現柔和的朦朧感，彷彿它對焦在你身上。0 表示關閉。需要開啟視覺效果頁面中的「鏡頭朦朧」，它也可整體調高或調低。"
L["A string of this script to give to friends."] = "此腳本的字串，可分享給朋友。"
L["A style with +2 has two settings of its own over the one it starts from (the Style tab lists them)."] = "標有 +2 的樣式，比起它所依據的樣式多了兩項自己的設定（樣式分頁會列出）。"
L["A tank (by role, or main tank in a raid) shows once their health drops below this. 100% shows tanks always, at full health too."] = "坦克（依職責，或團隊中的主坦克）的生命值降到此值以下時顯示。100% 表示坦克一律顯示，生命值全滿時也一樣。"
L["A theme of your own, made from the one shown."] = "你自己的主題，以目前顯示的主題為基礎建立。"
L["A thick black border around the letters."] = "文字周圍的粗黑色外框。"
L["A thin black border around the letters."] = "文字周圍的細黑色外框。"
L["A thin black edge, the icon zoomed in to cut its border, an edge glow when ready, Arial Narrow."] = "細黑邊，圖示放大以裁掉邊框，就緒時邊緣發光，Arial Narrow 字型。"
L["A thin line, no border or spark."] = "細線，沒有邊框或火花。"
L["A wave of the game's art creeping in from past the edges on each heartbeat (each second without one). With Blizzard art, or a Game art theme."] = "每次心跳（沒有心跳時每秒一次），遊戲美術圖從畫面邊緣外漸漸湧入的波動。搭配 Blizzard 美術圖，或「遊戲美術圖」主題。"
L["A whole look in one pick. Changing a setting after it shows Custom; picking Custom puts back your own settings from before the preset."] = "一次選定整體外觀。之後變更任何設定會顯示為「自訂」；選擇「自訂」會還原你套用預設之前的設定。"
L["ANY OF THESE WOULD SHOW IT"] = "以下任一項都會讓它顯示"
L["Achievement"] = "成就"
L["Across the middle of the screen on a dark band with soft edges, coming in and going slowly, as YOU DIED does."] = "在畫面中央柔和邊緣的深色帶上，緩緩出現再緩緩消失，就像「你死了」一樣。"
L["Action bars 1-3"] = "快捷列 1-3"
L["Add %s"] = "加入 %s"
L["Add a rule"] = "新增規則"
L["Add a scene or shot a friend shared (the text from their Share button)."] = "加入朋友分享的場景或鏡頭片段（他們「分享」按鈕產生的文字）。"
L["Add a script someone shared with you."] = "加入別人分享給你的腳本。"
L["Add a sound"] = "加入音效"
L["Add a wheel someone shared with you: paste in its text, and read what's on it before you add it."] = "加入別人分享給你的輪盤：貼上它的文字，加入前先看看上面有什麼。"
L["Add an emote"] = "加入表情動作"
L["Add an emote: %s"] = "加入表情動作：%s"
L["Add an icon"] = "加入圖示"
L["Add back"] = "加回"
L["Add back all"] = "全部加回"
L["Add it"] = "加入"
L["Add it to the rows below, with its When set to anywhere but battlegrounds and arenas, out of fights (open its row to change that)."] = "將它加入下方各列，其「符合時機」設為戰場與競技場以外的任何地方、非戰鬥中（開啟其列即可變更）。"
L["Add row"] = "新增列"
L["Add script"] = "加入腳本"
L["Add this zone"] = "加入此區域"
L["Add wheel"] = "加入輪盤"
L["Added"] = "已加入"
L["Addon"] = "插件"
L["Addons installed but not loaded, and the ones supported but not installed."] = "已安裝但未載入的插件，以及支援但未安裝的插件。"
L["Adds \"%s\". A green dot: true where you are now."] = "加入「%s」。綠點：在你目前所在之處成立。"
L["Adds \"%s\": true for a tooltip of this kind (one can be more than one: a quest mob is an enemy too). Anything else: none of the others, and every tooltip of the UI."] = "加入「%s」：對此類滑鼠提示成立（一個提示可以同時屬於多類：任務怪也是敵人）。「其他任何」：不屬於其他任何一類，以及介面的所有滑鼠提示。"
L["Adds a row at the end of the grid, for any unit to start with, its settings open: pick what it's for on its Row line, and its look."] = "在表格最後新增一列，起初適用於任何單位，並開啟其設定：在其「列」一行選擇用途，以及其外觀。"
L["Adds a theme a friend shared with Share theme."] = "加入朋友用「分享主題」分享的主題。"
L["Adds an icon to the wheel, for a command of its own."] = "在輪盤上加入一個圖示，用於它自己的指令。"
L["After"] = "之後"
L["After a Zone or Subzone card, no other comes for this long, so passing through places quickly doesn't bring one after another. 0: every time."] = "顯示區域或子區域卡片後，在這段時間內不會再出現其他卡片，這樣快速經過各地時就不會一張接一張地出現。0：每次都顯示。"
L["After a fight"] = "戰鬥後"
L["After a reload (/reload, the Reload button or its key), what you had open opens again: these settings at the page you were on, your bags, the character window, map, spellbook and the game's other windows, and Cinematic's own."] = "重新載入後（/reload、「重新載入」按鈕或其按鍵），你先前開啟的東西會再次開啟：這些設定及你所在的頁面、你的背包、角色視窗、地圖、法術書及遊戲的其他視窗，以及 Cinematic 自己的視窗。"
L["After swinging behind you, the camera comes round this far to one side, so you see the quest giver past you at an angle rather than straight over your head. 0 stays straight behind you. It turns back behind you as the window closes."] = "轉到你身後後，鏡頭會再轉向一側這麼多，讓你從斜角越過自己看到任務 NPC，而不是直接從頭頂看過去。0 表示保持在你正後方。視窗關閉時它會轉回你身後。"
L["After the first pull-back, keep drifting to new random distances (within the limits below), pausing between each. Off: a single pull-back that then holds."] = "第一次拉遠後，持續飄移到新的隨機距離（在下方的限制內），每次之間會停頓。關閉：只拉遠一次，然後保持不動。"
L["After you drag the camera, use camera keys or zoom, this camera waits this long, then carries on from your new view."] = "在你拖曳鏡頭、使用鏡頭按鍵或縮放後，此鏡頭會等待這段時間，然後從你的新視角繼續。"
L["After you log in or /reload, the camera zooms to the distance below, rather than staying wherever you left it."] = "登入或 /reload 後，鏡頭會縮放到下方的距離，而不是停留在你離開時的位置。"
L["After you stop turning, the view holds this long before gliding around to your new facing, in case you turn again. Turning again starts the wait over."] = "你停止轉向後，視角會保持這段時間，然後才平滑轉到你的新面向，以防你再次轉向。再次轉向會重新開始等待。"
L["Aggro"] = "仇恨"
L["Aggro on a healer"] = "治療者獲得仇恨"
L["Aggro on non-tank"] = "非坦克獲得仇恨"
L["Aggro on not you"] = "仇恨不在你身上"
L["Aggro on you"] = "仇恨在你身上"
L["Align:"] = "對齊："
L["All"] = "全部"
L["All addons"] = "所有插件"
L["All addons %.1f%% (%.3f ms)"] = "所有插件 %.1f%%（%.3f 毫秒）"
L["All addons (the game's figures, ms a frame)"] = "所有插件（遊戲的數據，每幀毫秒）"
L["All bosses"] = "所有首領"
L["All changes"] = "所有變更"
L["All marks"] = "所有標記"
L["All of them"] = "全部"
L["All rows"] = "所有列"
L["Along the top"] = "沿著頂端"
L["Already on this card (or the card is full). Right-click: play it."] = "已在此卡片上（或卡片已滿）。右鍵：播放。"
L["Also for NPCs with nothing to say about quests (innkeepers, guards...), as the \"Talk to a quest giver\" event. Off: only when they have a quest to offer or take in, or a \"(Quest)\" line (the \"Talk about a quest\" event)."] = "也適用於沒有任務可談的 NPC（旅店老闆、衛兵……），作為「與任務 NPC 對話」事件。關閉：只在他們有任務可提供或交付，或有「（任務）」一行時（「談論任務」事件）。"
L["Always backed up just before Delete and Reset, and the saved version on Save."] = "在「刪除」和「重置」之前一律會備份，「儲存」時則備份已儲存的版本。"
L["Always is ticked"] = "已勾選「一律」"
L["Always is ticked on the Tooltips row"] = "滑鼠提示列已勾選「一律」"
L["Always list your own roll"] = "一律列出你自己的擲骰"
L["Always show the waypoint is on"] = "「一律顯示路徑點」已開啟"
L["Always show their"] = "一律顯示其"
L["Amber while you're behind, teal once you lead (or your own two)."] = "落後時為琥珀色，領先時為藍綠色（或你自己的兩種顏色）。"
L["Amount"] = "數量"
L["An NPC you're talking to (its window open, or closed in the last 30 seconds), your target, or a party NPC talking (their chat bubbles). The camera zooms in and swings toward whoever's talking, drifting while they go on, and turns back once no one's talked for a while. Moving hands the camera straight back to you. Its settings are under Chat Cam on the Camera Settings page."] = "你正在對話的 NPC（其視窗開啟中，或在 30 秒內關閉）、你的目標，或正在說話的隊伍 NPC（他們的對話泡泡）。鏡頭會拉近並轉向說話者，在對方持續說話時飄移，在一段時間沒有人說話後轉回。移動會立即將鏡頭交還給你。其設定位於鏡頭設定頁面的「聊天鏡頭」下。"
L["An addon"] = "插件"
L["An edge"] = "邊緣"
L["An icon before the words: each event's own (a map for a zone, a skull for a boss...), unless it's given another with the button beside this."] = "文字前的圖示：各事件自己的圖示（區域為地圖、首領為骷髏……），除非用旁邊的按鈕指定其他圖示。"
L["Animation:"] = "動畫："
L["Another of the game's effects over the first, added on as light and cut by the same edge (not over an edge like the red one). Theme's pick: the one picked to go with your theme, if any."] = "在第一個效果上再疊加遊戲的另一個效果，以光線方式加上，並以相同邊緣裁切（不會疊在紅色那類邊緣上）。主題的選擇：搭配你主題所選的效果（如果有）。"
L["Another thing that starts this scene: any one of its triggers starts it."] = "另一個會啟動此場景的事件：它的任何一個觸發條件都會啟動它。"
L["Any"] = "任何"
L["Any distance"] = "任何距離"
L["Any distance: all of them, near or far. Within or past 11, 28 or 40 yards: just those that far from you, say Any unit past 40 yards to fade the plates far off. 40 yards asks a 40-yard spell on your action bars; with none there, the row fits no unit past 28 yards."] = "任何距離：全部，無論遠近。11、28 或 40 碼以內或以外：只限距離你那麼遠的單位，例如「40 碼外的任何單位」可淡出遠處的名條。40 碼需要你的快捷列上有一個 40 碼的法術；若沒有，此列不會符合 28 碼以外的任何單位。"
L["Any edge"] = "任何邊緣"
L["Any enemy attacking a healer (you too, if you're one): for a healer, who's after you or the other healers; for a tank, the ones to pull off them."] = "任何正在攻擊治療者的敵人（如果你是治療者，也包括你）：對治療者而言，是在追你或其他治療者的敵人；對坦克而言，是要從他們身上拉走的敵人。"
L["Any enemy attacking a player who isn't a tank (you too, unless you're one): for a healer, who's in trouble; for a tank, the ones to taunt. A pet tanking doesn't count."] = "任何正在攻擊非坦克玩家的敵人（除非你是坦克，否則也包括你）：對治療者而言，是誰有危險；對坦克而言，是要嘲諷的敵人。寵物坦怪不算。"
L["Any enemy attacking you (you have its aggro). Above the Target row, or that one wins on your target. A cell set to Your target's takes the Target row's; change it to set this one apart."] = "任何正在攻擊你的敵人（你有它的仇恨）。放在目標列上方，否則目標列會在你的目標上優先。設為「你目標的」的儲存格會採用目標列的設定；變更它即可讓此列不同。"
L["Any enemy in a fight attacking someone friendly other than you: a group member, a pet or another player. For a tank, the ones to pick up."] = "戰鬥中任何正在攻擊你以外友方對象的敵人：隊伍成員、寵物或其他玩家。對坦克而言，是要接手的敵人。"
L["Any enemy in a fight attacking whoever its ticks say: you or someone friendly other than you, and their role (no role set counts as DPS; a pet only with all three roles ticked)."] = "戰鬥中任何正在攻擊其勾選對象的敵人：你或你以外的友方對象，以及其職責（未設定職責算作傷害輸出；寵物只有在三種職責都勾選時才算）。"
L["Any fight"] = "任何戰鬥"
L["Any living NPC, normal or elite."] = "任何活著的 NPC，普通或精英。"
L["Any time"] = "任何時候"
L["Any unit"] = "任何單位"
L["Anyone"] = "任何人"
L["Anything a player controls: pets, totems and guardians."] = "玩家控制的任何東西：寵物、圖騰與守護者。"
L["Anything else"] = "其他任何"
L["Anything targeted"] = "任何被選取的對象"
L["Arcade"] = "街機"
L["Arenas"] = "競技場"
L["Arrived"] = "已抵達"
L["Arrow"] = "箭頭"
L["Arrows and bullets at a vendor get a Fill button: it buys enough to fill your quiver or ammo pouch, topping up its part stacks and filling its empty slots, as far as your money goes. Point at it to see how many and the cost first."] = "在商人處購買箭矢與子彈時會出現「填滿」按鈕：在你的金錢範圍內，買足以填滿箭袋或彈藥袋的數量，補齊未滿的堆疊並填滿空格。先將滑鼠指向它，可看到數量與花費。"
L["Art"] = "美術圖"
L["As NPCs talk near you, the camera zooms in and swings toward whoever's talking (by their chat bubble), drifting slowly while they go on. It swings again only when someone else speaks, and turns back and zooms out once no one's talked for a while. Moving, or moving the camera yourself, hands it straight back to you."] = "當附近的 NPC 說話時，鏡頭會拉近並轉向說話者（依其對話泡泡），在對方持續說話時緩緩飄移。只有在其他人開口時才會再次轉向，一段時間沒有人說話後就會轉回並拉遠。移動，或自己移動鏡頭，會立即將鏡頭交還給你。"
L["As Roll Vision has always looked (the defaults)."] = "Roll Vision 一直以來的外觀（預設值）。"
L["As a fight starts or as it ends. Click to switch."] = "戰鬥開始時或結束時。點擊切換。"
L["As it always has, in its own look (the Style tab)."] = "照原本的方式，使用它自己的外觀（樣式分頁）。"
L["As it comes: amber when you're behind, teal when you lead, a thin border."] = "原樣：落後時為琥珀色，領先時為藍綠色，細邊框。"
L["As it comes: nothing changed."] = "原樣：沒有任何變更。"
L["As it shows"] = "顯示時"
L["As it starts, the camera rises this much to look down on your body; it comes back down afterwards. The game stops it just short of straight down, so a big number means \"as high as it goes\". 0 keeps your angle."] = "開始時，鏡頭會升高這麼多以俯視你的屍體；之後再降回來。遊戲會讓它停在接近正下方之前，所以很大的數值代表「能升多高就升多高」。0 表示保持你的角度。"
L["As it swings round, the camera also comes down this much toward the ground, so it feels low and close rather than looking down from above. It stops at the ground, so a big number just means \"as low as it goes\". 0 keeps your angle."] = "環繞時，鏡頭也會朝地面下降這麼多，讓畫面感覺低而貼近，而不是從上方俯視。它會停在地面，所以很大的數值只代表「能降多低就降多低」。0 表示保持你的角度。"
L["As little UI as possible: nameplates show only for enemies in fights, and fights don't bring the letterbox down. Fights bring up only your resource bar and the Cooldown Manager, the cast bar shows all through CineMode, your health shows at the screen's edges and your personal resource display fades in as it drops (Vitals Vision), and every camera can start music."] = "盡可能減少介面：名條只在戰鬥中顯示敵人，戰鬥不會撤下黑邊。戰鬥只會顯示你的資源條與冷卻管理器，施法條在 CineMode 期間全程顯示，你的生命值顯示在畫面邊緣，個人資源顯示在生命值下降時淡入（Vitals Vision），且每個鏡頭都能播放音樂。"
L["As the Style hub's General page says."] = "依「風格」分類的一般頁面設定。"
L["As the Visions hub's Style page says."] = "依「Vision」分類的樣式頁面設定。"
L["As the boss is pulled, as it dies or as your group wipes. Click to switch."] = "拉到首領時、首領死亡時或隊伍滅團時。點擊切換。"
L["As the card shows."] = "依卡片顯示的設定。"
L["As the game's options say (class colors, or green)."] = "依遊戲選項設定（職業顏色或綠色）。"
L["As you cast your Hearthstone, Astral Recall or a teleport, a portal's glowing rim closes in around you, brighter and turning quicker as the cast fills, and flashes as you're whisked away. It shows whenever the tele camera would play for that cast (Cameras), with or alongside it."] = "當你使用爐石、星界傳送或施放傳送時，一道傳送門的發光邊緣會向你收攏，隨施法進度變得更亮、轉得更快，並在你被傳走時閃光。只要該次施法會播放傳送鏡頭（鏡頭頁面），它就會顯示，可單獨出現或與鏡頭一起出現。"
L["As you land, the camera glides back to the zoom distance you had when you took off. If you zoomed yourself on the way, it stays where you put it."] = "降落時，鏡頭會平滑地回到你起飛時的縮放距離。若你在途中自己縮放過，則保持在你設定的位置。"
L["At full"] = "全滿時"
L["At most this many rows: #1 on down, and you in the last row if you're further down than that."] = "最多顯示這麼多列：從第 1 名往下，若你的排名更後面，則你會顯示在最後一列。"
L["At the start of a fight"] = "戰鬥開始時"
L["Auras"] = "光環"
L["Auras anchored to another frame fade with that frame."] = "依附在其他框架上的光環會隨該框架淡出。"
L["Auto"] = "自動"
L["Auto (%s)"] = "自動（%s）"
L["Auto-running. The camera's settings are under Auto-run Cam on the Camera Settings page."] = "自動奔跑。鏡頭的設定位於鏡頭設定頁面的「自動奔跑鏡頭」下。"
L["Auto-walking (auto-run in walk mode). The camera's settings are under RP Walk Cam on the Camera Settings page."] = "自動行走（行走模式下的自動奔跑）。鏡頭的設定位於鏡頭設定頁面的「RP 漫步鏡頭」下。"
L["Automatic"] = "自動"
L["Average"] = "平均"
L["Away"] = "離開"
L["BG objectives"] = "戰場目標"
L["Back as it comes:"] = "原樣還原："
L["Back to every card's row."] = "回到每張卡片的列。"
L["Back to its own settings"] = "回到它自己的設定"
L["Back to its style:"] = "回到它的樣式："
