L["Cast Fishing (or any event set to it on the Scenes page): the vista camera, made for fishing. The camera glides around behind you and sways only a little either side, so your bobber stays in view. It carries on after the cast until you move or jump."] = "施放釣魚（或在場景頁面中設為此鏡頭的任何事件）：專為釣魚設計的遠景鏡頭。鏡頭會平滑轉到你身後，只向兩側輕微擺動，讓你的浮標保持在畫面中。施法後仍會繼續，直到你移動或跳躍。"
L["Cast bar is the bar under the target and focus frames as they cast."] = "施法條是目標與專注目標框架在施法時，其下方的計量條。"
L["Cast bar style"] = "施法條樣式"
L["Casting your Hearthstone or a teleport, the camera swings round in front of you, quickly enough to be there before you go, then spins around you faster and faster as it zooms in. Cancel the cast and it goes back to where it was; once you're there, it swings around behind you. Its music, haze and tooltips follow the Cozy Cam's settings. The events on the Scenes page can also make it wait a moment."] = "使用爐石或施放傳送時，鏡頭會轉到你前方，速度快到能在你傳走前就位，接著一邊拉近一邊繞著你越轉越快。取消施法時它會回到原位；抵達後，它會轉到你身後。它的音樂、朦朧與滑鼠提示依照悠閒鏡頭的設定。場景頁面中的事件也可以讓它稍等片刻。"
