L["DPS"] = "傷害輸出"
L["Daily"] = "每日"
L["Damage"] = "傷害"
L["Damage Vision"] = "Damage Vision"
L["Damage Vision test: a made-up fight for 25 seconds. Close the settings to see it."] = "Damage Vision 測試：一場持續 25 秒的模擬戰鬥。關閉設定後即可看到。"
L["Damage Vision:"] = "Damage Vision："
L["Damage report"] = "傷害報告"
L["Damage taken alert"] = "受到傷害警示"
L["Dark"] = "深色"
L["Dark and flat with a thin edge, names in class and reaction colors, in Arial Narrow."] = "深色平面帶細邊，名稱使用職業與反應顏色，Arial Narrow 字型。"
L["Dark fill, draining"] = "深色填色，逐漸消退"
L["Dark ground"] = "深色底"
L["Darkness"] = "黑暗"
L["Dawn, Morning, Midday, Afternoon, Evening, Dusk or Night as you log in or reload: over the name on this card, or under the game's zone name with Zone unticked. Follows the clock picked on the Tint page."] = "登入或重新載入時顯示黎明、早晨、正午、午後、傍晚、黃昏或夜晚：顯示在此卡片的名稱上方，或在未勾選「區域」時顯示在遊戲的區域名稱下方。依色調頁面所選的時鐘而定。"
L["Day/night dial"] = "日夜轉盤"
L["Dead"] = "死亡"
L["Dead members are hidden whatever their health, debuffs or role (unless one is your target). How much of them still shows. 0% hides them completely."] = "死亡的成員不論生命值、減益或職責都會隱藏（除非是你的目標）。此為他們仍顯示的程度。0% 表示完全隱藏。"
L["Dead opacity"] = "死亡時不透明度"
L["Death banner:"] = "死亡橫幅："
L["Deaths"] = "死亡次數"
L["Debuffs that last longer than this (their full time, not what's left: Deserter, Resurrection Sickness...) don't bring them up, nor keep them up until gone. Not in fights, when what they are can't be seen. Buffs always do."] = "持續時間比此更長的減益（指其完整時間而非剩餘時間：逃亡者、復活虛弱……）不會讓它們顯示，也不會讓它們保持顯示直到消失。戰鬥中無法得知減益是什麼，所以不適用。增益則一律會。"
L["Default"] = "預設"
L["Defeat"] = "失敗"
L["Delete the camera %s? Scenes set to it go back to no camera."] = "要刪除鏡頭 %s 嗎？設為此鏡頭的場景會改回無鏡頭。"
L["Delete the scene %s and its settings?"] = "要刪除場景 %s 及其設定嗎？"
L["Delete the scene %s? It starts no camera until you bring it back with Add back, above the rows (its settings are kept)."] = "要刪除場景 %s 嗎？在你用各列上方的「加回」找回它之前，它不會啟動任何鏡頭（其設定會保留）。"
L["Delete the shot %s? Scenes that played it go back to its camera."] = "要刪除鏡頭片段 %s 嗎？播放它的場景會改回其鏡頭。"
L["Delete the theme %s?"] = "要刪除主題 %s 嗎？"
L["Delete the wheel %s?"] = "要刪除輪盤 %s 嗎？"
L["Delete this scene of your own, with its copies."] = "刪除你自己的這個場景，連同其複本。"
L["Delete this scene: its rows go and it starts no camera. Add back, above the rows, brings it back with its settings."] = "刪除此場景：它的各列會移除，也不再啟動任何鏡頭。各列上方的「加回」可連同其設定找回它。"
L["Delete this shot. Scenes that played it go back to its camera."] = "刪除此鏡頭片段。播放它的場景會改回其鏡頭。"
L["Delete wheel"] = "刪除輪盤"
L["Deleted"] = "已刪除"
L["Deleted %s, kept until %s"] = "已刪除 %s，保留至 %s"
L["Deletes this script (click twice). Rows set to it go back to no camera."] = "刪除此腳本（點擊兩次）。設為此腳本的列會改回無鏡頭。"
L["Deletes this theme of yours."] = "刪除你的這個主題。"
L["Deletes this wheel, and takes its keys off."] = "刪除此輪盤，並解除其按鍵設定。"
L["Departing"] = "出發中"
L["Describe the camera:"] = "描述鏡頭："
L["Detailed"] = "詳細"
L["Detailed CPU recording  %d:%02d"] = "詳細 CPU 記錄  %d:%02d"
L["Detailed CPU recording for %d seconds: play as usual."] = "詳細 CPU 記錄 %d 秒：照常遊戲即可。"
L["Details"] = "詳細資訊"
L["Dialogue"] = "對話"
L["Diamond"] = "菱形"
L["Dim"] = "暗淡"
L["Discovered"] = "已發現"
L["Do /%s"] = "執行 /%s"
L["Dock"] = "停靠"
L["Dots:"] = "圓點："
L["Drag over the lines you want (or Select all), then press Ctrl+C to copy them."] = "拖曳選取你要的行（或「全選」），然後按 Ctrl+C 複製。"
L["Drag to move it."] = "拖曳即可移動。"
L["Dragging the window moves only it, not the game's roll frames, and dragging those moves only them, so the two can sit anywhere on the screen. The window comes up where you last dropped it. Until you've dragged it, it comes up by the game's roll frames as usual. Its dragging works even with \"Drag windows to move them\" off."] = "拖曳視窗只會移動它本身，不會移動遊戲的擲骰框架；拖曳擲骰框架也只會移動它們，所以兩者可以放在畫面上任何位置。視窗會出現在你上次放下的位置。在你拖曳它之前，它會照常出現在遊戲擲骰框架旁。即使「拖曳視窗來移動它們」已關閉，它仍可拖曳。"
L["Drifting gas"] = "飄移的氣體"
L["Drops the rule: its ticks, as they were, decide again."] = "放棄規則：改回由原本的勾選方塊決定。"
L["Drops the rule: the row's dropdowns decide again, ticked as they were before."] = "放棄規則：改回由該列的下拉選單決定，勾選維持先前的狀態。"
L["Duel"] = "決鬥"
L["Duel Vision"] = "Duel Vision"
L["Duel Vision test: not shown now (%s)."] = "Duel Vision 測試：目前不顯示（%s）。"
L["Duel starts"] = "決鬥開始"
L["Dungeon"] = "地城"
L["Dungeon done"] = "地城完成"
L["Dungeon line"] = "地城行"
L["Dungeons & raids"] = "地城與團隊副本"
L["Dying while a boss fight is on, you keep your own view to watch the rest of it. The death camera starts once the encounter ends (a kill or a wipe), if you're still dead."] = "在首領戰進行中死亡時，你會保持自己的視角觀看剩下的戰鬥。遭遇戰結束（擊殺或滅團）後，若你仍處於死亡狀態，死亡鏡頭才會啟動。"
L["Dying, until you release or are resurrected. The camera's settings are under Death Cam on the Camera Settings page."] = "死亡，直到你釋放靈魂或被復活。鏡頭的設定位於鏡頭設定頁面的「死亡鏡頭」下。"
L["Each Vision's own"] = "各 Vision 自己的"
L["Each bar a share of the screen's height."] = "每條計量條佔畫面高度的一部分。"
L["Each dot its player's class icon."] = "每個圓點是其玩家的職業圖示。"
L["Each event's card on or off, and where it shows."] = "開啟或關閉每個事件的卡片，以及它顯示的位置。"
L["Each fight"] = "每場戰鬥"
L["Each line slides up from below the bottom of the screen, as if from behind the camera, instead of just fading in."] = "每一行從畫面底部下方滑上來，彷彿從鏡頭後方出現，而不只是淡入。"
L["Each moment's card has a button for each emote under it, in that order. Untick a moment for no card at all. + opens a moment."] = "每個時刻的卡片下方都有各表情動作的按鈕，依此順序排列。取消勾選某個時刻則完全不顯示卡片。+ 可開啟某個時刻。"
L["Each move also tilts the camera to a random angle between the down and up limits. 0 on both keeps it level."] = "每次移動也會將鏡頭傾斜到向下與向上限制之間的隨機角度。兩者都設為 0 則保持水平。"
L["Each page as its own defaults have it (the game's look)."] = "各頁面依其自身預設值（遊戲的外觀）。"
L["Each player's number at the end of their row once the game reveals the rolls. Unticked: just who won."] = "遊戲揭曉擲骰結果後，在每位玩家的列尾顯示其點數。未勾選：只顯示誰贏了。"
L["Each row is a scene: when one of its triggers happens, it plays its camera. When two scenes are on at once, a Hearthstone or teleport cast comes first, then logging out, going AFK, the latest emote, a drawn weapon, a campfire, and standing still last. Click a row to open its settings: its camera, Music and CineMode, When it may start, its triggers, and anything it needs. The chips beside its name show what's set apart from the usual. Where its When doesn't fit, a row starts no camera. Untick the box at the start of a row to turn it off for now."] = "每一列都是一個場景：當它的某個觸發條件發生時，就播放它的鏡頭。當兩個場景同時成立時，優先順序為使用爐石或施放傳送，接著是登出、暫離、最近的表情動作、拔出武器、營火，最後是站著不動。點擊某列可開啟其設定：它的鏡頭、音樂與 CineMode、何時可以啟動、它的觸發條件，以及它所需的任何東西。名稱旁的標籤顯示與一般不同的設定。若其「符合時機」不符，該列不會啟動任何鏡頭。取消勾選列首的方塊可暫時關閉它。"
L["Each time the camera starts, it picks clockwise or anticlockwise at random (and keeps to it until it stops)."] = "每次鏡頭啟動時，會隨機選擇順時針或逆時針（並維持該方向直到停止）。"
L["Earlier around the wheel (the first is at the top)."] = "在輪盤上較前面（第一個在頂端）。"
L["Edge darkness"] = "邊緣暗度"
L["Edge pulse"] = "邊緣脈動"
L["Edge reach"] = "邊緣範圍"
L["Edge:"] = "邊緣："
L["Edges creep in over"] = "邊緣漸入時間"
L["Edges lift as you near your body"] = "接近屍體時邊緣褪去"
L["Edges reach in"] = "邊緣向內延伸"
L["Edit"] = "編輯"
L["Edit Mode keeps its old list of layouts until you reload, and saving there before then would undo this. Reload now?"] = "編輯模式在你重新載入前會保留舊的版面配置清單，在那之前於編輯模式中儲存會還原這項變更。現在重新載入嗎？"
L["Edit as a rule"] = "以規則編輯"
L["Edit style"] = "編輯樣式"
L["Editing"] = "編輯中"
L["Edwin VanCleef"] = "艾德溫·范克里夫"
L["Elite NPC"] = "精英 NPC"
L["Elite near (11 yards)"] = "附近有精英（11 碼）"
L["Elite near (28 yards)"] = "附近有精英（28 碼）"
L["Elite near (40 yards)"] = "附近有精英（40 碼）"
L["Elite/rare icon"] = "精英/稀有圖示"
L["Emote"] = "表情動作"
L["Emote Vision"] = "Emote Vision"
L["Emote Vision test: you'd %s %s."] = "Emote Vision 測試：你會%s %s。"
L["Emote Vision:"] = "Emote Vision："
L["Emotes (someone's /point, an NPC that laughs or looks around) never have a bubble: they show with the off-screen bubbles too, in a bubble with no tail so they don't read as speech, instead of bringing up chat."] = "表情動作（某人的 /point、會笑或四處張望的 NPC）從不會有泡泡：它們會跟畫面外的泡泡一起顯示，使用沒有尾巴的泡泡，以免被誤認為說話，而不是讓聊天出現。"
L["Emotes: the command, with or without its slash. Spells and buffs: the name in your game language, or a spell ID (works in any language). Places: the zone or subzone name as the game shows it."] = "表情動作：指令，有無斜線皆可。法術與增益：使用你遊戲語言的名稱，或法術 ID（適用於任何語言）。地點：遊戲顯示的區域或子區域名稱。"
L["Empties the rule."] = "清空規則。"
L["Empty: its ticks decide."] = "留空：由勾選方塊決定。"
L["Enable Cameras"] = "啟用鏡頭"
L["Enable Style"] = "啟用風格"
L["Enable Visual Effects"] = "啟用視覺效果"
L["Encounter"] = "遭遇戰"
L["Encounter bar"] = "遭遇戰計量條"
L["Ending"] = "結束"
L["Ends"] = "結束"
L["Enemy"] = "敵方"
L["Enemy targeted"] = "已選取敵人"
L["Entering combat"] = "進入戰鬥"
L["Epic and up"] = "史詩以上"
L["Essential"] = "核心"
L["Essential Cooldowns"] = "核心冷卻"
L["Essential: stay up while a cooldown is recharging"] = "核心：冷卻充能中時保持顯示"
L["Event boxes (top of the screen)"] = "事件方框（畫面頂端）"
L["Events"] = "事件"
L["Every Style page at once: a switch for them all, and the settings they share. Each page's shared settings start on General and follow it; change one on its page and it's that page's own."] = "一次設定所有樣式頁面：一個控制全部的開關，以及它們共用的設定。各頁面的共用設定起初依照「一般」；在某頁面變更其中一項，它就成為該頁面自己的設定。"
L["Every Vision's words bigger or smaller, times each one's own size on its page (cards too)."] = "所有 Vision 的文字放大或縮小，再乘以各自頁面上的大小（卡片也是）。"
L["Every Vision's words that follow this page. Each Vision's own: the game's font, or the one its page starts with."] = "所有依此頁面設定的 Vision 文字。各 Vision 自己的：遊戲的字型，或其頁面起初使用的字型。"
L["Every camera's settings are on the Scripts page now."] = "所有鏡頭的設定現在都在腳本頁面中。"
L["Every camera, built in and yours: click to pick another."] = "所有鏡頭，包括內建的與你的：點擊以選擇其他鏡頭。"
L["Every camera, made of small steps: rotate, tilt, zoom, sway, wait, and Together and Repeat for steps at once or again. Stop rules say what happens when you move the camera, walk, zoom, a fight starts or its trigger ends. The built-in ones are our own cameras' steps, with your settings: set a row on the Scenes page to one to run it instead of the camera, or Copy it to make it yours. A hollow dot: that camera isn't a script yet."] = "所有鏡頭都由小步驟組成：旋轉、傾斜、縮放、擺動、等待，以及用於同時執行或重複步驟的「同時」與「重複」。停止規則說明當你移動鏡頭、行走、縮放、戰鬥開始或其觸發條件結束時會發生什麼。內建的是我們自己鏡頭的步驟，套用你的設定：在場景頁面將某列設為其中之一，即可改為執行它而非原本的鏡頭，或「複製」它成為你的。空心圓點：該鏡頭尚未變成腳本。"
L["Every card's words bigger or smaller, for a big or wide screen (a card in a letterbox bar goes by the bar's height instead)."] = "所有卡片的文字放大或縮小，適用於大螢幕或寬螢幕（位於黑邊中的卡片則依黑邊高度而定）。"
L["Every change made to Cinematic, newest first, as written when it was made (in English)."] = "Cinematic 的所有變更，最新的在前，保持當時撰寫的內容（英文）。"
L["Every fight"] = "每場戰鬥"
L["Every kind of cast bar looks as this tab says until its own tab has Use default settings unticked."] = "每種施法條都依此分頁的設定顯示，直到它自己的分頁取消勾選「使用預設設定」。"
L["Every moment that puts words on your screen, as a card: going into a fight and coming out of it, a boss, a new zone, what you did last time, the time of day, a place under attack, a duel, your death. A row for each: its tick, the style it uses and where it shows; click it for its settings. How they look: the Style tab. One card at a time: a more important one cuts in, a less important one waits for it."] = "每個在你畫面上顯示文字的時刻，都以卡片呈現：進入與離開戰鬥、首領、新區域、你上次做了什麼、時段、遭受攻擊的地點、決鬥、你的死亡。每個時刻一列：它的勾選、使用的樣式及顯示位置；點擊可開啟其設定。外觀：樣式分頁。一次只顯示一張卡片：較重要的會插隊，較不重要的會等待。"
L["Every moment's emotes as they come."] = "各時刻的表情動作，依出現順序。"
L["Every other plate, when no row above fits it: the game's own look to start with (no mark, its own colors). Give it a mark or an Also color to change them all."] = "其他所有名條，當上方沒有任何列符合時：起初為遊戲本身的外觀（沒有標記，使用其自身顏色）。給它一個標記或「附加」顏色即可全部變更。"
L["Every page's bars that follow General. The game's: each page's own. Below the game's own few: any other addon shares (through LibSharedMedia)."] = "所有依「一般」設定之頁面的計量條。遊戲的：各頁面自己的。在遊戲本身的少數幾種之下：其他插件共用的任何材質（透過 LibSharedMedia）。"
L["Every page's words that follow General. The game's: each page's own. Russian, Korean or Chinese text keeps the game's, so its letters show."] = "所有依「一般」設定之頁面的文字。遊戲的：各頁面自己的。俄文、韓文或中文文字會保留遊戲的字型，以便正確顯示字元。"
L["Every part below is Cinematic's own code: an addon can only time its own. For other addons, see All addons above."] = "下方每個部分都是 Cinematic 自己的程式碼：插件只能為自己計時。其他插件請看上方的「所有插件」。"
L["Every plate's, those no row fits too, times its row's own. When they show is the Target Indicator row's, as the rows'."] = "所有名條的，包括沒有任何列符合的，再乘以其列自己的值。何時顯示依「目標指示」列而定，與各列相同。"
L["Every plate: NPCs, players and minions."] = "所有名條：NPC、玩家與僕從。"
L["Every tooltip: units, things in the world and the UI's (action bars, bags, menus and the rest)."] = "所有滑鼠提示：單位、世界中的物體，以及介面的（快捷列、背包、選單等）。"
L["Every way to style this part, in a panel beside the settings. Pop out to drag it anywhere; Escape or its X closes it."] = "在設定旁的面板中提供此部分的所有樣式設定方式。點「彈出」可拖曳到任何位置；Esc 或其 X 可關閉。"
L["Every wheel back on the master wheel, in their usual order (your own wheels off it)."] = "所有輪盤都回到主輪盤上，依其一般順序（你自己的輪盤不在其中）。"
L["Everyone passed"] = "所有人都放棄"
L["Everything at once, bars and words."] = "全部一起，計量條與文字。"
L["Everything here as text, to copy and send us (on Discord, or in a bug report): your game version, the graph's figures, every addon's and the last recording. It's in English, for us to read."] = "此處的所有內容以文字呈現，可複製並傳給我們（在 Discord 上或錯誤回報中）：你的遊戲版本、圖表的數據、每個插件的數據及上次記錄。內容為英文，方便我們閱讀。"
L["Everything here is hidden in CineMode unless ticked. Always shows a frame the whole time; its Fights dropdown, only while you fight or have something targeted; its Places dropdown, the whole time while you're there (Grouped: in a party or raid). Edit turns a row into a rule, for AND, NOT and more places. Frames fade in and out at the fade times on the CineMode page. Other addons' frames are on the Addon Frames page."] = "除非勾選，否則此處所有項目在 CineMode 中都會隱藏。「一律」讓框架全程顯示；其「戰鬥」下拉選單，只在你戰鬥中或有選取目標時顯示；其「地點」下拉選單，在你身處該地時全程顯示（組隊時：在隊伍或團隊中）。「編輯」會將一列轉為規則，可使用 AND、NOT 及更多地點。框架依 CineMode 頁面的淡入淡出時間顯示與隱藏。其他插件的框架位於插件框架頁面。"
L["Exalted"] = "崇拜"
L["Exit CineMode while a vendor, bank, mailbox, class trainer, trade or auction house window is open. When off, the window still shows but the rest stays hidden."] = "開啟商人、銀行、郵箱、職業訓練師、交易或拍賣場視窗時退出 CineMode。關閉時，視窗仍會顯示，但其餘部分保持隱藏。"
L["Exit CineMode while the spellbook, character sheet, talents, macros, key bindings or these options are open. When off, the window still shows but the rest stays hidden."] = "開啟法術書、角色資訊、天賦、巨集、按鍵設定或這些選項時退出 CineMode。關閉時，視窗仍會顯示，但其餘部分保持隱藏。"
