L["Flash style:"] = "閃光樣式："
L["Flash: the icon flashes for a few seconds as its cooldown ends, shown then even if its setting has it faded."] = "閃光：圖示在冷卻結束時閃爍幾秒，即使其設定為淡出，此時也會顯示。"
L["Flashes every icon in the Essential and Utility bars once, in this style."] = "以此樣式讓「核心」與「輔助」列中的每個圖示各閃爍一次。"
L["Flashes the icon for a few seconds when the spell's cooldown ends."] = "法術冷卻結束時，讓圖示閃爍幾秒。"
L["Flat"] = "平面"
L["Flat bars and Arial Narrow, thinly outlined."] = "平面計量條與 Arial Narrow 字型，帶細外框。"
L["Flat bars with a thin black edge, class-colored names, Arial Narrow."] = "帶細黑邊的平面計量條，名稱使用職業顏色，Arial Narrow 字型。"
L["Flat bars with a thin black edge, health and names in class and reaction colors, Arial Narrow."] = "帶細黑邊的平面計量條，生命值與名稱使用職業與反應顏色，Arial Narrow 字型。"
L["Flat bars, health in your class color, with a thin black edge."] = "帶細黑邊的平面計量條，生命值使用你的職業顏色。"
