L["Frame:"] = "框架："
L["Framed like the game's extra ability button (the defaults)."] = "外框如同遊戲的額外技能按鈕（預設值）。"
L["Frames where the addon took over 5 ms, and their share of all frames."] = "插件耗時超過 5 毫秒的幀，以及其佔所有幀的比例。"
L["Frames with no name that %s made."] = "%s 建立的無名稱框架。"
