L["Friendly player"] = "友方玩家"
L["Friendly players around you duel for 30 seconds, in pretend: their nameplates, made-up crowd control, and winners and losers, to see how it looks. Needs CineMode and other players nearby. Clicking Stop ends it."] = "你周圍的友方玩家假裝決鬥 30 秒：他們的名條、模擬的控場效果，以及贏家與輸家，讓你看看效果。需要 CineMode 及附近有其他玩家。點擊「停止」即可結束。"
L["Friendly players:"] = "友方玩家："
L["From far out, the zoom in or back out speeds up so it's done in this long. A short zoom still goes at the speeds above."] = "從遠處開始時，拉近或拉遠會加速，在這段時間內完成。短距離的縮放仍依上方的速度。"
L["From your settings now"] = "依你目前的設定"
L["Frost"] = "冰霜"
L["Full"] = "完整"
