L["Ground clutter changes show as the ground around you loads again: move on a little, or /reload. Changing the game's Graphics menu doesn't undo these: they're written again over its new settings."] = "地面雜物的變更會在你周圍的地面重新載入時顯示：稍微往前走一點，或 /reload。變更遊戲的圖形選單不會還原這些設定：它們會再次寫入、覆蓋其新設定。"
