L["Heal Vision"] = "Heal Vision"
L["Heal Vision %s."] = "Heal Vision %s。"
L["Heal Vision after a fight, until the Calm Timer (CineMode page) has run out."] = "戰鬥後的 Heal Vision，直到平靜計時（CineMode 頁面）結束。"
L["Heal Vision everywhere. The rest of the row keeps its ticks for when you untick this."] = "到處都顯示 Heal Vision。該列其餘部分保留其勾選，供你取消勾選此項時使用。"
L["Heal Vision in fights."] = "戰鬥中的 Heal Vision。"
L["Heal Vision out of fights while you have a living enemy targeted."] = "非戰鬥中，選取了活著的敵人時的 Heal Vision。"
L["Heal Vision out of fights while you have anything else targeted: friends, NPCs, dead enemies."] = "非戰鬥中，選取了其他任何對象時的 Heal Vision：友方、NPC、死亡的敵人。"
L["Heal Vision while you're in a party (not a raid), wherever you are."] = "身處隊伍（非團隊）時，無論在哪裡的 Heal Vision。"
L["Heal Vision while you're in a raid, wherever you are."] = "身處團隊時，無論在哪裡的 Heal Vision。"
L["Healer"] = "治療者"
L["Healers"] = "治療者"
L["Healing"] = "治療"
L["Healing report"] = "治療報告"
L["Health"] = "生命值"
L["Health bar and Power bar are the bars (Power: mana, rage, energy...). Bar numbers are the percent and value on them, hidden with their bar too."] = "生命條與能量條是計量條（能量：法力、怒氣、能量……）。計量條數字是其上的百分比與數值，會隨其計量條一起隱藏。"
L["Health bar waits for your health to change"] = "生命條等待你的生命值變化"
