L["Health bars"] = "生命條"
L["Health:"] = "生命值："
L["Heartbeat"] = "心跳"
L["Height with a plate"] = "有名條時的高度"
L["Height:"] = "高度："
L["Held back at the fight's start while you're at rest (Resource Display page)"] = "戰鬥開始時若處於靜止狀態則暫緩顯示（資源顯示頁面）"
L["Held till you've been out of the fight 5 seconds (back in it, longer: a feign death or vanish doesn't let it through), then shown. Dropped after 5 minutes."] = "暫緩到你離開戰鬥 5 秒後（重新進入戰鬥則更久：假死或消失不會讓它通過）才顯示。5 分鐘後捨棄。"
L["Help"] = "說明"
L["Here"] = "此處"
L["Hide all except"] = "全部隱藏，除了"
L["Hide error messages"] = "隱藏錯誤訊息"
L["Hide other duels while you duel"] = "你決鬥時隱藏其他決鬥"
L["Hide until the mouse is still"] = "隱藏直到滑鼠靜止"
L["Hide until the mouse is still: the mouse hadn't been still long enough"] = "隱藏直到滑鼠靜止：滑鼠靜止的時間還不夠久"
L["Hide when the mouse is still"] = "滑鼠靜止時隱藏"
L["Hide when the mouse is still: a tooltip in the world or on a unit frame hides once it's been up this long with the mouse still. Move the mouse and it comes back. Hide until the mouse is still: it shows only once the mouse has rested on it this long. Off leaves tooltips be."] = "滑鼠靜止時隱藏：世界中或單位框架上的滑鼠提示，在滑鼠靜止且顯示達此時間後隱藏。移動滑鼠它就會回來。隱藏直到滑鼠靜止：只有在滑鼠停在其上達此時間後才顯示。關閉則不處理滑鼠提示。"
L["Hit text"] = "命中文字"
L["Hold to bring up a wheel of the ground markers (the colored lights you drop on the floor): point at one and let go, and it drops under the cursor. Picking one that's down moves it; Clear all takes them all up. Tap it instead and the wheel stays up for you to click one. Only in a group."] = "按住可叫出地面標記（你放在地上的彩色光標）的輪盤：指向其中一個再放開，它就會放在游標下方。選擇已放下的標記會移動它；「全部清除」會將它們全部收起。改為輕按一下，輪盤會保持顯示讓你點擊。僅限組隊時。"
L["Hold to bring up a wheel of the raid target markers (skull, cross, square...) for your target, or with none, whatever the cursor is on: point at one and let go to put it on them, or at None to take theirs off. Tap it instead and the wheel stays up for you to click one."] = "按住可叫出團隊目標標記（骷髏、十字、方塊……）的輪盤，套用於你的目標，若沒有目標則套用於游標所指的對象：指向其中一個再放開即可標上，指向「無」則移除其標記。改為輕按一下，輪盤會保持顯示讓你點擊。"
L["Hold to bring up a wheel of the visions (Heal, Quest, Duel...), ringed while they're on: point at one and let go to turn it on or off, in a fight too. Tap it instead and the wheel stays up for you to click one."] = "按住可叫出 Vision（Heal、Quest、Duel……）的輪盤，開啟中的會加上外圈：指向其中一個再放開即可開啟或關閉，戰鬥中也可以。改為輕按一下，輪盤會保持顯示讓你點擊。"
L["Hold to bring up a wheel of the wheels below (camera, menu, marker...): point at one and let go to open it, then click what you want on it. Tap it instead and the wheel stays up for you to click one. The camera wheel can't open in a fight."] = "按住可叫出下方各輪盤（鏡頭、選單、標記……）的輪盤：指向其中一個再放開即可開啟它，然後點擊你要的項目。改為輕按一下，輪盤會保持顯示讓你點擊。鏡頭輪盤無法在戰鬥中開啟。"
L["Holds the card up so you can drag it where you want it; Done lets it go. Close the settings to see it."] = "讓卡片保持顯示，以便你將它拖曳到想要的位置；「完成」即可放開。關閉設定後即可看到。"
L["Honored"] = "尊敬"
L["Horizon Suite's quest tracker (Focus), its dungeon banner and its floating quest item button fade with the Quest tracker row on the Game Frames page."] = "Horizon Suite 的任務追蹤（Focus）、其地城橫幅及浮動的任務物品按鈕，會隨遊戲框架頁面的任務追蹤列一起淡出。"
L["Hostile"] = "敵對"
L["Hover Find"] = "指向尋找"
L["Hover Find: %d frame put on the Find frames list."] = "指向尋找：已將 %d 個框架放入尋找框架清單。"
L["Hover Find: %d frames put on the Find frames list."] = "指向尋找：已將 %d 個框架放入尋找框架清單。"
L["Hover Find: hover over the frames you want, then click Stop: they go on the Find frames list, to add. The game's own frames and ones already faded are left out."] = "指向尋找：將滑鼠移到你要的框架上，然後點擊「停止」：它們會放入尋找框架清單供你加入。遊戲本身的框架和已經淡出的框架不會列入。"
L["Hover group \"%s\": %s"] = "滑鼠指向群組「%s」：%s"
L["Hover over the frames you want (move this window out of the way, or close it), then click Stop: they go on the list below, to add. The game's own frames and ones already faded are left out. /cine add cancel drops them."] = "將滑鼠移到你要的框架上（把此視窗移開或關閉），然後點擊「停止」：它們會放入下方清單供你加入。遊戲本身的框架和已經淡出的框架不會列入。/cine add cancel 可放棄它們。"
L["Hovering the chat, typing or a whisper to read still brings it all up."] = "滑鼠指向聊天、輸入文字或有密語待讀時，仍會讓它全部顯示。"
L["How Damage Vision looks and where it sits. Press Test on the Settings tab and close the settings to see it."] = "Damage Vision 的外觀與位置。在設定分頁按「測試」，然後關閉設定即可看到。"
L["How big a name is with its unit about 10 yards from the camera, next to the plates' own. Nearer, bigger still; further, smaller, as the game's names over heads."] = "單位距離鏡頭約 10 碼時名稱的大小，相對於名條本身的大小。更近時更大；更遠時更小，與遊戲頭頂名稱相同。"
L["How big a name is with its unit about 50 yards from the camera: about the size of the game's names where those take over, at the edge of nameplate range."] = "單位距離鏡頭約 50 碼時名稱的大小：大約是遊戲名稱在名條範圍邊緣接手顯示時的大小。"
L["How big speech from behind you is, next to a bubble overhead: smaller sounds further away."] = "來自你身後的話語，相對於頭頂泡泡的大小：越遠的聲音越小。"
L["How big the names are, next to the plates' own."] = "名稱的大小，相對於名條本身的大小。"
L["How big the text is, next to its usual size."] = "文字的大小，相對於其一般大小。"
L["How big the words are, next to their usual size."] = "文字的大小，相對於其一般大小。"
L["How big they are, next to the usual."] = "它們的大小，相對於一般大小。"
L["How big your class resource is (combo points, holy power, runes and the like), next to the game's."] = "你的職業資源（連擊點數、聖能、符文之類）的大小，相對於遊戲的大小。"
L["How bright both arts' colors are: at 50% as the theme has them; less, darker, down to black at 0%; more, lighter, toward white."] = "兩種美術圖顏色的亮度：50% 時為主題的原樣；較低則較暗，0% 時為黑色；較高則較亮，趨向白色。"
L["How chat bubbles look, and speech from behind you with them. Where bubbles show: the UI Manager's Chat bubbles page. Bubbles already showing change with the next thing said."] = "對話泡泡的外觀，以及與其一起顯示的來自你身後的話語。泡泡在哪裡顯示：介面管理器的對話泡泡頁面。已顯示的泡泡會在下一句話時改變。"
L["How close to the waypoint the wind stops (you're there)."] = "風在離路徑點多近時停止（你已抵達）。"
L["How dark it is behind the bar."] = "計量條後方的暗度。"
L["How dark it is behind the bars, with a border of ours."] = "計量條後方的暗度，使用我們的邊框。"
L["How dark it is behind the fill (with a fill of your own; the game's keeps its own)."] = "填色後方的暗度（使用你自己的填色時；遊戲的填色保留自己的）。"
L["How dark it is behind the health bar, with a border of ours."] = "生命條後方的暗度，使用我們的邊框。"
L["How dark the black edges get."] = "黑色邊緣的最大暗度。"
L["How dark the edges are at full."] = "全滿時邊緣的暗度。"
L["How dark the empty part of the bar is."] = "計量條空白部分的暗度。"
L["How dark the shadow is."] = "陰影的暗度。"
L["How dark the world gets outside the portal's rim, in a deep shade of its color."] = "傳送門邊緣外世界變暗的程度，使用其顏色的深色調。"
L["How faded the page count (2 / 3) and the numbers by the replies and buttons are."] = "頁數（2 / 3）以及回覆與按鈕旁數字的淡化程度。"
L["How far above the letters it falls (below, below 0)."] = "它落在文字上方多遠（低於 0 則在下方）。"
L["How far away buildings keep their full detail."] = "建築物在多遠距離內保持完整細節。"
L["How far away creatures and characters keep their full detail before they're swapped for simpler models."] = "生物與角色在多遠距離內保持完整細節，之後才換成較簡單的模型。"
L["How far away grass and flowers grow full before they start thinning out towards the clutter distance. Above the clutter distance it makes no more difference."] = "草與花在多遠距離內完整生長，之後才開始朝雜物距離逐漸稀疏。超過雜物距離後就不再有差別。"
L["How far away grass and flowers still show."] = "草與花在多遠距離內仍會顯示。"
L["How far away nameplates show, in yards. The game won't go past its own limit. Reset page puts the game's default back."] = "名條顯示的距離，以碼為單位。遊戲不會超過其自身上限。「重置頁面」會還原遊戲的預設值。"
L["How far away small objects stay before they fade out. Much higher costs a lot of frame rate for little to see."] = "小型物體在多遠距離內保持顯示，之後才淡出。設得太高會大幅降低幀數，卻沒多少東西可看。"
L["How far away the land is drawn in full before it turns into the flat, faded horizon, and how far anything is drawn at all. Very demanding: with terrain and building detail turned up too, most of all."] = "地形在多遠距離內完整繪製，之後才變成平坦、淡化的地平線，以及任何東西最遠繪製到多遠。非常耗效能：尤其是同時調高地形與建築細節時。"
L["How far away the land keeps its full shape before it turns low detail."] = "地形在多遠距離內保持完整形狀，之後才變成低細節。"
L["How far away trees, rocks and other objects keep their full detail before they're swapped for simpler ones or fade out."] = "樹木、岩石與其他物體在多遠距離內保持完整細節，之後才換成較簡單的版本或淡出。"
L["How far either side of behind the flight, RP walk and auto-run cameras may swing indoors."] = "室內時，飛行、RP 漫步與自動奔跑鏡頭可在背後兩側擺動多遠。"
L["How far in it all comes: at 50% as the settings below say (and the theme's own); less, nearer the edges, down to none at 0% (the shadow only to half); more, further in, up to double. It scales the shadow's reach and both arts' reach."] = "整體向內延伸的程度：50% 時依下方設定（及主題本身）；較低則更靠近邊緣，0% 時完全沒有（陰影只減到一半）；較高則更往內，最多兩倍。它會縮放陰影的範圍及兩種美術圖的範圍。"
L["How far in it comes from the left and right of the screen at full (screens are wide: the same share comes further in there)."] = "全滿時從畫面左右兩側向內延伸的程度（畫面較寬：同樣的比例在那裡會延伸得更遠）。"
L["How far in it comes from the top and bottom of the screen at full."] = "全滿時從畫面上下兩側向內延伸的程度。"
L["How far in its clear middle closes at full."] = "全滿時其清晰中央收攏的程度。"
L["How far in the black edges come as the cast fills (a share of the screen from each side)."] = "隨施法進度，黑色邊緣向內延伸的程度（從每一側起算的畫面比例）。"
L["How far out you can zoom the camera, as times the game's base distance. The game won't go past its own limit. Idle zoom's \"past your max\" still raises it to 2.6 while it zooms, if it's lower."] = "鏡頭最多可拉遠的距離，以遊戲基本距離的倍數表示。遊戲不會超過其自身上限。若此值較低，閒置縮放的「超過你的最大值」仍會在縮放時將它提高到 2.6。"
L["How far past the bars' edge they fade into the scene."] = "它們超出黑邊邊緣多遠後才融入場景。"
L["How far past your own distance the slow zoom may pull back indoors. It also never raises the max zoom distance indoors. Walking in pulled back, the camera glides in to this."] = "室內時，緩慢縮放最多可超過你自己的距離拉遠多少。它也不會提高室內的最大縮放距離。在拉遠狀態下走進室內時，鏡頭會平滑拉近到此距離。"
L["How far past your own zoom the camera pulls back (the first move always goes this far)."] = "鏡頭會超過你自己的縮放距離拉遠多少（第一次移動一定會拉這麼遠）。"
L["How far right (X) and up (Y) from the middle of the screen it sits; below 0, left or down. Dragging it with Move fills these in."] = "它位於畫面中央偏右（X）與偏上（Y）多遠；低於 0 則偏左或偏下。用「移動」拖曳它會自動填入這些數值。"
L["How far right (X) of the middle of the screen, and up (Y) from its bottom, the card sits. Typing here or dragging it with Move puts it there; Reset puts it back above speech from behind you."] = "卡片位於畫面中央偏右（X）多遠，以及從底部往上（Y）多遠。在此輸入或用「移動」拖曳它即可放到那裡；「重置」會將它放回來自你身後之話語的上方。"
L["How far right of the letters it falls (left, below 0)."] = "它落在文字右側多遠（低於 0 則在左側）。"
L["How far around you the camera turns with each move."] = "鏡頭每次移動繞著你轉多遠。"
L["How far the camera comes down toward eye level, from wherever you had it. Much more and, close up, it can meet the ground or scenery behind you (a small jump). It goes back up as the window closes (unless you moved the camera yourself meanwhile). 0 keeps your angle."] = "鏡頭從你原本的位置向視線高度下降多少。太多的話，在近距離時可能碰到你身後的地面或景物（會輕微跳動）。視窗關閉時它會升回去（除非你在此期間自己移動過鏡頭）。0 表示保持你的角度。"
L["How far the camera may come in from its distance."] = "鏡頭可從其距離拉近多少。"
L["How far the camera may pull back from its distance."] = "鏡頭可從其距離拉遠多少。"
L["How far the camera may sway either side of where it settles."] = "鏡頭可在其停駐位置兩側擺動多遠。"
L["How far the camera may swing to either side of directly behind your character. 90° reaches side-on; smaller keeps it closer behind."] = "鏡頭可在你角色正後方兩側擺動多遠。90° 可到達正側面；較小則保持更靠近背後。"
L["How far the camera may tilt down as it moves."] = "鏡頭移動時最多可向下傾斜多少。"
L["How far the camera may tilt up as it moves."] = "鏡頭移動時最多可向上傾斜多少。"
L["How far the dark edges reach in once they've closed in, as a share of the screen from each side."] = "深色邊緣收攏後向內延伸的程度，以從每一側起算的畫面比例表示。"
L["How far up the screen the list of replies starts: its top edge, from the bottom of the screen. Changing this also forgets where you dragged the list to."] = "回覆清單在畫面上從多高開始：其頂端，從畫面底部起算。變更此值也會忘記你將清單拖曳到的位置。"
L["How fast"] = "速度"
L["How fast they travel to the waypoint, next to the style's own speed."] = "它們往路徑點移動的速度，相對於樣式本身的速度。"
L["How it looks: the theme, our art and Blizzard's, the shadow and the heartbeat."] = "外觀：主題、我們與 Blizzard 的美術圖、陰影與心跳。"
L["How long"] = "時長"
L["How long a card stays before it fades. The mouse over it holds it."] = "卡片在淡出前停留多久。滑鼠移到上面會讓它保持顯示。"
L["How long a plate takes to change its opacity or size a whole 100% when the row it goes by changes: from 100% to 15% takes a bit less. If it changes back before it's there, it turns back from where it is, so a quick look away from an elite and back barely shows. A plate just come into view starts at its row's. 0: at once."] = "當名條所依據的列改變時，名條將其不透明度或大小改變整整 100% 所需的時間：從 100% 到 15% 會稍短一些。若在到達之前又改回，它會從目前的位置轉回，所以快速從精英身上移開視線再看回來時幾乎看不出變化。剛進入視野的名條會從其列的值開始。0：立即。"
L["How long a recording runs."] = "一次記錄持續多久。"
L["How long a repeat is ignored for."] = "重複的事件會被忽略多久。"
L["How long before the cast ends the black takes over the whole screen. 0: it doesn't."] = "施法結束前多久黑色會覆蓋整個畫面。0：不會。"
L["How long each move takes, start to stop. Longer is slower and smoother."] = "每次移動從開始到停止所需的時間。越長越慢、越平順。"
L["How long each zoom in or out takes."] = "每次拉近或拉遠所需的時間。"
L["How long it stays up once a fight is over."] = "戰鬥結束後它保持顯示多久。"
L["How long its camera runs."] = "其鏡頭運作多久。"
L["How long the bars take to come in or go. 0: as long as the UI's own fades (the main page's Fade in and Fade out times)."] = "黑邊出現或消失所需的時間。0：與介面本身的淡入淡出時間相同（主頁面的淡入與淡出時間）。"
L["How long the camera holds still between moves."] = "鏡頭在兩次移動之間靜止多久。"
L["How long the camera rests between sweeps. 0 keeps it turning continuously at the turn speed, without slowing between sweeps."] = "鏡頭在兩次環繞之間停留多久。0 表示以旋轉速度持續轉動，環繞之間不減速。"
L["How long the card stays between fading in and out (Typewriter: once typed)."] = "卡片在淡入與淡出之間停留多久（打字機：打完字後）。"
L["How long the dark edges take to close in after you die, starting gently and settling at the end."] = "你死亡後深色邊緣收攏所需的時間，起初輕緩，最後緩緩停住。"
L["How long the icon flashes once its cooldown ends."] = "冷卻結束後圖示閃爍多久。"
L["How long the session was."] = "本次遊戲時長。"
L["How long things must stay calm (no cast, window, dragging and the like) before CineMode comes back. After a fight it comes back at once instead. 0 returns at once."] = "必須保持平靜（沒有施法、視窗、拖曳之類）多久，CineMode 才會恢復。戰鬥後則會立即恢復。0 表示立即恢復。"
L["How long things take to fade out, in and out of fights: letting go of a target, after a mouseover, and after a fight once the Calm Timer below is over. The mouseover time (Mouseover groups page) includes it: a time shorter than the fade just fades straight away."] = "介面淡出所需的時間，戰鬥中和戰鬥外都用：放開目標、滑鼠指向之後，以及戰鬥後下方的平靜計時結束時。滑鼠指向時間（滑鼠指向群組頁面）包含它：比淡出更短的時間會立即淡出。"
L["How long you stand still before NPCs chatting nearby start this row's camera. 0: straight away. Moving starts the count over."] = "你站著不動多久後，附近閒聊的 NPC 才會啟動此列的鏡頭。0：立即。移動會重新開始計時。"
L["How loud the sounds are, next to your sound effects' volume."] = "音效的音量，相對於你的音效音量。"
L["How many come a minute at full (a big hit brings a few more)."] = "全滿時每分鐘出現多少次（重擊會多帶來幾次）。"
L["How many dungeon or raid bosses you killed."] = "你擊殺了多少地城或團隊副本首領。"
L["How many quests you turned in."] = "你交付了多少任務。"
L["How many seconds before it's ready the icon comes back: 0 for once it's ready. Leave it empty for %d%% of its cooldown."] = "圖示在就緒前多少秒重新出現：0 表示就緒時才出現。留空則為其冷卻時間的 %d%%。"
L["How many streaks (or leaves, or motes) start each second."] = "每秒產生多少條流光（或葉片、或光點）。"
L["How many times you died."] = "你死了多少次。"
L["How much further in each beat pushes the edges (some themes throb more or less)."] = "每次跳動將邊緣再往內推多少（有些主題跳動得更多或更少）。"
L["How much of a hidden damage dealer still shows, and of the group titles. 0% hides them completely."] = "隱藏的傷害輸出者及小隊標題仍顯示的程度。0% 表示完全隱藏。"
L["How much of a hidden healer still shows. 0% hides them completely."] = "隱藏的治療者仍顯示的程度。0% 表示完全隱藏。"
L["How much of a hidden pet still shows. 0% hides them completely."] = "隱藏的寵物仍顯示的程度。0% 表示完全隱藏。"
L["How much of a hidden tank still shows. 0% hides them completely."] = "隱藏的坦克仍顯示的程度。0% 表示完全隱藏。"
L["How much of each move is spent speeding up, and again slowing down. 50% is one smooth swell, gentlest at the ends. Lower values get up to speed quicker and cruise in the middle."] = "每次移動中用於加速、再用於減速的比例。50% 為一次平順的起伏，兩端最輕柔。較低的值會更快達到速度，並在中段等速移動。"
L["How much of each zoom is spent speeding up, and again slowing down. 50% is one smooth swell; lower gets moving sooner and glides in the middle."] = "每次縮放中用於加速、再用於減速的比例。50% 為一次平順的起伏；較低會更快開始移動，並在中段滑行。"
L["How much of the screen's height the dark top and bottom edges cover at full."] = "全滿時上下深色邊緣覆蓋畫面高度的比例。"
L["How much of the screen's width the dark left and right edges cover at full."] = "全滿時左右深色邊緣覆蓋畫面寬度的比例。"
L["How much of your computer's time Cinematic takes. The graph is the game's own figure for this addon: its share of each frame's time, sampled every second (the last five minutes, kept over a reload), each bar colored by what was going on. A recording times the addon's busy parts: it starts when you close the settings, and its results show here. If Cinematic seems slow for you, record a while of your usual play (a fight too), then Copy report and send it to us: it helps us find what to speed up."] = "Cinematic 佔用你電腦多少時間。圖表是遊戲本身對此插件的統計：它佔每幀時間的比例，每秒取樣一次（最近五分鐘，重新載入後仍保留），每條柱依當時的狀況著色。記錄會為插件的忙碌部分計時：它在你關閉設定時開始，結果會顯示在此。如果你覺得 Cinematic 很慢，請記錄一段你平常的遊戲過程（包括一場戰鬥），然後「複製報告」並傳給我們：這有助於我們找出要加速的地方。"
L["How much richer you came out, if you did."] = "你多賺了多少（如果有的話）。"
L["How much this theme throbs, next to Throb above."] = "此主題的跳動程度，相對於上方的「跳動」。"
L["How names look on nameplates showing just the name: in CineMode, away from dungeons and raids, a name kept up over a faded plate is drawn by the plate. Changes show at once, here and on the plates around you."] = "只顯示名稱之名條上的名稱外觀：在 CineMode 中、地城與團隊副本以外，淡出名條上保留的名稱是由名條繪製的。變更會立即顯示，包括此處及你周圍的名條。"
L["How see-through the background is."] = "背景的透明度。"
L["How see-through the bars are."] = "計量條的透明度。"
L["How see-through the bubble is."] = "泡泡的透明度。"
L["How see-through the cards are."] = "卡片的透明度。"
L["How see-through the names are, on top of their fades."] = "名稱的透明度，疊加在其淡出效果之上。"
L["How see-through the panels are."] = "底板的透明度。"
L["How see-through the whole of it is."] = "整體的透明度。"
L["How solid speech from behind you is: fainter sounds muffled, out of view."] = "來自你身後之話語的不透明程度：較微弱的聲音被遮蔽，不在視野中。"
L["How solid the game's dark background behind each frame is."] = "每個框架後方遊戲深色背景的不透明程度。"
L["How strong"] = "強度"
L["How strong it all is: at 50% as the settings below say (and the theme's own); less, lighter, down to nothing at 0%; more, up to double. It scales the darkness, the shadow's reach, the throb and both arts' opacity. The color grade (the world draining toward grey, tinged with the theme's color) is as strong as this says."] = "整體的強度：50% 時依下方設定（及主題本身）；較低則較淡，0% 時完全沒有；較高則最多兩倍。它會縮放暗度、陰影範圍、跳動及兩種美術圖的不透明度。色彩分級（世界褪向灰色，並染上主題的顏色）的強度依此值而定。"
L["How strong it is as the cast ends (it starts faint)."] = "施法結束時的強度（起初較淡）。"
L["How strong it is at full."] = "全滿時的強度。"
L["How strong the edges are out of a fight (eating and drinking back up, say), next to in one. Some clients keep your health secret in fights; there the edges only fade in and out with it."] = "非戰鬥中（例如吃喝回血時）邊緣的強度，相對於戰鬥中。有些用戶端在戰鬥中會隱藏你的生命值；在那裡邊緣只會隨之淡入淡出。"
L["How strong the glow is, next to the art."] = "光暈的強度，相對於美術圖。"
L["How strongly the tint colors the world, for every preset."] = "色調為世界染色的強度，適用於所有預設。"
L["How tall each bar is, as a share of the screen's height."] = "每條黑邊的高度，以畫面高度的比例表示。"
L["How tall the bar for the time left is."] = "剩餘時間計量條的高度。"
L["How tall the bar is (the race track's line is half that, the ladder's rows a little more)."] = "計量條的高度（賽道的線為其一半，排行榜的列稍高一些）。"
L["How tall the words are on the screen; the other lines go by them. (In a letterbox bar: Letterbox scale.)"] = "文字在畫面上的高度；其他行依此調整。（在黑邊中：黑邊縮放。）"
L["How the bars at the top and bottom of the screen look and come in. When they show: the Letterbox tab. Changes show at once, here and on the bars."] = "畫面上下黑邊的外觀與出現方式。何時顯示：黑邊分頁。變更會立即顯示，包括此處及黑邊上。"
L["How the big button for the nearest quest's item looks. Turning it on: the Vision tab. Where it sits: the extra ability button's place in Edit Mode. Changes show at once (its size after a fight, if you're in one)."] = "最近任務之物品大按鈕的外觀。開啟它：Vision 分頁。位置：編輯模式中額外技能按鈕的位置。變更會立即顯示（若你在戰鬥中，大小會在戰鬥後改變）。"
L["How the card comes in."] = "卡片出現的方式。"
L["How the card is set: a title card, a subtitle, a chapter line or a banner."] = "卡片的版式：標題卡、字幕、章節行或橫幅。"
L["How the cast bars look: on nameplates, yours, your target's and focus's, and the bosses' and arena enemies'. The Default tab's settings are every bar's until its own tab has Use default settings unticked. All but the nameplates' keep the game's look until their tab's Restyle these bars is ticked. Whether the nameplates' show in CineMode: the Nameplates page's Plate parts grid. Changes show at once, here and on bars casting now."] = "施法條的外觀：名條上的、你的、你目標與專注目標的，以及首領與競技場敵人的。「預設」分頁的設定適用於每條施法條，直到它自己的分頁取消勾選「使用預設設定」。除了名條的以外，其他都保留遊戲的外觀，直到其分頁勾選「重新設計這些計量條」。名條上的施法條是否在 CineMode 中顯示：名條頁面的名條部件表格。變更會立即顯示，包括此處及正在施法的計量條上。"
L["How the dialogue looks, the \"Show the game's window\" link and the number keys."] = "對話的外觀、「顯示遊戲視窗」連結及數字鍵。"
L["How the game world looks in CineMode (or over the normal UI, with Start in CineMode off on the main page): vignette, inn glow, weather and depth of field. The letterbox bars and the color grading have pages of their own (Letterbox, Tint). The UI isn't tinted. Names and nameplates are on the Nameplates page."] = "CineMode 中遊戲世界的外觀（或在主頁面關閉「以 CineMode 啟動」時，套用於一般介面之上）：暗角、旅店光暈、天氣與景深。黑邊與色彩分級有各自的頁面（黑邊、色調）。介面不會被染色。名稱與名條位於名條頁面。"
L["How the game's tooltips look: their background, edge and words, names in their colors and the health bar. Which lines show and when: the Interface hub's Tooltips page."] = "遊戲滑鼠提示的外觀：背景、邊緣與文字、名稱顏色及生命條。顯示哪些行與何時顯示：「介面」分類的滑鼠提示頁面。"
L["How the low-health edges look: the theme, our art and Blizzard's, the shadow and the effects. When they show: the Vision tab. Changes show at once in the preview."] = "低生命值邊緣的外觀：主題、我們與 Blizzard 的美術圖、陰影與效果。何時顯示：Vision 分頁。變更會立即顯示在預覽中。"
L["How the personal resource display under your character looks: its health and power bars, and your class resource. When the bars come up: the Interface hub's Resource Display page."] = "角色下方個人資源顯示的外觀：其生命條與能量條，以及你的職業資源。計量條何時出現：「介面」分類的資源顯示頁面。"
L["How the quest item button looks."] = "任務物品按鈕的外觀。"
L["How the raid frames look, the party's when the game draws them raid-style, and the arena's. The Default tab's settings are each group's until its own tab has Use default settings unticked. Which parts show: the Game Frames page's party and raid rows."] = "團隊框架的外觀、遊戲以團隊樣式繪製時的隊伍框架，以及競技場框架。「預設」分頁的設定適用於每個群組，直到它自己的分頁取消勾選「使用預設設定」。顯示哪些部分：遊戲框架頁面的隊伍與團隊列。"
L["How the result shows: its card (with the words above), or a souls banner: VICTORY ACHIEVED or DEFEATED across the middle of the screen, who it was against under it."] = "結果的顯示方式：其卡片（附上方的文字），或靈魂風格橫幅：畫面中央的「獲得勝利」或「戰敗」，下方顯示對手是誰。"
L["How the roll window looks."] = "擲骰視窗的外觀。"
L["How the rows are listed: Camera groups them by camera name, Scene by scene name. Either way a scene's rows stay together, in the order they're tried."] = "各列的排列方式：「鏡頭」依鏡頭名稱分組，「場景」依場景名稱分組。無論哪種，同一場景的列都會在一起，依嘗試的順序排列。"
L["How the window of the group's loot rolls looks: its cards, the bar for the time left, and each player's pick and number. Turning it on: the Vision tab. Changes show at once, here and on the window."] = "隊伍拾取擲骰視窗的外觀：其卡片、剩餘時間計量條，以及每位玩家的選擇與點數。開啟它：Vision 分頁。變更會立即顯示，包括此處及視窗上。"
L["How thick the border is, in pixels."] = "邊框的粗細，以像素為單位。"
L["How thickly grass, flowers and stones grow on the ground."] = "地面上草、花與石頭生長的密度。"
L["How this card looks. It starts from a style (a subzone's, the zone's), each setting following it until you change it here, then the card's own until you put it back. Change the style itself on the Card Types tab, for every card using it. Changes play at once in the preview."] = "此卡片的外觀。它從某個樣式開始（子區域的或區域的），每項設定都依照該樣式，直到你在此變更它，之後就成為卡片自己的設定，直到你還原它。要變更樣式本身，請到卡片類型分頁，那會套用於使用它的每張卡片。變更會立即在預覽中播放。"
L["How wide a line of speech from behind you can get before it wraps onto the next row, as a bubble overhead does."] = "來自你身後的一行話語在換行前最多可以多寬，與頭頂泡泡相同。"
L["How wide it is."] = "它的寬度。"
L["How your player, target, focus, pet, target of target and party frames look. The Default tab's settings are every frame's until its own tab has Use default settings unticked. Which parts show: the Interface hub's Unit Frames page."] = "你的玩家、目標、專注目標、寵物、目標的目標及隊伍框架的外觀。「預設」分頁的設定適用於每個框架，直到它自己的分頁取消勾選「使用預設設定」。顯示哪些部分：「介面」分類的單位框架頁面。"
L["How your target, focus and the unit under the mouse stand out on the nameplates, for when no target frame shows them: a mark on each one's plate, a row for each in the grid, and its name, health bar or border in its mark's color (the row's Also color). When they show is the Target Indicator row's, on the Nameplates page's Cinematic plate parts grid. Changes show at once, here and on the plates."] = "當沒有目標框架顯示時，你的目標、專注目標及滑鼠下的單位如何在名條上突顯：每個對象名條上的標記、表格中各自的一列，以及以其標記顏色（該列的「附加」顏色）顯示的名稱、生命條或邊框。何時顯示依名條頁面「Cinematic 名條部件」表格中的「目標指示」列而定。變更會立即顯示，包括此處及名條上。"
L["How:"] = "方式："
L["Icon"] = "圖示"
L["Icon shows"] = "圖示顯示"
L["Icons"] = "圖示"
L["Icons have a dark border of their own: zoomed in a little, it's cut off."] = "圖示本身有深色邊框：稍微放大後就會被裁掉。"
L["Icons of your own, after the wheel's own: each runs a command, as on your own wheels. Room for %d. The same for all your characters."] = "你自己的圖示，放在輪盤本身的圖示之後：每個都執行一個指令，與你自己的輪盤相同。可放 %d 個。所有角色共用。"
L["Icons on it"] = "其上的圖示"
L["Ignore repeats from the same person"] = "忽略同一個人的重複動作"
L["Ignored for:"] = "忽略時間："
L["Immerse yourself in the world. How much do you want?"] = "沉浸在這個世界中。你想要多沉浸？"
L["Import a Vitals theme"] = "匯入 Vitals 主題"
L["Import a camera script"] = "匯入鏡頭腳本"
L["Import a scene or shot"] = "匯入場景或鏡頭片段"
L["Import a wheel"] = "匯入輪盤"
L["Import theme"] = "匯入主題"
L["In %s"] = "在%s"
L["In CineMode"] = "CineMode 中"
L["In CineMode the death camera hides all the frames it fades (bars, chat, unit frames...). The Mouseover page's groups ticked here stay up throughout, party or raid frames say, to watch your group. The release and resurrect popups always show."] = "在 CineMode 中，死亡鏡頭會隱藏它淡出的所有框架（快捷列、聊天、單位框架……）。在此勾選的滑鼠指向群組會全程保持顯示，例如隊伍或團隊框架，讓你看著你的隊伍。釋放靈魂與復活的對話框一律顯示。"
L["In CineMode, a health bar faded out comes back as your health drops: hidden above its Starts, fading in to fully up at its Full."] = "在 CineMode 中，淡出的生命條會隨你的生命值下降而恢復：高於其「開始」時隱藏，逐漸淡入，到其「全滿」時完全顯示。"
L["In CineMode, as it rains, the view distance comes in from yours: the harder the rain, the closer. At 100% a downpour brings it all the way in, as far as the Graphics menu's lowest View distance; it never goes further out than yours. Yours is put back once the rain stops or you go indoors."] = "在 CineMode 中，下雨時視野距離會從你的設定往內縮：雨越大，越近。100% 時傾盆大雨會讓它一路縮到圖形選單中最低的視野距離；它不會比你的設定更遠。雨停或你進入室內後，會還原你的設定。"
L["In CineMode, away from dungeons and raids, nameplates stay on (just faded), and the game takes its own names away from over the heads of units with a plate. So where a name is kept up over a faded plate, Cinematic draws it on the plate itself, made to look like the game's names: colored, and smaller further off. Beyond nameplate range the game's own names show, so a name can change a little in size or place as its unit crosses that range."] = "在 CineMode 中、地城與團隊副本以外，名條會保持開啟（只是淡出），而遊戲會移除有名條之單位頭上的名稱。所以當淡出名條上需要保留名稱時，Cinematic 會直接在名條上繪製它，外觀模仿遊戲的名稱：有顏色，越遠越小。超出名條範圍後會顯示遊戲本身的名稱，所以當單位越過該範圍時，名稱的大小或位置可能會稍有變化。"
L["In CineMode, the nameplates of two players dueling near you show, so you can watch their health. Only in the open world, out of fights. Turns on friendly player nameplates while it watches, kept invisible and click-through bar the duelists'. Each duel has its own color, and the winner and loser show when it ends. Needs the Nameplates page enabled."] = "在 CineMode 中，你附近兩名正在決鬥之玩家的名條會顯示，讓你看他們的生命值。僅限開放世界、非戰鬥中。觀看期間會開啟友方玩家名條，除了決鬥者以外都保持隱形且可穿透點擊。每場決鬥有各自的顏色，結束時會顯示贏家與輸家。需要啟用名條頁面。"
L["In CineMode, where and when tooltips show; the rest of the time they're hidden. For some kinds only (enemies, friendlies, gatherables, quest objectives, anything else), Edit its rule: the Tooltip line has a word for each."] = "在 CineMode 中，滑鼠提示在何處、何時顯示；其他時候它們都會隱藏。若只想用於某些類別（敵方、友方、可採集物、任務目標、其他任何），請編輯其規則：滑鼠提示一行中每一類都有一個字詞。"
L["In CineMode, your player frame shows whenever your mana is under this share, in a fight or not: drinking, or saving mana for the pull. Off: 0."] = "在 CineMode 中，只要你的法力低於此比例，無論是否在戰鬥中，你的玩家框架都會顯示：例如喝水時，或為拉怪保留法力時。關閉：0。"
L["In CineMode, your resource bar shows whenever your mana is under this share, in a fight or not: drinking, or saving mana for the pull. Off: 0."] = "在 CineMode 中，只要你的法力低於此比例，無論是否在戰鬥中，你的資源條都會顯示：例如喝水時，或為拉怪保留法力時。關閉：0。"
L["In a camera mode"] = "在鏡頭模式中"
L["In a fight"] = "戰鬥中"
L["In a fight:"] = "戰鬥中："
L["In a group, items rolled on show in a window instead of only as lines in chat: each item, a bar for the time left, and everyone's pick (need, greed, transmog) and number, the winner lit at the top. It opens as an item drops, just under the game's roll frame, so you can see who's picked what before you choose, and takes its place once you have. Each item fades a few seconds after it's won (point at them to keep them). It stays with the game's roll frames: with \"Drag windows to move them\" on, dragging either moves both. /cine rolls shows the latest rolls."] = "在隊伍中，擲骰的物品會顯示在一個視窗中，而不只是聊天中的文字：每件物品、剩餘時間計量條，以及每個人的選擇（需求、貪婪、塑形）與點數，贏家會在頂端亮起。物品掉落時它就會開啟，位於遊戲擲骰框架正下方，讓你在選擇前就能看到誰選了什麼，並在你選擇後取代擲骰框架的位置。每件物品在被贏得幾秒後淡出（指向它們可保持顯示）。它會跟著遊戲的擲骰框架：開啟「拖曳視窗來移動它們」時，拖曳任一個都會一起移動。/cine rolls 可顯示最近的擲骰。"
L["In a raid, each item lists only this many players' rolls: the winner, then need before greed, the highest numbers first. The rest are counted on an \"and N more\" line. In a party, everyone is listed. Click an item's panel to list everyone on it."] = "在團隊中，每件物品只列出這麼多位玩家的擲骰：贏家，然後需求優先於貪婪，點數高的在前。其餘的會計入「還有 N 人」一行。在隊伍中，所有人都會列出。點擊物品的面板即可列出所有人。"
L["In class color"] = "職業顏色"
L["In combat is ticked, and you're fighting"] = "已勾選「戰鬥中」，且你正在戰鬥"
L["In combat is ticked, but CineMode doesn't stay on in fights"] = "已勾選「戰鬥中」，但 CineMode 在戰鬥中不會保持開啟"
L["In combat is ticked: it shows when a fight starts"] = "已勾選「戰鬥中」：戰鬥開始時顯示"
L["In gusts"] = "陣風"
L["In no scene"] = "不在任何場景中"
L["In the bar:"] = "計量條內："
L["In the middle of the screen (a subtitle: low on it)."] = "在畫面中央（字幕：在下方）。"
L["In the zones listed here, the minimap stays up during CineMode: say, one where you do a lot of dailies. Caves and towns inside a zone count as the zone."] = "在此列出的區域中，CineMode 期間小地圖會保持顯示：例如你常做每日任務的區域。區域內的洞穴與城鎮算作該區域。"
L["In these zones:"] = "在這些區域中："
L["Inner edge:"] = "內側邊緣："
L["Inside buildings and caves, the camera modes zoom out less and swing less, so the camera doesn't keep pushing into walls and ceilings. Uses the game's own indoor check."] = "在建築物與洞穴中，鏡頭模式會拉遠得較少、擺動得較少，讓鏡頭不會一直撞進牆壁與天花板。使用遊戲本身的室內判斷。"
L["Inside it: %s"] = "其內：%s"
L["Inspect: click any frame to see why it's showing or hidden. Right-click or Escape to stop."] = "檢查：點擊任何框架即可查看它為何顯示或隱藏。按右鍵或 Esc 停止。"
L["Inspecting someone, a button just right of their level and class opens their talents, and one with their portrait on the talents window takes you back to the inspect window. Not in a fight."] = "觀察某人時，他們等級與職業右側的按鈕可開啟他們的天賦，天賦視窗上有他們頭像的按鈕可帶你回到觀察視窗。戰鬥中無法使用。"
L["Instead of a rule, this row shows whenever another row of its table does, however that one is set now or later. All or nothing: none of this row's own settings count while it follows, and they're kept for when it stops (Grid on the row)."] = "此列不使用規則，而是在其表格的另一列顯示時就顯示，無論那一列現在或之後如何設定。全有或全無：跟隨期間，此列自己的設定都不算數，並會保留到停止跟隨時（該列的「表格」）。"
L["Instead of stopping between moves, the camera keeps creeping slowly back toward the middle."] = "鏡頭在兩次移動之間不會停下，而是持續緩慢地往中央移回。"
L["Interface Style"] = "介面風格"
L["Interrupted"] = "已打斷"
L["Is Cinematic slowing your game?"] = "Cinematic 讓你的遊戲變慢了嗎？"
L["It ends"] = "它結束"
L["It goes with the %s row, which is hidden"] = "它跟隨 %s 列，而該列已隱藏"
L["It shows only if something happened that's ticked here: quests, a level, bosses, deaths or gold. The zone and time played come with it."] = "只有當此處勾選的事情發生過時才會顯示：任務、升級、首領、死亡或金幣。區域與遊戲時間會一併顯示。"
L["It sits where the game's %s was, or is named like it: it takes that row's ticks on the Game Frames page until you give it its own."] = "它位於遊戲的 %s 原本的位置，或名稱與之相似：在你給它自己的設定之前，它會採用遊戲框架頁面中該列的勾選。"
L["It starts once the swing behind you is done, while the zoom carries on. The tilt down follows."] = "它在轉到你身後完成後開始，縮放則持續進行。之後接著向下傾斜。"
L["It stops"] = "它停止"
L["It's full (or you can't afford any)."] = "已經滿了（或你買不起）。"
L["Items shown at once"] = "同時顯示的物品數"
L["Items you can't use (armor or weapons you can't wear, another class's, or a level you're not yet: anything in red on its tooltip) don't get a panel. Their rolls are only in chat."] = "你無法使用的物品（無法穿戴的護甲或武器、其他職業的，或你尚未達到的等級：滑鼠提示上任何紅字的東西）不會有面板。它們的擲骰只會出現在聊天中。"
L["Its card"] = "其卡片"
L["Its cast bar isn't faded, like the game's."] = "它的施法條不會淡出，與遊戲的一樣。"
L["Its choices come next."] = "接下來是它的選項。"
L["Its color."] = "它的顏色。"
L["Its color. Auto: your class and spec's (the glow of the Vitals Vision theme Auto picks for you), changing with your spec. Or pick any class and spec's, or your own color beside this."] = "它的顏色。自動：你職業與專精的顏色（Vitals Vision 主題「自動」為你選的光暈），隨你的專精改變。或選擇任何職業與專精的顏色，或旁邊你自己的顏色。"
L["Its colors, bars and words, and where it sits."] = "它的顏色、計量條與文字，以及它的位置。"
L["Its group is kept up through the death camera"] = "它的群組在死亡鏡頭期間保持顯示"
L["Its height, next to the game's (nameplates only). The health bar and name ride up on it."] = "它的高度，相對於遊戲的高度（僅限名條）。生命條與名稱會隨之上移。"
L["Its icon is on the master wheel, which opens it. Untick to leave it off: its own key still brings it up. The master wheel is the same for all your characters."] = "它的圖示在主輪盤上，可由主輪盤開啟。取消勾選可將它移除：它自己的按鍵仍可叫出它。主輪盤所有角色共用。"
L["Its info panel (XP bar and minimap) follows the Minimap row on the Game Frames page; its unit frames, bars, buffs, chat and quest tracker follow the rows of the frames they replace."] = "它的資訊面板（經驗值條與小地圖）跟隨遊戲框架頁面的小地圖列；它的單位框架、計量條、增益、聊天與任務追蹤則跟隨它們所取代之框架的列。"
L["Its key binding in the corner"] = "角落顯示其按鍵設定"
L["Its look is on the Style tab, a sound for each time of day on the Sounds tab."] = "它的外觀在樣式分頁，每個時段的音效在音效分頁。"
L["Its look is on the Style tab, its sound on the Sounds tab."] = "它的外觀在樣式分頁，音效在音效分頁。"
L["Its look is the Victory style's (the Style tab), its sound on the Sounds tab."] = "它的外觀為「勝利」樣式（樣式分頁），音效在音效分頁。"
L["Its messages show chat any time the UI is faded. (The other columns then have nothing to add.)"] = "介面淡出時，它的訊息隨時都會顯示聊天。（其他欄便沒有什麼可補充的了。）"
L["Its messages show chat in battlegrounds and arenas."] = "它的訊息在戰場與競技場中會顯示聊天。"
L["Its messages show chat in capital cities."] = "它的訊息在主城中會顯示聊天。"
L["Its messages show chat in dungeons, scenarios and raids."] = "它的訊息在地城、事件與團隊副本中會顯示聊天。"
L["Its messages show chat in fights (while you stay cinematic in them)."] = "它的訊息在戰鬥中會顯示聊天（當你在戰鬥中保持電影模式時）。"
L["Its messages show chat out in the world, inns included (capital cities are Cities)."] = "它的訊息在野外（包括旅店）會顯示聊天（主城屬於「主城」）。"
L["Its messages show chat out of combat with a living enemy targeted."] = "非戰鬥中選取活著的敵人時，它的訊息會顯示聊天。"
L["Its messages show chat out of combat with anything else targeted (friends, NPCs, dead enemies)."] = "非戰鬥中選取其他任何對象（友方、NPC、死亡的敵人）時，它的訊息會顯示聊天。"
L["Its messages show chat while you're in a party or raid, wherever you are."] = "身處隊伍或團隊時，無論在哪裡，它的訊息都會顯示聊天。"
L["Its name in the wheel's middle as you point at it. Empty: its command's first line."] = "指向它時顯示在輪盤中央的名稱。留空：其指令的第一行。"
L["Its name, mark and the rest of the plate move with the bar's edges. Not on WoW Forever: its plates don't change size."] = "它的名稱、標記及名條的其餘部分會隨計量條的邊緣移動。WoW Forever 上無效：其名條不會改變大小。"
L["Its numbers in a color of your own."] = "使用你自己所選顏色的數字。"
L["Its other bars, pet, stance, bag, micro menu, status and art bars are rows on the Standard Frames page."] = "它的其他計量條，寵物、姿態、背包、微型選單、狀態與美術圖列，都是標準框架頁面上的列。"
L["Its other bars, pet, stance, totem, micro, bag and data bars are rows on the Standard Frames page, with its unit frames, buffs and chat panels."] = "它的其他計量條，寵物、姿態、圖騰、微型選單、背包與資料列，都是標準框架頁面上的列，還有它的單位框架、增益與聊天面板。"
L["Its own colors"] = "其自身顏色"
L["Its own:"] = "其自身："
L["Its own: %s. The rest: %s."] = "其自身：%s。其餘：%s。"
L["Its rule, as things are now: %s"] = "它目前的規則：%s"
L["Its size, next to the game's."] = "它的大小，相對於遊戲的大小。"
L["Its style, words, frame and face, and where it sits."] = "它的樣式、文字、框架與外觀，以及它的位置。"
L["Its type, and that type's settings."] = "它的類型，以及該類型的設定。"
L["Its unit frames, cast bar, resource bars, buffs, quest tracker, party and raid frames, XP bar and totems are rows on the Game Frames page."] = "它的單位框架、施法條、資源條、增益、任務追蹤、隊伍與團隊框架、經驗值條及圖騰，都是遊戲框架頁面上的列。"
L["Its unnamed frames"] = "它的無名稱框架"
L["Its warnings aren't faded, like the game's raid warnings."] = "它的警告不會淡出，與遊戲的團隊警告一樣。"
L["Its width, next to the game's, about its middle (nameplates only)."] = "它的寬度，相對於遊戲的寬度，以中央為基準（僅限名條）。"
L["Just at the top"] = "只在頂端"
L["Just the new one"] = "只有新的"
L["Just the text, over the world."] = "只有文字，疊在世界之上。"
L["Just the words, over the world: an outline helps them read."] = "只有文字，疊在世界之上：外框有助於閱讀。"
L["KEEPING IT HIDDEN"] = "使它保持隱藏的原因"
L["Keep bubbles on screen"] = "讓泡泡保持在畫面內"
L["Keep open: a tracked quest"] = "保持開啟：有追蹤的任務"
L["Keep open: always"] = "保持開啟：一律"
L["Keep open: in this zone"] = "保持開啟：在此區域"
L["Keep open: indoors, and you're inside"] = "保持開啟：室內，且你在室內"
L["Keep the active profile as it is now: Reset and each page's Reset put it back to this instead of Cinematic's own settings."] = "保留目前設定檔的現況：「重置」與各頁面的「重置」會還原為此狀態，而不是 Cinematic 本身的設定。"
L["Keep windows open across a reload"] = "重新載入後保持視窗開啟"
L["Keeping a frame up, always or in fights, is on the Game Frames page; your own while you recover, on the Resource Display page."] = "要讓框架一直顯示或在戰鬥中顯示，請到遊戲框架頁面；你在恢復期間的框架，請到資源顯示頁面。"
L["Keeps the Cooldown Manager up until every cooldown in its Essential bar (and Enhanced Cooldown Manager's cooldown bars) is ready again, then it fades. Not the global cooldown, nor its buff bars. (It brings up the Hover groups with Cooldown recharging ticked: the Cooldowns group by default.)"] = "讓冷卻管理器保持顯示，直到其「核心」列中的每個冷卻（以及 Enhanced Cooldown Manager 的冷卻條）都再次就緒，然後淡出。不含公共冷卻，也不含其增益列。（它會讓勾選了「冷卻充能中」的滑鼠指向群組顯示：預設為冷卻群組。）"
L["Keeps the Cooldown Manager up until every cooldown in its Utility bar is ready again, then it fades. (It brings up the Hover groups with Cooldown recharging ticked: the Cooldowns group by default.)"] = "讓冷卻管理器保持顯示，直到其「輔助」列中的每個冷卻都再次就緒，然後淡出。（它會讓勾選了「冷卻充能中」的滑鼠指向群組顯示：預設為冷卻群組。）"
L["Keeps the quest tracker's timers up in CineMode, and in fights, while one counts down: a scenario's or assault's timer, a dungeon's clock, a timed quest's bar. Just the timer's quest or scenario: the rest of the tracker stays faded. Hovering it shows it all."] = "在 CineMode 及戰鬥中，當任務追蹤中有計時器在倒數時保持顯示：事件或突襲的計時器、地城的時鐘、限時任務的計量條。只顯示該計時器的任務或事件：追蹤的其餘部分保持淡出。滑鼠指向它會全部顯示。"
L["Keeps your pet frame up after a fight or a fall, within the Calm Timer, until your pet's health is full."] = "戰鬥或墜落後，在平靜計時內保持顯示你的寵物框架，直到你寵物的生命值全滿。"
L["Keeps your pet frame up in CineMode, and in fights, while its happiness isn't green: content (yellow) or unhappy (red). It goes again once your pet is happy."] = "當寵物的快樂度不是綠色時（滿足：黃色，不快樂：紅色），在 CineMode 及戰鬥中保持顯示你的寵物框架。寵物快樂後就會再次隱藏。"
L["Keeps your player frame up after a fight, a fall or resurrecting, until your health and power are full. Rage and runic power don't count."] = "戰鬥、墜落或復活後，保持顯示你的玩家框架，直到你的生命值與能量全滿。怒氣與符文能量不計算在內。"
L["Kept from the %s profile, which Cinematic no longer has."] = "保留自 %s 設定檔，Cinematic 已不再提供該設定檔。"
L["Key"] = "按鍵"
L["Key binding"] = "按鍵設定"
L["Kill streak"] = "連殺"
L["Land and buildings"] = "地形與建築"
L["Last recording: %s, %s"] = "上次記錄：%s，%s"
L["Last recording: %s, %s, detailed"] = "上次記錄：%s，%s，詳細"
L["Last tooltip"] = "上一個滑鼠提示"
L["Later around the wheel."] = "在輪盤上較後面。"
L["Layout"] = "版面配置"
L["Learned"] = "已學會"
L["Leave the speaker off center"] = "讓說話者偏離中央"
L["Leaving combat"] = "離開戰鬥"
L["Leaving the quest giver, the camera stays close until you walk more than 10 yards from where you started talking (talk to another quest giver and it counts from there), then zooms back out to your own distance at this speed, in a few seconds at most. At 0 it stays in."] = "離開任務 NPC 時，鏡頭會保持近距離，直到你離開開始對話的位置超過 10 碼（與另一個任務 NPC 對話則從那裡重新計算），然後以此速度拉遠回你自己的距離，最多只需幾秒。設為 0 則保持拉近。"
L["Left-click: add a point. Right-click: take one back."] = "左鍵：加一點。右鍵：收回一點。"
L["Letterbox scale"] = "黑邊縮放"
L["Level %d"] = "等級 %d"
L["Level reached"] = "達到的等級"
L["Level required: %s"] = "需要等級：%s"
L["Level up"] = "升級"
L["Lift speed"] = "上升速度"
L["Light words on a dark, see-through bubble with a thin edge, in Arial Narrow."] = "深色半透明泡泡上的淺色文字，帶細邊，Arial Narrow 字型。"
L["Light words on dark, see-through panels, in Arial Narrow."] = "深色半透明底板上的淺色文字，Arial Narrow 字型。"
L["Lightning"] = "閃電"
L["Like the game's"] = "與遊戲相同"
L["Like the game's names"] = "與遊戲的名稱相同"
L["Like the quest window's page."] = "與任務視窗的頁面相同。"
L["Line along the edge:"] = "沿著邊緣的線："
L["Line up behind you over %s s"] = "在 %s 秒內轉到你身後"
L["Lines"] = "行"
L["Lit"] = "亮起"
L["Living NPCs that aren't elite, rare elite or a boss (minor critters too). Normal NPC - Enemy starts faded to 40% while an elite enemy is within about 28 yards (its When rule: elite28), so in a pull the elites stand out."] = "非精英、稀有精英或首領的活著 NPC（也包括次要小動物）。「普通 NPC - 敵方」在約 28 碼內有精英敵人時，起初淡出至 40%（其「符合時機」規則：elite28），讓拉怪時精英更醒目。"
L["Living elite, rare elite and boss NPCs."] = "活著的精英、稀有精英與首領 NPC。"
L["Location"] = "位置"
L["Logic"] = "邏輯"
L["Look around for speakers off screen"] = "四處尋找畫面外的說話者"
L["Look in the background"] = "背景中的外觀"
L["Look:"] = "外觀："
L["Looking out"] = "向外看"
L["Looking... %ds"] = "尋找中……%ds"
L["Looks once a second for a while, so a frame that only shows now and then is caught: bring it up while it runs. Click again to stop."] = "在一段時間內每秒尋找一次，以捕捉偶爾才顯示的框架：在它運作時讓那個框架出現。再次點擊即可停止。"
L["Looks over what's on screen for other addons' frames that nothing fades, and guesses which Game Frames row each stands in for. Add one to fade it: it goes on the Loaded tab, under its addon."] = "檢查畫面上沒有被淡出的其他插件框架，並猜測每個框架對應遊戲框架頁面的哪一列。加入其中一個即可淡出它：它會出現在「已載入」分頁中其插件之下。"
L["Loot rolls"] = "拾取擲骰"
L["Lost"] = "失敗"
L["Lost:"] = "失去："
L["Low mana"] = "法力不足"
L["Low mana brings up your player frame as well as your resource bar."] = "法力不足時除了資源條，也會顯示你的玩家框架。"
L["Low on the left of the screen, as a film names someone, its line fading out to the right."] = "畫面左下方，就像電影介紹人物一樣，其線條向右淡出。"
L["Lower picks: %d"] = "較低的選擇：%d"
L["Lower third"] = "下方三分之一"
L["Lower third with no letterbox"] = "無黑邊的下方三分之一"
L["Made by %s"] = "由 %s 製作"
L["Made from these settings. Copy the camera to change the step itself."] = "由這些設定產生。複製鏡頭才能變更步驟本身。"
L["Made up"] = "模擬"
L["Make a scene of your own: its triggers (an emote, a spell, a buff, a place, a moment, something you are, or a key), the camera it plays and when it ends."] = "建立你自己的場景：它的觸發條件（表情動作、法術、增益、地點、時刻、你的某種狀態，或按鍵）、它播放的鏡頭，以及何時結束。"
L["Make a shot, starting from the cozy camera's own numbers. Pick another camera for it below."] = "建立鏡頭片段，以悠閒鏡頭本身的數值為起點。可在下方為它選擇其他鏡頭。"
L["Make this layout again as Cinematic has it, undoing any changes you made to it in Edit Mode."] = "依 Cinematic 的方式重新建立此版面配置，還原你在編輯模式中對它所做的任何變更。"
L["Makes the tint stronger on this client, whose brighter, more colorful world shows the same tint less than retail does. Off: the tint as the Strength slider sets it."] = "在此用戶端上加強色調，因為它的世界更明亮、色彩更豐富，同樣的色調會比正式版顯得淡。關閉：色調依強度滑桿設定。"
L["Mana"] = "法力"
L["Mana bar"] = "法力條"
L["Mana bar:"] = "法力條："
L["Manage and share"] = "管理與分享"
L["Mark"] = "標記"
L["Mark %d%%"] = "標記 %d%%"
L["Mark's"] = "標記的"
L["Marker wheel"] = "標記輪盤"
L["Marks"] = "標記"
L["Master wheel"] = "主輪盤"
L["Max level"] = "最高等級"
L["Max width"] = "最大寬度"
L["Max zoom distance"] = "最大縮放距離"
L["Meanwhile the camera pulls back this far, and returns to your own distance afterwards. Zooming yourself leaves it where you put it."] = "同時鏡頭會拉遠這麼多，之後再回到你自己的距離。若你自己縮放，則保持在你設定的位置。"
L["Mechanical Squirrel"] = "機械松鼠"
L["Members more than 100 yards away show this much, out of reach of your heals, whatever their health, debuffs or role (unless one is your target). In a dungeon or raid, so does anyone not in it with you. In battlegrounds, where WoW Forever won't say how far anyone is, members out of range of your heals (about 40 yards) fade to this instead of the game's own dimming, on top of the rest of the page. 100% leaves them be; 0% hides them completely."] = "距離超過 100 碼、超出你治療範圍的成員，不論生命值、減益或職責，都以此程度顯示（除非是你的目標）。在地城或團隊副本中，沒有和你在一起的人也一樣。在戰場中，由於 WoW Forever 不會告知任何人的距離，超出你治療範圍（約 40 碼）的成員會淡出至此值，取代遊戲本身的變暗效果，並疊加此頁面的其他設定。100% 表示不處理；0% 表示完全隱藏。"
L["Memory made and thrown away, a second: the game spends time clearing it up."] = "每秒產生並丟棄的記憶體：遊戲需要花時間清理它。"
L["Menu look"] = "選單外觀"
L["Mine"] = "我的"
L["Minimal"] = "極簡"
L["Minimap Glow Helper"] = "小地圖光暈輔助"
L["Minimap header"] = "小地圖標題"
L["Minion"] = "僕從"
L["Mobs and NPCs you still need for a quest objective keep their nameplates up, with a quest mark on them and on your target frame, and the quest object in front of you glows."] = "你在任務目標中仍需要的怪物與 NPC 會保持顯示其名條，名條上及你的目標框架上會有任務標記，你面前的任務物體也會發光。"
L["Moment"] = "時刻"
L["Moments"] = "時刻"
L["Mor'Ladim"] = "莫拉迪姆"
L["More themes"] = "更多主題"
L["Motes of its color winding in from the rim."] = "其顏色的光點從邊緣蜿蜒而入。"
L["Motes spiraling in"] = "螺旋湧入的光點"
L["Mounted"] = "騎乘中"
L["Mouseover"] = "滑鼠指向"
L["Mouseover min opacity"] = "滑鼠指向最低不透明度"
L["Mouseover, at least"] = "滑鼠指向，至少"
L["Move"] = "移動"
L["Move across"] = "橫向移動"
L["Move apart from the game's roll frames"] = "與遊戲的擲骰框架分開移動"
L["Move down"] = "下移"
L["Move this emote up: its button comes first."] = "上移此表情動作：它的按鈕會排在前面。"
L["Move this row down: a plate tries it later."] = "下移此列：名條會較晚嘗試它。"
L["Move this row down: its trigger tries it later."] = "下移此列：其觸發條件會較晚嘗試它。"
L["Move this row up: a plate tries it sooner."] = "上移此列：名條會較早嘗試它。"
L["Move this row up: its trigger tries it sooner."] = "上移此列：其觸發條件會較早嘗試它。"
L["Move this rule up: it's read before the ones below it."] = "上移此規則：它會在下方規則之前判斷。"
L["Move up"] = "上移"
L["Moves a name up (or down, below 0) from where the plates put it, with its unit about 10 yards from the camera."] = "單位距離鏡頭約 10 碼時，將名稱從名條原本的位置上移（低於 0 則下移）。"
L["Moves a name up (or down, below 0) with its unit about 50 yards from the camera, as the game's names over heads sit closer to the head further off."] = "單位距離鏡頭約 50 碼時將名稱上移（低於 0 則下移），因為遊戲頭頂的名稱在較遠處會更貼近頭部。"
L["Moves the card from where its place puts it: right, or left below 0, as a share of the screen's width."] = "將卡片從其位置設定所在處移動：向右，低於 0 則向左，以畫面寬度的比例表示。"
L["Moves the card from where its place puts it: up, or down below 0, as a share of the screen's height."] = "將卡片從其位置設定所在處移動：向上，低於 0 則向下，以畫面高度的比例表示。"
L["Moves the marks drawn over the plate (arrow, chevron, diamond) up, or down below 0, from just over the name, while the plate shows."] = "名條顯示時，將繪製在名條上方的標記（箭頭、V 形、菱形）從名稱正上方上移，低於 0 則下移。"
L["Moves the marks drawn over the plate up, or down below 0, from where the plate's middle is, while nothing of the plate shows. As the plate fades in or out, the marks move between the two heights."] = "名條完全不顯示時，將繪製在名條上方的標記從名條中央上移，低於 0 則下移。名條淡入或淡出時，標記會在兩個高度之間移動。"
L["Moves the names up (or down, below 0) from where the plates put them."] = "將名稱從名條原本的位置上移（低於 0 則下移）。"
L["Moves the real camera through this script now (click again to stop it). Its stop rules count, as for a trigger."] = "現在就讓實際鏡頭照此腳本移動（再次點擊即可停止）。其停止規則有效，與觸發時相同。"
L["Moves the real camera through this script now, with a drawing of it beside the settings and its steps lit up as it goes (click again to stop it). Its stop rules count, as for a trigger."] = "現在就讓實際鏡頭照此腳本移動，設定旁會顯示其示意圖，並在進行時點亮各步驟（再次點擊即可停止）。其停止規則有效，與觸發時相同。"
L["Moving, jumping or Esc cancels the cast: the spin slows to a stop and turns back to where the camera was before you started. Off: it stops where it is."] = "移動、跳躍或 Esc 會取消施法：旋轉會減速停止，並轉回你開始前鏡頭所在的位置。關閉：停在原處。"
L["Music can play all through CineMode. (The other columns then have nothing to add.)"] = "音樂可在 CineMode 期間全程播放。（其他欄便沒有什麼可補充的了。）"
L["Music fades out once you leave the camera modes and move on: walking off from the cozy camera, say. Going from one camera straight to another (vista to cozy) keeps it playing, as does standing still. A fresh track fades in when the next camera starts (standing still counts once the AFK camera starts, with Go AFK's music on, Scenes page). Fades at the music fade time."] = "離開鏡頭模式並繼續前進時，音樂會淡出：例如從悠閒鏡頭走開。從一個鏡頭直接換到另一個（遠景到悠閒）會繼續播放，站著不動也一樣。下一個鏡頭啟動時會淡入新曲目（站著不動在暫離鏡頭啟動後才算，需在場景頁面開啟「暫離」的音樂）。依音樂轉換時間淡出。"
L["Music file IDs, separated by commas. One is picked at random while the Die row's Music is ticked on the Scenes page."] = "音樂檔案 ID，以逗號分隔。在場景頁面勾選「死亡」列的音樂時，會隨機選擇其中一首。"
L["Music file IDs, separated by commas; one is picked at random each time you die (Wowhead lists the IDs on each sound's page). Try one with /cine songtest <ID>."] = "音樂檔案 ID，以逗號分隔；每次你死亡時隨機選擇一首（Wowhead 在每個音效的頁面上列出 ID）。用 /cine songtest <ID> 試聽。"
L["Music plays in"] = "音樂播放於"
L["Music starts as its camera starts (Audio page)."] = "音樂在其鏡頭啟動時開始（音效頁面）。"
L["Music starts as this event's camera starts, unless the addon started music within the fatigue time (Audio page). Music already playing just carries on. Off: this camera never starts music. Needs the Audio page enabled."] = "音樂在此事件的鏡頭啟動時開始，除非插件在疲勞時間內已經播放過音樂（音效頁面）。已在播放的音樂會繼續。關閉：此鏡頭永不播放音樂。需要啟用音效頁面。"
L["My %s"] = "我的%s"
L["My Scene"] = "我的場景"
L["My Shots"] = "我的鏡頭片段"
L["My camera"] = "我的鏡頭"
L["My camera %d"] = "我的鏡頭 %d"
L["My wheel"] = "我的輪盤"
L["NOT CINEMATIC'S"] = "不屬於 CINEMATIC"
L["NOT FADED"] = "未淡出"
L["NOT SHOWING IT NOW"] = "目前未顯示它的原因"
L["NPC"] = "NPC"
L["NPC dialogue, and how it looks: the panels behind the NPC's words, your replies and the quest's card, and the words themselves. Where it sits: the Vision tab. Changes show at once, here and on a conversation going on."] = "NPC 對話及其外觀：NPC 話語後方的底板、你的回覆與任務卡片，以及文字本身。位置：Vision 分頁。變更會立即顯示，包括此處及進行中的對話。"
L["NPCs"] = "NPC"
L["NPCs chatting nearby"] = "附近閒聊的 NPC"
L["NPCs you talk to"] = "你對話的 NPC"
L["Name"] = "名稱"
L["Name color:"] = "名稱顏色："
L["Name style"] = "名稱樣式"
L["Name:"] = "名稱："
L["Nameplate"] = "名條"
L["Nameplate distance"] = "名條距離"
L["Names in Russian, Korean or Chinese keep the game's font, so their letters show."] = "俄文、韓文或中文名稱會保留遊戲的字型，以便正確顯示字元。"
L["Near (11 yards)"] = "近（11 碼）"
L["Near (28 yards)"] = "近（28 碼）"
L["Nearby"] = "附近"
L["Nearly every one of the addon's functions timed too, not just its busy parts, each listed under the part that called it: it shows what inside a busy part costs. The timing itself takes time, so everything reads higher than it is."] = "幾乎為插件的每個函式計時，而不只是其忙碌部分，每個都列在呼叫它的部分之下：它會顯示忙碌部分內部的耗費。計時本身也需要時間，所以所有數值都會比實際高。"
L["Need"] = "需求"
L["Need (off spec)"] = "需求（副專精）"
L["Need, Greed or Transmog after each name, in their colors."] = "每個名稱後以其顏色顯示需求、貪婪或塑形。"
L["Need, greed and who won."] = "需求、貪婪及誰贏了。"
L["Neutral"] = "中立"
L["Neutral players"] = "中立玩家"
L["Never"] = "永不"
L["Never counts in fights: the game won't say how far anyone is then. Spell range does."] = "戰鬥中永不計算：那時遊戲不會告知任何人的距離。法術範圍則可以。"
L["New features"] = "新功能"
L["New mount"] = "新坐騎"
L["New pet"] = "新寵物"
L["New scene"] = "新增場景"
L["New shot..."] = "新增鏡頭片段……"
L["Newest first. Restoring one adds it as a new profile and switches to it; the profile it came from stays as it is."] = "最新的在前。還原其中一個會將它加入為新設定檔並切換過去；它原本所屬的設定檔維持原狀。"
L["Next"] = "下一個"
L["Next rank:"] = "下一級："
L["Night (game time)"] = "夜晚（遊戲時間）"
L["No action"] = "無動作"
L["No border around the letters, like the game's names over heads."] = "文字周圍沒有外框，與遊戲的頭頂名稱相同。"
L["No bubble: just the words, outlined, like a film's subtitles."] = "沒有泡泡：只有帶外框的文字，像電影字幕一樣。"
L["No button"] = "無按鈕"
L["No card coming out of a fight shorter than this, so a stray hit doesn't bring it up. 0: after every fight."] = "比此更短的戰鬥結束時不顯示卡片，這樣隨意一擊就不會讓它出現。0：每場戰鬥後都顯示。"
L["No card uses it yet."] = "尚無卡片使用它。"
L["No emotes match."] = "沒有符合的表情動作。"
L["No emotes: no card"] = "沒有表情動作：沒有卡片"
L["No panels behind the cards: outlined text over the world, the winner just crowned."] = "卡片後方沒有底板：帶外框的文字疊在世界之上，贏家只加上王冠。"
L["No panels: outlined words, like a film's subtitles."] = "沒有底板：帶外框的文字，像電影字幕一樣。"
L["No profile yet"] = "尚無設定檔"
L["No recording yet."] = "尚無記錄。"
L["No red error text at the top of the screen (like \"Target not in line of sight\" or \"Can't do that while moving\") while you're fighting, and for the Calm Timer after it."] = "戰鬥中及戰鬥後的平靜計時內，畫面頂端不顯示紅色錯誤文字（例如「目標不在視線範圍內」或「移動中無法那麼做」）。"
L["No red error text at the top of the screen (like \"Target not in line of sight\" or \"Can't do that while moving\") while you're out of combat."] = "非戰鬥中，畫面頂端不顯示紅色錯誤文字（例如「目標不在視線範圍內」或「移動中無法那麼做」）。"
L["No rolls yet."] = "尚無擲骰。"
L["No samples yet (one a second)."] = "尚無取樣（每秒一次）。"
L["No scene plays it yet: pick it as a scene's camera on the Scenes page."] = "尚無場景播放它：在場景頁面將它選為某個場景的鏡頭。"
L["No scene plays this camera yet: pick it as a scene's camera on the Scenes page."] = "尚無場景播放此鏡頭：在場景頁面將它選為某個場景的鏡頭。"
L["No shots yet. + New shot makes one, or Import adds one a friend shared."] = "尚無鏡頭片段。「+ 新增鏡頭片段」可建立一個，或用「匯入」加入朋友分享的。"
L["No sounds: silent"] = "沒有音效：靜音"
L["No spell"] = "無法術"
L["No tooltip yet this session: point at something, then look again"] = "本次登入尚無滑鼠提示：先指向某個東西，再來看看"
L["None found"] = "找不到"
L["None of its own: it's all %s."] = "沒有自己的設定：全部依照 %s。"
L["None yet. A built-in profile is backed up just before Reset."] = "目前沒有。內建設定檔會在「重置」前備份。"
L["None yet. One's taken the first day this profile changes, and just before Delete."] = "目前沒有。此設定檔第一次變更的那天，以及「刪除」之前，會各備份一份。"
L["None yet. Your own profiles are backed up the first day they change, and just before Delete; built-in ones just before Reset."] = "目前沒有。你自己的設定檔會在變更的第一天及「刪除」之前備份；內建的則在「重置」之前。"
L["None: its own settings"] = "無：使用其自身設定"
L["Normal"] = "普通"
L["Normal NPC"] = "普通 NPC"
L["Not a script yet: it runs on its own code. Laying it out as steps needs %s, steps the runner doesn't have yet."] = "尚未變成腳本：它以自己的程式碼運作。要將它排成步驟，需要 %s，這些步驟執行器目前還沒有。"
L["Not after fights under"] = "短於此的戰鬥後不顯示"
L["Not again within"] = "在此時間內不再顯示"
L["Not bosses"] = "非首領"
L["Not finished: %s. Closing now puts back the rule it had."] = "尚未完成：%s。現在關閉會還原它原本的規則。"
L["Not finished: %s. Its ticks decide until it is."] = "尚未完成：%s。完成前由勾選方塊決定。"
L["Not finished: %s. The dropdowns decide until it is."] = "尚未完成：%s。完成前由下拉選單決定。"
L["Not for dailies"] = "不含每日任務"
L["Not in %s"] = "不在%s"
L["Not in a fight."] = "非戰鬥中。"
L["Not in fights"] = "非戰鬥中"
L["Not in the Cooldown Manager now"] = "目前不在冷卻管理器中"
L["Not on flight paths"] = "不在飛行路線上"
L["Not on it"] = "不在其上"
L["Not on screen right now."] = "目前不在畫面上。"
L["Not on you"] = "不在你身上"
L["Not ones lasting longer than"] = "不含持續時間超過"
L["Not shown at all in a fight, or in the 5 seconds after one."] = "戰鬥中及戰鬥後 5 秒內完全不顯示。"
L["Not the damage meter's numbers: your race with the player ahead of you, or your lead over #2 once you're #1. It reads the game's own damage meter, so that needs to be on (Options, Gameplay Enhancements: Enable Damage Meter). Its type: the Settings tab. How it looks: the Look tab."] = "不是傷害統計的數字：而是你與前一名玩家的競賽，或你成為第 1 名後對第 2 名的領先。它讀取遊戲本身的傷害統計，所以需要開啟（選項 > 遊戲玩法增強：啟用傷害統計）。其類型：設定分頁。外觀：外觀分頁。"
L["Not with a soulstone or Reincarnation"] = "有靈魂石或復生時除外"
L["Not you"] = "不是你"
L["Nothing"] = "無"
L["Nothing found yet. Smart Find looks at what's on screen: run it while the frames you want are showing."] = "尚未找到任何東西。「智慧尋找」會檢查畫面上的內容：請在你要的框架顯示時執行它。"
L["Nothing in the Cooldown Manager right now."] = "冷卻管理器目前沒有任何內容。"
L["Nothing is ticked on its row: tick Always to keep it up"] = "其列上沒有勾選任何項目：勾選「一律」可讓它保持顯示"
L["Nothing of its own here: its look is on the Style tab, its sound on the Sounds tab."] = "此處沒有它自己的設定：它的外觀在樣式分頁，音效在音效分頁。"
L["Nothing on it yet"] = "上面還沒有東西"
L["Nothing on the meter yet."] = "統計上還沒有任何數據。"
L["Nothing ticked"] = "未勾選任何項目"
L["Nothing yet."] = "目前沒有。"
L["Now"] = "現在"
L["Now and then in the middle of a flight, the camera slowly turns round to look back past you, holds there, then turns back behind you. On a route's first flight (its length not known yet), just one, early on. Dragging the camera stops it. /cine flyby starts one whenever you like. Once you move the camera yourself on a flight, there are no more for that flight."] = "飛行途中不時地，鏡頭會緩緩轉身越過你往後看，停留一會兒，然後轉回你身後。在某條路線的第一次飛行（尚不知其長度）時，只會在早段出現一次。拖曳鏡頭會停止它。/cine flyby 可隨時啟動一次。你在飛行中自己移動鏡頭後，該次飛行就不會再出現。"
L["Now: %s"] = "現在：%s"
L["Numbers follow the game's Show Numbers for Cooldowns"] = "數字依照遊戲的「顯示冷卻時間數字」"
L["Numbers opacity"] = "數字不透明度"
L["Object detail distance"] = "物體細節距離"
L["Object fade distance"] = "物體淡出距離"
L["Objective boxes (below the minimap)"] = "目標方框（小地圖下方）"
L["Objects and creatures"] = "物體與生物"
L["Off with the General page's switch."] = "已由一般頁面的開關關閉。"
L["Off-screen bubble"] = "畫面外泡泡"
L["Off-screen plates in CineMode"] = "CineMode 中的畫面外名條"
L["Off. Right-click to turn this page on."] = "關閉。按右鍵開啟此頁面。"
L["Off: %s"] = "關閉：%s"
L["Off: right-click the Profiler icon to sample."] = "關閉：在效能分析器圖示上按右鍵即可取樣。"
L["Off: the UI stays as it is and the camera's left to you, with just the visual effects over it (as the Visual Effects page says), as in the Subtle profile. Triggers with CineMode ticked on the Scenes page still bring CineMode on while their camera runs: standing still or going AFK, say, for a screensaver."] = "關閉：介面維持原樣，鏡頭由你自己控制，只在上面套用視覺效果（依視覺效果頁面的設定），與「Subtle」設定檔相同。在場景頁面勾選了 CineMode 的觸發條件，仍會在其鏡頭運作期間開啟 CineMode：例如站著不動或暫離時，當作螢幕保護程式。"
L["Offline"] = "離線"
L["Offline members are hidden whatever their health, debuffs or role (unless one is your target). How much of them still shows. 0% hides them completely."] = "離線的成員不論生命值、減益或職責都會隱藏（除非是你的目標）。此為他們仍顯示的程度。0% 表示完全隱藏。"
L["Offline opacity"] = "離線時不透明度"
L["On a flight path the minimap stays hidden: pings, the reveals above and the tracking and zones under Keep open don't bring it up (you can't gather while flying), and nothing is pinged. Hovering it still shows it."] = "在飛行路線上，小地圖保持隱藏：信號、上方的顯示條件以及「保持開啟」下的追蹤與區域都不會讓它出現（飛行時無法採集），也不會發出任何信號。滑鼠指向它仍會顯示。"
L["On a healer"] = "在治療者身上"
L["On a non-tank"] = "在非坦克身上"
L["On after a fight, until the Calm Timer (CineMode page) has run out. With In combat too: the fight, then that."] = "戰鬥後開啟，直到平靜計時（CineMode 頁面）結束。同時勾選「戰鬥中」時：先是戰鬥，然後是那段時間。"
L["On flight paths. The camera swings around behind you as you take off, sways behind you on the way and settles behind you before landing."] = "搭乘飛行路線時。起飛時鏡頭轉到你身後，途中在你身後擺動，降落前停在你身後。"
L["On in fights, and with the Calm Timer, after them till it's run out."] = "戰鬥中開啟；勾選「平靜計時」時，戰鬥後持續到平靜計時結束。"
L["On out of fights, once the Calm Timer after one has run out. With Calm Timer too: as soon as a fight ends."] = "非戰鬥中開啟，在戰鬥後的平靜計時結束後。同時勾選「平靜計時」時：戰鬥一結束就開啟。"
L["On the bar:"] = "計量條上："
L["On the master wheel"] = "在主輪盤上"
L["On the screen"] = "畫面上"
L["On while a camera mode runs (flights, AFK, cozy and the rest)."] = "鏡頭模式運作時開啟（飛行、暫離、悠閒等）。"
L["On while you have one of these targeted, out of fights."] = "非戰鬥中選取以下其中一種對象時開啟。"
L["On while you're in any of these (Party and Raid: in one, wherever you are)."] = "身處以下任何一處時開啟（隊伍與團隊：身處其中，無論在哪裡）。"
L["On you"] = "在你身上"
L["On. Right-click to turn this page off."] = "開啟。按右鍵關閉此頁面。"
L["On: Heal Vision works as ticked below. Off: it doesn't, and each keeps its tick for when you turn this back on."] = "開啟：Heal Vision 依下方勾選運作。關閉：不運作，各項保留其勾選，供你重新開啟時使用。"
L["On: chat bubbles look as this page says. Off: the game's own bubbles (the preview shows that too). Each setting keeps its value for when you turn this back on. (Not in instances on retail: the game doesn't let addons change bubbles there.)"] = "開啟：對話泡泡依此頁面設定的外觀顯示。關閉：遊戲本身的泡泡（預覽也會顯示）。每項設定都會保留其值，供你重新開啟時使用。（正式版的副本中無效：遊戲不允許插件在那裡變更泡泡。）"
L["On: chat bubbles show where this page says. Off: the game's own chat bubble settings, as you had them."] = "開啟：對話泡泡依此頁面設定的位置顯示。關閉：遊戲本身的對話泡泡設定，維持你原本的設定。"
L["On: each card shows as its row says. Off: none of them do, and each row keeps its tick for when you turn this back on."] = "開啟：每張卡片依其列的設定顯示。關閉：全部不顯示，各列保留其勾選，供你重新開啟時使用。"
L["On: each card shows as the Events tab says, as this tab sets it. Off: none of them do. Each setting keeps its value for when you turn this back on."] = "開啟：每張卡片依事件分頁的設定顯示，並依此分頁設定。關閉：全部不顯示。每項設定都會保留其值，供你重新開啟時使用。"
L["On: each card shows as the Events tab says, in its style. Off: none of them do. Each setting keeps its value for when you turn this back on."] = "開啟：每張卡片依事件分頁的設定，以其樣式顯示。關閉：全部不顯示。每項設定都會保留其值，供你重新開啟時使用。"
L["On: each card shows as the Events tab says, looking as its Style page says. Off: none of them do. Each setting keeps its value for when you turn this back on."] = "開啟：每張卡片依事件分頁的設定顯示，外觀依其樣式頁面。關閉：全部不顯示。每項設定都會保留其值，供你重新開啟時使用。"
L["On: each card shows as the Events tab says, with its sounds. Off: none of them do. Each setting keeps its value for when you turn this back on."] = "開啟：每張卡片依事件分頁的設定顯示，並播放其音效。關閉：全部不顯示。每項設定都會保留其值，供你重新開啟時使用。"
L["On: every Style page looks as it says. Off: none of them do; everything shows the game's look. Each page keeps its settings for when you turn this back on."] = "開啟：每個樣式頁面都依其設定呈現。關閉：全部不套用；一切顯示為遊戲的外觀。各頁面保留其設定，供你重新開啟時使用。"
L["On: everything below works as ticked. Off: none of it does, and each keeps its tick for when you turn this back on."] = "開啟：下方所有項目依勾選運作。關閉：全部不運作，各項保留其勾選，供你重新開啟時使用。"
L["On: it looks as this page says. Off: Cinematic's plain look (the defaults). Each setting keeps its value for when you turn this back on."] = "開啟：依此頁面設定的外觀呈現。關閉：Cinematic 的簡樸外觀（預設值）。每項設定都會保留其值，供你重新開啟時使用。"
L["On: it shows as you cast. Off: it doesn't, and keeps its settings for when you turn this back on."] = "開啟：你施法時顯示。關閉：不顯示，並保留其設定，供你重新開啟時使用。"
L["On: new messages, typing, unread whispers and scrolling back bring up the chat windows as this page says. Off: none of them do, and the chat windows fade as their Game Frames row says."] = "開啟：新訊息、輸入文字、未讀密語與向上捲動會依此頁面設定讓聊天視窗顯示。關閉：全部不會，聊天視窗依其遊戲框架列的設定淡出。"
L["On: right-click (or a gamepad button) casts again, and the Fishing cast bar hides, as this page says. Off: fishing is left to the game. (The fish camera is on the Scenes page.)"] = "開啟：右鍵（或控制器按鈕）可再次拋竿，並依此頁面設定隱藏釣魚施法條。關閉：釣魚交給遊戲處理。（釣魚鏡頭在場景頁面。）"
L["On: the bars look as this page says. Off: Cinematic's own, thin black bars sliding in with the UI's fade (the preview shows that too). Each setting keeps its value for when you turn this back on."] = "開啟：黑邊依此頁面設定的外觀呈現。關閉：Cinematic 本身的細黑邊，隨介面淡出滑入（預覽也會顯示）。每項設定都會保留其值，供你重新開啟時使用。"
L["On: the bars look as this page says. Off: the game's own (the preview shows that too). Each setting keeps its value for when you turn this back on."] = "開啟：計量條依此頁面設定的外觀呈現。關閉：遊戲本身的（預覽也會顯示）。每項設定都會保留其值，供你重新開啟時使用。"
L["On: the button looks as this page says. Off: like the game's extra ability button (the preview shows that too). Each setting keeps its value for when you turn this back on."] = "開啟：按鈕依此頁面設定的外觀呈現。關閉：與遊戲的額外技能按鈕相同（預覽也會顯示）。每項設定都會保留其值，供你重新開啟時使用。"
L["On: the camera moves over your right shoulder. This uses one of Blizzard's experimental camera settings: the game shows its experimental camera warning (Accept keeps it working). The game's Keep Character Centered option (Accessibility) stops it, so that's turned off meanwhile. Off: your own settings come back."] = "開啟：鏡頭移到你的右肩上方。這使用 Blizzard 的一項實驗性鏡頭設定：遊戲會顯示其實驗性鏡頭警告（「接受」可讓它繼續運作）。遊戲的「保持角色置中」選項（協助工具）會阻止它，所以在此期間會關閉該選項。關閉：還原你自己的設定。"
L["On: the cameras start as the rows below say. Off: none of them ever starts, and the camera is left to you; CineMode still fades the UI."] = "開啟：鏡頭依下方各列的設定啟動。關閉：任何鏡頭都不會啟動，鏡頭由你自己控制；CineMode 仍會淡出介面。"
L["On: the cards show as ticked below. Off: none do, and it keeps its settings for when you turn this back on."] = "開啟：卡片依下方勾選顯示。關閉：全部不顯示，並保留其設定，供你重新開啟時使用。"
L["On: the cast bars look as this page says. Off: the game's own (the preview shows that too). Each setting keeps its value for when you turn this back on."] = "開啟：施法條依此頁面設定的外觀呈現。關閉：遊戲本身的（預覽也會顯示）。每項設定都會保留其值，供你重新開啟時使用。"
L["On: the dialogue looks as this page says. Off: parchment, in the game's fonts (the preview shows that too). Each setting keeps its value for when you turn this back on."] = "開啟：對話依此頁面設定的外觀呈現。關閉：羊皮紙，使用遊戲的字型（預覽也會顯示）。每項設定都會保留其值，供你重新開啟時使用。"
L["On: the edges look as this page says. Off: as they start out (each setting keeps its value for when you turn this back on)."] = "開啟：邊緣依此頁面設定的外觀呈現。關閉：依其初始狀態（每項設定都會保留其值，供你重新開啟時使用）。"
L["On: the graph samples the game's figure every second and keeps it over a reload, and you can record. Off (to start with): nothing is sampled or saved, and it costs nothing."] = "開啟：圖表每秒取樣遊戲的數據，重新載入後仍保留，你也可以記錄。關閉（預設）：不取樣也不儲存任何東西，不耗費任何效能。"
L["On: the marks and colors on this page show on the plates, when the Nameplates page's Target Indicator row says. Off: none of them do. Each setting keeps its value for when you turn this back on."] = "開啟：此頁面的標記與顏色會在名條頁面的「目標指示」列允許時顯示在名條上。關閉：全部不顯示。每項設定都會保留其值，供你重新開啟時使用。"
L["On: the raid frames look as this page says. Off: the game's own (the preview shows that too). Each setting keeps its value for when you turn this back on."] = "開啟：團隊框架依此頁面設定的外觀呈現。關閉：遊戲本身的（預覽也會顯示）。每項設定都會保留其值，供你重新開啟時使用。"
L["On: the settings below, as you've set them. Off: the game's own settings, put back as they were."] = "開啟：下方的設定，依你的設定。關閉：遊戲本身的設定，還原為原本的狀態。"
L["On: the unit frames look as this page says. Off: the game's own (the preview shows that too). Each setting keeps its value for when you turn this back on."] = "開啟：單位框架依此頁面設定的外觀呈現。關閉：遊戲本身的（預覽也會顯示）。每項設定都會保留其值，供你重新開啟時使用。"
L["On: the unit frames show the parts the grids below say. Off: CineMode leaves them alone, every part showing as the game has it."] = "開啟：單位框架顯示下方表格所設定的部分。關閉：CineMode 不予處理，每個部分都依遊戲的方式顯示。"
L["On: the window looks as this page says. Off: as Roll Vision has always looked. Each setting keeps its value for when you turn this back on."] = "開啟：視窗依此頁面設定的外觀呈現。關閉：Roll Vision 一直以來的外觀。每項設定都會保留其值，供你重新開啟時使用。"
L["On: these names look as this page says. Off: as the nameplate draws them: white or gray for every unit, with a heavy black outline, growing and shrinking with distance (the preview shows that too). Each setting keeps its value for when you turn this back on."] = "開啟：這些名稱依此頁面設定的外觀呈現。關閉：依名條的繪製方式：每個單位都是白色或灰色，帶粗黑外框，隨距離放大縮小（預覽也會顯示）。每項設定都會保留其值，供你重新開啟時使用。"
L["On: this page's peeks bring your buffs and debuffs up in CineMode. Off: no peeks; they still fade as their Game Frames row says."] = "開啟：此頁面的短暫顯示會在 CineMode 中讓你的增益與減益出現。關閉：不短暫顯示；它們仍依其遊戲框架列的設定淡出。"
L["On: this page's settings can bring the minimap up or keep it up in CineMode. Off: they don't; it still fades as its Game Frames rows say."] = "開啟：此頁面的設定可在 CineMode 中讓小地圖出現或保持顯示。關閉：不會；它仍依其遊戲框架列的設定淡出。"
L["On: this page's settings can bring the quest tracker, quest timer and durability figure up in CineMode. Off: they don't; they still fade as their Game Frames rows say."] = "開啟：此頁面的設定可在 CineMode 中讓任務追蹤、任務計時器與耐久度人形圖出現。關閉：不會；它們仍依其遊戲框架列的設定淡出。"
L["On: this page's settings can fade out the bars you aren't using. Off: they don't; the swing timer still fades as its Game Frames row says, every bar alike."] = "開啟：此頁面的設定可淡出你沒在使用的計時條。關閉：不會；揮擊計時器仍依其遊戲框架列的設定淡出，所有計時條都一樣。"
L["On: this page's settings can keep the Cooldown Manager up in CineMode, or show only the icons you pick. Off: they don't; it still fades as its Game Frames row says."] = "開啟：此頁面的設定可在 CineMode 中讓冷卻管理器保持顯示，或只顯示你選擇的圖示。關閉：不會；它仍依其遊戲框架列的設定淡出。"
L["On: tooltips look as this page says. Off: the game's own (the preview shows that too). Each setting keeps its value for when you turn this back on."] = "開啟：滑鼠提示依此頁面設定的外觀呈現。關閉：遊戲本身的（預覽也會顯示）。每項設定都會保留其值，供你重新開啟時使用。"
L["On: with your game music off, a camera starting (the ones ticked under Music on the Camera Triggers page) switches it on and fades it in, at your music volume; it fades out when the UI returns and your music is switched off again (logging out too). With your game music on, it's left alone, bar the stops below. Off: CineMode leaves your music alone."] = "開啟：當你的遊戲音樂關閉時，鏡頭啟動（鏡頭觸發頁面中「音樂」下勾選的鏡頭）會以你的音樂音量開啟並淡入音樂；介面恢復時淡出，並再次關閉你的音樂（登出時也是）。當你的遊戲音樂開啟時，除了下方的停止條件外不予處理。關閉：CineMode 不處理你的音樂。"
L["On: your player frame, pet frame and personal resource display stay up or wait as this page says, and its mana bar and mana cost show. Off: none of it; they come up only as their Game Frames rows say."] = "開啟：你的玩家框架、寵物框架與個人資源顯示依此頁面設定保持顯示或等待，並顯示其法力條與法力消耗。關閉：全部不套用；它們只依其遊戲框架列的設定出現。"
L["Once anyone picks need, players on greed or transmog for that item aren't listed (they can't win it), only counted on a \"Lower picks\" line. Players still choosing stay listed. Click an item's panel to list everyone on it."] = "一旦有人選擇需求，對該物品選擇貪婪或塑形的玩家就不會列出（他們無法贏得），只會計入「較低的選擇」一行。仍在選擇中的玩家會繼續列出。點擊物品的面板即可列出所有人。"
L["Once it has swung round to face you, the camera sways gently from side to side in front of your character, pausing between moves."] = "轉到面對你之後，鏡頭會在你角色前方輕輕左右擺動，每次移動之間會停頓。"
L["Once round in front, the spin keeps going and picks up speed until you go. 0 keeps a steady speed."] = "轉到前方後，旋轉會持續並加速，直到你傳走。0 表示保持穩定速度。"
L["Once the camera has settled on a speaker, it drifts slowly to and fro, side to side, across this many degrees, so the shot isn't stock-still. 0 holds still."] = "鏡頭對準說話者後，會在這麼多度的範圍內緩緩左右飄移，讓畫面不會完全靜止。0 表示保持不動。"
L["Once the camera has settled, it drifts slowly to and fro, side to side, across this many degrees, so the shot isn't stock-still. 0 holds still."] = "鏡頭停穩後，會在這麼多度的範圍內緩緩左右飄移，讓畫面不會完全靜止。0 表示保持不動。"
L["Once the conversation's over, the camera zooms back out to your own distance at this speed (not if you zoomed yourself meanwhile). At 0 it stays in."] = "對話結束後，鏡頭會以此速度拉遠回你自己的距離（若你在此期間自己縮放過則不會）。設為 0 則保持拉近。"
L["Once you're there (after the loading screen, if there is one), the camera swings around behind you."] = "抵達後（若有載入畫面則在其之後），鏡頭會轉到你身後。"
L["Once you've stood still for a while with the UI faded, or as soon as you go AFK, the camera slowly sweeps around your character. Moving stops it. What starts it, and how long you stand still first, is on the Scenes page."] = "在介面淡出的狀態下站著不動一段時間後，或一暫離，鏡頭就會緩緩繞著你的角色環繞。移動會停止它。什麼會啟動它，以及要先站著不動多久，在場景頁面設定。"
L["One line under the game's zone name, as it comes in at login, in place of a card. (The look above is the card's.)"] = "登入時在遊戲的區域名稱下方顯示一行，取代卡片。（上方的外觀是卡片的。）"
L["One size at any distance. Unticked, a name grows and shrinks with its plate as its unit comes nearer or goes."] = "在任何距離都是同一大小。未勾選時，名稱會隨其名條在單位靠近或遠離時放大縮小。"
L["One thing that starts this scene: an emote you do, a spell you cast, a buff on you, a place you're in, a moment (leveling up...), something you are (mounted...), or a key you press. Any one of a scene's triggers starts it."] = "會啟動此場景的一件事：你做的表情動作、你施放的法術、你身上的增益、你所在的地點、某個時刻（升級……）、你的某種狀態（騎乘中……），或你按下的按鍵。場景的任何一個觸發條件都會啟動它。"
L["Only after progress"] = "僅在有進展後"
L["Only after you use mana, for"] = "僅在你使用法力後，持續"
L["Only in CineMode"] = "僅限 CineMode 中"
L["Only in combat"] = "僅限戰鬥中"
L["Only items of this quality and better get a panel in the window. Rolls on the rest are only in chat. The test (/cine rolls test) goes by it too."] = "只有此品質及以上的物品會在視窗中有面板。其餘物品的擲骰只會出現在聊天中。測試（/cine rolls test）也依此設定。"
L["Only items you can use"] = "只限你能使用的物品"
L["Only out of combat"] = "僅限非戰鬥中"
L["Only show the best pick"] = "只顯示最佳選擇"
L["Only the buff you gained or refreshed shows; your other buffs stay faded. Hovering shows them all. In fights too, for new buffs (procs and the like)."] = "只顯示你獲得或刷新的那個增益；你的其他增益保持淡出。滑鼠指向會全部顯示。戰鬥中也適用於新增益（觸發效果之類）。"
L["Only while you stand still"] = "僅在你站著不動時"
L["Only with Zone ticked: it takes the game's zone text away. Its look follows Zone's until it's given its own here; its lines are Zone's."] = "僅在勾選「區域」時：它會取代遊戲的區域文字。在此給它自己的外觀之前，它的外觀依照「區域」；它的文字行就是「區域」的。"
L["Only:"] = "僅限："
L["Opacity"] = "不透明度"
L["Opacity while hidden"] = "隱藏時不透明度"
L["Opacity:"] = "不透明度："
L["Open"] = "開啟"
L["Open its settings page"] = "開啟其設定頁面"
L["Open on Scenes >"] = "在場景中開啟 >"
L["Open on Scripts >"] = "在腳本中開啟 >"
L["Open or close this moment's emotes."] = "開啟或關閉此時刻的表情動作。"
L["Open the Profiler"] = "開啟效能分析器"
L["Open the log"] = "開啟記錄"
L["Opens the Card Vision page."] = "開啟 Card Vision 頁面。"
L["Opens the Settings tab with this event picked."] = "開啟設定分頁並選取此事件。"
L["Opens the Sounds tab with this event picked."] = "開啟音效分頁並選取此事件。"
L["Opens the Style hub's Cast bars page: how nameplate cast bars look."] = "開啟「風格」分類的施法條頁面：名條施法條的外觀。"
L["Opens the Style hub's Chat bubbles page: how off-screen bubbles look and where they show."] = "開啟「風格」分類的對話泡泡頁面：畫面外泡泡的外觀與顯示位置。"
L["Opens the Style hub's Chat bubbles page: how the bubbles and speech from behind you look."] = "開啟「風格」分類的對話泡泡頁面：泡泡及來自你身後之話語的外觀。"
L["Opens the Style hub's Nameplates page: how nameplates look."] = "開啟「風格」分類的名條頁面：名條的外觀。"
L["Opens the Style hub's Names page: how names over heads look."] = "開啟「風格」分類的名稱頁面：頭頂名稱的外觀。"
L["Opens the Style hub's Personal Resource Display page: how the bars look."] = "開啟「風格」分類的個人資源顯示頁面：計量條的外觀。"
L["Opens the Style hub's Raid frames page: how the raid and raid-style party frames look."] = "開啟「風格」分類的團隊框架頁面：團隊及團隊樣式隊伍框架的外觀。"
L["Opens the Style hub's Tooltips page: how tooltips look."] = "開啟「風格」分類的滑鼠提示頁面：滑鼠提示的外觀。"
L["Opens the Style hub's Unit frames page: how the frames look."] = "開啟「風格」分類的單位框架頁面：框架的外觀。"
L["Opens the Style tab with this event picked."] = "開啟樣式分頁並選取此事件。"
L["Opens the rule editor, for AND, NOT and more places and situations than the dropdowns have."] = "開啟規則編輯器，可使用 AND、NOT，以及比下拉選單更多的地點與情況。"
L["Opens this chat window's lines to copy."] = "開啟此聊天視窗的內容以便複製。"
L["Opens this style on the Card Types tab: a change there is for every card using it."] = "在卡片類型分頁開啟此樣式：在那裡的變更會套用於使用它的每張卡片。"
L["Or find one:"] = "或搜尋一個："
L["Or hits adding up to"] = "或累計傷害達"
L["Orbiting stars"] = "環繞的星星"
L["Other NPCs talking near you, such as a city's citizens chatting among themselves. The same chat camera, once you've stood still for the time below, so passers-by don't swing it about while you're busy."] = "你附近其他正在說話的 NPC，例如主城中彼此閒聊的市民。使用同樣的聊天鏡頭，在你站著不動達下方時間後才啟動，這樣你忙碌時路人就不會讓鏡頭轉來轉去。"
L["Other buffs"] = "其他增益"
L["Other frames"] = "其他框架"
L["Out of combat"] = "非戰鬥中"
L["Out of how many"] = "總數"
L["Outdoors"] = "戶外"
L["Outline"] = "外框"
L["Outline color"] = "外框顏色"
L["Outline:"] = "外框："
L["Over %s"] = "超過 %s"
L["Over after no one talks for"] = "沒有人說話多久後結束"
L["Over it"] = "其上方"
L["Own row"] = "自己的列"
L["PARTLY SHOWN"] = "部分顯示"
L["Pages"] = "頁面"
L["Panel"] = "底板"
L["Panel:"] = "底板："
L["Panels"] = "底板"
L["Panels:"] = "底板："
L["Parchment, as the dialogue has always looked (the defaults)."] = "羊皮紙，對話一直以來的外觀（預設值）。"
L["Part"] = "部件"
L["Party frames (raid-style)"] = "隊伍框架（團隊樣式）"
L["Party title"] = "隊伍標題"
L["Pass"] = "放棄"
L["Passed: %s"] = "放棄：%s"
L["Passive"] = "被動"
L["Past 28 yards"] = "28 碼以外"
L["Past 40 yards"] = "40 碼以外"
L["Paste in a script someone shared (Ctrl+V), then Add script. It's added as a new script of yours."] = "貼上別人分享的腳本（Ctrl+V），然後點「加入腳本」。它會加入為你的新腳本。"
L["Paste in a wheel someone shared (Ctrl+V), read what's on it below, and Add wheel. It's added as a new wheel of yours."] = "貼上別人分享的輪盤（Ctrl+V），在下方看看上面有什麼，然後點「加入輪盤」。它會加入為你的新輪盤。"
L["Paste the text a friend sent (Ctrl+V). What it holds shows below before you add it."] = "貼上朋友傳來的文字（Ctrl+V）。加入前，其內容會顯示在下方。"
L["Pattern:"] = "圖樣："
L["Peak"] = "峰值"
L["People joining and leaving your group."] = "加入與離開你隊伍的人。"
L["Personal Resource Display"] = "個人資源顯示"
L["Personal mana bar"] = "個人法力條"
L["Personal resource display"] = "個人資源顯示"
L["Pick Greed's color."] = "選擇貪婪的顏色。"
L["Pick Need's color."] = "選擇需求的顏色。"
L["Pick Transmog's color."] = "選擇塑形的顏色。"
L["Pick a frame in game"] = "在遊戲中選取框架"
L["Pick a level to try it now. You can change it any time, here or on the Profiles page."] = "選擇一個等級立即試用。你隨時可以在此處或設定檔頁面變更。"
L["Pick a profile to switch to it."] = "選擇一個設定檔即可切換過去。"
L["Pick a setting"] = "選擇設定"
L["Pick an emote to add as a button on this card: a common one, any of the game's, or a voice emote (said out loud). Up to six."] = "選擇一個表情動作，作為按鈕加到此卡片上：常用的、遊戲中任何一個，或語音表情動作（會說出聲音）。最多六個。"
L["Pick its style, then how its words and frame look and where it sits. The font, outline, shadow and border start on Visions Style's. Press Test and close the settings to see it."] = "選擇它的樣式，然後設定文字與框架的外觀及位置。字型、外框、陰影與邊框起初依照 Visions 樣式。按「測試」並關閉設定即可看到。"
L["Pick its type, then that type's settings below. Press Test and close the settings to see it. Its colors and words: the Look tab."] = "選擇它的類型，然後在下方設定該類型。按「測試」並關閉設定即可看到。它的顏色與文字：外觀分頁。"
L["Pick sounds for this rule from the game's."] = "從遊戲的音效中為此規則選擇音效。"
L["Pick the bar's color."] = "選擇計量條的顏色。"
L["Pick the bars' color."] = "選擇計量條的顏色。"
L["Pick the color of a cast or channel that can't be interrupted."] = "選擇無法被打斷之施法或引導的顏色。"
L["Pick the color of a cast that was interrupted (when the game says: not in every fight)."] = "選擇被打斷之施法的顏色（遊戲有告知時：並非每場戰鬥都有）。"
L["Pick the color of a cast."] = "選擇施法的顏色。"
L["Pick the color of a channel."] = "選擇引導的顏色。"
L["Pick the glow's color."] = "選擇光暈的顏色。"
L["Pick the line's color."] = "選擇線條的顏色。"
L["Pick the outline's color."] = "選擇外框的顏色。"
L["Pick the pulse's color."] = "選擇脈動的顏色。"
L["Pick the small lines' color."] = "選擇細線的顏色。"
L["Pick the text's color."] = "選擇文字的顏色。"
L["Pick the winner's color."] = "選擇贏家的顏色。"
L["Pick when each spell's icon shows. Always: as the game shows it. When ready: out of fights, and while it recharges, it fades out; it comes back once it's ready, or the seconds in its box before (empty: %d%% of its cooldown). While recharging: in fights or not, it shows only while it recharges. When it procs: in fights or not, it shows only while the game makes it glow (a proc, like an instant Lightning Bolt). A faded icon keeps its place in the bar. In fights the game may not say how long is left, so then it goes by when you last cast it. The settings beside each group's name set every spell in it at once."] = "選擇每個法術圖示何時顯示。一律：依遊戲的顯示方式。就緒時：非戰鬥中及充能期間淡出；就緒時（或就緒前其方框中設定的秒數，留空：其冷卻時間的 %d%%）重新出現。充能中：無論是否在戰鬥中，只在充能期間顯示。觸發時：無論是否在戰鬥中，只在遊戲讓它發光時顯示（觸發效果，例如瞬發的閃電箭）。淡出的圖示會保留其在列中的位置。戰鬥中遊戲可能不告知剩餘時間，此時依你上次施放的時間判斷。每個群組名稱旁的設定可一次設定其中所有法術。"
L["Picked now"] = "目前選擇"
L["Picking up an item or spell (to drag it to your action bars, say) brings the UI back until you put it down. Off: picking things up never does; mouse over a faded bar to see it when dragging there."] = "拿起物品或法術（例如要拖曳到快捷列上）會讓介面恢復顯示，直到你放下為止。關閉：拿起東西永遠不會；拖曳時將滑鼠移到淡出的快捷列上即可看到它。"
L["Picks"] = "選擇"
L["Place"] = "地點"
L["Place:"] = "地點："
L["Plain discs on arrows: you in your color, them in their class's."] = "箭頭上的簡單圓盤：你使用你的顏色，對方使用其職業顏色。"
L["Plate"] = "名條"
L["Plate color"] = "名條顏色"
L["Plate off screen"] = "名條在畫面外"
L["Plate parts"] = "名條部件"
L["Plate size %d%%"] = "名條大小 %d%%"
L["Plate size %d%% x %d%%"] = "名條大小 %d%% x %d%%"
L["Plate style"] = "名條樣式"
L["Play %s"] = "播放%s"
L["Play as usual. Stop on the Profiler page ends it."] = "照常遊戲。在效能分析器頁面按「停止」即可結束。"
L["Play it, at its volume."] = "以其音量播放。"
L["Play it, to see it (at no one)."] = "播放它看看（不對任何人）。"
L["Play this shot now (stand still). Press it again, or move, to stop."] = "現在播放此鏡頭片段（請站著不動）。再按一次或移動即可停止。"
L["Played by"] = "播放者"
L["Played by: %s"] = "播放者：%s"
L["Player frame waits for your health or power to change"] = "玩家框架等待你的生命值或能量變化"
L["Players in their class color, everyone else red, yellow or green by how they see you."] = "玩家使用其職業顏色，其他所有對象依其對你的態度顯示紅、黃或綠色。"
L["Players shown per item in a raid"] = "團隊中每件物品顯示的玩家數"
L["Players' names in their class color, NPCs' in their reaction to you (red, yellow or green)."] = "玩家名稱使用其職業顏色，NPC 名稱依其對你的反應（紅、黃或綠色）。"
L["Players' names show in their class color, as in the chat window. NPCs' don't have one."] = "玩家名稱以其職業顏色顯示，與聊天視窗相同。NPC 沒有職業顏色。"
L["Players, friendly or enemy as the Nameplates page has them (the other faction's are enemies)."] = "玩家，依名條頁面的設定分為友方或敵方（另一陣營的為敵方）。"
L["Plays a card in this style in the preview and on your screen (close the settings to see it there): the first card using it, else the zone you're in."] = "在預覽及你的畫面上播放此樣式的卡片（關閉設定即可在畫面上看到）：使用它的第一張卡片，否則為你所在的區域。"
L["Plays the card in the preview and on your screen, as it will look, with its sound (close the settings to see it there). A card with moments (Duel) plays each in turn; clicking Stop ends it."] = "在預覽及你的畫面上播放此卡片，呈現實際外觀並播放其音效（關閉設定即可在畫面上看到）。有多個時刻的卡片（決鬥）會依序播放每個時刻；點擊「停止」即可結束。"
L["Plays the scenes of yours whose trigger is this key: set a scene's trigger to it on the Scenes page. Press again to stop it."] = "播放你的場景中以此按鍵為觸發條件的場景：在場景頁面將場景的觸發條件設為它。再按一次即可停止。"
L["Points left"] = "剩餘點數"
L["Pop out"] = "彈出"
L["Pop out: drag the window anywhere (by its edge). Dock: back beside the settings."] = "彈出：將視窗拖曳到任何位置（拖曳其邊緣）。停靠：回到設定旁。"
L["Portal ring"] = "傳送門光環"
L["Portrait"] = "頭像"
L["Portrait:"] = "頭像："
L["Position"] = "位置"
L["Position:"] = "位置："
L["Power"] = "能量"
L["Power bar"] = "能量條"
L["Preset"] = "預設"
L["Preset:"] = "預設："
L["Press Ctrl+C to copy this, then paste it wherever your friend will see it."] = "按 Ctrl+C 複製，然後貼到你朋友看得到的地方。"
L["Press Ctrl+C to copy this, then paste it wherever your friends will see it. They add it with Import a wheel on their Your wheels page."] = "按 Ctrl+C 複製，然後貼到你朋友看得到的地方。他們可在自己的「你的輪盤」頁面用「匯入輪盤」加入。"
L["Press Ctrl+C to copy this, then paste it wherever your friends will see it. They add it with Import on their Scripts page."] = "按 Ctrl+C 複製，然後貼到你朋友看得到的地方。他們可在自己的腳本頁面用「匯入」加入。"
L["Pressing Enter to type brings up the chat window with the input box where it's ticked. Elsewhere just the input box comes up, so you can type without the chat window (or Mouseover groups set to come up for Typing) showing."] = "在勾選之處按 Enter 輸入文字時，會叫出帶有輸入框的聊天視窗。在其他地方則只會出現輸入框，讓你輸入時不必顯示聊天視窗（或設為因輸入而顯示的滑鼠指向群組）。"
L["Preview"] = "預覽"
L["Previewing - %s"] = "預覽中 - %s"
L["Previously"] = "前情提要"
L["Previously, on %s"] = "前情提要，%s"
L["Print to chat"] = "輸出到聊天"
L["Profession"] = "專業技能"
L["Profiler"] = "效能分析器"
L["Profiler: press Ctrl+C to copy"] = "效能分析器：按 Ctrl+C 複製"
L["Progress in a scenario (the stages and objectives the tracker shows for some raid bosses, dungeons and events) shows the quest tracker the same way."] = "事件中的進度（追蹤器為某些團隊首領、地城與活動顯示的階段與目標）也會以同樣方式顯示任務追蹤。"
L["Put %s back as it comes?"] = "要將 %s 還原為原始狀態嗎？"
L["Put back"] = "還原"
L["Put every spell's, buff's and group's icon setting, and Smart set, back to the active profile's own."] = "將每個法術、增益與群組的圖示設定，以及「智慧設定」，還原為目前設定檔本身的值。"
L["Put everything back over %s s"] = "在 %s 秒內全部還原"
L["Put the %d points the plan adds into your talents window, for its Apply Changes."] = "將計畫新增的 %d 點放入你的天賦視窗，供其「套用變更」使用。"
L["Put the active profile back to how you last saved it, or a built-in one back to its own values (your own profiles keep your changes as you go)."] = "將目前設定檔還原為你上次儲存的狀態，或將內建設定檔還原為其本身的值（你自己的設定檔會隨時保留你的變更）。"
L["Put the mouse on it"] = "將滑鼠移到上面"
L["Put the profile %s back to how you last saved it? Changes you've made since then go."] = "要將設定檔 %s 還原為你上次儲存的狀態嗎？之後所做的變更都會消失。"
L["Put the turn and tilt back over %s s"] = "在 %s 秒內還原轉向與傾斜"
L["Put these settings back to the profile's own?"] = "要將這些設定還原為設定檔本身的值嗎？"
L["Puts one of the event's own settings back, to come from the style it starts from again."] = "還原事件自己的某項設定，讓它重新依照其起始樣式。"
L["Puts one of your changes to the style back, as it comes."] = "將你對樣式所做的某項變更還原為原始狀態。"
L["Puts our script back, made from its camera's settings again, in place of your changes (click twice)."] = "還原我們的腳本，重新依其鏡頭的設定產生，取代你的變更（點擊兩次）。"
L["Puts the card back where it starts: just above where speech from behind you shows (the Chat Bubbles page's Move), beside the chat window."] = "將卡片放回起始位置：在來自你身後之話語顯示處的正上方（對話泡泡頁面的「移動」），聊天視窗旁。"
L["Puts the rule's words back in the dropdowns."] = "將規則的字詞放回下拉選單中。"
L["Puts this theme back as it comes, undoing your changes to its own settings (edge, colors, sparks, heartbeat)."] = "將此主題還原為原始狀態，取消你對其自身設定（邊緣、顏色、火花、心跳）所做的變更。"
L["PvP flagged"] = "已開啟 PvP"
