L["Quest mark (!)"] = "任務標記（!）"
L["Quest mark icon"] = "任務標記圖示"
L["Quest mobs' nameplates and marks, the quest item button, the glow on quest objects, and where the dialogue sits."] = "任務怪的名條與標記、任務物品按鈕、任務物體的光暈，以及對話的位置。"
L["Quest objective"] = "任務目標"
L["Quest talk"] = "任務對話"
L["Quest talk is on: talking to an NPC, what they say and what you can say back show here instead of the game's window"] = "任務對話已開啟：與 NPC 對話時，他們說的話及你可回覆的內容會顯示在這裡，而不是遊戲的視窗"
L["Quest/widget icons"] = "任務/小工具圖示"
L["Questie's quest tracker and its quest item buttons fade with the Quest tracker row on the Game Frames page."] = "Questie 的任務追蹤及其任務物品按鈕，會隨遊戲框架頁面的任務追蹤列一起淡出。"
L["Quests done"] = "完成的任務"
