L["Rage, runic power and the like count until drained"] = "怒氣、符文能量等在耗盡前都計算在內"
L["Rage, runic power and the other resources that drain away out of combat count too: the frames ticked above stay up until they're back to 0, within the Calm Timer."] = "怒氣、符文能量及其他在非戰鬥中會逐漸耗盡的資源也計算在內：上方勾選的框架會保持顯示，直到它們回到 0，以平靜計時為限。"
L["Raid marker"] = "團隊標記"
L["Raid-style"] = "團隊樣式"
L["Raid-style party buffs"] = "團隊樣式隊伍增益"
L["Raid-style party debuffs"] = "團隊樣式隊伍減益"
L["Raid-style party pet names"] = "團隊樣式隊伍寵物名稱"
L["Raid-style party pets"] = "團隊樣式隊伍寵物"
L["Raid-style party player names"] = "團隊樣式隊伍玩家名稱"
L["Raid-style party players"] = "團隊樣式隊伍玩家"
L["Raid-style party role icons"] = "團隊樣式隊伍職責圖示"
L["Raid-style party threat highlight"] = "團隊樣式隊伍仇恨高亮"
L["Raid-style party title"] = "團隊樣式隊伍標題"
L["Raises the game's max camera distance (to 2.6) while pulled back, so the zoom isn't cut short. Your own maximum comes back once you've zoomed in again."] = "拉遠時提高遊戲的最大鏡頭距離（至 2.6），讓縮放不會被截斷。再次拉近後會還原你自己的最大值。"
L["Random fly-bys are spread over the part of the flight below: one per this many seconds of it (at least one), each at a random moment in its share."] = "隨機掠過鏡頭分佈在下方設定的飛行區段中：每隔這麼多秒一次（至少一次），各自在其區段內的隨機時刻出現。"
L["Random zoom only. Each pause is picked at random this much shorter or longer than the pause above: 3 sec with a 10 sec pause waits anywhere from 7 to 13 sec. 0 keeps every pause the same."] = "僅限隨機縮放。每次停頓會隨機比上方的停頓時間縮短或延長最多這麼多：停頓 10 秒、變化 3 秒，則等待 7 到 13 秒之間的任意時間。0 表示每次停頓都相同。"
L["Rank %d/%d"] = "等級 %d/%d"
