L["Reach"] = "範圍"
L["Reach, sides"] = "範圍（左右）"
L["Reach, top and bottom"] = "範圍（上下）"
L["Read every command before you add it: each runs as if you'd typed it, and /run ones can do anything an addon can."] = "加入前請先閱讀每個指令：每個指令都會如同你親自輸入般執行，而 /run 指令可以做到插件能做的任何事。"
L["Ready"] = "就緒"
L["Ready also needs the resources to cast it: Maelstrom, mana, rage and so on. Until you have them the icon stays faded."] = "「就緒」也需要施放它所需的資源：漩渦、法力、怒氣等。在你擁有足夠資源前，圖示會保持淡出。"
L["Ready check"] = "準備確認"
L["Ready: it's up (you're near the quest's area) and not cooling down."] = "就緒：它已出現（你在任務區域附近）且沒有在冷卻中。"
L["Recap after:"] = "回顧時機："
L["Recaps"] = "回顧"
L["Recently deleted"] = "最近刪除"
L["Record"] = "記錄"
L["Recording (the addon's own timers)"] = "記錄（插件自己的計時器）"
L["Recording CPU  %d:%02d"] = "記錄 CPU  %d:%02d"
L["Recording: %d:%02d left."] = "記錄中：剩餘 %d:%02d。"
L["Red for hostile units, yellow for neutral ones and green for friendly ones, as over their heads. Unticked: the plate's own color, white or gray."] = "敵對單位為紅色，中立單位為黃色，友方單位為綠色，與其頭頂相同。未勾選：名條本身的顏色，白色或灰色。"
L["Reduce view distance in rain"] = "下雨時縮短視野距離"
L["Regenerate"] = "重新產生"
L["Released to a graveyard with no spirit healer's countdown, the dark edges stay as you walk back, and lift the closer you get to your body, gone once you're there."] = "釋放靈魂到沒有靈魂醫者倒數的墓地時，深色邊緣會在你走回去時保持，越接近屍體越淡，到達時消失。"
L["Reload button on the screen"] = "畫面上的重新載入按鈕"
L["Reload the UI"] = "重新載入介面"
L["Reloads the UI, like /reload. With Keep windows open across a reload ticked (Quality of life > General), what you had open opens again after."] = "重新載入介面，與 /reload 相同。勾選「重新載入後保持視窗開啟」（便利功能 > 一般）時，你先前開啟的東西之後會再次開啟。"
L["Remove this copy."] = "移除此複本。"
L["Remove this row. Add it again under the grid."] = "移除此列。可在表格下方再次加入。"
L["Remove this rule and its sounds."] = "移除此規則及其音效。"
L["Remove this step"] = "移除此步驟"
L["Remove this trigger."] = "移除此觸發條件。"
L["Rename the camera:"] = "重新命名鏡頭："
L["Rename the theme:"] = "重新命名主題："
L["Renown %d"] = "名望 %d"
L["Repeat %s times"] = "重複 %s 次"
L["Repeat until it ends"] = "重複直到結束"
L["Repeats:"] = "重複："
L["Replies to a /who, shift-clicking a name in the guild list too."] = "/who 的回覆，也包括在公會名單中 Shift+點擊名字。"
L["Requires %d points in %s"] = "需要投入 %d 點於%s"
L["Requires %d points in %s Talents"] = "需要投入 %d 點於%s天賦"
L["Reset addon"] = "重置插件"
