L["Resources"] = "資源"
L["Rested"] = "休息"
L["RestedXP's guide window, waypoint arrow, quest item and target buttons and level splits fade with the Quest tracker row on the Game Frames page."] = "RestedXP 的指南視窗、路徑點箭頭、任務物品與目標按鈕，以及等級分段，會隨遊戲框架頁面的任務追蹤列一起淡出。"
L["Resting (an inn or a city)"] = "休息中（旅店或主城）"
L["Resting at a campfire, sitting, sleeping, dancing and the like (whichever events pick it on the Scenes page): the camera swings slowly round to face you, then sways gently from side to side in front of you, and eases in close. Moving (or standing up) ends it."] = "在營火旁休息、坐下、睡覺、跳舞之類（場景頁面中選擇此鏡頭的任何事件）：鏡頭會緩緩轉過來面對你，然後在你前方輕輕左右擺動，並緩緩拉近。移動（或站起）會結束它。"
L["Restore"] = "還原"
L["Restored from a backup of %s from %s."] = "已從 %s 於 %s 的備份還原。"
L["Restyle these bars"] = "重新設計這些計量條"
L["Result"] = "結果"
L["Reveal on scenario progress"] = "事件有進展時顯示"
L["Right click attack also uses Auto-shot"] = "右鍵攻擊也使用自動射擊"
L["Right now: hidden"] = "目前：隱藏"
L["Right now: shown"] = "目前：顯示"
L["Right-click for more."] = "按右鍵查看更多。"
L["Right-click the Profiler icon to turn it on and record."] = "在效能分析器圖示上按右鍵即可開啟並記錄。"
L["Right-click: back to its own icon."] = "右鍵：回到它自己的圖示。"
L["Right-click: copy it, or rename, describe, change the icon of or delete one of yours."] = "右鍵：複製它；若是你的，也可重新命名、描述、變更圖示或刪除。"
L["Right-clicking an enemy targets it and attacks: Auto Shot when it's far enough away to shoot, a melee swing when it's too close, in a fight or out of one. In a fight the game only checks what's under the mouse a few times a second, so a very quick right-click on a new enemy can still be a melee one."] = "右鍵點擊敵人會選取並攻擊它：距離夠遠可射擊時使用自動射擊，太近時則近戰攻擊，戰鬥中或戰鬥外皆然。戰鬥中遊戲每秒只會檢查幾次滑鼠下的對象，所以對新敵人極快速的右鍵點擊仍可能是近戰攻擊。"
L["Ripple wave"] = "漣漪波"
L["Rise up from below the screen"] = "從畫面下方升起"
L["Rising heat"] = "升騰熱氣"
L["Rising motes"] = "上升的光點"
L["Role"] = "職責"
L["Role icon (damage)"] = "職責圖示（傷害）"
L["Role icon (healer)"] = "職責圖示（治療者）"
L["Role icon (tank)"] = "職責圖示（坦克）"
L["Roll Vision"] = "Roll Vision"
L["Rolling..."] = "擲骰中……"
L["Roomy"] = "寬敞"
L["Rotate %s° %s over %s s"] = "旋轉 %s° %s，耗時 %s 秒"
L["Round"] = "圓形"
L["Round each bar: the game's frame alone, or a border of ours (Custom: its thickness and color under it)."] = "每條計量條周圍：只有遊戲的框架，或我們的邊框（自訂：其下方設定粗細與顏色）。"
L["Round each frame: the game's, or a border of ours (Custom: its thickness and color under it)."] = "每個框架周圍：遊戲的，或我們的邊框（自訂：其下方設定粗細與顏色）。"
L["Round the button: the game's (the extra ability button's frame), or one of ours (Custom: its thickness and color under it)."] = "按鈕周圍：遊戲的（額外技能按鈕的框架），或我們的（自訂：其下方設定粗細與顏色）。"
L["Row"] = "列"
L["Rows:"] = "列："
L["Rule"] = "規則"
L["Rule: %s"] = "規則：%s"
L["Rule: %s (the rule decides, not the ticks)"] = "規則：%s（由規則決定，而非勾選）"
L["Rules for the card's sound, read top to bottom as it shows: the first that fits plays one of its sounds at random. A rule's condition uses the rules' words (Cities, Raids, In CineMode...); none: any time. A rule with no sounds: silent. Each sound's slider sets it next to the others, the cue volume sets them all (every card's sounds share it)."] = "卡片音效的規則，在卡片顯示時由上到下判斷：第一個符合的規則會隨機播放其中一個音效。規則的條件使用規則字詞（Cities、Raids、In CineMode……）；沒有條件：任何時候。沒有音效的規則：靜音。每個音效的滑桿設定它相對於其他音效的音量，提示音量則設定全部（所有卡片的音效共用）。"
L["Rules for the sounds, read top to bottom as a fight starts or ends: the first that fits plays one of its sounds at random. A rule's condition uses the rules' words (Boss fight, Raids, In CineMode...); none: any fight. Each sound's slider sets it next to the others, the cue volume sets them all. They play on the Ambience channel, its volume set for them and put back after."] = "音效的規則，在戰鬥開始或結束時由上到下判斷：第一個符合的規則會隨機播放其中一個音效。規則的條件使用規則字詞（Boss fight、Raids、In CineMode……）；沒有條件：任何戰鬥。每個音效的滑桿設定它相對於其他音效的音量，提示音量則設定全部。它們在環境音頻道播放，該頻道的音量會為它們調整，之後再還原。"
L["Rules for the sounds, read top to bottom as the time of day changes: the first for the new time that fits plays one of its sounds at random. A rule's condition uses the rules' words (Cities, In CineMode...); none: any time. A rule with no sounds: silent. Each sound's slider sets it next to the others, the cue volume sets them all (the fights' sounds share it)."] = "音效的規則，在時段變化時由上到下判斷：新時段第一個符合的規則會隨機播放其中一個音效。規則的條件使用規則字詞（Cities、In CineMode……）；沒有條件：任何時候。沒有音效的規則：靜音。每個音效的滑桿設定它相對於其他音效的音量，提示音量則設定全部（與戰鬥的音效共用）。"
L["Run"] = "執行"
L["Runs its command now, as picking it on the wheel would."] = "立即執行其指令，如同在輪盤上選擇它一樣。"
L["Runs this camera for 30 seconds where you stand, to see your settings at work. Moving, or clicking Stop, ends it."] = "在你站的地方執行此鏡頭 30 秒，看看你的設定效果。移動或點擊「停止」即可結束。"
L["Runs when the camera ends, whatever ends it (its stop rules say which do). Every camera has it: it can't be removed. Pick it and add steps to put them inside."] = "在鏡頭結束時執行，無論是什麼讓它結束（其停止規則說明哪些會）。每個鏡頭都有它：無法移除。選擇它並加入步驟，即可將步驟放入其中。"
L["SD (the game's look)"] = "SD（遊戲的外觀）"
L["SHOWING"] = "顯示中"
L["SHOWN BECAUSE"] = "顯示的原因"
L["Same as raid frames"] = "與團隊框架相同"
L["Same as target"] = "與目標相同"
L["Same as the words"] = "與文字相同"
L["Same back"] = "同樣回應"
L["Same size at any distance"] = "在任何距離都是同一大小"
L["Save"] = "儲存"
L["Says and yells whose bubble isn't on your screen (the speaker is behind you, or out of view) show in a bubble low on the screen, with the speaker's name, instead of bringing up chat. It needs the Chat page's Show chat when a message arrives and Hide speech you can see as a bubble."] = "泡泡不在你畫面上的說話與大喊（說話者在你身後或不在視野中），會以泡泡顯示在畫面下方，附上說話者的名稱，而不是讓聊天出現。需要聊天頁面的「收到訊息時顯示聊天」與「隱藏能在泡泡中看到的話」。"
L["Says and yells whose bubble isn't on your screen, shown low on the screen instead. Turn it on on the Interface hub's Chat bubbles page (with that page on)."] = "泡泡不在你畫面上的說話與大喊，改為顯示在畫面下方。請在「介面」分類的對話泡泡頁面開啟（並開啟該頁面）。"
L["Scale"] = "縮放"
L["Scale:"] = "縮放："
