L["Scripts"] = "腳本"
L["Scroll the mouse wheel over it, or type a number and press Enter."] = "將滑鼠滾輪移到上面滾動，或輸入數字後按 Enter。"
L["Search"] = "搜尋"
L["Seats"] = "座位"
L["Second pattern:"] = "第二圖樣："
L["Seconds left at its right end"] = "右端顯示剩餘秒數"
L["Seconds left in the middle"] = "中央顯示剩餘秒數"
L["Seconds the edges take to close all the way in when your health drops. Keep it short: it's the warning."] = "生命值下降時邊緣完全收攏所需的秒數。請保持短一點：這是警告。"
L["See-through"] = "半透明"
L["See-through and borderless, the health bar thin along the top."] = "半透明且無邊框，生命條細細地沿著頂端。"
L["Sending your log"] = "傳送你的記錄"
L["Separate"] = "分開"
L["Separate: the card stays where you drag it (or at the list's height), wherever the bubble goes."] = "分開：無論泡泡在哪裡，卡片都停在你拖曳到的位置（或清單的高度）。"
L["Server messages"] = "伺服器訊息"
L["Server shutdowns and restarts."] = "伺服器關機與重新啟動。"
L["Set by:"] = "設定來源："
L["Sets every buff in this group to this. Buffs you haven't set on their own follow it."] = "將此群組中的每個增益都設為此值。你沒有單獨設定的增益會依照它。"
L["Sets every spell in this group to this. Spells you haven't set on their own follow it, and a spell here made When ready on its own starts with its Resources and Show early."] = "將此群組中的每個法術都設為此值。你沒有單獨設定的法術會依照它，而此處單獨設為「就緒時」的法術會從其「資源」與「提前顯示」開始。"
L["Settings: %s"] = "設定：%s"
L["Shadow"] = "陰影"
L["Shadow reach, top and bottom"] = "陰影範圍（上下）"
L["Shadow sharpness"] = "陰影銳利度"
L["Shadow tint"] = "陰影色調"
L["Shadow:"] = "陰影："
L["Shadows"] = "陰影"
L["Shape:"] = "形狀："
L["Share"] = "分享"
