L["Share wheel"] = "分享輪盤"
L["Shared by: %s"] = "分享者：%s"
L["Shared look"] = "共用外觀"
L["Shared theme"] = "分享的主題"
L["Shared wheel"] = "分享的輪盤"
L["Shortly before you land, the rotation stops and the camera turns back behind you and stays there until you touch down. Needs one flight on a route to learn how long it takes. Skipped if you've moved the camera yourself on that flight: it stays how you set it."] = "降落前不久，旋轉會停止，鏡頭轉回你身後並停在那裡直到著陸。需要在某條路線上飛過一次，才能得知所需時間。若你在該次飛行中自己移動過鏡頭則略過：保持你設定的狀態。"
L["Shot:"] = "鏡頭片段："
L["Shoulder Cam"] = "肩膀鏡頭"
L["Shoulder Cam turned off: the game's experimental camera warning was disabled."] = "肩膀鏡頭已關閉：遊戲的實驗性鏡頭警告被停用了。"
L["Show all"] = "全部顯示"
L["Show all through CineMode in capital cities."] = "在主城中，CineMode 期間全程顯示。"
L["Show all through CineMode out in the world, inns included (capital cities are Cities)."] = "在野外（包括旅店），CineMode 期間全程顯示（主城屬於「主城」）。"
L["Show below health"] = "生命值低於此值時顯示"
L["Show below this much mana"] = "法力低於此值時顯示"
L["Show during:"] = "顯示於："
L["Show emotes too"] = "也顯示表情動作"
L["Show fewer"] = "顯示較少"
L["Show in"] = "顯示於"
L["Show in capital cities."] = "在主城中顯示。"
L["Show it"] = "顯示它"
L["Show it now"] = "立即顯示"
L["Show it the whole time, CineMode or not. Unticked, it's hidden, except as the other columns say."] = "全程顯示，無論是否處於 CineMode。未勾選時隱藏，除非其他欄另有設定。"
L["Show keybinds"] = "顯示按鍵設定"
L["Show mana cost indicator"] = "顯示法力消耗指示"
L["Show me"] = "給我看"
L["Show members with a debuff you can dispel"] = "顯示身上有你可驅散之減益的成員"
L["Show members with any debuff"] = "顯示身上有任何減益的成員"
L["Show off-screen bubbles"] = "顯示畫面外泡泡"
L["Show off-screen bubbles is on: a say or yell from someone you can't see shows here instead of bringing up the chat window"] = "「顯示畫面外泡泡」已開啟：你看不到的人說話或大喊時會顯示在這裡，而不是讓聊天視窗出現"
L["Show or hide this row's settings."] = "顯示或隱藏此列的設定。"
L["Show out in the world, inns included (capital cities are Cities)."] = "在野外顯示，包括旅店（主城屬於「主城」）。"
L["Show out of fights while you have a living enemy targeted."] = "非戰鬥中選取活著的敵人時顯示。"
L["Show out of fights while you have anything else targeted: friends, NPCs, dead enemies."] = "非戰鬥中選取其他任何對象時顯示：友方、NPC、死亡的敵人。"
L["Show remaining mana text"] = "顯示剩餘法力文字"
L["Show rolls on"] = "擲骰顯示於"
L["Show the counts under each item"] = "在每件物品下方顯示數量"
L["Show the game's window brings the game's own window back for the rest of the conversation"] = "「顯示遊戲視窗」會在對話剩餘的時間內恢復遊戲本身的視窗"
L["Show timers in the quest tracker while one is running"] = "有計時器進行中時在任務追蹤中顯示計時器"
L["Show tooltips"] = "顯示滑鼠提示"
L["Show who said it"] = "顯示說話者"
L["Show your mana when it isn't your power"] = "法力不是你的能量類型時也顯示法力"
L["Show your personal resource display until health and power are full"] = "顯示你的個人資源顯示直到生命值與能量全滿"
L["Show your pet frame until its health is full"] = "顯示你的寵物框架直到其生命值全滿"
L["Show your player frame until health and power are full"] = "顯示你的玩家框架直到生命值與能量全滿"
L["Show:"] = "顯示："
L["Showing in its own window. Click here to put it back."] = "正在獨立視窗中顯示。點擊此處放回。"
L["Shown as:"] = "顯示為："
L["Shown in fights: any of them, or only while you're PvP flagged."] = "在戰鬥中顯示：任何戰鬥，或只在你開啟 PvP 狀態時。"
L["Shown in the wheel's middle, on the master wheel and in the game's key bindings."] = "顯示在輪盤中央、主輪盤上，以及遊戲的按鍵設定中。"
L["Shows a box where speech from behind you appears: drag it where you want the lines."] = "顯示來自你身後之話語出現的方框：將它拖曳到你想要文字出現的位置。"
L["Shows a line of speech from behind you, from you, as it looks now."] = "以你自己為說話者，顯示一行來自你身後的話語，呈現目前的外觀。"
L["Shows all through CineMode. (The other columns then have nothing to add.)"] = "CineMode 期間全程顯示。（其他欄便沒有什麼可補充的了。）"
L["Shows as:"] = "顯示為："
L["Shows each of its cards in turn, to see how they look (close the settings to see them). Clicking Stop ends it."] = "依序顯示它的每張卡片，看看外觀（關閉設定即可看到）。點擊「停止」即可結束。"
L["Shows in every fight, wherever you are. (The other columns then have nothing to add.)"] = "每場戰鬥都顯示，無論你在哪裡。（其他欄便沒有什麼可補充的了。）"
L["Shows its card now, to see how it looks (close the settings to see it)."] = "立即顯示它的卡片，看看外觀（關閉設定即可看到）。"
L["Shows the key each spell is bound to in the corner of its icon in the Essential and Utility bars, as on an action button: the key of the first action bar button holding it (or a macro casting it)."] = "在「核心」與「輔助」列中，每個法術圖示的角落顯示其綁定的按鍵，與快捷鍵按鈕相同：放有該法術（或施放它的巨集）的第一個快捷列按鈕的按鍵。"
L["Shows the lines in their chat colors. Copied text keeps the color codes, so untick this to copy plain text."] = "以聊天顏色顯示各行。複製的文字會保留顏色代碼，所以若要複製純文字，請取消勾選此項。"
L["Shows the preview larger, in a window of its own beside the settings (its Pop out lets you move it anywhere) that you can resize from its corner, so you can watch it while you scroll down the page. Click again to put it back."] = "在設定旁的獨立視窗中顯示較大的預覽（其「彈出」可讓你將它移到任何位置），可從角落調整大小，讓你在往下捲動頁面時也能看著它。再次點擊即可放回。"
L["Shows wherever you are. (Never in a fight: a card from one waits for it to end.)"] = "無論你在哪裡都顯示。（戰鬥中永不顯示：戰鬥中產生的卡片會等到戰鬥結束。）"
L["Shows wherever you are. (The other columns then have nothing to add.)"] = "無論你在哪裡都顯示。（其他欄便沒有什麼可補充的了。）"
L["Sides"] = "兩側"
L["Size %d%%"] = "大小 %d%%"
L["Size:"] = "大小："
L["Sizes"] = "大小"
L["Skip it"] = "略過"
L["Slide in"] = "滑入"
L["Slim"] = "纖細"
L["Slow frames"] = "慢速幀"
L["Slow orbit"] = "緩慢環繞"
L["Slowly swings the camera around behind your character as you take off, ready for the sway behind you. Also once the pause after you move the camera mid-flight is up."] = "起飛時緩緩將鏡頭轉到你角色身後，為在你身後擺動做好準備。在飛行途中移動鏡頭後的暫停結束時也會如此。"
L["Small lines' color:"] = "細行文字顏色："
L["Small lines' font:"] = "細行文字字型："
L["Small lines' size"] = "細行文字大小"
L["Smaller hits count as a big one too once they've taken this much of your health together (since the last one; again each fight)."] = "較小的傷害累計造成你這麼多生命值時，也算作一次重擊（從上一次起算；每場戰鬥重新計算）。"
L["Smaller, no frame, a quiet edge glow and a dark cooldown fill, no key."] = "較小，無框架，安靜的邊緣光暈與深色冷卻填色，不顯示按鍵。"
L["Smallest ammo stack first after Clean Up Bags"] = "整理背包後最小的彈藥堆疊排在最前"
L["Smart Find"] = "智慧尋找"
L["Smart Find every 20 seconds while an addon is new to it (its first 15 minutes of play, for each addon you install that isn't supported), not in fights, so frames that come and go (another addon's popups) are caught while they're up. After that, look with the button below."] = "在插件剛安裝時（每個你安裝但不受支援的插件，其最初 15 分鐘遊戲時間內），每 20 秒執行一次智慧尋找，戰鬥中除外，這樣時隱時現的框架（其他插件的彈出視窗）就能在顯示時被捕捉到。之後請用下方的按鈕尋找。"
L["Smart Find for %d seconds"] = "智慧尋找 %d 秒"
L["Smart set"] = "智慧設定"
L["Smooth"] = "平滑"
L["Socials"] = "社交"
L["Soft"] = "柔和"
L["Soft (feathered)"] = "柔和（羽化）"
L["Soft bars and Friz Quadrata, thinly outlined."] = "柔和計量條與 Friz Quadrata 字型，帶細外框。"
L["Soft bars with a fine edge, class icons for players."] = "帶細邊的柔和計量條，玩家顯示職業圖示。"
L["Soft bars with a fine edge, names outlined."] = "帶細邊的柔和計量條，名稱帶外框。"
L["Soft wisps of heat rising from the bottom of the screen, flickering, higher the weaker you are. Fire themes have it."] = "從畫面底部升起的柔和熱氣，閃爍不定，你越虛弱升得越高。火焰主題具有此效果。"
L["Soft, thin bars with a fine edge, health in your class color."] = "柔和纖細的計量條，帶細邊，生命值使用你的職業顏色。"
L["Some nameplate and name changes only take effect once the fight ends."] = "部分名條與名稱的變更要等戰鬥結束後才會生效。"
L["Something has been taking the turnips at night, and nobody here is brave enough to keep watch. Would you?"] = "晚上一直有東西在偷蕪菁，這裡沒人有膽量守夜。你願意嗎？"
L["Sort by"] = "排序依據"
L["Sort:"] = "排序："
L["Souls banner"] = "靈魂風格橫幅"
L["Sound rule %d"] = "音效規則 %d"
L["Sounds"] = "音效"
L["Sounds for boss fights, read before the fights' (Entering and Leaving combat's): as a boss is pulled, killed or your group wipes, the first rule that fits plays one of its sounds at random. A rule here has Boss fight in its condition (taken out, it moves to the fights'). Each sound's slider sets it next to the others, the cue volume sets them all."] = "首領戰的音效，會在戰鬥音效（進入與離開戰鬥的）之前判斷：拉到首領、擊殺首領或隊伍滅團時，第一個符合的規則會隨機播放其中一個音效。此處的規則條件中含有 Boss fight（移除後會移到戰鬥音效中）。每個音效的滑桿設定它相對於其他音效的音量，提示音量則設定全部。"
L["Spark"] = "火花"
L["Sparks"] = "火花"
L["Speech from behind you"] = "來自你身後的話語"
L["Speech from behind you shows here."] = "來自你身後的話語會顯示在這裡。"
L["Speech from behind you shows here.\nDrag it where you want it, left-click to set, right-click to reset."] = "來自你身後的話語會顯示在這裡。\n將它拖曳到你想要的位置，左鍵點擊確定，右鍵點擊重置。"
L["Speech from behind you starts with the speaker's name (\"Name says: ...\"). Unticked, just their words show."] = "來自你身後的話語以說話者的名稱開頭（「名稱 說：……」）。未勾選時只顯示話語內容。"
