L["Square"] = "方形"
L["Start now"] = "立即開始"
L["Start right away, with the settings open, instead of when you close them: to measure the settings pages themselves. Click through the ones to check while it runs."] = "立即開始並保持設定開啟，而不是在你關閉設定時才開始：用來測量設定頁面本身。在它運作時點選要檢查的頁面。"
L["Start the RP walk camera"] = "啟動 RP 漫步鏡頭"
L["Start the auto-run camera"] = "啟動自動奔跑鏡頭"
L["Started as: %s"] = "開始時為：%s"
L["Starts"] = "開始"
L["Starts from:"] = "起始："
L["Starts on any of these: %s."] = "以下任一項時啟動：%s。"
L["Starts the RP walk camera now, walking or not. Press again to stop it; its stop rules (its Scripts page) say what else does."] = "立即啟動 RP 漫步鏡頭，無論是否在行走。再按一次即可停止；其停止規則（其腳本頁面）說明還有什麼會停止它。"
L["Starts the auto-run camera now, running or not. Press again to stop it; its stop rules (its Scripts page) say what else does."] = "立即啟動自動奔跑鏡頭，無論是否在奔跑。再按一次即可停止；其停止規則（其腳本頁面）說明還有什麼會停止它。"
L["Starts when you close the settings: %d seconds, detailed."] = "在你關閉設定時開始：%d 秒，詳細。"
L["Starts when you close the settings: %d seconds."] = "在你關閉設定時開始：%d 秒。"
L["Starts when: %s"] = "啟動時機：%s"
L["Starts when: no trigger yet. Set a row on the Scenes page to it."] = "啟動時機：尚無觸發條件。在場景頁面將某列設為它。"
L["Starts:"] = "開始："
L["State"] = "狀態"
L["Stays"] = "停留"
L["Stays after a fight:"] = "戰鬥後停留："
L["Stays for:"] = "停留時間："
L["Stays the row's rule (it can't go in the dropdowns: %s)."] = "保留為該列的規則（無法放入下拉選單：%s）。"
L["Stealthed"] = "潛行中"
L["Stop (%d)"] = "停止（%d）"
L["Stop and /stare out at the view (or any event set to it on the Scenes page): the camera glides around behind you and sways very gently there, looking out the way you're facing. Like the RP walk camera, only slower and softer. Moving, jumping or another emote ends it."] = "停下來 /stare 眺望風景（或在場景頁面中設為此鏡頭的任何事件）：鏡頭會平滑轉到你身後，並在那裡非常輕柔地擺動，朝你面對的方向望去。類似 RP 漫步鏡頭，只是更慢、更柔和。移動、跳躍或做其他表情動作會結束它。"
L["Stop button"] = "停止按鈕"
L["Stop camera"] = "停止鏡頭"
L["Stop music leaving a camera mode"] = "離開鏡頭模式時停止音樂"
L["Stop rules"] = "停止規則"
L["Stop the camera"] = "停止鏡頭"
L["Stopped. Run plays it again."] = "已停止。「執行」可再次播放。"
L["Stops following: its own ticks or rule, as they were, decide again."] = "停止跟隨：改回由它原本的勾選或規則決定。"
L["Stops within"] = "停止距離"
L["Stormwind"] = "暴風城"
L["Strength out of combat"] = "非戰鬥中強度"
L["Stuck, or something looks wrong? Read up in the guide, or report it to us. Click a link and press Ctrl+C to copy it, then paste it into your browser (addons can't open one)."] = "卡住了，或看起來不太對？請閱讀指南，或回報給我們。點擊連結並按 Ctrl+C 複製，然後貼到你的瀏覽器中（插件無法開啟網頁）。"
L["Style"] = "樣式"
L["Style:"] = "樣式："
L["Subtitle"] = "字幕"
L["Subtitles"] = "字幕"
L["Subtle"] = "細微"
L["Sure?"] = "確定嗎？"
L["Sway either side"] = "兩側擺動"
L["Sway within %s° of behind you over %s s"] = "在你身後 %s° 範圍內擺動，耗時 %s 秒"
L["Sway within %s° of your front over %s s"] = "在你前方 %s° 範圍內擺動，耗時 %s 秒"
L["Swift Gray Gryphon"] = "迅捷灰色獅鷲獸"
L["Swimming"] = "游泳中"
L["Swing speed"] = "轉向速度"
L["Swing to who's talking, %s° off the middle, over %s s"] = "轉向說話者，偏離中央 %s°，耗時 %s 秒"
L["Swirl"] = "漩渦"
L["Swirling clouds"] = "旋轉的雲霧"
L["Switch to it"] = "切換到它"
L["TO FADE IT"] = "淡出它的方法"
L["Tabs"] = "分頁"
L["Tail on top"] = "尾巴在上方"
L["Tail position"] = "尾巴位置"
L["Tailoring"] = "裁縫"
L["Take it off this card."] = "將它從此卡片移除。"
L["Take it off this rule."] = "將它從此規則移除。"
L["Takes off the piece before the cursor."] = "刪除游標前的一段。"
L["Takes the bars out and brings them back in, as at a fight's start and end."] = "將黑邊移出再移入，就像戰鬥開始與結束時一樣。"
L["Takes this icon off the wheel."] = "將此圖示從輪盤上移除。"
L["Talent calculator"] = "天賦模擬器"
L["Talent calculator button on the talents window"] = "天賦視窗上的天賦模擬器按鈕"
L["Talents button when inspecting someone"] = "觀察他人時的天賦按鈕"
L["Talk about a quest"] = "談論任務"
L["Talking to a quest giver, the camera zooms in and swings around behind you, looking past you at them. It goes back once you close the window or move off (your zoom stays if you zoomed yourself meanwhile). Works whether or not CineMode is on. The \"Talk to a quest giver\" and \"Talk about a quest\" events on the Scenes page can also turn it off or make it wait a moment."] = "與任務 NPC 對話時，鏡頭會拉近並轉到你身後，越過你看向對方。關閉視窗或走開後會轉回（若你在此期間自己縮放過，則保持你的縮放）。無論 CineMode 是否開啟都有效。場景頁面中的「與任務 NPC 對話」與「談論任務」事件也可以關閉它或讓它稍等片刻。"
L["Talking to an NPC with a \"(Quest)\" line to pick but no quest to pick up or hand in: a quest step done by talking to them. Works whether or not CineMode is on."] = "與有「（任務）」選項可選、但沒有任務可接或交付的 NPC 對話：透過與其對話完成的任務步驟。無論 CineMode 是否開啟都有效。"
L["Tank"] = "坦克"
L["Tanks"] = "坦克"
L["Tar enemy is ticked, and you target an enemy"] = "已勾選「選取敵方」，且你選取了敵人"
L["Tar enemy is ticked: it shows when you target an enemy"] = "已勾選「選取敵方」：你選取敵人時顯示"
L["Tar friendly is ticked, and you target a friend"] = "已勾選「選取友方」，且你選取了友方"
L["Tar friendly is ticked: it shows when you target a friend"] = "已勾選「選取友方」：你選取友方時顯示"
L["Target Indicator"] = "目標指示"
L["Target circle"] = "目標圓圈"
L["Target min opacity"] = "目標最低不透明度"
L["Target the last speaker"] = "選取上一位說話者"
L["Targets the last NPC who spoke near you (your character turns their head to them). Addons can't target on their own: the game only lets a key press do it. Out of fights."] = "選取在你附近最後說話的 NPC（你的角色會轉頭看向對方）。插件無法自行選取目標：遊戲只允許按鍵這麼做。僅限非戰鬥中。"
L["Tele Vision"] = "Tele Vision"
L["Tele Vision colors: %d specs, %d seconds each (/cine teleport colors again to stop)."] = "Tele Vision 顏色：%d 個專精，每個 %d 秒（再次輸入 /cine teleport colors 即可停止）。"
L["Tele Vision colors: all %d shown."] = "Tele Vision 顏色：%d 個全部已顯示。"
L["Tele Vision colors: stopped."] = "Tele Vision 顏色：已停止。"
L["Terrain detail distance"] = "地形細節距離"
L["Territory"] = "領地"
L["Test"] = "測試"
L["Test item"] = "測試物品"
L["Test recap"] = "測試回顧"
L["Text"] = "文字"
L["Text only"] = "僅文字"
L["Text size"] = "文字大小"
L["Text to send a friend: they add this scene (and the shot it plays) with Import on their Scenes page. Where it may start (its When) stays with you."] = "傳給朋友的文字：他們可在自己的場景頁面用「匯入」加入此場景（及其播放的鏡頭片段）。它可以啟動的地點（其「符合時機」）會留在你這邊。"
L["Text to send a friend: they add this shot with Import here or on their Scenes page."] = "傳給朋友的文字：他們可在這裡或自己的場景頁面用「匯入」加入此鏡頭片段。"
L["Texture:"] = "材質："
L["Thanks"] = "感謝"
L["That isn't a Vitals theme."] = "那不是 Vitals 主題。"
L["That isn't all of it: copy it again, every letter."] = "內容不完整：請再複製一次，每個字元都要。"
L["The AFK camera sweeps right round your character, which can bump into walls in tight rooms. Its zoom still runs (within the limit above)."] = "暫離鏡頭會繞著你的角色整圈環繞，在狹窄的房間中可能撞到牆壁。其縮放仍會運作（在上方的限制內）。"
L["The Card Vision page's Last time line: what you did last session, as you log in"] = "Card Vision 頁面的「上次」一行：登入時顯示你上次遊戲做了什麼"
L["The Card Vision page's time of day at login, under the zone's name"] = "Card Vision 頁面登入時的時段，顯示在區域名稱下方"
L["The Corpse line on a dead player, NPC or mob."] = "死亡玩家、NPC 或怪物身上的「屍體」一行。"
L["The Deadmines"] = "死亡礦坑"
L["The Default row is what frames you add, and addons you install later, start with; its Copy to all gives it to every row here."] = "「預設」列是你加入的框架及之後安裝的插件的起始設定；其「複製到全部」會將它套用到此處每一列。"
L["The Defias Brotherhood"] = "迪菲亞兄弟會"
L["The Tooltips page is off, so Cinematic leaves tooltips alone"] = "滑鼠提示頁面已關閉，所以 Cinematic 不處理滑鼠提示"
L["The Tooltips row was off then for: %s"] = "當時滑鼠提示列因以下原因關閉：%s"
L["The Tooltips row was on then for: %s"] = "當時滑鼠提示列因以下原因開啟：%s"
L["The UI fades and the look stays, with just a few cameras: flights, AFK, and your Hearthstone and teleports. No cozy, vista, fish, RP walk, auto-run, death or quest cameras."] = "介面淡出並保留畫面效果，只有少數鏡頭：飛行、暫離，以及你的爐石與傳送。沒有悠閒、遠景、釣魚、RP 漫步、自動奔跑、死亡或任務鏡頭。"
L["The Unloaded tab has the addons installed but not loaded, to set them up before you turn them on, and the ones supported but not installed."] = "「未載入」分頁列出已安裝但未載入的插件，讓你在開啟前先設定，以及支援但未安裝的插件。"
L["The addons loaded now: their frames, and the ones you added."] = "目前已載入的插件：它們的框架，以及你加入的框架。"
L["The arrow by your buffs that folds them away. Hidden in CineMode even while your buffs show; hovering your buffs brings it up."] = "增益旁可將增益收起的箭頭。在 CineMode 中即使你的增益顯示也會隱藏；滑鼠指向你的增益會讓它出現。"
L["The arrow, chevron and diamond bob up and down, the brackets, carets and corners close in and out, the glow and underline pulse. Unticked, it holds still."] = "箭頭、V 形與菱形會上下浮動，括號、尖角與角落會內外收放，光暈與底線會脈動。未勾選時保持靜止。"
L["The art's color."] = "美術圖的顏色。"
L["The background's color, for Custom."] = "背景的顏色，用於「自訂」。"
L["The bar behind the zone's name above the minimap (the name has a row of its own). Untick it to leave the name floating on its own. Hovering the minimap brings it up with the map: to keep it hidden then too, take Minimap header out of the Minimap group on the Hover groups page."] = "小地圖上方區域名稱後方的長條（名稱有自己的一列）。取消勾選則讓名稱單獨浮著。滑鼠指向小地圖會讓它隨地圖一起出現：若此時也要保持隱藏，請到滑鼠指向群組頁面，將「小地圖標題」從小地圖群組中移除。"
L["The bar in your class's color, whether you lead or chase."] = "無論你領先或追趕，計量條都使用你的職業顏色。"
L["The bar's color once you lead. Picking one turns Colors to Your own."] = "你領先時計量條的顏色。選擇一個顏色會將「顏色」改為「你自己的」。"
L["The bar's color while you're behind. Picking one turns Colors to Your own."] = "你落後時計量條的顏色。選擇一個顏色會將「顏色」改為「你自己的」。"
L["The bar's fill. Below the game's own few: any other addon shares (through LibSharedMedia)."] = "計量條的填色。在遊戲本身的少數幾種之下：其他插件共用的任何材質（透過 LibSharedMedia）。"
L["The bars and boxes the game puts at the top of the screen for a zone event or scenario, such as a timer to the next event. Until you change its ticks it does what the quest tracker's row does."] = "遊戲在區域事件或事件中放在畫面頂端的計量條與方框，例如距離下一個事件的計時器。在你變更其勾選之前，它跟隨任務追蹤列的設定。"
L["The bars as tall as it takes for what's left between them to have a film's shape, whatever your screen."] = "黑邊的高度會調整到讓中間剩下的畫面呈現電影比例，無論你的螢幕為何。"
L["The bars fade in at their full height."] = "黑邊以完整高度淡入。"
L["The bars fade into the scene past their edge."] = "黑邊超出其邊緣後融入場景。"
L["The bars grow in from the screen's edges."] = "黑邊從畫面邊緣向內延伸。"
L["The bars of every Vision that follows this page (Damage Vision's, Roll Vision's time left). Below the game's own few: any other addon shares (through LibSharedMedia)."] = "所有依此頁面設定之 Vision 的計量條（Damage Vision 的、Roll Vision 的剩餘時間）。在遊戲本身的少數幾種之下：其他插件共用的任何材質（透過 LibSharedMedia）。"
L["The bars' border: the game's, or one of ours (Custom: its thickness and color under it)."] = "計量條的邊框：遊戲的，或我們的（自訂：其下方設定粗細與顏色）。"
L["The bars' fill."] = "計量條的填色。"
L["The bars' fill. Below the game's own few: any other addon shares (through LibSharedMedia)."] = "計量條的填色。在遊戲本身的少數幾種之下：其他插件共用的任何材質（透過 LibSharedMedia）。"
L["The battle begins"] = "戰鬥開始"
L["The big words across the screen. <NAME>: the name of the one that fell."] = "橫跨畫面的大字。<NAME>：倒下者的名稱。"
L["The big words as you lose a duel."] = "你輸掉決鬥時的大字。"
L["The big words as you win a duel."] = "你贏得決鬥時的大字。"
L["The border round every page's bars, panels and buttons that follow General. The game's: as each page's default has it. Custom: its thickness and color under it."] = "所有依「一般」設定之頁面的計量條、底板與按鈕周圍的邊框。遊戲的：依各頁面的預設值。自訂：其下方設定粗細與顏色。"
L["The border around the Vision parts that follow this page (the quest item button's frame). Custom: its thickness and color under it."] = "依此頁面設定之 Vision 部件周圍的邊框（任務物品按鈕的框架）。自訂：其下方設定粗細與顏色。"
L["The border the game puts round your target's health bar, in its mark's color."] = "遊戲在你目標生命條周圍加上的邊框，使用其標記的顏色。"
L["The border's color."] = "邊框的顏色。"
L["The border's color. Picking one turns it to Custom."] = "邊框的顏色。選擇一個顏色會將它改為「自訂」。"
L["The boss's name as its fight starts, in place of Entering combat's card. Once a run for each boss."] = "首領戰開始時顯示首領的名稱，取代「進入戰鬥」的卡片。每次副本進度中每個首領一次。"
L["The boss's name as you first come within about 28 yards of it, before the fight. A dungeon or raid boss is told by its level: a skull, or on retail two over yours."] = "你第一次接近首領約 28 碼內時（戰鬥前）顯示其名稱。地城或團隊副本首領依其等級判斷：骷髏，或在正式版中比你高兩級。"
L["The boss's name as you first target it, before the fight. A dungeon or raid boss is told by its level: a skull, or on retail two over yours."] = "你第一次選取首領時（戰鬥前）顯示其名稱。地城或團隊副本首領依其等級判斷：骷髏，或在正式版中比你高兩級。"
L["The boxes the game puts under the minimap for a scenario's or quest's current step, such as a capture bar. Always shown to start with."] = "遊戲在小地圖下方為事件或任務目前的步驟放置的方框，例如佔領進度條。起初一律顯示。"
L["The bubble's color, for Custom."] = "泡泡的顏色，用於「自訂」。"
L["The bubble's tail sits on top, pointing up, instead of under it pointing down. (In a bubble only: not with no bubble behind the words.)"] = "泡泡的尾巴放在上方並朝上，而不是在下方朝下。（僅限有泡泡時：文字後方沒有泡泡時無效。）"
L["The bubble's words in a color of your own (the quest card keeps its ink)."] = "泡泡的文字使用你自己所選的顏色（任務卡片保留其墨色）。"
L["The buff fades"] = "增益消失"
L["The button's width and height."] = "按鈕的寬度與高度。"
L["The buttons beside the chat window (chat menu, channels, voice...) come up with a new message."] = "聊天視窗旁的按鈕（聊天選單、頻道、語音……）會在有新訊息時出現。"
L["The calendar button on the minimap header. Untick it to hide it in CineMode even while the minimap is up. Hovering the minimap brings it up with the map."] = "小地圖標題上的行事曆按鈕。取消勾選可在 CineMode 中即使小地圖顯示時也隱藏它。滑鼠指向小地圖會讓它隨地圖一起出現。"
L["The camera distance to start at. The game's furthest out may be less than this."] = "起始的鏡頭距離。遊戲的最遠距離可能小於此值。"
L["The camera eases out a little, then drifts in and out around your own distance. When you stop it glides back."] = "鏡頭稍微拉遠，然後在你自己的距離附近前後飄移。你停下時它會平滑回到原位。"
L["The camera eases out a little, then drifts in and out around your own distance. When you stop walking it glides back."] = "鏡頭稍微拉遠，然後在你自己的距離附近前後飄移。你停止行走時它會平滑回到原位。"
L["The camera eases out a little, then drifts slowly in and out around your own distance. Your own distance comes back afterwards."] = "鏡頭稍微拉遠，然後在你自己的距離附近緩緩前後飄移。之後會還原你自己的距離。"
L["The camera is %d yards from you: a unit next to you is about %d yards from it, one at 20 yards about %d, one at 35 about %d."] = "鏡頭距離你 %d 碼：你身旁的單位距離鏡頭約 %d 碼，20 碼外的約 %d 碼，35 碼外的約 %d 碼。"
L["The camera it moves like: cozy swings round to face you, vista and fish settle behind you (fish sways less), AFK turns right around you. Its other settings (Camera Settings page) go on as they are."] = "它模仿的鏡頭動作：悠閒會轉過來面對你，遠景與釣魚會停在你身後（釣魚擺動較少），暫離會繞你整圈。它的其他設定（鏡頭設定頁面）照舊。"
L["The camera lines up behind you, then turns this far round: 180 looks straight back at you."] = "鏡頭轉到你身後，然後再轉這麼多：180 表示直接回頭看著你。"
L["The camera never tilts more than this far below where it was when auto-run started, even when it lowers while you steer."] = "鏡頭向下傾斜的角度，永遠不會比自動奔跑開始時再低超過此值，即使你操控方向時鏡頭降低也一樣。"
L["The camera slowly pulls back, then (with random zoom) drifts in and out. Moving glides it back to your distance; zooming yourself keeps your new distance."] = "鏡頭緩緩拉遠，然後（開啟隨機縮放時）前後飄移。移動會讓它平滑回到你的距離；你自己縮放則保留新的距離。"
L["The camera snaps straight to whoever's talking instead of swinging, the letterbox comes in twice as tall for the conversation with subtitles in its bottom bar, and the whole UI fades out: the minimap, frames, nameplates, names and the circle under your target."] = "鏡頭直接切到說話者而不是轉過去，對話期間黑邊高度加倍並在底部黑邊中顯示字幕，整個介面淡出：小地圖、框架、名條、名稱以及目標腳下的圓圈。"
L["The camera sways this much lower than where it lines up behind you, so it looks out across the view rather than down at it. 0 keeps your angle."] = "鏡頭在你身後的對位位置下方這麼多處擺動，讓它眺望景色而非俯視。0 表示保持你的角度。"
L["The camera sways this much lower than where it lines up behind you, so it looks out across the water rather than down at it. 0 keeps your angle."] = "鏡頭在你身後的對位位置下方這麼多處擺動，讓它眺望水面而非俯視。0 表示保持你的角度。"
L["The camera sweeps around your character, pausing between sweeps. Moving or dragging the camera stops it."] = "鏡頭繞著你的角色環繞，每次環繞之間會停頓。移動或拖曳鏡頭會停止它。"
L["The camera swings a little from side to side behind your character, pausing between moves. Narrower than the vista camera's sway."] = "鏡頭在你角色身後輕微地左右擺動，每次移動之間會停頓。比遠景鏡頭的擺動幅度更窄。"
L["The camera swings from side to side behind your character, pausing between moves. Dragging the camera pauses it."] = "鏡頭在你角色身後左右擺動，每次移動之間會停頓。拖曳鏡頭會暫停它。"
L["The camera swings gently from side to side behind your character, pausing between moves."] = "鏡頭在你角色身後輕輕地左右擺動，每次移動之間會停頓。"
L["The camera swings very gently from side to side behind your character, pausing between moves."] = "鏡頭在你角色身後非常輕柔地左右擺動，每次移動之間會停頓。"
L["The camera this row starts. No camera: none (and its trigger's rows below aren't tried)."] = "此列啟動的鏡頭。無鏡頭：不啟動（且不會嘗試其觸發條件下方的列）。"
L["The camera turns back over the 6 seconds before this, so it's settled behind you this long before you land."] = "鏡頭在此之前的 6 秒內轉回，所以會在你降落前這麼久就停在你身後。"
L["The camera waits this long on a quest window before starting. Accept a quest and go sooner, and it doesn't move at all; stay to read, and it starts. Clicking through several quests, each new window adds a second to the wait. 0 starts at once."] = "鏡頭在任務視窗上等待這麼久才開始。若你接受任務並較早離開，它完全不會移動；若你留下閱讀，它就會開始。連續點過多個任務時，每個新視窗都會讓等待增加一秒。0 表示立即開始。"
L["The camera waits this long on the window before starting. Close it sooner, and it doesn't move at all. 0 starts at once."] = "鏡頭在視窗上等待這麼久才開始。若你較早關閉，它完全不會移動。0 表示立即開始。"
L["The camera's steps, in order, and what it does when it ends."] = "鏡頭的步驟（依順序），以及它結束時會做什麼。"
L["The card fades in and out."] = "卡片淡入淡出。"
L["The cast bar's border: the game's, or one of ours (Custom: its thickness and color under it)."] = "施法條的邊框：遊戲的，或我們的（自訂：其下方設定粗細與顏色）。"
L["The cast ends"] = "施法結束"
L["The chat window's dark background comes up with a new message. Untick for just the lines of text."] = "有新訊息時，聊天視窗的深色背景會出現。取消勾選則只顯示文字行。"
L["The chat window's tabs (General, Combat Log...) come up with a new message."] = "有新訊息時，聊天視窗的分頁（一般、戰鬥記錄……）會出現。"
L["The chat windows, with their tabs and buttons. Tick where they stay up while the rest fades; which messages bring them up for a moment is on the Chat page."] = "聊天視窗，連同其分頁與按鈕。勾選它們在其餘部分淡出時仍保持顯示的地方；哪些訊息會讓它們短暫出現，在聊天頁面設定。"
L["The classic smooth fill in your colors, no border."] = "經典的平滑填色，使用你的顏色，無邊框。"
L["The clock on the minimap header. Untick it to hide it in CineMode even while the minimap is up. Hovering the minimap brings it up with the map."] = "小地圖標題上的時鐘。取消勾選可在 CineMode 中即使小地圖顯示時也隱藏它。滑鼠指向小地圖會讓它隨地圖一起出現。"
L["The close-up distance the cozy camera zooms in to, if you're further out. The zoom settings above then work around it. Your own distance comes back afterwards."] = "若你距離較遠，悠閒鏡頭會拉近到的特寫距離。上方的縮放設定會以它為基準運作。之後會還原你自己的距離。"
L["The color grading over the game world: a preset, the time of day and each zone's mood. Where and when it shows: the Tint tab. The UI isn't tinted."] = "遊戲世界上的色彩分級：預設、時段及每個區域的氛圍。在何處、何時顯示：色調分頁。介面不會被染色。"
L["The dark edges' color, at full Shadow tint."] = "深色邊緣在陰影色調全滿時的顏色。"
L["The day and night dial by the minimap. Untick it to hide it in CineMode even while the minimap is up. Hovering the minimap brings it up with the map."] = "小地圖旁的日夜轉盤。取消勾選可在 CineMode 中即使小地圖顯示時也隱藏它。滑鼠指向小地圖會讓它隨地圖一起出現。"
L["The death camera fades everything while you're dead"] = "你死亡期間，死亡鏡頭會淡出所有東西"
L["The dungeon or raid and its difficulty under the boss's name (beside it in a letterbox bar)."] = "首領名稱下方顯示地城或團隊副本及其難度（在黑邊中則顯示在旁邊）。"
L["The edge in a unit's class or reaction color, or an item's quality."] = "邊緣使用單位的職業或反應顏色，或物品的品質顏色。"
L["The edges flash in the theme's color when a hit takes a lot at once. (What counts as big: the Vision tab.)"] = "一次受到大量傷害時，邊緣以主題的顏色閃光。（多少算重擊：Vision 分頁。）"
L["The edges of the screen flash for a moment as the card shows, this strongly. 0: no pulse."] = "卡片顯示時畫面邊緣短暫閃光，此為其強度。0：不脈動。"
L["The edges throb with a heartbeat, quicker as you weaken."] = "邊緣隨心跳跳動，你越虛弱跳得越快。"
L["The extra bar some bosses, quests and vehicles bring up, such as a boss's own power."] = "某些首領、任務與載具會帶出的額外計量條，例如首領自己的能量。"
L["The fastest the camera swings toward a new speaker. Each swing speeds up and slows down gently, as the flight camera's fly-bys do, so a short one never gets this fast and takes a few seconds."] = "鏡頭轉向新說話者的最快速度。每次轉向都會平緩地加速與減速，就像飛行鏡頭的掠過鏡頭一樣，所以短距離的轉向永遠不會達到這麼快，並需要幾秒鐘。"
L["The fastest the edges lift when you're healed, as a share of all the way each second (40%: a full heal takes at least 2.5 seconds). They speed up to it and slow as they settle."] = "你被治療時邊緣褪去的最快速度，以每秒佔全程的比例表示（40%：完整治療至少需要 2.5 秒）。它們會加速到此速度，並在停穩時減速。"
L["The first swing waits for the zoom in to finish."] = "第一次轉向會等待拉近完成。"
L["The first time you log in after Cinematic updates, a line in chat says so, with a What's new link to what's been added. Chat shows for it while the UI is faded."] = "Cinematic 更新後你第一次登入時，聊天中會有一行提示，附上「新功能」連結，列出新增的內容。介面淡出時，聊天會為它顯示。"
L["The full report: how you did on the run, boss by boss and the rest, with the whole party (/cine report). Made-up bosses while the meter has none."] = "完整報告：你在這次副本中的表現，逐一首領及其餘部分，包括整個隊伍（/cine report）。統計中沒有首領時會使用模擬的首領。"
L["The game only shows a bubble over someone on your screen, and puts one from someone above you at the very top of the screen, under the letterbox bar. So Cinematic draws bubbles of its own, looking like the game's, for speech whose bubble you can't see. How they look, and where speech from behind you shows: the Style hub's Chat bubbles page."] = "遊戲只會在你畫面上的人頭頂顯示泡泡，而在你上方的人的泡泡會放在畫面最頂端、黑邊下方。所以 Cinematic 會為你看不到泡泡的話語繪製自己的泡泡，外觀與遊戲的相同。它們的外觀，以及來自你身後之話語的顯示位置：「風格」分類的對話泡泡頁面。"
L["The game shows only your main power under your character: Maelstrom, Insanity, Astral Power, rage or energy in a form. Ticked, your mana gets a bar of its own under it. When it comes up is the Personal mana bar row on the Game Frames page."] = "遊戲只會在你角色下方顯示你的主要能量：漩渦、瘋狂、星能，或某種形態下的怒氣或能量。勾選時，你的法力會在其下方有自己的計量條。何時出現依遊戲框架頁面的「個人法力條」列而定。"
L["The game's"] = "遊戲的"
L["The game's Show Offscreen Nameplates in CineMode. Ticked: on, plates for units out of view stay, pinned to the edge of the screen, so rows and rules that look for plates still find them, like an elite behind you for the elite rules. Unticked: off in CineMode. Your own setting comes back when CineMode ends."] = "CineMode 中遊戲的「顯示畫面外名條」。勾選：開啟，視野外單位的名條會保留並固定在畫面邊緣，讓尋找名條的列與規則仍能找到它們，例如精英規則所需的你身後的精英。未勾選：CineMode 中關閉。CineMode 結束時會還原你自己的設定。"
L["The game's background tinted a color of your own (the swatch)."] = "遊戲的背景，染上你自己所選的顏色（色塊）。"
L["The game's bars, as it draws them (the defaults)."] = "遊戲的計量條，依其繪製方式（預設值）。"
L["The game's bubbles, with bigger words."] = "遊戲的泡泡，文字較大。"
L["The game's dice and coin before each name."] = "每個名稱前顯示遊戲的骰子與錢幣圖示。"
L["The game's effect shown. Theme's pick: the one picked to go with your theme (it changes with it)."] = "顯示的遊戲效果。主題的選擇：搭配你主題所選的效果（會隨主題改變）。"
L["The game's effects slide slowly under their edge, as they do in the game (not an edge like the red one)."] = "遊戲的效果在其邊緣下緩緩滑動，就像在遊戲中一樣（不是像紅色那類的邊緣）。"
L["The game's figure"] = "遊戲的數據"
L["The game's figure, the last five minutes"] = "遊戲的數據，最近五分鐘"
L["The game's frame"] = "遊戲的框架"
L["The game's frames, as it draws them (the defaults)."] = "遊戲的框架，依其繪製方式（預設值）。"
L["The game's mark and name for who the spell is cast at."] = "遊戲為法術施放對象顯示的標記與名稱。"
L["The game's mark on casts it counts as important, ones worth interrupting or getting out of."] = "遊戲為其視為重要之施法加上的標記，值得打斷或躲開的施法。"
L["The game's menu doesn't change it. Its default is %s."] = "遊戲的選單不會變更它。其預設值為 %s。"
L["The game's menu doesn't change it: it's %s."] = "遊戲的選單不會變更它：它是 %s。"
L["The game's menu goes from %s to %s."] = "遊戲的選單範圍為 %s 到 %s。"
L["The game's own bubble."] = "遊戲本身的泡泡。"
L["The game's own bubbles (the defaults)."] = "遊戲本身的泡泡（預設值）。"
L["The game's own cast bars (the defaults)."] = "遊戲本身的施法條（預設值）。"
L["The game's own chat bubble."] = "遊戲本身的對話泡泡。"
L["The game's own graphics settings one by one, past its Graphics menu either way: higher for a better look, lower for a faster game. They're this computer's: the same in every profile."] = "遊戲本身的圖形設定，逐項設定，可超出其圖形選單的範圍：較高畫面較好，較低遊戲較順。它們屬於這台電腦：在每個設定檔中都相同。"
L["The game's own screen effects (fire, frost, lightning, ripples...) cut to an edge, closing in with ours, over it. Each theme has one picked to go with it. Classic has only a few of them."] = "遊戲本身的畫面效果（火焰、冰霜、閃電、漣漪……）裁切成邊緣，隨我們的效果一起收攏，疊在其上。每個主題都有一個搭配的效果。經典版只有其中少數幾種。"
L["The game's own screen effects, cut to an edge, over ours."] = "遊戲本身的畫面效果，裁切成邊緣，疊在我們的效果上。"
L["The game's own setting (Options, Nameplates, Style): the size and color of its plates' bars, all in the same texture. Shown here for what it is; Cinematic doesn't change it."] = "遊戲本身的設定（選項 > 名條 > 樣式）：其名條計量條的大小與顏色，全部使用同一材質。在此僅供參考；Cinematic 不會變更它。"
L["The game's party and raid frames show only who needs healing: everyone (pets too) while below full health, and tanks as set below. The group titles hide. The members stay in their places, so there are gaps. Out of combat, the mouse over the frames brings everyone back. Ticked in the grid, it's on there. Always: everywhere. Party and Raid: while you're in one, wherever you are. Members with debuffs can't be shown: the game doesn't let addons see your group's debuffs in fights."] = "遊戲的隊伍與團隊框架只顯示需要治療的人：生命值未滿的所有人（包括寵物），以及依下方設定的坦克。小隊標題會隱藏。成員保持在原位，所以會有空隙。非戰鬥中，滑鼠移到框架上會讓所有人重新顯示。在表格中勾選即在該處開啟。一律：到處都開啟。隊伍與團隊：身處其中時，無論在哪裡。無法顯示有減益的成員：遊戲不允許插件在戰鬥中看到你隊伍的減益。"
L["The game's profiler isn't on this client."] = "此用戶端沒有遊戲的效能分析器。"
L["The game's profiler isn't on this client: use a recording below."] = "此用戶端沒有遊戲的效能分析器：請使用下方的記錄。"
L["The game's raid frames, as it draws them (the defaults)."] = "遊戲的團隊框架，依其繪製方式（預設值）。"
L["The game's shield over the icon while the cast can't be interrupted."] = "施法無法被打斷時，圖示上顯示遊戲的盾牌。"
L["The game's sweep"] = "遊戲的掃描效果"
L["The game's tooltips, as it draws them (the defaults)."] = "遊戲的滑鼠提示，依其繪製方式（預設值）。"
L["The game's: each part in its own (the quest window's for the words). Russian, Korean or Chinese text keeps the game's, so its letters show."] = "遊戲的：每個部分使用其自身的（文字使用任務視窗的）。俄文、韓文或中文文字會保留遊戲的字型，以便正確顯示字元。"
L["The game's: its own fill, in its own colors. Below the game's own few: any other addon shares (through LibSharedMedia)."] = "遊戲的：其自身的填色，使用其自身的顏色。在遊戲本身的少數幾種之下：其他插件共用的任何材質（透過 LibSharedMedia）。"
L["The glow round it, added on as light (Glow's only color)."] = "環繞它的光暈，以光線方式加上（「光暈」的唯一顏色）。"
L["The health bar's color, for Custom."] = "生命條的顏色，用於「自訂」。"
L["The health bar's fill. Below the game's own few: any other addon shares (through LibSharedMedia)."] = "生命條的填色。在遊戲本身的少數幾種之下：其他插件共用的任何材質（透過 LibSharedMedia）。"
L["The health bar's height, next to the game's."] = "生命條的高度，相對於遊戲的高度。"
L["The health bar's height."] = "生命條的高度。"
L["The health bar's width."] = "生命條的寬度。"
L["The icon glows bright and dim while it flashes."] = "閃爍時圖示忽明忽暗。"
L["The icon grows a little and back with each beat while it flashes."] = "閃爍時圖示隨每次跳動稍微放大再縮回。"
L["The icon's size, next to the game's. On nameplates, the health bar and name ride up on it."] = "圖示的大小，相對於遊戲的大小。在名條上，生命條與名稱會隨之上移。"
L["The icon. Click to pick it from all the game's. Right-click: back to the event's own."] = "圖示。點擊可從遊戲的所有圖示中選擇。右鍵：回到事件自己的圖示。"
L["The icons this bar shows sit together in their order, centered on the bar, instead of faded ones leaving gaps. Edit Mode shows the game's own layout."] = "此列顯示的圖示會依序排在一起，置中於列上，而不是讓淡出的圖示留下空隙。編輯模式會顯示遊戲本身的版面配置。"
L["The item's quality"] = "物品的品質"
L["The key you've bound to it (Key Bindings, Cinematic: Use the quest item), in its top corner."] = "你為它綁定的按鍵（按鍵設定 > Cinematic：使用任務物品），顯示在其頂端角落。"
L["The kind of plate the row is for: your target, focus or the unit under the mouse; Aggro, enemies by who they're attacking; Units, by what they are; or Default, every other plate."] = "此列適用的名條類別：你的目標、專注目標或滑鼠下的單位；仇恨，依敵人正在攻擊的對象；單位，依其種類；或預設，其他所有名條。"
L["The last tooltip, %d sec ago"] = "上一個滑鼠提示，%d 秒前"
L["The least of the member you've targeted that shows while they'd be hidden. It only ever makes them more visible: a target whose own opacity above is higher (a tank shown always, say) keeps it. 100% always shows them, at full health too."] = "你所選取的成員在原本會被隱藏時，仍顯示的最低程度。它只會讓他們更明顯：若目標本身在上方的不透明度更高（例如一律顯示的坦克），則保留該值。100% 表示一律顯示他們，生命值全滿時也一樣。"
L["The letters start spread apart and close up, as a film's title comes in; the other lines rise in after. A name the game keeps secret (a boss's before its fight, on retail) opens as Reveal instead."] = "字母一開始分散然後聚攏，就像電影標題出現一樣；其他行隨後升起。遊戲保密的名稱（正式版中首領在戰鬥前的名稱）會改以「揭曉」方式呈現。"
L["The level you reached, if you went up."] = "你達到的等級（如果有升級）。"
L["The line round a Dark or Custom bubble. Custom: its thickness and color under it."] = "深色或自訂泡泡周圍的線條。自訂：其下方設定粗細與顏色。"
L["The lines under an item's players: \"and N more\", \"Lower picks\", who passed, and \"Click to list everyone\". Off: just the players. Clicking an item's panel still lists everyone."] = "物品玩家下方的行：「還有 N 人」、「較低的選擇」、誰放棄了，以及「點擊以列出所有人」。關閉：只顯示玩家。點擊物品的面板仍會列出所有人。"
L["The list comes with each release. (For the dev copy, run Tools/commits.sh and /reload.)"] = "此清單隨每個版本更新。（開發版請執行 Tools/commits.sh 並 /reload。）"
L["The little point under the bubble. Unticked, just the bubble."] = "泡泡下方的小尖角。未勾選時只有泡泡。"
L["The look every Vision shares. Each setting starts on the Style hub's General page's; a Vision with a setting of its own on its page keeps it."] = "所有 Vision 共用的外觀。每項設定起初依照「風格」分類一般頁面的設定；在自己頁面上有專屬設定的 Vision 會保留它。"
L["The look of Cinematic's settings pages and windows, for all your characters. HD: flat and dark, with thin edges. SD: the game's own buttons and windows. Auto: HD on retail, SD on classic, and on WoW Forever as your Character Models setting is (Standard: SD)."] = "Cinematic 設定頁面與視窗的外觀，套用於你所有的角色。HD：平面深色，細邊。SD：遊戲本身的按鈕與視窗。自動：正式版為 HD，經典版為 SD，WoW Forever 則依你的角色模型設定（標準：SD）。"
L["The look: Auto picks your class and spec's (by the talent tree you've put most into, on clients without specs), or pick any. Each class has a theme for each spec. Create theme makes one of your own from the one shown, under Your themes; the theme's own settings below change the one shown (ours become your version, which Reset theme puts back)."] = "外觀：「自動」會選擇你職業與專精的主題（在沒有專精的用戶端上，依你投入最多點數的天賦樹），或任選一個。每個職業的每個專精都有一個主題。「建立主題」會以目前顯示的主題為基礎建立你自己的主題，放在「你的主題」下；下方的主題設定會變更目前顯示的主題（我們的會變成你的版本，可用「重置主題」還原）。"
L["The mana bar shows for this many seconds after you spend mana, then fades out until you spend some again. 0: whenever it's up."] = "法力條在你消耗法力後顯示這麼多秒，然後淡出，直到你再次消耗法力。0：只要它出現就顯示。"
L["The mana bar's color, for Custom."] = "法力條的顏色，用於「自訂」。"
L["The mana bar's height, next to the power bar's."] = "法力條的高度，相對於能量條的高度。"
L["The mark on important casts"] = "重要施法的標記"
L["The mark's color."] = "標記的顏色。"
L["The mark's own opacity (the plate's is on the Plate line)."] = "標記本身的不透明度（名條的在「名條」一行）。"
L["The mark's size."] = "標記的大小。"
L["The member under your mouse fades in to at least this, in fights too, and starts fading out the moment the mouse leaves them. 0% turns it off."] = "滑鼠下的成員至少淡入到此程度，戰鬥中也一樣，滑鼠離開時立即開始淡出。0% 表示關閉。"
L["The meter's totals are hidden in a fight (and for a whole key). The report fills in once it's over."] = "戰鬥中（以及整個鑰石期間）統計的總計會隱藏。結束後報告就會填入。"
L["The minimap stays up only this long after you pick up a quest or make progress on a tracked one, then fades until you do again. Off: it stays up the whole time a quest is tracked."] = "你接受任務或追蹤中的任務有進展後，小地圖只保持顯示這麼久，然後淡出，直到下次再有進展。關閉：只要有追蹤任務就全程保持顯示。"
L["The moment this rule is for. Click to switch."] = "此規則適用的時刻。點擊切換。"
L["The most the addon took in one frame."] = "插件在單一幀中耗費的最長時間。"
L["The mouse is on it, or on a frame in its Hover group"] = "滑鼠在它上面，或在其滑鼠指向群組中的某個框架上"
L["The name's font. Russian, Korean or Chinese names keep the game's, so their letters show."] = "名稱的字型。俄文、韓文或中文名稱會保留遊戲的字型，以便正確顯示字元。"
L["The name's size, next to the game's."] = "名稱的大小，相對於遊戲的大小。"
L["The names and portraits above the chat of who's talking in voice chat. Untick Always to hide them in CineMode."] = "聊天上方顯示語音聊天中正在說話者的名稱與頭像。取消勾選「一律」可在 CineMode 中隱藏它們。"
L["The new angle is never within this many degrees of the current one, either way. Keep it below the swing for varied moves."] = "新角度與目前角度的差距，無論哪個方向，都不會小於這麼多度。請保持低於擺動幅度，讓移動更多變。"
L["The new buff shows at the start of the row, not in its own place among empty spaces."] = "新增益顯示在該列的開頭，而不是在空格之間它自己的位置。"
L["The other player's name as they challenge you to a duel."] = "對方向你提出決鬥時顯示其名稱。"
L["The other player's name as you challenge them to a duel."] = "你向對方提出決鬥時顯示其名稱。"
L["The parts of the plate in its color, ticks."] = "名條中使用其顏色的部分，以勾選設定。"
L["The pattern's own"] = "圖樣自己的"
L["The pattern's own choice"] = "圖樣自己的選擇"
L["The place's color (and the recap's title). Picking one turns it to Your own."] = "地點的顏色（以及回顧的標題）。選擇一個顏色會將它改為「你自己的」。"
L["The plan adds nothing to your talents."] = "此計畫沒有為你的天賦新增任何東西。"
L["The plan needs level %d; you're level %d."] = "此計畫需要等級 %d；你目前是等級 %d。"
L["The plan takes back talents you've learned: only a class trainer can unlearn them."] = "此計畫會收回你已學會的天賦：只有職業訓練師才能遺忘它們。"
L["The plate's color, for the parts ticked beside it. -: the next row that fits the plate decides (the game's if none does). The game's: the game's, whatever the rows below say. Mark's: the mark's color. The rest as the mark's colors."] = "名條的顏色，用於旁邊勾選的部分。-：由下一個符合此名條的列決定（若都不符合則為遊戲的）。遊戲的：遊戲的顏色，不論下方各列怎麼設定。標記的：標記的顏色。其餘依標記的顏色。"
L["The power bar's height, next to the game's."] = "能量條的高度，相對於遊戲的高度。"
L["The quest camera can't start now: it's off (Scenes page), you're moving or in a fight, or it's turned off where you are."] = "任務鏡頭現在無法啟動：它已關閉（場景頁面）、你正在移動或戰鬥中，或它在你所在之處已關閉。"
L["The quest card and the list of replies have the bubble's look instead of their own dark one, their words in colors that suit it."] = "任務卡片與回覆清單改用泡泡的外觀，而不是它們自己的深色外觀，文字使用搭配的顏色。"
L["The quest mark's icon on enemies you still need for a quest (a mob to kill): on their nameplates or names, and on your target frame. Click to pick another."] = "你在任務中仍需要的敵人（要擊殺的怪物）身上的任務標記圖示：在其名條或名稱上，以及你的目標框架上。點擊可選擇其他圖示。"
L["The quest mark's icon on friendly NPCs you still need for a quest (an NPC to talk to): on their nameplates or names, on your target frame, and over the quest object that glows. One you can't do anything with yourself shows it grayed (with the !, the game's \"in progress\" mark). Click to pick another."] = "你在任務中仍需要的友方 NPC（要對話的 NPC）身上的任務標記圖示：在其名條或名稱上、你的目標框架上，以及發光的任務物體上方。你自己無法互動的會以灰色顯示（帶有 !，遊戲的「進行中」標記）。點擊可選擇其他圖示。"
L["The ranged bar goes on top, where the main hand's was, and the main hand and off-hand bars each move down one. Set for each class on its own (ticked for hunters, mages, priests and warlocks to start with), so one profile suits all your characters."] = "遠程計時條放到頂端主手原本的位置，主手與副手計時條各往下移一格。每個職業各自設定（起初獵人、法師、牧師與術士為勾選），讓一個設定檔適用於你所有的角色。"
L["The ready check's tick, cross or question mark on each member's raid frame."] = "每位成員團隊框架上的準備確認勾號、叉號或問號。"
L["The recap card, with the meter's whole run if you've one, else made up (Stop hides it)."] = "回顧卡片，若有統計資料則使用整場副本的資料，否則使用模擬資料（「停止」可隱藏它）。"
L["The rest of its settings are on the Scripts page, under the steps they make: pick this camera there."] = "它的其餘設定在腳本頁面中，位於其產生的步驟下方：在那裡選擇此鏡頭。"
L["The rule isn't finished. Finish it, or close with X or Escape to put back the rule it had."] = "規則尚未完成。請完成它，或用 X 或 Esc 關閉以還原它原本的規則。"
L["The same for your personal health bar: it comes up with the first hit or heal you take."] = "你的個人生命條也一樣：在你第一次受到攻擊或治療時出現。"
L["The same for your personal resource display."] = "你的個人資源顯示也一樣。"
L["The same for your player frame: it comes up once your health or your power changes."] = "你的玩家框架也一樣：在你的生命值或能量變化時出現。"
L["The same person doing the same again (buffing you again, another wave) brings up no card for the minutes below. Their other moments still do."] = "同一個人再次做同樣的事（再次為你上增益、再次揮手），在下方設定的分鐘數內不會再出現卡片。他們的其他時刻仍會出現。"
L["The same place shows at most once every 90 seconds."] = "同一個地點最多每 90 秒顯示一次。"
L["The screen's edges close in as your health drops, with your theme's art (all the sections below)."] = "隨你的生命值下降，畫面邊緣會向內收攏，搭配你主題的美術圖（下方所有區段）。"
L["The seconds left in the middle of the button while it cools down."] = "冷卻期間，按鈕中央顯示剩餘秒數。"
L["The seconds left on the Cooldown Manager's icons show only when the game's Show Numbers for Cooldowns (Options > Action Bars) is on. Unticked, the Cooldown Manager shows them as it likes."] = "只有在遊戲的「顯示冷卻時間數字」（選項 > 快捷列）開啟時，冷卻管理器的圖示上才會顯示剩餘秒數。未勾選時，冷卻管理器依其自己的方式顯示。"
L["The seconds left on the cast, at the bar's right end (in the same font). Hidden while the game keeps them secret, in some fights."] = "施法的剩餘秒數，顯示在計量條右端（使用相同字型）。某些戰鬥中遊戲保密時會隱藏。"
L["The selection circle on the ground under your target. Hidden, your own setting is put back when the UI returns."] = "目標腳下地面上的選取圓圈。隱藏時，介面恢復顯示後會還原你自己的設定。"
L["The settings below as they are while you're this role (your specialization's, or the one picked in the group finder)."] = "你擔任此職責時下方的設定（依你的專精，或在隊伍搜尋器中選擇的職責）。"
L["The settings below for every role that uses the default settings."] = "下方的設定，適用於所有使用預設設定的職責。"
L["The settings every frame has while its tab uses the default settings."] = "每個框架在其分頁使用預設設定時所套用的設定。"
L["The settings every group has while its tab uses the default settings."] = "每個群組在其分頁使用預設設定時所套用的設定。"
L["The settings every kind of cast bar has while its tab uses the default settings."] = "每種施法條在其分頁使用預設設定時所套用的設定。"
L["The share of your health a hit has to take at once to count as big."] = "一次攻擊必須造成你多少比例的生命值才算重擊。"
L["The shield on casts that can't be interrupted"] = "無法被打斷之施法上的盾牌"
L["The shot to show and change."] = "要顯示與變更的鏡頭片段。"
L["The shot's name, as the Scenes page lists it."] = "鏡頭片段的名稱，如場景頁面中所列。"
L["The size of the bubble and the list as a whole (their words grow with them)."] = "泡泡與清單的整體大小（其文字會隨之放大）。"
L["The size of the game's shadow maps: bigger gives crisper shadow edges, smaller saves frame rate. Players found nothing more above 2048, so 4096 may look the same. Needs shadows on in the game's menu."] = "遊戲陰影貼圖的大小：較大可讓陰影邊緣更銳利，較小可提升幀數。玩家發現超過 2048 後就沒有差別，所以 4096 看起來可能一樣。需要在遊戲選單中開啟陰影。"
L["The slow drift the camera keeps up between moves. 0: none."] = "鏡頭在兩次移動之間持續的緩慢飄移。0：無。"
L["The small lines over and under the words, bigger or smaller than they come (100%: as they come, by the words' size)."] = "文字上下方的細行，比原本更大或更小（100%：原樣，依文字大小）。"
L["The small lines' font, over and under the words."] = "文字上下方細行的字型。"
L["The spark at the fill's end"] = "填色末端的火花"
L["The spell's icon"] = "法術的圖示"
L["The spell's name"] = "法術的名稱"
L["The spell's name and seconds left in a color of your own."] = "法術名稱與剩餘秒數使用你自己所選的顏色。"
L["The strength, reach and brightness of it all, the shadow, the heartbeat and big hits."] = "整體的強度、範圍與亮度、陰影、心跳與重擊。"
L["The style this card starts from. Settings you give it on the Style tab go over it."] = "此卡片的起始樣式。你在樣式分頁給它的設定會覆蓋在上面。"
L["The style this card starts from. The settings below that you change go over it, as its own."] = "此卡片的起始樣式。你在下方變更的設定會覆蓋在上面，成為它自己的設定。"
L["The style this tab shows and sets."] = "此分頁顯示並設定的樣式。"
L["The styles the cards start from. Change one here and every card that starts from it changes too, except where a card has a setting of its own (its Style page, from its row on the Events tab). Changes play at once in the preview."] = "卡片的起始樣式。在此變更其中一個，所有以它為起始的卡片也會跟著改變，除非某張卡片有自己的設定（其樣式頁面，從事件分頁中它的列進入）。變更會立即在預覽中播放。"
L["The styles the cards start from: change one for every card using it."] = "卡片的起始樣式：變更其中一個會套用於使用它的每張卡片。"
L["The swing round to face you is timed to get there this long before the cast ends. More is a quicker swing."] = "轉過來面對你的時機，會設定為在施法結束前這麼久到位。越多轉得越快。"
L["The swing stops with the speaker this far from the middle of the screen, on their side, so you stay in the shot beside them. 0 aims right at them (you may block the view)."] = "轉向停止時，說話者位於畫面中央偏其一側這麼遠，讓你也在畫面中、在他們旁邊。0 表示直接對準他們（你可能會擋住視線）。"
L["The tail curls the other way, as if seen in a mirror."] = "尾巴往另一個方向彎，如同鏡像。"
L["The tail pointing at who's talking"] = "尾巴指向說話者"
L["The talent calculator can't read your talents here."] = "天賦模擬器無法在此讀取你的天賦。"
L["The theme's art soaking in from the edges as they close in (blood, smoke, a glow...)."] = "主題的美術圖隨邊緣收攏從邊緣滲入（血液、煙霧、光暈……）。"
L["The theme's art: smoke billowing in, a soft glow, blood (or water) soaking in, frost on glass, fur... None: no art, its sparks and shadow only."] = "主題的美術圖：湧入的煙霧、柔和的光暈、滲入的血液（或水）、玻璃上的冰霜、毛皮……無：沒有美術圖，只有火花與陰影。"
L["The theme's color"] = "主題的顏色"
L["The theme's color: the effect turned grey and tinted to match your theme. Its own colors: as the game draws it."] = "主題的顏色：效果轉為灰色並染上符合你主題的顏色。其自身顏色：依遊戲的繪製方式。"
L["The theme's own art and its sparks."] = "主題本身的美術圖及其火花。"
L["The theme's sparks (motes, stars, lightning) and the haze drifting over the edges."] = "主題的火花（光點、星星、閃電）及飄過邊緣的朦朧。"
L["The theme's swirl turning over the screen, closing in from past the corners as they close in, and turning quicker the weaker you are."] = "主題的漩渦在畫面上旋轉，隨邊緣收攏從角落外向內收攏，你越虛弱轉得越快。"
L["The theme's swirl: up to two layers turning over the screen."] = "主題的漩渦：最多兩層在畫面上旋轉。"
L["The thing on the ground you pick up or use for a quest objective glows gold, with the quest mark over it, in CineMode and out. One at a time: the one in front of you that your interact key would use, up to 20 yards away. Only while a quest in this zone still needs something picked up or used. Then it turns on the game's soft targeting for things to interact with (Interact key on keyboard and mouse too); your own settings come back after."] = "任務目標中你要拾取或使用的地上物品會發出金光，上方有任務標記，CineMode 中及之外都是。一次一個：你面前、互動鍵會使用的那個，最遠 20 碼。僅在此區域有任務仍需要拾取或使用東西時。此時它會開啟遊戲的互動物件軟選取（鍵盤與滑鼠的互動鍵也可用）；之後會還原你自己的設定。"
L["The time of day this rule is for. Click to switch."] = "此規則適用的時段。點擊切換。"
L["The tint's strength slowly wanders up and down over a few minutes, so a still scene feels a little more alive: how far either way, as a share of the strength. Paused while the Style tab is open. Off: it stays put."] = "色調的強度會在幾分鐘內緩緩上下飄動，讓靜止的畫面感覺更有生氣：此為上下的幅度，以強度的比例表示。樣式分頁開啟時暫停。關閉：保持不變。"
L["The tooltip fades out over the first 3 seconds of the cast too, and comes back as the cast ends or is cancelled."] = "滑鼠提示也會在施法的前 3 秒內淡出，並在施法結束或取消時恢復。"
L["The tooltip's edge. In its color: a unit's class or reaction color, an item's quality. Custom: its thickness and color under it."] = "滑鼠提示的邊緣。使用其顏色：單位的職業或反應顏色、物品的品質。自訂：其下方設定粗細與顏色。"
L["The tracking button on the minimap header. Untick it to hide it in CineMode even while the minimap is up. Hovering the minimap brings it up with the map."] = "小地圖標題上的追蹤按鈕。取消勾選可在 CineMode 中即使小地圖顯示時也隱藏它。滑鼠指向小地圖會讓它隨地圖一起出現。"
L["The two colors after it."] = "它之後的兩種顏色。"
L["The unit under the mouse. Hovering a unit itself works too, not just its plate. Just the marks over the plate: the others hang in the air where its plate is hidden."] = "滑鼠下的單位。直接指向單位本身也有效，不只是其名條。只有名條上方的標記：其他標記會懸在名條隱藏處的空中。"
L["The unit's health bar in its mark's color."] = "單位的生命條使用其標記的顏色。"
L["The unit's name in its mark's color, on its plate or shown alone."] = "單位的名稱使用其標記的顏色，在其名條上或單獨顯示時。"
L["The wheel's icon, as it shows on the master wheel. Click to pick another."] = "輪盤的圖示，顯示在主輪盤上。點擊可選擇其他圖示。"
L["The whole card at once."] = "整張卡片同時出現。"
L["The whole plate's opacity while this row fits it, whether it has a mark or not. CineMode's own fade comes on top."] = "此列符合時整個名條的不透明度，無論是否有標記。CineMode 本身的淡出會再疊加上去。"
L["The whole run"] = "整場副本"
L["The window shows this many items at once, newest at the top: four down, the rest in a second column. When another drops, the oldest goes."] = "視窗同時顯示這麼多件物品，最新的在頂端：往下四件，其餘放在第二欄。再掉落一件時，最舊的會移除。"
L["The window sits to the right of the game's roll frames, level with their top, instead of under them, so a long list of drops doesn't push it down the screen. It stays there once you've chosen."] = "視窗位於遊戲擲骰框架的右側，與其頂端對齊，而不是在其下方，這樣掉落物清單很長時就不會把它推到畫面下方。你選擇後它仍留在那裡。"
L["The windows you have open open again after."] = "你開啟的視窗之後會再次開啟。"
L["The words before it all (on a card, over the zone name)."] = "最前面的文字（在卡片上，區域名稱上方）。"
L["The words come in a letter at a time from the left, as if typed; the other lines rise in after. A secret name opens as Reveal instead."] = "文字從左邊一個字一個字出現，像打字一樣；其他行隨後升起。保密的名稱會改以「揭曉」方式呈現。"
L["The words coming out of a fight. Empty: none, just the rest of the card."] = "離開戰鬥時的文字。留空：沒有文字，只顯示卡片的其餘部分。"
L["The words going into a fight. Empty: none, just the rest of the card."] = "進入戰鬥時的文字。留空：沒有文字，只顯示卡片的其餘部分。"
L["The words open out from their middle (or from their side, in the lower third or at a bar's side), the line drawing out with them; the other lines rise in after."] = "文字從中央展開（在下方三分之一或黑邊側邊時則從側邊），線條隨之延伸；其他行隨後升起。"
L["The words over a line that draws out, as a new scene starts."] = "新場景開始時，文字位於一條延伸出來的線上。"
L["The words the banner shows with Custom picked. Left blank: YOU DIED."] = "選擇「自訂」時橫幅顯示的文字。留空：你死了。"
L["The words the banner shows with Custom picked. Left blank: the first ones in the list."] = "選擇「自訂」時橫幅顯示的文字。留空：清單中的第一個。"
L["The words under both names as the duel starts. Empty: none."] = "決鬥開始時雙方名稱下方的文字。留空：無。"
L["The words' color; the lines with them in a lighter shade."] = "文字的顏色；與其一起的線條使用較淺的色調。"
L["The words' font. Russian, Korean or Chinese text keeps the game's, so its letters show."] = "文字的字型。俄文、韓文或中文文字會保留遊戲的字型，以便正確顯示字元。"
L["The words' height next to the bar's: they grow and shrink with your letterbox. (With no letterbox up, a bar as tall as your letterbox's comes in for the card.)"] = "文字相對於黑邊的高度：會隨你的黑邊放大縮小。（沒有黑邊時，會為卡片帶入一條與你黑邊同高的黑邊。）"
L["The words' size, next to their own."] = "文字的大小，相對於其原本大小。"
L["The world dims and goes cold and gray-blue, with a heavy vignette closing in from the edges. It clears when you release or come back."] = "世界變暗並轉為冰冷的灰藍色，厚重的暗角從邊緣收攏。你釋放靈魂或復活時就會消失。"
L["The zone you spent the most time in (on a card, its big name)."] = "你待最久的區域（在卡片上，以大字顯示其名稱）。"
L["The zone's name on the minimap header. Untick it to hide it in CineMode even while the minimap is up. Hovering the minimap brings it up with the map."] = "小地圖標題上的區域名稱。取消勾選可在 CineMode 中即使小地圖顯示時也隱藏它。滑鼠指向小地圖會讓它隨地圖一起出現。"
L["Their class's color, as the plates draw them."] = "他們的職業顏色，與名條的繪製方式相同。"
L["Their color."] = "他們的顏色。"
L["Their face"] = "他們的臉孔"
L["Their face."] = "他們的臉孔。"
L["Their name"] = "他們的名稱"
L["Their numbers, once the rolls are shown"] = "擲骰顯示後的點數"
L["Their portrait on the card (their class's icon when they're out of sight)."] = "卡片上他們的頭像（不在視野內時為其職業圖示）。"
L["Theme colors"] = "主題顏色"
L["Theme's pick"] = "主題的選擇"
L["Theme's sparks"] = "主題的火花"
L["Theme's speed"] = "主題的速度"
L["Theme's swirl"] = "主題的漩渦"
L["Theme's throb"] = "主題的跳動"
L["Theme:"] = "主題："
L["These bubbles show everywhere, in fights and out. (The other columns then have nothing to add.)"] = "這些泡泡到處都顯示，戰鬥中與戰鬥外皆然。（其他欄便沒有什麼可補充的了。）"
L["These cast bars' settings: Default's until you untick Use default settings."] = "這些施法條的設定：在你取消勾選「使用預設設定」之前依照「預設」。"
L["These settings back on General."] = "這些設定改回依照「一般」。"
L["These settings back on the Visions hub's Style page."] = "這些設定改回依照「Vision」分類的樣式頁面。"
L["Thick"] = "粗"
L["Thick + shadow"] = "粗 + 陰影"
L["Thickness"] = "粗細"
L["Thin"] = "細"
L["Thin bars with a thin gold line along their edge."] = "細計量條，邊緣有一條細金線。"
L["Thin black bars that slide in with the UI's fade (the defaults)."] = "隨介面淡出滑入的細黑邊（預設值）。"
L["Thin, borderless bars that barely show over the world."] = "細而無邊框的計量條，在世界上幾乎看不出來。"
L["This Edit Mode layout's action bars come on or off after a reload. Reload now?"] = "此編輯模式版面配置的快捷列會在重新載入後開啟或關閉。現在重新載入嗎？"
L["This Vision's shared settings back on Visions Style."] = "此 Vision 的共用設定改回依照 Visions 樣式。"
L["This boss only"] = "僅此首領"
L["This boss only: everyone starts at 0 as a boss is pulled, and when it dies it's back to the whole run. The whole run: the meter's Overall. Each fight: every pull starts at 0."] = "僅此首領：拉到首領時所有人從 0 開始，首領死亡後回到整場副本。整場副本：統計的「總計」。每場戰鬥：每次拉怪都從 0 開始。"
L["This camera can't be tested now: Cinematic or the camera is off (Camera Triggers page), or you're moving, flying or in a fight."] = "此鏡頭現在無法測試：Cinematic 或該鏡頭已關閉（鏡頭觸發頁面），或你正在移動、飛行或戰鬥中。"
L["This card's rules as they come."] = "此卡片規則的原始狀態。"
L["This client has no damage meter."] = "此用戶端沒有傷害統計。"
L["This frame's settings: Default's until you untick Use default settings."] = "此框架的設定：在你取消勾選「使用預設設定」之前依照「預設」。"
L["This game version has none of these settings."] = "此遊戲版本沒有這些設定。"
L["This group's settings: Default's until you untick Use default settings."] = "此群組的設定：在你取消勾選「使用預設設定」之前依照「預設」。"
L["This is from a newer Cinematic: update it to add this one."] = "這來自較新版本的 Cinematic：請更新後再加入。"
L["This page's shared settings back on General."] = "此頁面的共用設定改回依照「一般」。"
L["This row fits everywhere. The rest of the row keeps its ticks for when you untick this."] = "此列到處都符合。該列其餘部分保留其勾選，供你取消勾選此項時使用。"
L["This row's camera may start anywhere. The rest of the row keeps its ticks for when you untick this."] = "此列的鏡頭可在任何地方啟動。該列其餘部分保留其勾選，供你取消勾選此項時使用。"
L["This row's camera waits until the Calm Timer (CineMode page) has run out after a fight."] = "此列的鏡頭會等到戰鬥後的平靜計時（CineMode 頁面）結束後才啟動。"
L["This row: just the enemies among them."] = "此列：只限其中的敵方。"
L["This row: just the friendly ones among them."] = "此列：只限其中的友方。"
L["This row: just the neutral ones among them."] = "此列：只限其中的中立。"
L["This row: just these among them: %s."] = "此列：只限其中的這些：%s。"
L["This row: just those about that far from you. 11 and 28 yards are the game's interact distances; 40 asks a 40-yard spell on your action bars (harmful for enemies, helpful for friends), and with none there the row fits no unit past 28 yards."] = "此列：只限距離你大約那麼遠的單位。11 與 28 碼是遊戲的互動距離；40 碼需要你的快捷列上有一個 40 碼的法術（對敵人為傷害法術，對友方為輔助法術），若沒有，此列不會符合 28 碼以外的任何單位。"
L["This sound's volume, next to the others."] = "此音效的音量，相對於其他音效。"
L["This swing bar isn't in use"] = "此揮擊計時條未使用中"
L["This tab's rules as they come: a sound as any other fight starts and one as it ends."] = "此分頁規則的原始狀態：其他戰鬥開始時一個音效，結束時一個音效。"
L["This tab's rules as they come: a war horn as a boss is pulled; a kill and a wipe, no sound yet."] = "此分頁規則的原始狀態：拉到首領時吹響戰號；擊殺與滅團目前沒有音效。"
L["This tab's rules as they come: one for each time of day, a rooster at dawn, a horse in the morning, your faction's bell at midday, frogs in the evening, an owl at dusk and a wolf at night."] = "此分頁規則的原始狀態：每個時段一個，黎明時公雞、早晨時馬兒、正午時你陣營的鐘聲、傍晚時青蛙、黃昏時貓頭鷹、夜晚時狼。"
L["This theme as a line of text to send a friend, who adds it with Import theme in their theme menu. Only the theme (edge, colors, sparks, heartbeat), not this page's other settings."] = "將此主題轉為一行文字傳給朋友，他們可在自己的主題選單中用「匯入主題」加入。只包含主題（邊緣、顏色、火花、心跳），不含此頁面的其他設定。"
L["This theme's heartbeat, next to the beats a minute above (slower for a creeping theme)."] = "此主題的心跳，相對於上方的每分鐘心跳數（緩慢逼近的主題會較慢）。"
L["Threat glow"] = "仇恨光暈"
L["Throb"] = "跳動"
L["Tick Enemy, Neutral or Friendly for just those of them; all of them: any."] = "勾選敵方、中立或友方則只限其中那些；全部：任何。"
L["Ticked, \"#2 of 5\". Unticked, just \"#2\"."] = "勾選時顯示「#2 of 5」。未勾選時只顯示「#2」。"
L["Ticked, a bright spark at the edge of the filled part."] = "勾選時，在已填滿部分的邊緣顯示明亮的火花。"
L["Ticked, a crown pops in as you take #1."] = "勾選時，你拿下第 1 名時會跳出王冠。"
L["Ticked, how you did on that boss as it dies."] = "勾選時，在該首領死亡時顯示你對它的表現。"
L["Ticked, how you did on the whole run as it's done."] = "勾選時，在整場副本結束時顯示你的表現。"
L["Ticked, only while the UI is faded."] = "勾選時，只在介面淡出時。"
L["Ticked, supported addons you install later start with Always ticked: shown the whole time in CineMode. Unticked, they start hidden, except as the other columns say. (Frames you add yourself start faded either way.)"] = "勾選時，你之後安裝的支援插件起初會勾選「一律」：在 CineMode 中全程顯示。未勾選時，它們起初隱藏，除非其他欄另有設定。（你自己加入的框架無論如何起初都會淡出。）"
L["Ticked, the bars glide to each new value instead of jumping."] = "勾選時，計量條會平滑移動到每個新數值，而不是跳過去。"
L["Ticked, the name of the one you race, in their class's color."] = "勾選時，以其職業顏色顯示你競賽對手的名稱。"
L["Ticked, the wind comes and goes in gusts every few seconds. Unticked, it blows steadily."] = "勾選時，風每隔幾秒一陣一陣地吹。未勾選時穩定地吹。"
L["Ticked, the wind drops while you're in a fight."] = "勾選時，你在戰鬥中風會停止。"
L["Ticked, your damage (or healing) so far."] = "勾選時，顯示你目前的傷害（或治療）。"
L["On the rows:"] = "列上顯示："
L["Ticked, each player's name on their row."] = "勾選時，在每列顯示該玩家的名稱。"
L["Ticked, your place over it (#2)."] = "勾選時，在其上方顯示你的名次（#2）。"
L["Ticked: party frames shown raid-style (the game's Use Raid-Style Party Frames, in Edit Mode) fade as the Raid tab's rows say. Untick it to give them rows of their own."] = "勾選：以團隊樣式顯示的隊伍框架（遊戲的「使用團隊樣式隊伍框架」，在編輯模式中）依團隊分頁各列的設定淡出。取消勾選可給它們自己的列。"
L["Ticked: the spells with no cooldown you haven't set yourself go by what they cost, until you set their group's mode: When ready with Resources if they spend a resource you build up (like Maelstrom), else When it procs (like Lightning Bolt). Spells with a cooldown or charges go by their group's setting. It also turns on Flash for Utility Cooldowns, until you set that group's Flash. Unticked: every spell you haven't set yourself goes by its group's setting."] = "勾選：你沒有自行設定的無冷卻法術會依其消耗判斷，直到你設定其群組的模式：若它們消耗你累積的資源（如漩渦），則為「就緒時」並計入資源，否則為「觸發時」（如閃電箭）。有冷卻或充能次數的法術依其群組的設定。它也會為「輔助冷卻」開啟閃光，直到你設定該群組的閃光。未勾選：你沒有自行設定的每個法術都依其群組的設定。"
L["Ticked: these cast bars look as the Default tab says. Unticked: as the settings below say (they start as Default's, and are kept while it's ticked)."] = "勾選：這些施法條依「預設」分頁的設定呈現。未勾選：依下方的設定（起初與「預設」相同，勾選期間會保留）。"
L["Ticked: these cast bars take this page's look (the Default tab's, or this tab's own). Unticked: they keep the game's own. Their size stays the game's (yours is sized in Edit Mode)."] = "勾選：這些施法條採用此頁面的外觀（「預設」分頁的，或此分頁自己的）。未勾選：保留遊戲本身的外觀。它們的大小仍為遊戲的（你的在編輯模式中調整大小）。"
L["Ticked: this card shows where its row says. Unticked: never."] = "勾選：此卡片依其列設定的地點顯示。未勾選：永不顯示。"
L["Ticked: this frame looks as the Default tab says. Unticked: as the settings below say (they start as Default's, and are kept while it's ticked)."] = "勾選：此框架依「預設」分頁的設定呈現。未勾選：依下方的設定（起初與「預設」相同，勾選期間會保留）。"
L["Ticked: this frame shows the parts the Target grid says. Untick it to give the frame choices of its own."] = "勾選：此框架顯示目標表格所設定的部分。取消勾選可讓此框架有自己的選擇。"
L["Ticked: this group looks as the Default tab says. Unticked: as the settings below say (they start as Default's, and are kept while it's ticked)."] = "勾選：此群組依「預設」分頁的設定呈現。未勾選：依下方的設定（起初與「預設」相同，勾選期間會保留）。"
L["Ticked: while no letterbox is up, the card shows in the lower third. Unticked: a bar of its own comes in for it."] = "勾選：沒有黑邊時，卡片顯示在下方三分之一處。未勾選：會為它帶入一條專屬的黑邊。"
L["Ticked: while you're this role, Heal Vision goes by the Default tab. Unticked: by the settings on this tab."] = "勾選：你擔任此職責時，Heal Vision 依「預設」分頁的設定。未勾選：依此分頁的設定。"
L["Tied: rolling again"] = "平手：重新擲骰"
L["Tighter rows and smaller text, for raids."] = "更緊密的列與更小的文字，適用於團隊。"
L["Tilt %s° down over %s s"] = "向下傾斜 %s°，耗時 %s 秒"
L["Tilt %s° up over %s s"] = "向上傾斜 %s°，耗時 %s 秒"
L["Tilt 0° (no tilt)"] = "傾斜 0°（不傾斜）"
L["Tilt down to"] = "向下傾斜至"
L["Tilt to %s° give or take %s/%s over %s s"] = "傾斜至 %s°，上下浮動 %s/%s，耗時 %s 秒"
L["Tilt up to"] = "向上傾斜至"
L["Time"] = "時間"
L["Time left"] = "剩餘時間"
L["Time played"] = "遊戲時間"
L["Times the addon's busy parts as you play, for as long as is picked beside it. It starts when you close the settings (or right away, with Start now), and the results show here. Click it again to stop."] = "在你遊戲時為插件的忙碌部分計時，持續時間依旁邊的選擇。它在你關閉設定時開始（或用「立即開始」馬上開始），結果會顯示在此。再次點擊即可停止。"
L["Timing and extras"] = "時機與額外選項"
L["Title card"] = "標題卡"
L["To fade something else, use the Find frames tab: search by name, pick frames by hovering, or let Smart Find look for them. Or hover over a frame and type |cffffd100/cine add|r. Frames you add are listed under their addon, with the same columns; the X takes one off the list."] = "若要淡出其他東西，請使用尋找框架分頁：依名稱搜尋、以滑鼠指向選取框架，或讓「智慧尋找」幫你找。或將滑鼠移到框架上並輸入 |cffffd100/cine add|r。你加入的框架會列在其插件之下，使用相同的欄位；X 可將它從清單中移除。"
L["Today, %s"] = "今天，%s"
L["Together (empty: pick it and add steps)"] = "同時（空的：選擇它並加入步驟）"
L["Together: these at once"] = "同時：這些一起執行"
L["Toggle Duel Vision"] = "切換 Duel Vision"
L["Toggle Heal Vision"] = "切換 Heal Vision"
L["Toggle Quest Vision"] = "切換 Quest Vision"
L["Toggle Roll Vision"] = "切換 Roll Vision"
L["Toggle Vitals Vision"] = "切換 Vitals Vision"
L["Tooltip"] = "滑鼠提示"
L["Tooltip: %s"] = "滑鼠提示：%s"
L["Tooltips show all through CineMode. (The other columns then have nothing to add.)"] = "滑鼠提示在 CineMode 期間全程顯示。（其他欄便沒有什麼可補充的了。）"
L["Top"] = "頂部"
L["Top letterbox bar"] = "頂部黑邊"
L["Top speed in the middle of a sweep. At 6°/sec with 50% ease, a 30° sweep takes 10 seconds."] = "環繞中段的最高速度。在 6°/秒、50% 緩動時，30° 的環繞需要 10 秒。"
L["Tracked Bars"] = "追蹤的計量條"
L["Tracked Buffs"] = "追蹤的增益"
L["Tracked buffs and bars: Always, In combat, Out of combat or Hidden (the game keeps your buffs secret in fights, so they go by that alone). Each group has a tab of its own."] = "追蹤的增益與計量條：一律、戰鬥中、非戰鬥中或隱藏（遊戲在戰鬥中會隱藏你的增益資訊，所以只依此判斷）。每個群組都有自己的分頁。"
L["Tracking a quest"] = "追蹤任務中"
L["Tracking button"] = "追蹤按鈕"
L["Tracking in"] = "追蹤於"
L["Transmog"] = "塑形"
L["Triggers"] = "觸發條件"
L["Triggers: %s"] = "觸發條件：%s"
L["Trying %s. Close this window to keep it."] = "正在試用 %s。關閉此視窗即可保留。"
L["Turn %d°   Tilt %d°   Zoom %s yd   %s / %s s"] = "轉向 %d°   傾斜 %d°   縮放 %s 碼   %s / %s 秒"
L["Turn %s° toward where you clicked them over %s s"] = "朝你點擊對方的那一側轉 %s°，耗時 %s 秒"
L["Turn each move"] = "每次移動的轉向"
L["Turn it on to see and change its settings."] = "開啟它即可查看並變更其設定。"
L["Turn off"] = "關閉"
L["Turn on"] = "開啟"
L["Turn on %s"] = "開啟%s"
L["Turn on the Profiler page and record a while of your usual play (a fight too), then click Copy report there and send it with your bug report."] = "開啟效能分析器頁面並記錄一段你平常的遊戲過程（包括一場戰鬥），然後在那裡點「複製報告」，連同你的錯誤回報一起傳送。"
L["Turn on the loot roll window first."] = "請先開啟拾取擲骰視窗。"
L["Turn around behind you over %s s"] = "轉到你身後，耗時 %s 秒"
L["Turn to face you before the cast ends"] = "在施法結束前轉過來面對你"
L["Turn to face you over %s s"] = "轉過來面對你，耗時 %s 秒"
L["Turning it on, and which rolls it shows."] = "開啟它，以及它顯示哪些擲骰。"
L["Turning it on, the moments a card shows for and each one's emotes."] = "開啟它、會顯示卡片的時刻，以及每個時刻的表情動作。"
L["Turning it on, when it shows and what it counts."] = "開啟它、何時顯示，以及它計算什麼。"
L["Turns Duel Vision on or off."] = "開啟或關閉 Duel Vision。"
L["Turns Heal Vision on or off (its Enable Page switch), in a fight too: off, the party and raid frames all show again."] = "開啟或關閉 Heal Vision（其「啟用頁面」開關），戰鬥中也可以：關閉時，隊伍與團隊框架會全部重新顯示。"
L["Turns Quest Vision on or off (its Enable Page switch)."] = "開啟或關閉 Quest Vision（其「啟用頁面」開關）。"
L["Turns Roll Vision on or off."] = "開啟或關閉 Roll Vision。"
L["Turns Vitals Vision on or off (its Enable Page switch)."] = "開啟或關閉 Vitals Vision（其「啟用頁面」開關）。"
L["Turns a minute at full (half that as it starts). Below 0: the other way."] = "全滿時每分鐘的轉數（開始時為一半）。低於 0：反方向。"
L["Turns the Tooltips page on or off (its Enable Page switch)."] = "開啟或關閉滑鼠提示頁面（其「啟用頁面」開關）。"
L["Turns the visual effects on or off (their Enable Visual Effects switch): the letterbox, tint, vignette, weather and the rest."] = "開啟或關閉視覺效果（其「啟用視覺效果」開關）：黑邊、色調、暗角、天氣等。"
L["Turns the whole Atmosphere hub on or off at once: the letterbox, tint, time of day, zone tints, vignette, inn glow, weather, depth of field, Graphics+ and Audio. Each keeps its own settings for when you turn this back on."] = "一次開啟或關閉整個「氛圍」分類：黑邊、色調、時段、區域色調、暗角、旅店光暈、天氣、景深、Graphics+ 與音效。各項保留自己的設定，供你重新開啟時使用。"
L["Turns this group on or off. While it's off it's kept as it is, but its frames come up on their own (or with their other groups), and its events don't bring it up."] = "開啟或關閉此群組。關閉期間它會維持原狀，但其框架會自行出現（或隨其所屬的其他群組出現），其事件也不會讓它出現。"
L["Twinkling stars"] = "閃爍的星星"
L["Type"] = "類型"
L["Type part of a frame's name or of the addon that made it. Hover over a match to see it marked on screen, click it to put it on the list below, to add. Only other addons' frames that aren't faded yet are listed."] = "輸入框架名稱或建立它之插件名稱的一部分。將滑鼠移到符合項目上可在畫面上看到它被標示，點擊即可放入下方清單供你加入。只會列出尚未淡出的其他插件框架。"
L["Type part of a name to see the icons it matches: any spell, the items you carry and wear, mounts, or an icon's file name such as INV_Misc_Bag_07. Enter picks the first."] = "輸入名稱的一部分，即可看到符合的圖示：任何法術、你攜帶與穿戴的物品、坐騎，或圖示的檔名，例如 INV_Misc_Bag_07。按 Enter 選擇第一個。"
L["Type part of an icon's name to see the ones it matches, such as bang, turnin or speak. Enter picks the first."] = "輸入圖示名稱的一部分，即可看到符合的圖示，例如 bang、turnin 或 speak。按 Enter 選擇第一個。"
L["Typewriter"] = "打字機"
L["Typing brings up the chat window any time. (The other columns then have nothing to add.)"] = "輸入文字時隨時都會叫出聊天視窗。（其他欄便沒有什麼可補充的了。）"
L["Ultra immersive"] = "極致沉浸"
L["Uncommon and up"] = "優秀以上"
L["Under it"] = "其下方"
L["Under the indicator, while you cast: your mana's numbers on the bar show what you'll have once the cast is done, paler. The amount and the percent, whichever the game shows there (its Status Text setting); with the game's numbers off, the amount in the middle of the bar."] = "在指示下方，施法時：計量條上你的法力數字會以較淡的顏色顯示施法完成後你將剩下的法力。數值與百分比，依遊戲在那裡顯示的內容（其「狀態文字」設定）；若遊戲的數字關閉，則在計量條中央顯示數值。"
L["Under the name, what the game says of the place: Contested Territory, Sanctuary, Alliance or Horde Territory..."] = "名稱下方顯示遊戲對該地點的描述：爭奪中的領土、安全區域、聯盟或部落領土……"
L["Under the tooltip, where the game puts it."] = "在滑鼠提示下方，遊戲放置它的位置。"
L["Under the words: their color, lighter. Over them: a pale gray."] = "文字下方：其顏色，較淺。文字上方：淡灰色。"
L["Under the zone name"] = "在區域名稱下方"
L["Underline"] = "底線"
L["Undo"] = "復原"
L["Undo pending changes"] = "復原待處理的變更"
L["Unit Name"] = "單位名稱"
L["Unit frame"] = "單位框架"
L["Units"] = "單位"
L["Unloaded"] = "未載入"
L["Untick to leave the camera running when this happens. Moving the camera yourself still takes over: it carries on a second after you let go."] = "取消勾選則在此情況發生時讓鏡頭繼續運作。你自己移動鏡頭仍會接管：放開後一秒它會繼續。"
L["Until %s s before landing"] = "直到降落前 %s 秒"
L["Until %s s go by"] = "直到經過 %s 秒"
L["Until someone new talks"] = "直到有新的人說話"
L["Until the cast ends"] = "直到施法結束"
L["Until the cast is %s s from done"] = "直到施法剩 %s 秒完成"
L["Until you're back to life"] = "直到你復活"
L["Use General"] = "使用一般"
L["Use Visions Style"] = "使用 Visions 樣式"
L["Use default settings"] = "使用預設設定"
L["Use the camera's own numbers"] = "使用鏡頭本身的數值"
L["Use the quest item"] = "使用任務物品"
L["Use this row. Unticked, its trigger passes it over: the next row for it is tried, and with none it starts no camera. Its settings stay for when you tick it again."] = "使用此列。未勾選時，其觸發條件會略過它：改為嘗試它的下一列，若沒有則不啟動任何鏡頭。其設定會保留，供你再次勾選時使用。"
L["Used by: %s"] = "使用者：%s"
L["Uses the item on Quest Vision's quest item button, while it shows."] = "在 Quest Vision 的任務物品按鈕顯示時，使用其上的物品。"
L["Usual order"] = "一般順序"
L["Utility"] = "輔助"
L["Utility Cooldowns"] = "輔助冷卻"
L["Utility: stay up while a cooldown is recharging"] = "輔助：冷卻充能中時保持顯示"
L["Version %s, %d settings changed"] = "版本 %s，%d 項設定已變更"
L["Victory"] = "勝利"
L["View distance"] = "視野距離"
L["Vision"] = "Vision"
L["Vision wheel"] = "Vision 輪盤"
L["Visions"] = "Visions"
L["Visions Style"] = "Visions 樣式"
L["Visions in use"] = "使用中的 Vision"
L["Vitals Vision"] = "Vitals Vision"
L["Vitals Vision demo stopped."] = "Vitals Vision 示範已停止。"
L["Vitals Vision demo: a new theme every %s seconds (/cine vital demo to stop)."] = "Vitals Vision 示範：每 %s 秒換一個新主題（輸入 /cine vital demo 即可停止）。"
L["Vitals Vision demo: all %d shown."] = "Vitals Vision 示範：%d 個全部已顯示。"
L["Vitals Vision demo: no class called \"%s\"."] = "Vitals Vision 示範：沒有名為「%s」的職業。"
L["Vitals Vision shows it as far as your health says"] = "Vitals Vision 依你的生命值顯示它"
L["Vitals Vision test done."] = "Vitals Vision 測試完成。"
L["Voice chat speakers"] = "語音聊天說話者"
L["W"] = "W"
L["Wait"] = "等待"
L["Wait %s s"] = "等待 %s 秒"
L["Wait %s sec"] = "等待 %s 秒"
L["Wait %s to %s s"] = "等待 %s 到 %s 秒"
L["Wait before starting"] = "開始前的等待"
L["Wait for boss fights to end"] = "等待首領戰結束"
L["Wait for the Calm Timer"] = "等待平靜計時"
L["Wait till after"] = "等到之後"
L["Wait to the side"] = "在一旁等待"
L["Warsong Gulch"] = "戰歌峽谷"
L["What blows: Auto picks your class and spec's (the same as Vitals Vision's theme), or pick any, or plain wind or motes of light."] = "吹的是什麼：「自動」會選擇你職業與專精的（與 Vitals Vision 的主題相同），或任選一個，或普通的風或光點。"
L["What cuts the pattern to an edge, so it stays around the screen's sides. None: the pattern over all of the screen (an edge already, like the red one, needs none)."] = "將圖樣裁切成邊緣的方式，讓它保持在畫面四周。無：圖樣覆蓋整個畫面（本身已是邊緣的，例如紅色那種，不需要）。"
L["What each row of frames is doing right now, and the settings behind it. Click a row for all its reasons. To ask about one frame on the screen, pick it in game (or type /cine why)."] = "每一列框架目前的狀態，以及其背後的設定。點擊某列可查看其所有原因。若要詢問畫面上的某個框架，請在遊戲中選取它（或輸入 /cine why）。"
L["What happens when you move the camera, a fight starts, you walk, you zoom or its trigger ends; and its edge haze and Stop button while it runs."] = "當你移動鏡頭、戰鬥開始、你行走、你縮放或其觸發條件結束時會發生什麼；以及它運作時的邊緣朦朧與停止按鈕。"
L["What it counts"] = "它計算什麼"
L["What it is: motes of light floating up, stars twinkling, lightning flickering, gas drifting in over the edges, motes spiraling in the way the swirl turns, or stars circling the middle. None: not there."] = "它是什麼：向上飄浮的光點、閃爍的星星、閃動的閃電、從邊緣飄入的氣體、順著漩渦方向螺旋湧入的光點，或環繞中央的星星。無：沒有。"
L["What it is: wispy spiral arms (added on as light), clouds wound into a whirlpool, or a portal's glowing rim closing in around you. None: not there."] = "它是什麼：纖細的螺旋臂（以光線方式加上）、捲成漩渦的雲霧，或在你周圍收攏的傳送門發光邊緣。無：沒有。"
L["What picking it does: a slash command, such as /rw Pull in 10, or several, a line each (anything a macro can do). The game cuts a line at 255 letters."] = "選擇它時會做什麼：一個斜線指令，例如 /rw Pull in 10，或多個指令，每行一個（巨集能做的任何事）。遊戲會在 255 個字元處截斷一行。"
L["What shows of mobs and NPCs you still need for a quest objective (a mob to kill, an NPC to talk to), whatever the Nameplates page's grids say; tick any. Nameplate: their whole nameplates. Name: their names, on their nameplates. Quest mark: a golden ! added to the nameplate or name shown, else the ! alone. These three in CineMode, in fights and out, and need the Nameplates page enabled; once the objective is done, they fade with the rest. Unit frame: the same mark beside your target frame's health bar while your target is one of them, in CineMode and out. None ticked: as the Nameplates page's settings say."] = "你在任務目標中仍需要的怪物與 NPC（要擊殺的怪物、要對話的 NPC）顯示哪些部分，不論名條頁面的表格怎麼設定；可任意勾選。名條：其完整名條。名稱：其名條上的名稱。任務標記：在顯示的名條或名稱上加上金色 !，否則只顯示 !。這三項適用於 CineMode 中、戰鬥中及戰鬥外，且需要啟用名條頁面；目標完成後，它們會隨其餘部分淡出。單位框架：當你的目標是其中之一時，在你目標框架的生命條旁顯示同樣的標記，CineMode 中及之外皆然。都未勾選：依名條頁面的設定。"
L["What the addon's timers measured: ms a frame, and its share of the frame."] = "插件計時器測得的數據：每幀毫秒，以及其佔每幀的比例。"
L["What the bubble and card do while the camera moves: the quest camera's swing, zoom and turn (its drift is Hold the camera still's), or you turning it. Follow: they stay over the NPC's nameplate, sliding with it. Fade out: they fade out, and back in over the NPC once it's still. Dim: they fade down, still readable. Wait to the side: they stay still where Default would put them, and fade over to the NPC once the camera's still."] = "鏡頭移動時泡泡與卡片的行為：任務鏡頭的轉向、縮放與轉身（其飄移屬於「保持鏡頭靜止」），或你自己轉動鏡頭。跟隨：它們保持在 NPC 名條上方，隨之滑動。淡出：它們淡出，待鏡頭靜止後在 NPC 上方淡入。暗淡：它們變淡，但仍可閱讀。在一旁等待：它們停在「預設」會放置的位置不動，待鏡頭靜止後淡移到 NPC 那裡。"
L["What the game measured for Cinematic meanwhile, the timers' parts and all the rest."] = "在此期間遊戲為 Cinematic 測得的數據，包括計時器的部分及其餘所有部分。"
L["What this card does if it comes while you're in a fight, or in the 5 seconds after one."] = "若此卡片在你戰鬥中或戰鬥後 5 秒內出現時，它會怎麼做。"
L["What this card plays as it shows."] = "此卡片顯示時播放的內容。"
L["What's new"] = "新功能"
L["What's new in Cinematic, newest first. Show me opens the page a feature is on. Every change, fixes too, is on the All changes page."] = "Cinematic 的新功能，最新的在前。「給我看」會開啟該功能所在的頁面。所有變更（包括修正）都在「所有變更」頁面。"
L["What's this card's alone: when it shows, the lines with its name, its words. How it looks: the Style tab."] = "此卡片專屬的設定：何時顯示、包含其名稱的行、其文字。外觀：樣式分頁。"
L["Whatever style that event starts from."] = "該事件起始的任何樣式。"
L["Wheels"] = "輪盤"
L["Wheels on it"] = "其上的輪盤"
L["When"] = "符合時機"
L["When all a quest giver has to offer or take in is daily or weekly quests, the camera stays as it is."] = "當任務 NPC 能提供或接收的都只是每日或每週任務時，鏡頭保持不變。"
L["When it blows"] = "何時吹"
L["When it ends"] = "結束時"
L["When it ends: nothing, it stays where it is"] = "結束時：不做任何事，停在原處"
L["When it procs"] = "觸發時"
L["When it's ready"] = "就緒時"
L["When its camera stops. Moving always stops it too, as it does every camera that runs while you stand still. It ends: when the trigger that started it ends (the cast, the buff, leaving the place)."] = "在其鏡頭停止時。移動也一定會停止它，就像所有在你站著不動時運作的鏡頭一樣。它結束：在啟動它的觸發條件結束時（施法、增益、離開該地點）。"
L["When ready"] = "就緒時"
L["When someone does something for you or at you, a small card shows who it was, with a few emotes to answer in one click. It waits out fights and fades away by itself. Pick the moments and their emotes below. When it shows: the Settings tab. Its style and look: the Look tab."] = "當有人為你或對你做了某件事時，會出現一張小卡片顯示是誰，附上幾個可一鍵回應的表情動作。它會等戰鬥結束，並自行淡出。在下方選擇時刻及其表情動作。何時顯示：設定分頁。樣式與外觀：外觀分頁。"
L["When someone talks out of sight (behind you, say), the camera turns around, a full turn at most, until their chat bubble shows, then frames them. If they're nowhere to be seen, it ends up back where it was."] = "當有人在視野外說話時（例如在你身後），鏡頭會轉過去，最多轉一整圈，直到看見他們的對話泡泡，然後將他們納入畫面。若到處都看不到他們，鏡頭會回到原位。"
L["When the cards show and for how long. The moments and their emotes: the Vision tab. Its look: the Look tab."] = "卡片何時顯示及顯示多久。時刻及其表情動作：Vision 分頁。外觀：外觀分頁。"
L["When the cards show, and for how long."] = "卡片何時顯示，以及顯示多久。"
L["When the edges close in, the health bars and how fast."] = "邊緣何時收攏、生命條，以及速度。"
L["When the release popup offers a way to come back yourself (a soulstone, Reincarnation, an ankh...), there's no death camera: you keep your own view to pick your moment."] = "當釋放靈魂視窗提供你自行復活的方式時（靈魂石、復生、十字章……），不會啟動死亡鏡頭：你會保持自己的視角，選擇你的時機。"
L["When this buff's icon or bar shows. The game keeps your buffs secret in fights, so these go by whether you're in one."] = "此增益的圖示或計量條何時顯示。遊戲在戰鬥中會隱藏你的增益資訊，所以這些只依你是否在戰鬥中判斷。"
L["When this group works: any time, only out of combat or only in combat. Click to change. The rest of the time its frames come up on their own (or with their other groups), and its events don't bring it up."] = "此群組何時運作：任何時候、僅非戰鬥中或僅戰鬥中。點擊變更。其他時候，其框架會自行出現（或隨其所屬的其他群組出現），其事件也不會讓它出現。"
L["When this rule fits. Click to write it in the rule editor; empty: any fight."] = "此規則何時符合。點擊可在規則編輯器中撰寫；留空：任何戰鬥。"
L["When this rule fits. Click to write it in the rule editor; empty: any time."] = "此規則何時符合。點擊可在規則編輯器中撰寫；留空：任何時候。"
L["When this spell's icon shows in the Cooldown Manager."] = "此法術的圖示何時在冷卻管理器中顯示。"
L["When you die, the camera turns slowly round your body until you release or are resurrected. CineMode stays on (straight away), with the release button (and any soulstone or Reincarnation button) still showing."] = "你死亡時，鏡頭會繞著你的屍體緩緩旋轉，直到你釋放靈魂或被復活。CineMode 保持開啟（立即），釋放靈魂按鈕（以及任何靈魂石或復生按鈕）仍會顯示。"
L["When you turn left or right, the camera doesn't snap round with you: it carries on as it was (sway and all) until you stop turning, then glides gently around to your new facing, easing in and out. Dragging with either mouse button hands the camera straight back to you."] = "你向左或向右轉時，鏡頭不會立即跟著你轉：它會照原樣繼續（包括擺動），直到你停止轉向，然後平緩地轉到你的新面向，含緩入與緩出。用任一滑鼠按鍵拖曳都會立即將鏡頭交還給你。"
L["Where"] = "地點"
L["Where and when each effect shows in CineMode. Always: everywhere. Combat: In combat, Calm Timer (after a fight, till it's run out), Out of combat (the rest of the time), In a camera mode (flights, AFK, cozy and the rest). Location: the places. Nothing ticked: it's off."] = "每個效果在 CineMode 中於何處、何時顯示。一律：到處。戰鬥：戰鬥中、平靜計時（戰鬥後，直到結束）、非戰鬥中（其餘時間）、在鏡頭模式中（飛行、暫離、悠閒等）。位置：各地點。都未勾選：關閉。"
L["Where and when each kind of bubble shows. Always: everywhere. Nothing ticked: never."] = "每種泡泡在何處、何時顯示。一律：到處。都未勾選：永不。"
L["Where and when music can play in CineMode; anywhere else it fades out (your own game music too) and back in after. Always: everywhere. Out of combat: back once the Calm Timer has run out after a fight (with Calm Timer too: as soon as the fight ends)."] = "音樂在 CineMode 中可於何處、何時播放；在其他地方會淡出（包括你自己的遊戲音樂），之後再淡入。一律：到處。非戰鬥中：在戰鬥後的平靜計時結束後恢復（同時勾選平靜計時：戰鬥一結束就恢復）。"
L["Where chat bubbles show. How they look: the Style hub's Chat bubbles page."] = "對話泡泡在哪裡顯示。外觀：「風格」分類的對話泡泡頁面。"
L["Where in the letterbox bar the card sits."] = "卡片在黑邊中的位置。"
L["Where it comes when other scenes are on at the same time: the first one on in this order plays. Going AFK while doing an emote is the AFK scene, say."] = "當其他場景同時成立時它的順序：依此順序第一個成立的會播放。例如做表情動作時暫離，就是暫離場景。"
L["Where the bubble goes. Over the head: over the NPC's nameplate, following them on the screen. Default: above the middle of the screen, or wherever you drag it. Opposite clicked: wherever you drag it, but when you clicked the NPC on that half of the screen, at the same spot on the other half (they stand where you clicked, so that half is clearer), the quest card beside it. With nobody to stand over or no click (a quest from an item, or the interact key), it goes where Default would."] = "泡泡的位置。頭上：在 NPC 名條上方，隨其在畫面上移動。預設：畫面中央上方，或你拖曳到的任何位置。點擊的對側：你拖曳到的位置，但若你在畫面某一半點擊 NPC，則放在另一半的相同位置（他們站在你點擊的地方，所以那一半較清楚），任務卡片在旁邊。若沒有可站在其上方的對象或沒有點擊（來自物品的任務，或互動鍵），則放在「預設」的位置。"
L["Where the card shows: in the middle of the screen, in a letterbox bar or in the lower third. (A banner goes across the middle.)"] = "卡片顯示的位置：畫面中央、黑邊中或下方三分之一處。（橫幅橫跨中央。）"
L["Where the tail sits along the bubble: 0 at its left end, 50 in the middle, 100 at its right end."] = "尾巴沿著泡泡的位置：0 在左端，50 在中央，100 在右端。"
L["Where the zoom ends as the cast does, if you're further out. Closer already, it stays where it is. Arriving, the camera is back at your own distance."] = "若你距離較遠，施法結束時縮放停止的位置。若已經更近，則保持不動。抵達時，鏡頭會回到你自己的距離。"
L["Where this row's camera may start (Grouped: in a party or raid). Anywhere else the next row of its trigger is tried, and with none the camera doesn't start (or stops if it's running). For flights, Cities means taking off from one, and Open world taking off anywhere else."] = "此列的鏡頭可以在哪裡啟動（組隊時：在隊伍或團隊中）。在其他地方會嘗試其觸發條件的下一列，若沒有則鏡頭不會啟動（若正在運作則會停止）。就飛行而言，「主城」指從主城起飛，「開放世界」指從其他任何地方起飛。"
L["Where to find Cinematic outside the game. Click a link and press Ctrl+C to copy it, then paste it into your browser."] = "在遊戲外哪裡可以找到 Cinematic。點擊連結並按 Ctrl+C 複製，然後貼到你的瀏覽器中。"
L["Where your damage came from"] = "你的傷害來源"
L["Where your extra ability button goes (the extra abilities frame's place in Edit Mode), a big button with the item the nearest tracked quest gives you to use, the one in the quest tracker. Click it or press its key (Keybinds page). Shows near the quest's area, beside the game's own button when that's up. It can't show, hide or move in a fight: it stays as it was until the fight ends."] = "你額外技能按鈕的位置（編輯模式中額外技能框架的位置），一個大按鈕，上面是最近追蹤任務給你使用的物品，也就是任務追蹤中的那個。點擊它或按其按鍵（按鍵設定頁面）。在任務區域附近顯示，若遊戲本身的按鈕出現則在其旁邊。戰鬥中無法顯示、隱藏或移動：它會維持原狀直到戰鬥結束。"
L["Where your healing came from"] = "你的治療來源"
L["Whether this row's camera may start in a fight (unticked, one running stops when a fight starts), and whether it waits for things to calm down after one."] = "此列的鏡頭是否可在戰鬥中啟動（未勾選時，運作中的鏡頭會在戰鬥開始時停止），以及戰鬥後是否等待局勢平靜。"
L["Whether you won or lost (or someone fled) as the duel ends."] = "決鬥結束時顯示你贏了或輸了（或有人逃跑）。"
L["Which Visions follow this page. One with a setting of its own shows which; Use Visions Style puts them all back on this page. The name opens its page."] = "哪些 Vision 依照此頁面。有自己設定的 Vision 會顯示是哪些；「使用 Visions 樣式」會讓它們全部改回依照此頁面。點擊名稱可開啟其頁面。"
L["Which addons the table shows: tick the ones to compare, or All addons for every one."] = "表格顯示哪些插件：勾選要比較的插件，或選「所有插件」顯示全部。"
L["Which edge they start from."] = "它們從哪個邊緣開始。"
L["Which items"] = "哪些物品"
L["Which of them, ticks. Aggro: who the enemy's attacking, You or Not you (someone friendly: a group member, a pet or another player), and their role, Tank, Healer or DPS (no role set counts as DPS; a pet only with all three ticked). Units: any of Normal NPC, Elite NPC (elite, rare elite and bosses), Players, and Minions (their pets, totems and guardians); all four, any unit."] = "其中哪些，以勾選設定。仇恨：敵人正在攻擊誰，你或不是你（友方對象：隊伍成員、寵物或其他玩家），以及其職責，坦克、治療者或傷害輸出（未設定職責算作傷害輸出；寵物只有在三種都勾選時才算）。單位：普通 NPC、精英 NPC（精英、稀有精英與首領）、玩家，以及僕從（他們的寵物、圖騰與守護者）中的任何一種；四種都勾選，即任何單位。"
L["Which one. Key bindings are set in the game's Key Bindings, under Cinematic."] = "哪一個。按鍵設定在遊戲的「按鍵設定」中，位於 Cinematic 之下。"
L["Which pages follow General. A page with a setting of its own shows which; Use General puts them all back on General. The page's name opens it."] = "哪些頁面依照「一般」。有自己設定的頁面會顯示是哪些；「使用一般」會讓它們全部改回依照「一般」。點擊頁面名稱可開啟它。"
L["Which parts of the player, target, focus and pet frames show. Keeping a frame up, always or in fights, is on the Game Frames page; your own while you recover, on the Resource Display page."] = "玩家、目標、專注目標與寵物框架顯示哪些部分。要讓框架一直顯示或在戰鬥中顯示，請到遊戲框架頁面；你在恢復期間的框架，請到資源顯示頁面。"
L["Which parts of the unit frames show, CineMode or not: your own frame and your pet's, and the target, focus and target of target frames. Pick a frame's tab to see its grid: the focus and target of target go as the target's grid says until you untick Same as target. Untick parts to keep just the bars. The frame art is the portrait ring, the name box and the bars' borders: the game draws them as one picture. Icons are the rest Zzz, the group leader's crown, role and quest icons, and the raid marker (skull, moon...) on the target and focus frames. Auras are the buffs and debuffs on the target and focus frames. Hit text is the damage and healing numbers on your and your pet's portraits. Threat is the threat percentage and aggro glow on the target and focus frames, for NPCs you can fight."] = "單位框架顯示哪些部分，無論是否處於 CineMode：你自己的框架與寵物的框架，以及目標、專注目標與目標的目標框架。選擇框架的分頁即可看到其表格：在你取消勾選「與目標相同」之前，專注目標與目標的目標依照目標的表格。取消勾選部分可只保留計量條。框架美術圖是頭像外圈、名稱框與計量條的邊框：遊戲將它們繪製成一張圖。圖示是休息的 Zzz、隊長的王冠、職責與任務圖示，以及目標與專注目標框架上的團隊標記（骷髏、月亮……）。光環是目標與專注目標框架上的增益與減益。命中文字是你與寵物頭像上的傷害與治療數字。仇恨是目標與專注目標框架上的仇恨百分比與仇恨光暈，適用於你可以攻擊的 NPC。"
L["Which side the camera comes round to. On your right, the quest giver is on the right of the screen. (The game doesn't tell addons where the quest giver stands, or what's around you, so it can't pick the open side.) \"Where you clicked them\": the side of the screen you clicked the quest giver on, and the camera turns toward it; talking to them with a key instead, the side is picked at random."] = "鏡頭轉到哪一側。在你的右側時，任務 NPC 在畫面右側。（遊戲不會告訴插件任務 NPC 站在哪裡，或你周圍有什麼，所以無法選擇空曠的一側。）「你點擊對方的那一側」：你在畫面上點擊任務 NPC 的那一側，鏡頭會轉向那裡；若改用按鍵與他們對話，則隨機選擇一側。"
L["Which way the lines line up: their left edges, their middles or their right edges. By where it's moved to: by which side of the screen the Move box is on."] = "各行的對齊方式：左邊緣、中央或右邊緣。依移動到的位置：依「移動」方框位於畫面的哪一側。"
L["While CineMode is on, the camera comes alive when something happens: an emote, a campfire, going AFK, your Hearthstone, fishing, a flight, a quest giver, auto-walking or dying. The Scenes page says what starts which camera; the Scripts page has each camera's steps and settings. Moving by hand cancels them all, and everything goes back to normal when the UI returns."] = "CineMode 開啟時，鏡頭會在發生某些事時動起來：表情動作、營火、暫離、你的爐石、釣魚、飛行、任務 NPC、自動行走或死亡。場景頁面說明什麼會啟動哪個鏡頭；腳本頁面有每個鏡頭的步驟與設定。手動移動會取消所有鏡頭，介面恢復顯示時一切都會恢復正常。"
L["While a quest is tracked in the quest tracker, the minimap stays up during CineMode, so you can see where to go. Untrack your quests and it fades again."] = "當任務追蹤中有追蹤的任務時，CineMode 期間小地圖會保持顯示，讓你看到該往哪裡走。取消追蹤你的任務後，它會再次淡出。"
L["While a vision is doing something (Heal Vision fading frames, a duel being watched, the roll window up...), the minimap button glows in its color. Its menu and tooltip list that vision, and the camera running, with a link to its page."] = "當某個 Vision 正在運作時（Heal Vision 淡出框架、觀看決鬥、擲骰視窗開啟……），小地圖按鈕會以其顏色發光。其選單與滑鼠提示會列出該 Vision 及正在運作的鏡頭，並附上其頁面的連結。"
L["While it runs"] = "運作期間"
L["While recharging"] = "充能中"
L["While the UI is faded, a new message briefly shows just the chat window it arrived in. Choose which messages below, and what of the window comes up with them under Chat window."] = "介面淡出時，新訊息會短暫只顯示它所在的聊天視窗。在下方選擇哪些訊息，以及在「聊天視窗」下選擇視窗的哪些部分會隨之出現。"
L["While the camera moves"] = "鏡頭移動時"
L["While you cast a spell that costs mana, the mana it will take shows as a pale stretch at the end of your mana: what's left after the cast is the fill to its left."] = "施放消耗法力的法術時，所需的法力會以淡色區段顯示在你法力的末端：施法後剩下的是其左側的填色。"
L["While you're auto-running (the auto-run key). Pressing forward or back, or stopping, ends it; stop and stand, and the AFK camera takes over. Auto-walking counts as RP walk instead."] = "自動奔跑時（自動奔跑鍵）。按前進或後退，或停下來，會結束它；停下站著不動，暫離鏡頭就會接手。自動行走則算作 RP 漫步。"
L["While you're auto-walking (auto-run in walk mode). Walking by hand cancels the camera, as all moving by hand does. Stop and stand, and the AFK camera takes over. Walking is recognized from your speed; /cine walk shows what the addon thinks."] = "自動行走時（行走模式下的自動奔跑）。手動行走會取消鏡頭，就像所有手動移動一樣。停下站著不動，暫離鏡頭就會接手。行走是依你的速度辨識的；/cine walk 會顯示插件的判斷。"
L["While you're in a duel (or have asked for one, or been asked), other players' duels nearby don't show. Off: they show all through yours."] = "你在決鬥中（或已提出決鬥、或被邀請決鬥）時，附近其他玩家的決鬥不會顯示。關閉：在你的決鬥期間全程顯示。"
L["While you're moving the card waits, and shows once you stop (if that's within 20 seconds)."] = "你移動時卡片會等待，在你停下後顯示（若在 20 秒內）。"
L["Whirlpool clouds"] = "漩渦雲霧"
L["White"] = "白色"
L["Who it's cast at"] = "施放對象"
L["Whole run"] = "整場副本"
L["Why Is It Showing?"] = "為什麼會顯示？"
L["Why is it showing?"] = "為什麼會顯示？"
L["Width"] = "寬度"
L["Width:"] = "寬度："
L["Wind Guide"] = "風之嚮導"
L["Wind Guide can't tell which way you face here."] = "風之嚮導無法在此判斷你面對的方向。"
L["Wind Guide test done."] = "風之嚮導測試完成。"
L["Wind Guide test: blowing toward your waypoint."] = "風之嚮導測試：正朝你的路徑點吹。"
L["Wind Guide test: no waypoint, so a pretend one off to your right."] = "風之嚮導測試：沒有路徑點，所以朝你右側的假想點吹。"
L["Windows the game opens on the left (quest log, group finder, profession book and the like) open on the right instead, near the top, leaving your character in view. Two open at once still sit side by side. Narrow ones on their own (character, trade, merchant, mail) and quest givers' windows open a little in from the left edge instead, halfway up the screen, leaving the world and the quest giver in view. A window another addon has moved stays where that addon put it."] = "遊戲在左側開啟的視窗（任務日誌、隊伍搜尋器、專業技能書之類）改為在右側靠近頂端開啟，讓你的角色保持在視野中。同時開啟兩個時仍會並排。單獨開啟的窄視窗（角色、交易、商人、郵件）及任務 NPC 的視窗，改為在離左邊緣稍遠、畫面一半高度處開啟，讓世界與任務 NPC 保持在視野中。被其他插件移動過的視窗會留在該插件放置的位置。"
L["Winner"] = "贏家"
L["Winner color:"] = "贏家顏色："
L["Winner's row:"] = "贏家的列："
L["Wipe"] = "滅團"
L["With \"Start in CineMode\" off (Cinematic's main page), its camera starting brings CineMode on, and it ends with the camera."] = "關閉「以 CineMode 啟動」時（Cinematic 主頁面），其鏡頭啟動會開啟 CineMode，並隨鏡頭一起結束。"
L["With Custom dialogue frames unticked, it places the game's own gossip and quest window instead. Default: wherever you drag it (else where the game puts it). Opposite clicked: the same, but on the other half of the screen from where you clicked the NPC. Over the head isn't for a whole window (it would cover them): the game's window is left where the game puts it."] = "取消勾選「自訂對話框」時，改為放置遊戲本身的閒聊與任務視窗。預設：你拖曳到的任何位置（否則為遊戲放置的位置）。點擊的對側：相同，但放在與你點擊 NPC 處相反的另一半畫面。「頭上」不適用於整個視窗（會遮住他們）：遊戲的視窗會留在遊戲放置的位置。"
L["With Legacy"] = "含傳承"
L["With Smart set ticked, until you set a bar's mode, its spells with no cooldown go by what they cost; unticked, by their group's setting."] = "勾選「智慧設定」時，在你設定某列的模式之前，其無冷卻的法術依其消耗判斷；未勾選時，依其群組的設定。"
L["With no one talking for this long, the camera turns back and zooms back out. Moving ends it at once, leaving the camera where it is."] = "沒有人說話達這麼久時，鏡頭會轉回並拉遠。移動會立即結束它，讓鏡頭停在原處。"
L["With the UI"] = "隨介面"
L["Within 11 yards"] = "11 碼以內"
L["Within 28 yards"] = "28 碼以內"
L["Within 40 yards"] = "40 碼以內"
L["Won"] = "贏得"
L["Won:"] = "贏得："
L["Words"] = "文字"
L["Words in Russian, Korean or Chinese keep the game's font, so their letters show."] = "俄文、韓文或中文文字會保留遊戲的字型，以便正確顯示字元。"
L["Words that mark a campfire when they're in the name its tooltip shows (\"Campfire\"), separated by commas. Use words in your game language."] = "當營火滑鼠提示顯示的名稱中含有這些字詞時（「營火」），即視為營火，以逗號分隔。請使用你遊戲語言的字詞。"
L["Words:"] = "文字："
L["Worst"] = "最差"
L["Worst frame"] = "最差幀"
L["Worst ms"] = "最差毫秒"
L["X"] = "X"
L["XP bars"] = "經驗值條"
L["Y"] = "Y"
L["YOU DIED"] = "你死了"
L["YOU DIED, \"wasted\" (a picture) or words of your own."] = "「你死了」、「wasted」（圖片）或你自己的文字。"
L["Yesterday, %s"] = "昨天，%s"
L["You"] = "你"
L["You challenge"] = "你提出決鬥"
L["You challenge them to a duel"] = "你向對方提出決鬥"
L["You come back to life"] = "你復活了"
L["You earn an achievement"] = "你獲得成就"
L["You fled from %s"] = "你從 %s 面前逃跑了"
L["You have %d scenes of your own already: delete one to make another."] = "你已經有 %d 個自己的場景：刪除一個才能再建立。"
L["You have %d shots already: delete one to make another."] = "你已經有 %d 個鏡頭片段：刪除一個才能再建立。"
L["You have %d wheels already: delete one to make another."] = "你已經有 %d 個輪盤：刪除一個才能再建立。"
L["You have 30 camera scripts already: delete one to add another."] = "你已經有 30 個鏡頭腳本：刪除一個才能再加入。"
L["You haven't made a wheel yet."] = "你還沒有建立任何輪盤。"
L["You leave"] = "你離開"
L["You level up"] = "你升級了"
L["You move"] = "你移動"
L["You press its key again"] = "你再次按下其按鍵"
L["You set it to always show (Custom frames, Addon Frames page)"] = "你已設定它一律顯示（插件框架頁面的自訂框架）"
L["You turn in a quest"] = "你交付任務"
L["You were holding the key that shows tooltips"] = "你正按住顯示滑鼠提示的按鍵"
L["You're challenged"] = "你被邀請決鬥"
L["You're not on the meter"] = "你不在統計上"
L["You're not on the meter yet"] = "你還不在統計上"
L["You're typing in chat"] = "你正在聊天中輸入文字"
L["Your camera"] = "你的鏡頭"
L["Your cast bar fades out over the first 3 seconds of the cast, so you see it start, then the portal closing in is its progress. Other casts show it as usual."] = "你的施法條在施法的前 3 秒內淡出，讓你看到它開始，之後收攏的傳送門就是其進度。其他施法照常顯示施法條。"
L["Your character looks around as the camera starts turning, as if they'd spotted something. Players nearby see the emote in chat. Fly-bys you start count too."] = "鏡頭開始旋轉時，你的角色會四處張望，彷彿發現了什麼。附近的玩家會在聊天中看到此表情動作。你自己啟動的掠過鏡頭也算。"
L["Your class"] = "你的職業"
L["Your class's color, whether you lead or chase."] = "無論你領先或追趕，都使用你的職業顏色。"
L["Your class's color."] = "你的職業顏色。"
L["Your face on your dot, their class icon on theirs."] = "你的圓點上是你的臉孔，對方的圓點上是其職業圖示。"
L["Your focus."] = "你的專注目標。"
L["Your frame stays up while you recover"] = "你恢復期間你的框架保持顯示"
L["Your gear is damaged (durability alert)"] = "你的裝備已損壞（耐久度警示）"
L["Your group"] = "你的隊伍"
L["Your group kills a boss"] = "你的隊伍擊殺首領"
L["Your health at a glance, without the portrait: as it drops, the screen's edges close in, with your theme's art soaking in from them (blood, smoke, a glow in its color), a heartbeat that quickens as you weaken and a flash on big hits. Auto picks a theme for your class and spec. The death screen takes over if you die."] = "不必看頭像，一眼就能看出你的生命值：隨著它下降，畫面邊緣會向內收攏，你主題的美術圖從邊緣滲入（血液、煙霧、其顏色的光暈），心跳隨你變虛弱而加快，重擊時閃光。「自動」會為你的職業與專精選擇主題。若你死亡，死亡畫面會接手。"
L["Your health falls in hits in the preview, and on the screen as the Vitals Vision page's Test says. Close the settings to see it all."] = "你的生命值在預覽中一次次下降，在畫面上則依 Vitals Vision 頁面的「測試」呈現。關閉設定即可看到全部。"
L["Your health the edges are all the way in at (under Starts)."] = "邊緣完全收攏時你的生命值（低於「開始」）。"
L["Your health the edges start creeping in below."] = "邊緣開始漸入時你的生命值（低於此值）。"
L["Your health this bar is fully up at (under Starts)."] = "此計量條完全顯示時你的生命值（低於「開始」）。"
L["Your health this bar starts fading in below."] = "此計量條開始淡入時你的生命值（低於此值）。"
L["Your icons on it"] = "其上你的圖示"
L["Your mana under your character when it isn't your power (Elemental Shaman, Shadow Priest...): once it's on, on the Resource Display page."] = "當法力不是你的能量類型時（元素薩滿、暗影牧師……），在你角色下方顯示你的法力：開啟後，請到資源顯示頁面設定。"
L["Your own"] = "你自己的"
L["Your own color"] = "你自己的顏色"
L["Your own color for it."] = "你為它自選的顏色。"
L["Your own mix of this part's settings"] = "你自己對此部分設定的組合"
L["Your own pick and number are always on an item's panel, even when it lists only the top few players or only the best pick."] = "你自己的選擇與點數一律顯示在物品的面板上，即使它只列出前幾名玩家或只列出最佳選擇。"
L["Your own profile"] = "你自己的設定檔"
L["Your own profile. Right-click it, then Description to say what it's for."] = "你自己的設定檔。在它上面按右鍵，然後選「描述」說明它的用途。"
L["Your own settings, as they were before you picked a preset."] = "你自己的設定，即你選擇預設之前的狀態。"
L["Your own words."] = "你自己的文字。"
L["Your party uses its own frames, not raid-style ones: they follow the Unit frames page's Party tab."] = "你的隊伍使用其自身的框架，而非團隊樣式框架：它們依照單位框架頁面的隊伍分頁。"
L["Your party uses raid-style frames (Edit Mode's party frames setting): they follow the Raid frames page, not this tab."] = "你的隊伍使用團隊樣式框架（編輯模式的隊伍框架設定）：它們依照團隊框架頁面，而非此分頁。"
L["Your personal resource display (the health bar under your character) fades in as your health drops."] = "你的個人資源顯示（角色下方的生命條）會隨你的生命值下降而淡入。"
L["Your pet is unhappy"] = "你的寵物不快樂"
L["Your place"] = "你的名次"
L["Your player frame (portrait and health bar) fades in as your health drops."] = "你的玩家框架（頭像與生命條）會隨你的生命值下降而淡入。"
L["Your player frame too"] = "你的玩家框架也一樣"
L["Your player frame, pet frame and personal resource display in CineMode: kept up while you recover after a fight or run low on mana, and held back at the start of a fight until there's something to see. When they come up at all (always, in fights, in places) is their rows' on the Game Frames page."] = "CineMode 中你的玩家框架、寵物框架與個人資源顯示：在你戰鬥後恢復期間或法力不足時保持顯示，並在戰鬥開始時暫緩，直到有東西可看。它們究竟何時出現（一律、戰鬥中、特定地點）依遊戲框架頁面中其各列的設定。"
