L["Not the damage meter's numbers: your race with the player ahead of you, or your lead over #2 once you're #1. It reads the game's own damage meter, so that needs to be on (Options, Gameplay Enhancements: Enable Damage Meter). Its type and how it looks: the Look tab."] = "不是傷害統計的數字：而是你與前一名玩家的競賽，或你成為第 1 名後對第 2 名的領先。它讀取遊戲本身的傷害統計，所以需要開啟（選項 > 遊戲玩法增強：啟用傷害統計）。其類型和外觀：外觀分頁。"
L["Turning it on, when it shows, what it counts, its tests and the picked type's settings."] = "開啟、何時顯示、計算什麼、它的測試，以及所選類型的設定。"
L["%.2f yards"] = "%.2f 碼"

-- Options.lua: Reset addon (Reset Settings, Reset EVERYTHING)
L["Reset Settings puts every setting back and keeps what you made: your own profiles, cameras, scripts, themes and backups. Reset EVERYTHING deletes all of it. Either reloads the UI."] = "「重置設定」會還原所有設定，並保留你建立的內容：你自己的設定檔、鏡頭、腳本、主題和備份。「全部重置」會刪除這一切。兩者都會重新載入介面。"
L["Reset Cinematic?\n\nReset Settings: every setting goes back to how it was on install, and you start on the default profile. Nothing you made is deleted: your own profiles, cameras, scripts, themes, rules, wheels and backups stay, and so do flight times and what Cinematic has learned as you played.\n\nReset EVERYTHING: deletes all of it, as on a fresh install.\n\nEither way the UI reloads, and Cinematic's Edit Mode layouts are removed so your own comes back."] = "重置 Cinematic？\n\n重置設定：所有設定恢復到安裝時的樣子，並從預設設定檔開始。你建立的內容都不會刪除：你自己的設定檔、鏡頭、腳本、主題、規則、輪盤和備份都會保留，飛行時間和 Cinematic 在你遊玩中學到的東西也會保留。\n\n全部重置：刪除這一切，如同全新安裝。\n\n無論哪種都會重新載入介面，並移除 Cinematic 的編輯模式版面配置，讓你自己的回來。"
L["Delete everything in Cinematic? Your own profiles, cameras, scripts, themes, rules, wheels and backups are deleted for good, along with every setting. This can't be undone."] = "刪除 Cinematic 中的一切？你自己的設定檔、鏡頭、腳本、主題、規則、輪盤和備份將連同所有設定被永久刪除。此操作無法復原。"
L["Reset Settings"] = "重置設定"
L["Reset EVERYTHING"] = "全部重置"

-- ShoulderCam.lua
L["Over your shoulder wherever you are. (The other columns then have nothing to add.)"] = "無論在哪裡都越過你的肩膀。（其他欄此時沒有可添加的。）"
L["Frames follow you"] = "框架跟隨你"
L["Your cast bar and Personal Resource Display slide over to where you are on the screen, and glide back as the camera goes behind you. Edit Mode still places them: this moves them from there."] = "你的施法條和個人資源顯示會滑到你在畫面上的位置，鏡頭回到你身後時滑回。它們仍由編輯模式擺放：這只是從那裡移動它們。"
L["Follow strength"] = "跟隨強度"
L["How far they slide. Where you are on the screen is worked out from the camera, not read: if they land short of you or past you, turn this up or down."] = "它們滑動的距離。你在畫面上的位置是根據鏡頭推算的，而非讀取：如果它們沒到你或超過你，就調高或調低此項。"
L["The camera sits over your shoulder, with you to one side of the screen."] = "鏡頭位於你的肩膀上方，你在畫面的一側。"
L["On: the camera moves over your shoulder. This uses one of Blizzard's experimental camera settings: the game shows its experimental camera warning (Accept keeps it working). The game's Keep Character Centered option (Accessibility) stops it, so that's turned off meanwhile. Off: your own settings come back."] = "開啟：鏡頭移到你的肩膀上方。這會用到暴雪的一項實驗性鏡頭設定：遊戲會顯示實驗性鏡頭警告（選擇接受可保持生效）。遊戲的「保持角色置中」選項（協助工具）會阻止它，因此期間會關閉該選項。關閉：恢復你自己的設定。"
L["Shoulder"] = "肩膀"
L["Offset"] = "偏移"
L["How far to the side the camera moves. About 1 is subtle; 1.5 to 2 is a strong over-the-shoulder look."] = "鏡頭向側邊移動的距離。約 1 較為含蓄；1.5 到 2 則是明顯的過肩視角。"
L["Right shoulder"] = "右肩"
L["Left shoulder"] = "左肩"
L["Which shoulder the camera looks over. The swap key below flips it."] = "鏡頭越過哪一側肩膀。下方的切換鍵可以翻轉。"
L["Swap shoulders key"] = "切換肩膀按鍵"
L["Not during Cinematic's cameras that frame you"] = "Cinematic 以你為中心的鏡頭期間不生效"
L["On a mount the camera stays straight behind you: a big mount's head fills the shot from the side."] = "騎乘時鏡頭保持在你正後方：從側面看，大型坐騎的頭會佔滿畫面。"
L["While the standing-still, AFK, flight, fly-by or death camera runs, the camera goes back behind you, as their shots are built around you in the middle. It comes back as they end. The quest and chat cameras keep it."] = "靜止不動、暫離、飛行、飛掠或死亡鏡頭運行時，鏡頭會回到你身後，因為它們的畫面以你為中心構圖。它們結束後恢復。任務和聊天鏡頭會保留。"
L["Frames"] = "框架"
L["Pause"] = "暫停"

-- TalkingHeads.lua (its option on the Quest Vision page)
L["Talking heads"] = "對話頭像"
L["Hide repeated talking heads"] = "隱藏重複的對話頭像"
L["The game's talking head (the NPC portrait at the top of the screen, with their line and voice) closes at once when it's a line you've already seen. Daily and world quest lines come back every day, so you see them once; the story's lines play only once anyway. Each character remembers its own, ticked or not, so an alt still sees the story's."] = "遊戲的對話頭像（畫面頂部的 NPC 頭像，帶台詞和語音）若是你已看過的台詞，會立即關閉。每日和世界任務的台詞每天都會重來，所以你只看一次；劇情台詞本來就只播放一次。無論是否勾選，每個角色各自記錄，所以分身仍能看到劇情台詞。"

-- ProfileChoices.lua and Welcome.lua: profile choices
L["Fights and opening windows bring your UI back"] = "戰鬥和開啟視窗會讓介面回來"
L["Most of the time"] = "大部分時間"
L["Between fights, and fights bring back less: no minimap, fewer group nameplates"] = "戰鬥之間，戰鬥中回來得更少：沒有小地圖，更少的隊伍名條"
L["Always show"] = "總是顯示"
L["Action bars (Classic group)"] = "快捷列（經典組）"
L["Action bars (Retail group)"] = "快捷列（正式服組）"
L["General and Trade too"] = "也包括綜合和交易"
L["Neither NPC speech nor public channels bring chat up"] = "NPC 發言和公共頻道都不會讓聊天出現"
L["No NPC chatter; speech from behind you shows low on the screen"] = "沒有 NPC 閒聊；你身後的話語顯示在畫面下方"
L["A portal opens around you as you hearth or teleport"] = "使用爐石或傳送時，你周圍會打開一道傳送門"
L["A card shows who buffed you or emoted at you"] = "卡片顯示誰給你加了增益或對你做了表情"
L["Your race with the top of the meter, in dungeons and raids"] = "在地城和團隊副本中與統計榜首的競賽"
L["NPC speech brings chat up; public channels don't"] = "NPC 發言會讓聊天出現；公共頻道不會"
L["NPC speech, and the General and Trade channels"] = "NPC 發言，以及綜合和交易頻道"

-- CardMoments.lua, CardsPage.lua, FlightLine.lua: Flight departure
L["Click to target %s"] = "點擊以選取%s"
L["As a flight lands: where it took you, and how long the flight took."] = "飛行降落時：它把你帶到了哪裡，以及飛了多久。"
L["Flight departure"] = "起飛"
L["As a flight takes off: where it's taking you, and about how long it takes on a route you've flown before. With a line along the top or bottom of the screen filling up on the way, if you like."] = "飛行起飛時：它要帶你去哪裡，以及在飛過的航線上大約要多久。如果你願意，畫面頂部或底部還會有一條隨途中進度填滿的線。"
L["Flying to"] = "飛往"
L["First time on this route"] = "首次飛這條航線"
L["about %d min"] = "約 %d 分鐘"
L["%s flight"] = "飛行 %s"
L["Progress line"] = "進度線"
L["Show a line as you fly"] = "飛行時顯示一條線"
L["On a route you've flown before, a thin line along a letterbox bar (or that edge of the screen) fills up as you fly, with the time left at its end. It shows while your UI is faded, and goes a moment before you land. A route's first flight has none: it's timed as you fly it."] = "在飛過的航線上，一條細線會沿著寬螢幕黑邊（或畫面那一側邊緣）隨飛行填滿，末端顯示剩餘時間。介面淡出時顯示，降落前片刻消失。航線的首次飛行沒有：會在飛行中計時。"
L["Flight progress line"] = "飛行進度線"
L["Top bar"] = "頂部黑邊"
L["Only at the start and end"] = "僅在開始和結束時"
L["The line shows for this long as the flight starts and before it lands, and is hidden in between: point the mouse at its place to see it. 0: it shows the whole way."] = "線會在飛行開始和降落前顯示這麼久，中途隱藏：把滑鼠指向它的位置即可看到。0：全程顯示。"
L["Bottom bar"] = "底部黑邊"
L["The letterbox bar the line and its time go in (no letterbox up: that edge of the screen)."] = "線和時間所在的寬螢幕黑邊（沒有黑邊時：畫面那一側邊緣）。"
L["Not on flights"] = "飛行時不顯示"
L["No Zone or Subzone card on a flight path: the places you fly over don't bring one after another, and the Flight departure and arrival cards say where you're going."] = "飛行路線上不顯示區域或子區域卡片：飛過的地方不會一張接一張地出現，起飛和抵達卡片會告訴你要去哪裡。"
L["Minutes only"] = "僅分鐘"
L["\"2 min\", rounded up, then \"under a minute\"."] = "「2 分鐘」，無條件進位，然後「不到一分鐘」。"
L["Minutes and seconds"] = "分和秒"
L["\"1:12\", counting down."] = "「1:12」，倒數計時。"
L["Don't show"] = "不顯示"
L["Just the line."] = "只顯示線。"
L["Time left:"] = "剩餘時間："
L["The time left at the line's end."] = "線末端的剩餘時間。"
L["The Flight departure card's line is on: on a route you've flown before, it fills up as you fly"] = "起飛卡片的線已開啟：在飛過的航線上，它會隨飛行填滿"
L["Where:"] = "位置："

-- EmoteVision.lua
L["Emote Vision: %s is too far away now."] = "Emote Vision：%s 現在太遠了。"

-- Options.lua: the CineMode page's Overview
L["Overview"] = "總覽"
L["Everything CineMode can do, page by page, and whether each page is on."] = "CineMode 能做的一切，逐頁列出，以及每頁是否開啟。"
L["How fast the UI fades, the Calm Timer, combat text and error messages."] = "介面淡出的速度、平靜計時器、戰鬥文字和錯誤訊息。"
L["What fades in CineMode, and what brings it back."] = "CineMode 中什麼會淡出，以及什麼會讓它回來。"
L["How the world looks and sounds in CineMode."] = "CineMode 中世界的樣子和聲音。"
L["The camera coming alive while CineMode is on."] = "CineMode 開啟時活起來的鏡頭。"
L["On and off with the General page's switch."] = "隨「一般」頁面的開關開啟和關閉。"
L["On. Click to turn this page off."] = "已開啟。點擊關閉此頁面。"
L["Off. Click to turn this page on."] = "已關閉。點擊開啟此頁面。"
L["Everything CineMode can do, page by page. Click On or Off to turn a page on or off; Open takes you there."] = "CineMode 能做的一切，逐頁列出。點擊「開」或「關」來開啟或關閉一個頁面；「開啟」會帶你過去。"
L["Go to this page."] = "前往此頁面。"
L["%d of %d pages on."] = "已開啟 %d / %d 個頁面。"

-- ShowMe.lua and Welcome.lua: See it first, Show me
L["Nothing to show here."] = "這裡沒有可展示的。"
L["Not in a fight: try it once the fight ends."] = "戰鬥中不可用：戰鬥結束後再試。"
L["Click the row to turn it on first."] = "請先點擊該行將其開啟。"
L["See it first"] = "先看看"
L["Click one to see it for a few seconds."] = "點擊一項可觀看幾秒鐘。"
L["Vitals"] = "生命徵象"
L["Teleport"] = "傳送"
L["Black bars at the top and bottom of the screen, as in a film."] = "畫面頂部和底部的黑邊，就像電影一樣。"
L["A color wash over the world that follows the time of day and the zone, with soft dark edges and weather to match."] = "覆蓋世界的色調，隨時段和區域變化，帶有柔和的暗邊和相配的天氣。"
L["The camera moves on its own at quiet moments: on flights, when you go AFK, by a campfire. This shows a half turn around you; move the camera yourself to stop it."] = "鏡頭會在安靜時刻自行移動：飛行時、暫離時、營火旁。這裡展示繞你半圈；自己移動鏡頭即可停止。"
L["As your health drops, the screen's edges close in, so you feel a fight without watching your health bar."] = "生命值下降時，畫面邊緣會向內收攏，讓你無需盯著生命條也能感受戰鬥。"
L["As you cast your Hearthstone or a teleport, a portal opens around you and the world fades out as you leave."] = "施放爐石或傳送時，你周圍會打開一道傳送門，離開時世界逐漸消失。"
